/** Focused topology and RGB-identity proof for unusual native powders. */
async function auditUnusualPowderGraphics(cdp, mode, options = {}) {
  const expectedCount = options.count ?? 10;
  const expectedMaterials = options.materials ?? [43, 44, 45, 46, 47, 48, 49, 51, 198, 217];
  const expectedContactMaterial = options.contactMaterial ?? 1;
  const powderLabel = options.label ?? 'unusual-powder';
  const started = performance.now();
  const stage = (name) => console.error(
    `[${powderLabel}-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(cdp, `${mode} initial blank unusual-powder framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareUnusualPowderGraphicsFixture !== 'function'
      || typeof audit.unusualPowderGraphicsAtlas !== 'function'
      || typeof audit.setUnusualPowderStyling !== 'function'
      || typeof audit.setPowderRenderStyle !== 'function') {
      throw new Error('Unusual powder graphics audit API unavailable');
    }
    audit.prepareUnusualPowderGraphicsFixture();
    audit.setPowderRenderStyle('smooth');
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.unusualPowderGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === ${expectedCount} ? atlas : false;
  })()`), 15_000, `${mode} unusual powder graphics fixture`);
  const atlas = normalizeUnusualPowderGraphicsAtlas(rawAtlas);
  assert(atlas.cards.length === expectedCount
      && atlas.cards.every(({ material }, index) => material === expectedMaterials[index]),
  `${mode}: unusual powder atlas identity changed (${JSON.stringify(atlas.cards)})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.unusualPowderGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const key = ({ x, y }) => x + ',' + y;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      const empty = new Set([
        ...Array.from({ length: entry.hole.height }, (_, dy) =>
          Array.from({ length: entry.hole.width }, (_, dx) => key({ x: entry.hole.x + dx, y: entry.hole.y + dy }))),
        entry.openNotch.map(key),
      ].flat());
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const expected = empty.has(x + ',' + y) ? 0 : entry.material;
          bodyExact = bodyExact && audit.cell(x, y) === expected;
        }
      }
      return {
        material: entry.material,
        code: entry.code,
        bodyExact,
        thinColumnExact: exactRect(entry.thinColumn, entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        contactOwnerExact: exactRect(entry.contact.owner, entry.material),
        contactUnlikeExact: exactRect(entry.contact.unlike, entry.contact.unlikeMaterial),
        unlikeMaterial: entry.contact.unlikeMaterial,
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.thinColumnExact
      && entry.isolated === entry.material && entry.guardedBlankEmpty
      && entry.contactOwnerExact && entry.contactUnlikeExact
      && entry.unlikeMaterial === expectedContactMaterial),
  `${mode}: unusual powder fixture lost body/hole/notch/column/isolated/blank/contact semantics (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(false); true');
  const flat = await waitForStablePageCapture(cdp, `${mode} flat smooth unusual-powder framebuffer`);
  const flatBacking = await sampleUnusualPowderBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(true); true');
  const styled = await waitForStablePageCapture(cdp, `${mode} styled smooth unusual-powder framebuffer`);
  const styledBacking = await sampleUnusualPowderBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualPowderStyling(false); true');
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat smooth unusual-powder framebuffer`);
  const repeatedBacking = await sampleUnusualPowderBackingTopology(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertUnusualPowderBackingTopology(backing, `${mode} ${state} Smooth`, false, expectedCount);

  const backingResponses = summarizeUnusualPowderBackingResponses(
    flatBacking, styledBacking, repeatedBacking, expectedCount,
  );
  assert(backingResponses.every(({ rgbRms, rgbPeak, repeatRgbPeak }) => (
    rgbRms >= 0.05 && rgbRms <= 32 && rgbPeak > 0 && rgbPeak <= 64 && repeatRgbPeak === 0
  )), `${mode}: unusual powder response is absent, unbounded, or non-repeatable (${JSON.stringify(backingResponses)})`);
  assert(new Set(backingResponses.map(({ responseSignature }) => responseSignature)).size === expectedCount,
    `${mode}: powder identities do not have ${expectedCount} distinct response signatures (${JSON.stringify(backingResponses)})`);

  const bodyRegions = atlas.cards.map((entry) => ({
    name: `unusual-powder-${entry.code}`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  }));
  const atlasBounds = containingCellularRegion(atlas.cards.map(({ card }) => card));
  const responses = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, [...bodyRegions, { name: 'unusual-powder-atlas', ...atlasBounds }], flat.canvasRect);
  const atlasResponse = responses.at(-1);
  assert(atlasResponse.repeatRgbPeak === 0,
    `${mode}: unusual powder flat→styled→flat framebuffer was not exact (${JSON.stringify(atlasResponse)})`);
  assert(responses.slice(0, expectedCount).every((sample) => sample.rgbRms > 0 && sample.rgbPeak <= 64),
    `${mode}: at least one unusual powder has no bounded composed response (${JSON.stringify(responses)})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
  ]);
  assert(flatSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0)
      && styledSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0),
  `${mode}: at least one unusual powder body is not visible (${JSON.stringify({ flatSupport, styledSupport })})`);
  stage('smooth-response-ready');

  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setUnusualPowderStyling(true);
    audit.setPowderRenderStyle('grains');
    return true;
  })()`);
  await waitForStablePageCapture(cdp, `${mode} Grains unusual-powder framebuffer`);
  const grainsBacking = await sampleUnusualPowderBackingTopology(cdp);
  assertUnusualPowderBackingTopology(grainsBacking, `${mode} Grains`, true, expectedCount);
  await evaluate(cdp, "window.__ANIFOR_INPUT_AUDIT__.setPowderRenderStyle('local'); true");
  await waitForStablePageCapture(cdp, `${mode} Local unusual-powder framebuffer`);
  const localBacking = await sampleUnusualPowderBackingTopology(cdp);
  assertUnusualPowderBackingTopology(localBacking, `${mode} Local`, false, expectedCount);
  stage('style-controls-ready');

  const cardSignatures = atlas.cards.map((entry, index) => ({
    index: entry.index,
    material: entry.material,
    code: entry.code,
    flatSignature: flatSupport[index].signature,
    styledSignature: styledSupport[index].signature,
    flatVisible: flatSupport[index].visible,
    styledVisible: styledSupport[index].visible,
    rgbRms: responses[index].rgbRms,
    rgbPeak: responses[index].rgbPeak,
    responseSignature: responses[index].responseSignature,
    backingRgbRms: backingResponses[index].rgbRms,
    backingRgbPeak: backingResponses[index].rgbPeak,
    backingChangedCellRatio: backingResponses[index].changedCellRatio,
    backingRepeatRgbPeak: backingResponses[index].repeatRgbPeak,
    backingResponseSignature: backingResponses[index].responseSignature,
    backingResponseProfile: backingResponses[index].responseProfile,
  }));
  return {
    cards: cardSignatures.length,
    holeCells: atlas.holes.length,
    openNotchCells: atlas.openNotches.length,
    thinColumnCells: atlas.thinColumns.length,
    isolatedControls: atlas.isolated.length,
    unlikeSandContacts: atlas.contacts.length,
    exactRepeatedOff: atlasResponse.repeatRgbPeak === 0,
    grainsBackingScale: `${grainsBacking.scaleX}x${grainsBacking.scaleY}`,
    grainsExactSquareCells: grainsBacking.cards.reduce(
      (total, card) => total + card.allOccupiedFullySupported, 0,
    ),
    localFineControls: localBacking.cards.reduce(
      (total, card) => total + card.thinColumnSupported + Number(card.isolatedAlphaPeak > 0), 0,
    ),
    cardSignatures,
  };
}

async function sampleUnusualPowderBackingTopology(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Unusual powder backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let minimum = 255;
      let peak = 0;
      let supported = 0;
      let pixelsInCell = 0;
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        minimum = Math.min(minimum, alpha);
        peak = Math.max(peak, alpha);
        supported += Number(alpha === 255);
        pixelsInCell++;
      }
      return { minimum, peak, supported, pixels: pixelsInCell };
    };
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const sampleBody = (body) => {
      const rgb = [];
      for (let y = body.y; y < body.y + body.height; y++) {
        for (let x = body.x; x < body.x + body.width; x++) {
          const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
          const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
          const offset = (py * copy.width + px) * 4;
          rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
        }
      }
      return { width: body.width, height: body.height, rgb };
    };
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.unusualPowderGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      cards: cards.map((entry) => {
        const key = ({ x, y }) => x + ',' + y;
        const holePoints = rectPoints(entry.hole);
        const emptyKeys = new Set([...holePoints, ...entry.openNotch].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
        const thinPoints = rectPoints(entry.thinColumn);
        const guardPoints = rectPoints(entry.guardedBlank);
        const ownerContact = rectPoints(entry.contact.owner);
        const unlikeContact = rectPoints(entry.contact.unlike);
        const occupied = [...bodyPoints, ...thinPoints, entry.isolated, ...ownerContact, ...unlikeContact];
        return {
          index: entry.index,
          material: entry.material,
          code: entry.code,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlpha(point).peak > 0).length,
          holesExpected: holePoints.length,
          holesTransparent: holePoints.filter((point) => cellAlpha(point).peak === 0).length,
          openNotchesExpected: entry.openNotch.length,
          openNotchesTransparent: entry.openNotch.filter((point) => cellAlpha(point).peak === 0).length,
          openNotchesOpen: entry.openNotch.filter((point) => cellAlpha(point).minimum === 0).length,
          thinColumnExpected: thinPoints.length,
          thinColumnSupported: thinPoints.filter((point) => cellAlpha(point).peak > 0).length,
          isolatedAlphaPeak: cellAlpha(entry.isolated).peak,
          guardedBlankExpected: guardPoints.length,
          guardedBlankTransparent: guardPoints.filter((point) => cellAlpha(point).peak === 0).length,
          contactOwnerExpected: ownerContact.length,
          contactOwnerSupported: ownerContact.filter((point) => cellAlpha(point).peak > 0).length,
          contactUnlikeExpected: unlikeContact.length,
          contactUnlikeSupported: unlikeContact.filter((point) => cellAlpha(point).peak > 0).length,
          allOccupiedExpected: occupied.length,
          allOccupiedFullySupported: occupied.filter((point) => {
            const alpha = cellAlpha(point);
            return alpha.minimum === 255 && alpha.supported === alpha.pixels
              && alpha.pixels === scaleX * scaleY;
          }).length,
          ...sampleBody(entry.body),
        };
      }),
    };
  })()`);
}

function assertUnusualPowderBackingTopology(backing, label, exactSquares, expectedCount = 10) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: backing does not preserve integral world scaling (${JSON.stringify(backing)})`);
  if (exactSquares) assert(backing.scaleX === backing.scaleY,
    `${label}: Grains backing cells are not square (${backing.scaleX}x${backing.scaleY})`);
  assert(backing.cards.length === expectedCount && backing.cards.every((card) => (
    card.bodySupported === card.bodyExpected
    && card.holesTransparent === card.holesExpected
    // Smooth/Local deliberately antialias a curved pile boundary into its
    // neighbouring cell. Each authored notch cell must still retain genuine
    // transparent backing samples; Grains remains the exact square reference.
    && (exactSquares
      ? card.openNotchesTransparent === card.openNotchesExpected
      : card.openNotchesOpen === card.openNotchesExpected)
    && card.thinColumnSupported === card.thinColumnExpected
    && card.isolatedAlphaPeak > 0
    && card.guardedBlankTransparent === card.guardedBlankExpected
    && card.contactOwnerSupported === card.contactOwnerExpected
    && card.contactUnlikeSupported === card.contactUnlikeExpected
    && (!exactSquares || card.allOccupiedFullySupported === card.allOccupiedExpected)
  )), `${label}: backing changed body/hole/notch/column/isolated/blank/contact topology (${JSON.stringify(backing.cards)})`);
}

function summarizeUnusualPowderBackingResponses(flat, styled, repeated, expectedCount = 10) {
  assert(flat.cards.length === expectedCount && styled.cards.length === expectedCount
      && repeated.cards.length === expectedCount,
    'Unusual powder backing response atlas is incomplete');
  return flat.cards.map((base, cardIndex) => {
    const changed = styled.cards[cardIndex];
    const returned = repeated.cards[cardIndex];
    assert(changed.material === base.material && returned.material === base.material
        && changed.width === base.width && returned.width === base.width
        && changed.height === base.height && returned.height === base.height
        && changed.rgb.length === base.rgb.length && returned.rgb.length === base.rgb.length,
    `Unusual powder backing response geometry changed for ${base.code}`);
    let squared = 0;
    let rgbPeak = 0;
    let repeatRgbPeak = 0;
    let changedCells = 0;
    let responseSignature = 2166136261;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.rgb.length; offset += 3) {
      const cell = offset / 3;
      const x = cell % base.width;
      const y = Math.floor(cell / base.width);
      const bucket = Math.min(3, Math.floor(y * 4 / base.height)) * 4
        + Math.min(3, Math.floor(x * 4 / base.width));
      let cellChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.rgb[offset + channel] - base.rgb[offset + channel];
        const repeat = returned.rgb[offset + channel] - base.rgb[offset + channel];
        squared += delta * delta;
        rgbPeak = Math.max(rgbPeak, Math.abs(delta));
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        cellChanged ||= delta !== 0;
        responseSignature = Math.imul(responseSignature ^ (delta + 255), 16777619) >>> 0;
      }
      changedCells += Number(cellChanged);
    }
    const total = Math.max(1, buckets.reduce((sum, value) => sum + value, 0));
    return {
      material: base.material,
      code: base.code,
      rgbRms: round(Math.sqrt(squared / Math.max(1, base.rgb.length)), 4),
      rgbPeak,
      changedCellRatio: round(changedCells / Math.max(1, base.width * base.height), 5),
      repeatRgbPeak,
      responseSignature,
      responseProfile: Array.from(buckets, (value) => round(value / total, 5)),
    };
  });
}

function normalizeUnusualPowderGraphicsAtlas(snapshot) {
  const cards = (Array.isArray(snapshot) ? snapshot : snapshot?.cards ?? []).map((entry) => ({
    ...entry,
    card: cellularRect(entry.card ?? entry),
    body: cellularRect(entry.body),
    hole: cellularRect(entry.hole),
    openNotch: cellularPoints(entry.openNotch),
    thinColumn: cellularRect(entry.thinColumn),
    isolated: cellularPoint(entry.isolated),
    guardedBlank: cellularRect(entry.guardedBlank),
    contact: {
      ...entry.contact,
      owner: cellularRect(entry.contact.owner),
      unlike: cellularRect(entry.contact.unlike),
    },
  }));
  return {
    cards,
    holes: Array.isArray(snapshot)
      ? cards.flatMap(({ hole }) => cellularRectPoints(hole)) : cellularPoints(snapshot?.holes),
    openNotches: Array.isArray(snapshot)
      ? cards.flatMap(({ openNotch }) => openNotch) : cellularPoints(snapshot?.openNotches),
    thinColumns: Array.isArray(snapshot)
      ? cards.flatMap(({ thinColumn }) => cellularRectPoints(thinColumn))
      : cellularPoints(snapshot?.thinColumns),
    isolated: cellularPoints(
      Array.isArray(snapshot) ? cards.map(({ isolated }) => isolated) : snapshot?.isolated,
    ),
    guardedBlanks: Array.isArray(snapshot)
      ? cards.map(({ guardedBlank }) => guardedBlank)
      : (snapshot?.guardedBlanks ?? []).map(cellularRect),
    contacts: Array.isArray(snapshot) ? cards.map(({ contact }) => contact) : snapshot?.contacts ?? [],
  };
}

/** Focused topology and RGB-identity proof for eleven unusual native solids. */
async function auditUnusualSolidGraphics(cdp, mode) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[unusual-solid-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  const blank = await waitForStablePageCapture(cdp, `${mode} initial blank unusual-solid framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareUnusualSolidGraphicsFixture !== 'function'
      || typeof audit.unusualSolidGraphicsAtlas !== 'function'
      || typeof audit.setUnusualSolidStyling !== 'function') {
      throw new Error('Unusual solid graphics audit API unavailable');
    }
    audit.prepareUnusualSolidGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.unusualSolidGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 11 ? atlas : false;
  })()`), 15_000, `${mode} unusual solid graphics fixture`);
  const atlas = normalizeUnusualSolidGraphicsAtlas(rawAtlas);
  const expectedMaterials = [196, 206, 80, 208, 209, 210, 216, 203, 204, 211, 212];
  assert(atlas.cards.length === 11
      && atlas.cards.every(({ material }, index) => material === expectedMaterials[index]),
  `${mode}: unusual solid atlas identity/order changed (${JSON.stringify(atlas.cards.map(({ code, material }) => ({ code, material })))})`);
  const shieldCards = atlas.cards.filter(({ code }) => code.startsWith('SHLD'));
  assert(shieldCards.map(({ code }) => code).join(',') === 'SHLD1,SHLD2,SHLD3,SHLD4'
      && shieldCards.map(({ material }) => material).join(',') === '80,208,209,210',
  `${mode}: shield stage order changed (${JSON.stringify(shieldCards.map(({ code, material }) => ({ code, material })))})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.unusualSolidGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const key = ({ x, y }) => x + ',' + y;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      const hole = [];
      for (let y = entry.hole.y; y < entry.hole.y + entry.hole.height; y++) {
        for (let x = entry.hole.x; x < entry.hole.x + entry.hole.width; x++) hole.push({ x, y });
      }
      const empty = new Set([...hole, ...entry.openNotch].map(key));
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const expected = empty.has(x + ',' + y) ? 0 : entry.material;
          bodyExact = bodyExact && audit.cell(x, y) === expected;
        }
      }
      let shellExact = true;
      for (let y = entry.shell.outer.y; y < entry.shell.outer.y + entry.shell.outer.height; y++) {
        for (let x = entry.shell.outer.x; x < entry.shell.outer.x + entry.shell.outer.width; x++) {
          const inside = x >= entry.shell.interior.x
            && x < entry.shell.interior.x + entry.shell.interior.width
            && y >= entry.shell.interior.y
            && y < entry.shell.interior.y + entry.shell.interior.height;
          shellExact = shellExact && audit.cell(x, y) === (inside ? 0 : entry.material);
        }
      }
      return {
        code: entry.code,
        material: entry.material,
        bodyExact,
        shellExact,
        spurExact: exactRect(entry.spur, entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        contactOwnerExact: exactRect(entry.contact.owner, entry.material),
        contactUnlikeExact: exactRect(entry.contact.unlike, entry.contact.unlikeMaterial),
        unlikeMaterial: entry.contact.unlikeMaterial,
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.shellExact
      && entry.spurExact && entry.isolated === entry.material && entry.guardedBlankEmpty
      && entry.contactOwnerExact && entry.contactUnlikeExact && entry.unlikeMaterial === 23),
  `${mode}: unusual solid fixture lost authored semantics (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualSolidStyling(false); true');
  const flat = await waitForStablePageCapture(cdp, `${mode} flat unusual-solid framebuffer`);
  const flatBacking = await sampleUnusualSolidBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualSolidStyling(true); true');
  const styled = await waitForStablePageCapture(cdp, `${mode} styled unusual-solid framebuffer`);
  const styledBacking = await sampleUnusualSolidBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setUnusualSolidStyling(false); true');
  const repeated = await waitForStablePageCapture(cdp, `${mode} repeated flat unusual-solid framebuffer`);
  const repeatedBacking = await sampleUnusualSolidBackingTopology(cdp);
  for (const [state, backing] of [
    ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
  ]) assertUnusualSolidBackingTopology(backing, `${mode} ${state}`);
  assert(flatBacking.cards.every((card, index) => (
    card.alphaSignature === styledBacking.cards[index].alphaSignature
      && card.alphaSignature === repeatedBacking.cards[index].alphaSignature
  )), `${mode}: unusual solid styling changed raw backing support (${JSON.stringify({
    flat: compactUnusualSolidTopology(flatBacking),
    styled: compactUnusualSolidTopology(styledBacking),
    repeated: compactUnusualSolidTopology(repeatedBacking),
  })})`);
  assert(flatBacking.cards.every((card, index) => (
    arraysEqual(card.contactUnlikeRgb, styledBacking.cards[index].contactUnlikeRgb)
      && arraysEqual(card.contactUnlikeRgb, repeatedBacking.cards[index].contactUnlikeRgb)
  )), `${mode}: unusual solid styling leaked into an unlike-Metal contact`);

  const backingResponses = summarizeUnusualSolidBackingResponses(
    flatBacking, styledBacking, repeatedBacking,
  );
  assert(backingResponses.every(({ rgbRms, rgbPeak, repeatRgbPeak }) => (
    rgbRms >= 0.05 && rgbRms <= 32 && rgbPeak > 0 && rgbPeak <= 64 && repeatRgbPeak === 0
  )), `${mode}: unusual solid response is absent, unbounded, or non-repeatable (${JSON.stringify(backingResponses)})`);
  assert(new Set(backingResponses.map(({ responseSignature }) => responseSignature)).size === 11,
    `${mode}: unusual solids do not have eleven distinct response signatures (${JSON.stringify(backingResponses)})`);
  const shieldResponses = backingResponses.filter(({ code }) => code.startsWith('SHLD'));
  assert(shieldResponses.map(({ code }) => code).join(',') === 'SHLD1,SHLD2,SHLD3,SHLD4'
      && new Set(shieldResponses.map(({ responseSignature }) => responseSignature)).size === 4,
  `${mode}: SHLD1-4 lost ordered distinct stage responses (${JSON.stringify(shieldResponses)})`);

  const bodyRegions = atlas.cards.map((entry) => ({
    name: `unusual-solid-${entry.code}`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  }));
  const atlasBounds = containingCellularRegion(atlas.cards.map(({ card }) => card));
  const responses = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, [...bodyRegions, { name: 'unusual-solid-atlas', ...atlasBounds }], flat.canvasRect);
  const atlasResponse = responses.at(-1);
  assert(atlasResponse.repeatRgbPeak === 0,
    `${mode}: unusual solid flat→styled→flat framebuffer was not exact (${JSON.stringify(atlasResponse)})`);
  assert(responses.slice(0, atlas.cards.length).every((sample) => sample.rgbRms > 0 && sample.rgbPeak <= 64),
    `${mode}: at least one unusual solid has no bounded composed response (${JSON.stringify(responses)})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
  ]);
  assert(flatSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0)
      && styledSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0),
  `${mode}: at least one unusual solid body is not visible (${JSON.stringify({ flatSupport, styledSupport })})`);
  stage('responses-ready');

  const cardSignatures = atlas.cards.map((entry, index) => ({
    index: entry.index,
    material: entry.material,
    code: entry.code,
    flatSignature: flatSupport[index].signature,
    styledSignature: styledSupport[index].signature,
    flatVisible: flatSupport[index].visible,
    styledVisible: styledSupport[index].visible,
    rgbRms: responses[index].rgbRms,
    rgbPeak: responses[index].rgbPeak,
    responseSignature: responses[index].responseSignature,
    backingRgbRms: backingResponses[index].rgbRms,
    backingRgbPeak: backingResponses[index].rgbPeak,
    backingChangedCellRatio: backingResponses[index].changedCellRatio,
    backingRepeatRgbPeak: backingResponses[index].repeatRgbPeak,
    backingResponseSignature: backingResponses[index].responseSignature,
    backingResponseProfile: backingResponses[index].responseProfile,
  }));
  return {
    cards: cardSignatures.length,
    holeCells: atlas.holes.length,
    centralProtectedHoleCells: atlas.cards.length * 16,
    openNotchCells: atlas.openNotches.length,
    shellCells: atlas.shellCells.length,
    shellInteriorCells: atlas.shellInteriors.length,
    spurCells: atlas.spurs.length,
    isolatedControls: atlas.isolated.length,
    unlikeMetalContacts: atlas.contacts.length,
    exactRepeatedOff: atlasResponse.repeatRgbPeak === 0,
    shieldStages: shieldCards.map(({ code, material }, stage) => ({ stage: stage + 1, code, material })),
    cardSignatures,
  };
}

async function sampleUnusualSolidBackingTopology(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Unusual solid backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let peak = 0;
      const values = [];
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        peak = Math.max(peak, alpha);
        values.push(alpha);
      }
      return { peak, values };
    };
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const shellPoints = (shell) => rectPoints(shell.outer).filter(({ x, y }) => (
      x < shell.interior.x || x >= shell.interior.x + shell.interior.width
        || y < shell.interior.y || y >= shell.interior.y + shell.interior.height
    ));
    const sampleBody = (body) => {
      const rgb = [];
      for (let y = body.y; y < body.y + body.height; y++) {
        for (let x = body.x; x < body.x + body.width; x++) {
          const px = Math.min(copy.width - 1, Math.floor((x + 0.5) * scaleX));
          const py = Math.min(copy.height - 1, Math.floor((y + 0.5) * scaleY));
          const offset = (py * copy.width + px) * 4;
          rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
        }
      }
      return { width: body.width, height: body.height, rgb };
    };
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.unusualSolidGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      cards: cards.map((entry) => {
        const key = ({ x, y }) => x + ',' + y;
        const holePoints = rectPoints(entry.hole);
        const centralHole = rectPoints({
          x: entry.hole.x + 1, y: entry.hole.y + 1,
          width: entry.hole.width - 2, height: entry.hole.height - 2,
        });
        const emptyKeys = new Set([...holePoints, ...entry.openNotch].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
        const ringPoints = shellPoints(entry.shell);
        const shellInterior = rectPoints(entry.shell.interior);
        const centralShellInterior = rectPoints({
          x: entry.shell.interior.x + 1, y: entry.shell.interior.y + 1,
          width: entry.shell.interior.width - 2, height: entry.shell.interior.height - 2,
        });
        const spurPoints = rectPoints(entry.spur);
        const guardPoints = rectPoints(entry.guardedBlank);
        const ownerContact = rectPoints(entry.contact.owner);
        const unlikeContact = rectPoints(entry.contact.unlike);
        const signatureMap = new Map();
        for (const point of [
          ...rectPoints(entry.body), ...rectPoints(entry.shell.outer), ...spurPoints,
          entry.isolated, ...guardPoints, ...ownerContact, ...unlikeContact,
        ]) signatureMap.set(key(point), point);
        let alphaSignature = 2166136261;
        for (const point of signatureMap.values()) for (const alpha of cellAlpha(point).values) {
          alphaSignature = Math.imul(alphaSignature ^ alpha, 16777619) >>> 0;
        }
        return {
          index: entry.index,
          material: entry.material,
          code: entry.code,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlpha(point).peak > 0).length,
          holeExpected: holePoints.length,
          holeTransparent: holePoints.filter((point) => cellAlpha(point).peak === 0).length,
          centralHoleExpected: centralHole.length,
          centralHoleTransparent: centralHole.filter((point) => cellAlpha(point).peak === 0).length,
          openNotchesExpected: entry.openNotch.length,
          openNotchesTransparent: entry.openNotch.filter((point) => cellAlpha(point).peak === 0).length,
          shellExpected: ringPoints.length,
          shellSupported: ringPoints.filter((point) => cellAlpha(point).peak > 0).length,
          shellInteriorExpected: shellInterior.length,
          shellInteriorTransparent: shellInterior.filter((point) => cellAlpha(point).peak === 0).length,
          centralShellInteriorExpected: centralShellInterior.length,
          centralShellInteriorTransparent: centralShellInterior.filter(
            (point) => cellAlpha(point).peak === 0,
          ).length,
          spurExpected: spurPoints.length,
          spurSupported: spurPoints.filter((point) => cellAlpha(point).peak > 0).length,
          isolatedAlphaPeak: cellAlpha(entry.isolated).peak,
          guardedBlankExpected: guardPoints.length,
          guardedBlankTransparent: guardPoints.filter((point) => cellAlpha(point).peak === 0).length,
          contactOwnerExpected: ownerContact.length,
          contactOwnerSupported: ownerContact.filter((point) => cellAlpha(point).peak > 0).length,
          contactUnlikeExpected: unlikeContact.length,
          contactUnlikeSupported: unlikeContact.filter((point) => cellAlpha(point).peak > 0).length,
          alphaSignature,
          ...sampleBody(entry.body),
          contactUnlikeRgb: sampleBody(entry.contact.unlike).rgb,
        };
      }),
    };
  })()`);
}

function assertUnusualSolidBackingTopology(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: backing does not preserve integral world scaling (${backing.scaleX}x${backing.scaleY})`);
  const valid = backing.cards.length === 11 && backing.cards.every((card) => (
    card.bodySupported === card.bodyExpected
    && card.holeTransparent >= card.centralHoleExpected
    && card.centralHoleTransparent === card.centralHoleExpected
    && card.openNotchesTransparent === card.openNotchesExpected
    && card.shellSupported === card.shellExpected
    && card.shellInteriorTransparent >= card.centralShellInteriorExpected
    && card.centralShellInteriorTransparent === card.centralShellInteriorExpected
    && card.spurSupported === card.spurExpected
    && card.isolatedAlphaPeak > 0
    && card.guardedBlankTransparent === card.guardedBlankExpected
    && card.contactOwnerSupported === card.contactOwnerExpected
    && card.contactUnlikeSupported === card.contactUnlikeExpected
  ));
  assert(valid,
    `${label}: backing changed solid topology (${JSON.stringify(compactUnusualSolidTopology(backing))})`);
}

function compactUnusualSolidTopology(backing) {
  return {
    scale: `${backing.scaleX}x${backing.scaleY}`,
    cards: backing.cards.map(({
      rgb: _rgb, contactUnlikeRgb: _contactUnlikeRgb,
      width: _width, height: _height, ...card
    }) => card),
  };
}

function summarizeUnusualSolidBackingResponses(flat, styled, repeated) {
  assert(flat.cards.length === 11 && styled.cards.length === 11 && repeated.cards.length === 11,
    'Unusual solid backing response atlas is incomplete');
  return flat.cards.map((base, cardIndex) => {
    const changed = styled.cards[cardIndex];
    const returned = repeated.cards[cardIndex];
    assert(changed.material === base.material && returned.material === base.material
        && changed.width === base.width && returned.width === base.width
        && changed.height === base.height && returned.height === base.height
        && changed.rgb.length === base.rgb.length && returned.rgb.length === base.rgb.length,
    `Unusual solid backing response geometry changed for ${base.code}`);
    let squared = 0;
    let rgbPeak = 0;
    let repeatRgbPeak = 0;
    let changedCells = 0;
    let responseSignature = 2166136261;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.rgb.length; offset += 3) {
      const cell = offset / 3;
      const x = cell % base.width;
      const y = Math.floor(cell / base.width);
      const bucket = Math.min(3, Math.floor(y * 4 / base.height)) * 4
        + Math.min(3, Math.floor(x * 4 / base.width));
      let cellChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.rgb[offset + channel] - base.rgb[offset + channel];
        const repeat = returned.rgb[offset + channel] - base.rgb[offset + channel];
        squared += delta * delta;
        rgbPeak = Math.max(rgbPeak, Math.abs(delta));
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        cellChanged ||= delta !== 0;
        responseSignature = Math.imul(responseSignature ^ (delta + 255), 16777619) >>> 0;
      }
      changedCells += Number(cellChanged);
    }
    const total = Math.max(1, buckets.reduce((sum, value) => sum + value, 0));
    return {
      material: base.material,
      code: base.code,
      rgbRms: round(Math.sqrt(squared / Math.max(1, base.rgb.length)), 4),
      rgbPeak,
      changedCellRatio: round(changedCells / Math.max(1, base.width * base.height), 5),
      repeatRgbPeak,
      responseSignature,
      responseProfile: Array.from(buckets, (value) => round(value / total, 5)),
    };
  });
}

function normalizeUnusualSolidGraphicsAtlas(snapshot) {
  const cards = (Array.isArray(snapshot) ? snapshot : snapshot?.cards ?? []).map((entry) => ({
    ...entry,
    card: cellularRect(entry.card ?? entry),
    body: cellularRect(entry.body),
    hole: cellularRect(entry.hole),
    openNotch: cellularPoints(entry.openNotch),
    shell: {
      outer: cellularRect(entry.shell.outer),
      interior: cellularRect(entry.shell.interior),
    },
    spur: cellularRect(entry.spur),
    isolated: cellularPoint(entry.isolated),
    guardedBlank: cellularRect(entry.guardedBlank),
    contact: {
      ...entry.contact,
      owner: cellularRect(entry.contact.owner),
      unlike: cellularRect(entry.contact.unlike),
    },
  }));
  const shellPoints = ({ outer, interior }) => cellularRectPoints(outer).filter(({ x, y }) => (
    x < interior.x || x >= interior.x + interior.width
      || y < interior.y || y >= interior.y + interior.height
  ));
  return {
    cards,
    holes: Array.isArray(snapshot)
      ? cards.flatMap(({ hole }) => cellularRectPoints(hole)) : cellularPoints(snapshot?.holes),
    openNotches: Array.isArray(snapshot)
      ? cards.flatMap(({ openNotch }) => openNotch) : cellularPoints(snapshot?.openNotches),
    shellCells: Array.isArray(snapshot)
      ? cards.flatMap(({ shell }) => shellPoints(shell)) : cellularPoints(snapshot?.shellCells),
    shellInteriors: Array.isArray(snapshot)
      ? cards.flatMap(({ shell }) => cellularRectPoints(shell.interior))
      : cellularPoints(snapshot?.shellInteriors),
    spurs: Array.isArray(snapshot)
      ? cards.flatMap(({ spur }) => cellularRectPoints(spur)) : cellularPoints(snapshot?.spurs),
    isolated: cellularPoints(
      Array.isArray(snapshot) ? cards.map(({ isolated }) => isolated) : snapshot?.isolated,
    ),
    guardedBlanks: Array.isArray(snapshot)
      ? cards.map(({ guardedBlank }) => guardedBlank)
      : (snapshot?.guardedBlanks ?? []).map(cellularRect),
    contacts: Array.isArray(snapshot) ? cards.map(({ contact }) => contact) : snapshot?.contacts ?? [],
  };
}

/** Focused topology and RGB-identity proof for canonical liquid families. */
async function auditLiquidIdentityGraphics(cdp, mode, useEightXCapture = false) {
  const started = performance.now();
  const stage = (name) => console.error(
    `[liquid-identity-graphics:${mode}] ${name} ${Math.round(performance.now() - started)}ms`,
  );
  // A true-8x semantic mesh can still own its completed frame fence after the
  // UI setter returns. Ordinary 2x fixture audits benefit from exact stable
  // screenshots; 8x instead waits for that fence before each heavyweight PNG
  // capture so the test neither samples a previous frame nor queues enough
  // 15M-fragment work to destabilize Chrome.
  const capture = (label) => useEightXCapture
    ? captureSettledPage(cdp, label, 1_200)
    : waitForStablePageCapture(cdp, label);
  const blank = await capture(`${mode} initial blank liquid-identity framebuffer`);
  await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit.prepareLiquidIdentityGraphicsFixture !== 'function'
      || typeof audit.liquidIdentityGraphicsAtlas !== 'function'
      || typeof audit.setLiquidIdentityStyling !== 'function') {
      throw new Error('Liquid identity graphics audit API unavailable');
    }
    audit.prepareLiquidIdentityGraphicsFixture();
    return true;
  })()`);
  const rawAtlas = await waitFor(() => evaluate(cdp, `(() => {
    const atlas = window.__ANIFOR_INPUT_AUDIT__.liquidIdentityGraphicsAtlas();
    const cards = Array.isArray(atlas) ? atlas : atlas?.cards;
    return cards?.length === 16 ? atlas : false;
  })()`), 15_000, `${mode} liquid identity graphics fixture`);
  const atlas = normalizeLiquidIdentityGraphicsAtlas(rawAtlas);
  const expectedMaterials = [38, 54, 55, 56, 57, 62, 202, 207, 59, 60, 61, 100, 102, 104, 36, 37];
  const expectedCodes = [
    'SOAP', 'BIZR', 'CBNW', 'GEL', 'GLOW', 'VIRS', 'FRZW', 'RFGL',
    'MWAX', 'PSTE', 'RSST', 'DEUT', 'EXOT', 'ISOZ', 'MERC', 'LN2',
  ];
  assert(atlas.cards.length === 16
      && atlas.cards.every(({ material, code }, index) => (
        material === expectedMaterials[index] && code === expectedCodes[index]
      )),
  `${mode}: liquid identity atlas order changed (${JSON.stringify(atlas.cards.map(
    ({ code, material }) => ({ code, material }),
  ))})`);

  const semanticState = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const snapshot = audit.liquidIdentityGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    const inside = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    return cards.map((entry) => {
      let bodyExact = true;
      for (let y = entry.body.y; y < entry.body.y + entry.body.height; y++) {
        for (let x = entry.body.x; x < entry.body.x + entry.body.width; x++) {
          const empty = inside(x, y, entry.cavity) || inside(x, y, entry.openChimney);
          bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : entry.material);
        }
      }
      return {
        code: entry.code,
        material: entry.material,
        bodyExact,
        surfaceProbeExact: exactRect(entry.surfaceProbe, entry.material),
        coreProbeExact: exactRect(entry.coreProbe, entry.material),
        cavityEmpty: exactRect(entry.cavity, 0),
        chimneyEmpty: exactRect(entry.openChimney, 0),
        strandExact: exactRect(entry.strand, entry.material),
        isolated: audit.cell(entry.isolated.x, entry.isolated.y),
        guardedBlankEmpty: exactRect(entry.guardedBlank, 0),
        liquidOwnerExact: exactRect(entry.liquidContact.owner, entry.material),
        liquidUnlikeExact: exactRect(
          entry.liquidContact.unlike, entry.liquidContact.unlikeMaterial,
        ),
        liquidUnlikeMaterial: entry.liquidContact.unlikeMaterial,
        solidOwnerExact: exactRect(entry.solidContact.owner, entry.material),
        solidUnlikeExact: exactRect(
          entry.solidContact.unlike, entry.solidContact.unlikeMaterial,
        ),
        solidUnlikeMaterial: entry.solidContact.unlikeMaterial,
      };
    });
  })()`);
  assert(semanticState.every((entry) => entry.bodyExact && entry.surfaceProbeExact
      && entry.coreProbeExact && entry.cavityEmpty && entry.chimneyEmpty
      && entry.strandExact && entry.isolated === entry.material && entry.guardedBlankEmpty
      && entry.liquidOwnerExact && entry.liquidUnlikeExact && entry.liquidUnlikeMaterial === 2
      && entry.solidOwnerExact && entry.solidUnlikeExact && entry.solidUnlikeMaterial === 23),
  `${mode}: liquid identity fixture lost authored semantics (${JSON.stringify(semanticState)})`);
  stage('fixture-ready');

  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidIdentityStyling(false); true');
  const flat = await capture(`${mode} flat liquid-identity framebuffer`);
  const flatBacking = useEightXCapture ? undefined : await sampleLiquidIdentityBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidIdentityStyling(true); true');
  const styled = await capture(`${mode} styled liquid-identity framebuffer`);
  const styledBacking = useEightXCapture ? undefined : await sampleLiquidIdentityBackingTopology(cdp);
  await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.setLiquidIdentityStyling(false); true');
  const repeated = await capture(`${mode} repeated flat liquid-identity framebuffer`);
  const repeatedBacking = useEightXCapture ? undefined : await sampleLiquidIdentityBackingTopology(cdp);
  let backingResponses;
  if (!useEightXCapture) {
    for (const [state, backing] of [
      ['flat', flatBacking], ['styled', styledBacking], ['repeated-flat', repeatedBacking],
    ]) assertLiquidIdentityBackingTopology(backing, `${mode} ${state}`);

    assert(flatBacking.cards.every((card, index) => (
      card.alphaSignature === styledBacking.cards[index].alphaSignature
        && card.alphaSignature === repeatedBacking.cards[index].alphaSignature
        && card.supportSignature === styledBacking.cards[index].supportSignature
        && card.supportSignature === repeatedBacking.cards[index].supportSignature
    )), `${mode}: liquid identity styling changed backing alpha/support (${JSON.stringify({
      flat: compactLiquidIdentityTopology(flatBacking),
      styled: compactLiquidIdentityTopology(styledBacking),
      repeated: compactLiquidIdentityTopology(repeatedBacking),
    })})`);
    const contactLeaks = flatBacking.cards.flatMap((card, index) => {
      const changed = styledBacking.cards[index];
      const returned = repeatedBacking.cards[index];
      const leaks = [];
      if (!arraysEqual(card.liquidUnlikeRgb, changed.liquidUnlikeRgb)
        || !arraysEqual(card.liquidUnlikeRgb, returned.liquidUnlikeRgb)) leaks.push('Water');
      if (!arraysEqual(card.solidUnlikeRgb, changed.solidUnlikeRgb)
        || !arraysEqual(card.solidUnlikeRgb, returned.solidUnlikeRgb)) leaks.push('Metal');
      return leaks.map((control) => ({ code: card.code, control }));
    });
    assert(contactLeaks.length === 0,
      `${mode}: liquid identity styling leaked into contact controls (${JSON.stringify(contactLeaks)})`);

    backingResponses = summarizeLiquidIdentityBackingResponses(
      flatBacking, styledBacking, repeatedBacking,
    );
    assert(backingResponses.every(({ rgbRms, rgbPeak, repeatRgbPeak }) => (
      rgbRms >= 0.05 && rgbRms <= 12 && rgbPeak > 0 && rgbPeak <= 18 && repeatRgbPeak === 0
    )), `${mode}: liquid identity response is absent, unbounded, or non-repeatable (${JSON.stringify(backingResponses)})`);
    assert(backingResponses.every(({ responseProfile }) => (
      responseProfile.length === 16
        && Math.abs(responseProfile.reduce((sum, value) => sum + value, 0) - 1) <= 0.001
    )), `${mode}: liquid identity response profiles are not normalized 4x4 fields (${JSON.stringify(backingResponses)})`);
    assert(new Set(backingResponses.map(({ responseSignature }) => responseSignature)).size === 16,
      `${mode}: liquid identities do not have sixteen distinct backing responses (${JSON.stringify(backingResponses)})`);
  }

  const bodyRegions = atlas.cards.map((entry) => ({
    name: `liquid-identity-${entry.code}`,
    x: entry.body.x + entry.body.width / 2,
    y: entry.body.y + entry.body.height / 2,
    radiusX: entry.body.width / 2,
    radiusY: entry.body.height / 2,
    signature: true,
    silhouette: true,
    fastSupport: true,
  }));
  const atlasBounds = containingCellularRegion(atlas.cards.map(({ card }) => card));
  const responses = await sampleBackdropRefractionRegions(cdp, {
    straight: flat.capture.data,
    refracted: styled.capture.data,
    repeatedStraight: repeated.capture.data,
  }, [...bodyRegions, { name: 'liquid-identity-atlas', ...atlasBounds }], flat.canvasRect);
  const atlasResponse = responses.at(-1);
  assert(atlasResponse.repeatRgbPeak === 0,
    `${mode}: liquid identity flat→styled→flat framebuffer was not exact (${JSON.stringify(atlasResponse)})`);
  assert(responses.slice(0, 16).every((sample) => (
    sample.rgbRms > 0 && sample.rgbRms <= 12 && sample.rgbPeak > 0 && sample.rgbPeak <= 20
      && sample.repeatRgbPeak === 0
  )), `${mode}: a liquid identity has no bounded composed response (${JSON.stringify(responses.slice(0, 16))})`);
  const [flatSupport, styledSupport] = await Promise.all([
    samplePageRegions(
      cdp, flat.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
    samplePageRegions(
      cdp, styled.capture.data, bodyRegions,
      blank.capture.data, blank.reference.data, flat.canvasRect,
    ),
  ]);
  assert(flatSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0)
      && styledSupport.every((sample) => sample.visible > 0 && sample.worldArea > 0),
  `${mode}: a liquid identity body is not visible (${JSON.stringify({ flatSupport, styledSupport })})`);
  stage('responses-ready');

  const cardSignatures = atlas.cards.map((entry, index) => ({
    index: entry.index,
    material: entry.material,
    code: entry.code,
    flatSignature: flatSupport[index].signature,
    styledSignature: styledSupport[index].signature,
    flatVisible: flatSupport[index].visible,
    styledVisible: styledSupport[index].visible,
    rgbRms: responses[index].rgbRms,
    rgbPeak: responses[index].rgbPeak,
    responseSignature: responses[index].responseSignature,
    backingRgbRms: backingResponses?.[index]?.rgbRms,
    backingRgbPeak: backingResponses?.[index]?.rgbPeak,
    backingChangedSampleRatio: backingResponses?.[index]?.changedSampleRatio,
    backingRepeatRgbPeak: backingResponses?.[index]?.repeatRgbPeak,
    backingResponseSignature: backingResponses?.[index]?.responseSignature,
    backingResponseProfile: backingResponses?.[index]?.responseProfile,
  }));
  return {
    cards: cardSignatures.length,
    centralCavityCells: atlas.cards.length * 16,
    chimneyShaftCells: atlas.cards.reduce((sum, { openChimney }) => (
      sum + openChimney.height
    ), 0),
    strandCells: atlas.strands.length,
    isolatedControls: atlas.isolated.length,
    guardedBlanks: atlas.guardedBlanks.length,
    unlikeWaterContacts: atlas.liquidContacts.length,
    unlikeMetalContacts: atlas.solidContacts.length,
    exactRepeatedOff: atlasResponse.repeatRgbPeak === 0,
    cardSignatures,
  };
}

async function sampleLiquidIdentityBackingTopology(cdp) {
  return evaluate(cdp, `(() => {
    const world = document.querySelector('.world-canvas');
    if (!(world instanceof HTMLCanvasElement)) throw new Error('World canvas unavailable');
    const copy = document.createElement('canvas');
    copy.width = world.width;
    copy.height = world.height;
    const context = copy.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('Liquid identity backing sampler unavailable');
    context.drawImage(world, 0, 0);
    const pixels = context.getImageData(0, 0, copy.width, copy.height).data;
    const scaleX = copy.width / ${WORLD_WIDTH};
    const scaleY = copy.height / ${WORLD_HEIGHT};
    const cellAlpha = ({ x, y }) => {
      const left = Math.floor(x * scaleX);
      const top = Math.floor(y * scaleY);
      const right = Math.max(left + 1, Math.floor((x + 1) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((y + 1) * scaleY));
      let peak = 0;
      const values = [];
      for (let py = top; py < bottom; py++) for (let px = left; px < right; px++) {
        const alpha = pixels[(py * copy.width + px) * 4 + 3];
        peak = Math.max(peak, alpha);
        values.push(alpha);
      }
      return { peak, values };
    };
    const rectPoints = (rect) => {
      const points = [];
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) points.push({ x, y });
      }
      return points;
    };
    const sampleRect = (rect) => {
      const left = Math.floor(rect.x * scaleX);
      const top = Math.floor(rect.y * scaleY);
      const right = Math.max(left + 1, Math.floor((rect.x + rect.width) * scaleX));
      const bottom = Math.max(top + 1, Math.floor((rect.y + rect.height) * scaleY));
      const rgb = [];
      // Enumerate every backing sample, not only the centre of each world cell.
      // This makes toggle exactness and response bounds cover the actual 2x/4x/8x
      // presentation footprint with the same rigor as the alpha/support proof.
      for (let py = top; py < bottom; py++) {
        for (let px = left; px < right; px++) {
          const offset = (py * copy.width + px) * 4;
          rgb.push(pixels[offset], pixels[offset + 1], pixels[offset + 2]);
        }
      }
      return { width: right - left, height: bottom - top, rgb };
    };
    const snapshot = window.__ANIFOR_INPUT_AUDIT__.liquidIdentityGraphicsAtlas();
    const cards = Array.isArray(snapshot) ? snapshot : snapshot.cards;
    return {
      width: copy.width,
      height: copy.height,
      scaleX,
      scaleY,
      cards: cards.map((entry) => {
        const key = ({ x, y }) => x + ',' + y;
        const cavityPoints = rectPoints(entry.cavity);
        const centralCavity = rectPoints({
          x: entry.cavity.x + 1,
          y: entry.cavity.y + 1,
          width: entry.cavity.width - 2,
          height: entry.cavity.height - 2,
        });
        const chimneyPoints = rectPoints(entry.openChimney);
        const chimneyShaft = Array.from({ length: entry.openChimney.height }, (_, offset) => ({
          x: entry.openChimney.x + Math.floor(entry.openChimney.width / 2),
          y: entry.openChimney.y + offset,
        }));
        const emptyKeys = new Set([...cavityPoints, ...chimneyPoints].map(key));
        const bodyPoints = rectPoints(entry.body).filter((point) => !emptyKeys.has(key(point)));
        const strandPoints = rectPoints(entry.strand);
        const guardPoints = rectPoints(entry.guardedBlank);
        const liquidOwner = rectPoints(entry.liquidContact.owner);
        const liquidUnlike = rectPoints(entry.liquidContact.unlike);
        const solidOwner = rectPoints(entry.solidContact.owner);
        const solidUnlike = rectPoints(entry.solidContact.unlike);
        const signatureMap = new Map();
        for (const point of [
          ...rectPoints(entry.body), ...strandPoints, entry.isolated, ...guardPoints,
          ...liquidOwner, ...liquidUnlike, ...solidOwner, ...solidUnlike,
        ]) signatureMap.set(key(point), point);
        let alphaSignature = 2166136261;
        let supportSignature = 2166136261;
        for (const point of signatureMap.values()) {
          const alpha = cellAlpha(point);
          for (const value of alpha.values) {
            alphaSignature = Math.imul(alphaSignature ^ value, 16777619) >>> 0;
          }
          supportSignature = Math.imul(
            supportSignature ^ Number(alpha.peak > 0), 16777619,
          ) >>> 0;
        }
        return {
          index: entry.index,
          material: entry.material,
          code: entry.code,
          bodyExpected: bodyPoints.length,
          bodySupported: bodyPoints.filter((point) => cellAlpha(point).peak > 0).length,
          centralCavityExpected: centralCavity.length,
          centralCavityTransparent: centralCavity.filter(
            (point) => cellAlpha(point).peak === 0,
          ).length,
          chimneyShaftExpected: chimneyShaft.length,
          chimneyShaftTransparent: chimneyShaft.filter(
            (point) => cellAlpha(point).peak === 0,
          ).length,
          strandExpected: strandPoints.length,
          strandSupported: strandPoints.filter((point) => cellAlpha(point).peak > 0).length,
          isolatedAlphaPeak: cellAlpha(entry.isolated).peak,
          guardedBlankExpected: guardPoints.length,
          guardedBlankTransparent: guardPoints.filter(
            (point) => cellAlpha(point).peak === 0,
          ).length,
          liquidOwnerExpected: liquidOwner.length,
          liquidOwnerSupported: liquidOwner.filter((point) => cellAlpha(point).peak > 0).length,
          liquidUnlikeExpected: liquidUnlike.length,
          liquidUnlikeSupported: liquidUnlike.filter((point) => cellAlpha(point).peak > 0).length,
          solidOwnerExpected: solidOwner.length,
          solidOwnerSupported: solidOwner.filter((point) => cellAlpha(point).peak > 0).length,
          solidUnlikeExpected: solidUnlike.length,
          solidUnlikeSupported: solidUnlike.filter((point) => cellAlpha(point).peak > 0).length,
          alphaSignature,
          supportSignature,
          ...sampleRect(entry.body),
          liquidUnlikeRgb: sampleRect(entry.liquidContact.unlike).rgb,
          solidUnlikeRgb: sampleRect(entry.solidContact.unlike).rgb,
        };
      }),
    };
  })()`);
}

function assertLiquidIdentityBackingTopology(backing, label) {
  assert(Number.isInteger(backing.scaleX) && Number.isInteger(backing.scaleY)
      && backing.scaleX > 0 && backing.scaleY > 0,
  `${label}: backing does not preserve integral world scaling (${backing.scaleX}x${backing.scaleY})`);
  const valid = backing.cards.length === 16 && backing.cards.every((card) => (
    card.bodySupported === card.bodyExpected
    && card.centralCavityTransparent === card.centralCavityExpected
    && card.centralCavityExpected === 16
    // The closed inner endpoint may receive one antialiased contour cell. The
    // remaining centre shaft must stay fully transparent, preserving a visibly
    // continuous air path from the body's exterior.
    && card.chimneyShaftTransparent >= card.chimneyShaftExpected - 1
    && card.strandSupported === card.strandExpected
    && card.isolatedAlphaPeak > 0
    && card.guardedBlankTransparent === card.guardedBlankExpected
    && card.liquidOwnerSupported === card.liquidOwnerExpected
    && card.liquidUnlikeSupported === card.liquidUnlikeExpected
    && card.solidOwnerSupported === card.solidOwnerExpected
    && card.solidUnlikeSupported === card.solidUnlikeExpected
  ));
  assert(valid,
    `${label}: backing changed liquid topology (${JSON.stringify(compactLiquidIdentityTopology(backing))})`);
}

function compactLiquidIdentityTopology(backing) {
  return {
    scale: `${backing.scaleX}x${backing.scaleY}`,
    cards: backing.cards.map(({
      rgb: _rgb, liquidUnlikeRgb: _liquidUnlikeRgb, solidUnlikeRgb: _solidUnlikeRgb,
      width: _width, height: _height, ...card
    }) => card),
  };
}

function summarizeLiquidIdentityBackingResponses(flat, styled, repeated) {
  assert(flat.cards.length === 16 && styled.cards.length === 16 && repeated.cards.length === 16,
    'Liquid identity backing response atlas is incomplete');
  return flat.cards.map((base, cardIndex) => {
    const changed = styled.cards[cardIndex];
    const returned = repeated.cards[cardIndex];
    assert(changed.material === base.material && returned.material === base.material
        && changed.width === base.width && returned.width === base.width
        && changed.height === base.height && returned.height === base.height
        && changed.rgb.length === base.rgb.length && returned.rgb.length === base.rgb.length,
    `Liquid identity backing response geometry changed for ${base.code}`);
    let squared = 0;
    let rgbPeak = 0;
    let repeatRgbPeak = 0;
    let changedSamples = 0;
    let responseSignature = 2166136261;
    const buckets = new Float64Array(16);
    for (let offset = 0; offset < base.rgb.length; offset += 3) {
      const cell = offset / 3;
      const x = cell % base.width;
      const y = Math.floor(cell / base.width);
      const bucket = Math.min(3, Math.floor(y * 4 / base.height)) * 4
        + Math.min(3, Math.floor(x * 4 / base.width));
      let cellChanged = false;
      for (let channel = 0; channel < 3; channel++) {
        const delta = changed.rgb[offset + channel] - base.rgb[offset + channel];
        const repeat = returned.rgb[offset + channel] - base.rgb[offset + channel];
        squared += delta * delta;
        rgbPeak = Math.max(rgbPeak, Math.abs(delta));
        repeatRgbPeak = Math.max(repeatRgbPeak, Math.abs(repeat));
        buckets[bucket] += Math.abs(delta);
        cellChanged ||= delta !== 0;
        responseSignature = Math.imul(responseSignature ^ (delta + 255), 16777619) >>> 0;
      }
      changedSamples += Number(cellChanged);
    }
    const total = Math.max(1, buckets.reduce((sum, value) => sum + value, 0));
    return {
      material: base.material,
      code: base.code,
      rgbRms: round(Math.sqrt(squared / Math.max(1, base.rgb.length)), 4),
      rgbPeak,
      changedSampleRatio: round(changedSamples / Math.max(1, base.width * base.height), 5),
      repeatRgbPeak,
      responseSignature,
      responseProfile: Array.from(buckets, (value) => round(value / total, 5)),
    };
  });
}

function normalizeLiquidIdentityGraphicsAtlas(snapshot) {
  const cards = (Array.isArray(snapshot) ? snapshot : snapshot?.cards ?? []).map((entry) => ({
    ...entry,
    card: cellularRect(entry.card ?? entry),
    body: cellularRect(entry.body),
    surfaceProbe: cellularRect(entry.surfaceProbe),
    coreProbe: cellularRect(entry.coreProbe),
    cavity: cellularRect(entry.cavity),
    openChimney: cellularRect(entry.openChimney),
    strand: cellularRect(entry.strand),
    isolated: cellularPoint(entry.isolated),
    guardedBlank: cellularRect(entry.guardedBlank),
    liquidContact: {
      ...entry.liquidContact,
      owner: cellularRect(entry.liquidContact.owner),
      unlike: cellularRect(entry.liquidContact.unlike),
    },
    solidContact: {
      ...entry.solidContact,
      owner: cellularRect(entry.solidContact.owner),
      unlike: cellularRect(entry.solidContact.unlike),
    },
  }));
  return {
    cards,
    cavities: Array.isArray(snapshot)
      ? cards.flatMap(({ cavity }) => cellularRectPoints(cavity))
      : cellularPoints(snapshot?.cavities),
    openChimneys: Array.isArray(snapshot)
      ? cards.flatMap(({ openChimney }) => cellularRectPoints(openChimney))
      : cellularPoints(snapshot?.openChimneys),
    strands: Array.isArray(snapshot)
      ? cards.flatMap(({ strand }) => cellularRectPoints(strand))
      : cellularPoints(snapshot?.strands),
    isolated: cellularPoints(
      Array.isArray(snapshot) ? cards.map(({ isolated }) => isolated) : snapshot?.isolated,
    ),
    guardedBlanks: Array.isArray(snapshot)
      ? cards.map(({ guardedBlank }) => guardedBlank)
      : (snapshot?.guardedBlanks ?? []).map(cellularRect),
    liquidContacts: Array.isArray(snapshot)
      ? cards.map(({ liquidContact }) => liquidContact) : snapshot?.liquidContacts ?? [],
    solidContacts: Array.isArray(snapshot)
      ? cards.map(({ solidContact }) => solidContact) : snapshot?.solidContacts ?? [],
  };
}

