function assertRoleGraphicsSamples(samples, label) {
  const byName = Object.fromEntries(samples.map((sample) => [sample.name, sample]));
  for (const name of [
    'converter', 'cloneEmitter', 'poweredCloneEmitter',
    'portalSinkChannel', 'acceleratorForce',
  ]) {
    assert(byName[name].rgbRms >= 0.35 && byName[name].rgbPeak <= 32,
      `${label}: ${name} lost bounded fit-view role structure (${JSON.stringify(samples)})`);
  }
  assert(byName.cloneEmitter.responseRgb[0] > byName.cloneEmitter.responseRgb[2] + 0.2
    && byName.poweredCloneEmitter.responseRgb[0]
      > byName.poweredCloneEmitter.responseRgb[2] + 0.2,
  `${label}: emitter roles lost warm outward identity (${JSON.stringify(samples)})`);
  assert(byName.portalSinkChannel.responseRgb[2]
      > byName.portalSinkChannel.responseRgb[0] + 0.2,
  `${label}: sink/channel role lost cool inward identity (${JSON.stringify(samples)})`);
  assert(byName.acceleratorForce.responseRgb[2]
      > byName.acceleratorForce.responseRgb[0] + 0.2,
  `${label}: force role lost cool ring identity (${JSON.stringify(samples)})`);
  assert(byName.converter.responseRgb[0] >= 0.2 && byName.converter.responseRgb[2] >= 0.2,
    `${label}: converter lost composed emitter/sink identity (${JSON.stringify(samples)})`);
  assert(byName.deviceControl.rgbPeak <= 1,
    `${label}: role styling leaked into neutral device control (${JSON.stringify(samples)})`);
  assert(samples.every((sample) => sample.repeatRgbPeak <= 1),
    `${label}: semantic role off-on-off sequence was not deterministic (${JSON.stringify(samples)})`);
  assert(byName.emitterCore.rgbRms >= byName.emitterBackground.rgbRms + 0.5
    && byName.emitterRing.rgbRms >= byName.emitterBackground.rgbRms + 0.5,
  `${label}: emitter core/annulus geometry collapsed (${JSON.stringify(samples)})`);
  assert(byName.channelNode.rgbRms >= byName.channelRail.rgbRms + 0.2
    && byName.channelRail.rgbRms >= byName.channelOffRail.rgbRms + 0.5,
  `${label}: channel node/rail geometry collapsed (${JSON.stringify(samples)})`);
  assert(byName.forceInnerRing.rgbRms >= byName.forceGap.rgbRms + 0.5
    && byName.forceOuterRing.rgbRms >= byName.forceGap.rgbRms + 0.5,
  `${label}: force ring geometry collapsed (${JSON.stringify(samples)})`);
}

function assertPairedRoleGraphics(results) {
  const canvas = results.find((result) => result.backend === 'canvas2d')?.roleGraphicsSamples;
  const webgl = results.find((result) => result.backend === 'webgl')?.roleGraphicsSamples;
  if (!canvas || !webgl) return;
  for (const name of [
    'converter', 'cloneEmitter', 'poweredCloneEmitter',
    'portalSinkChannel', 'acceleratorForce',
  ]) {
    const canvasSample = canvas.find((sample) => sample.name === name);
    const webglSample = webgl.find((sample) => sample.name === name);
    assert(canvasSample && webglSample, `paired semantic-role sample missing ${name}`);
    const ratio = canvasSample.rgbRms / Math.max(0.05, webglSample.rgbRms);
    assert(ratio >= 0.25 && ratio <= 4.0,
      `Canvas/WebGL ${name} role response diverged (${canvasSample.rgbRms}/${webglSample.rgbRms})`);
  }
  for (const names of [
    ['emitterCore', 'emitterRing', 'emitterBackground'],
    ['channelNode', 'channelRail', 'channelOffRail'],
    ['forceInnerRing', 'forceOuterRing', 'forceGap'],
  ]) {
    const normalized = (samples) => {
      const values = names.map((name) => samples.find((sample) => sample.name === name)?.rgbRms ?? 0);
      const sum = Math.max(0.01, values.reduce((total, value) => total + value, 0));
      return values.map((value) => value / sum);
    };
    const canvasSignature = normalized(canvas);
    const webglSignature = normalized(webgl);
    const maximumDistance = Math.max(...canvasSignature.map(
      (value, index) => Math.abs(value - webglSignature[index]),
    ));
    assert(maximumDistance <= 0.20,
      `Canvas/WebGL ${names.join('/')} spatial signature diverged (${canvasSignature}/${webglSignature})`);
  }
}

function assertPairedCellularGraphics(results) {
  const canvas = results.find((result) => result.backend === 'canvas2d')?.cellularGraphics;
  const webgl = results.find((result) => result.backend === 'webgl')?.cellularGraphics;
  if (!canvas || !webgl) return;
  assert(canvas.cards === 24 && webgl.cards === 24,
    `paired cellular graphics atlas is incomplete (${canvas.cards}/${webgl.cards})`);
  for (const result of [canvas, webgl]) {
    assert(new Set(result.cardSignatures.map(
      ({ backingResponseSignature }) => backingResponseSignature,
    )).size === 24,
      `cellular motif responses are not distinct in all 24 cards (${JSON.stringify(result.cardSignatures)})`);
    const byPreset = new Map(result.cardSignatures.map((entry) => [entry.preset, entry]));
    for (const [left, right] of [[1, 19], [3, 23]]) {
      assert(byPreset.get(left)?.backingResponseSignature
          !== byPreset.get(right)?.backingResponseSignature,
        `same-palette LIFE presets ${left}/${right} lost distinct motif responses`);
    }
    assert(result.cardSignatures.every(({ backingRepeatRgbPeak }) => backingRepeatRgbPeak === 0),
      `cellular backing off→on→off sequence was not exact (${JSON.stringify(result.cardSignatures)})`);
  }
  const webglByPreset = new Map(webgl.cardSignatures.map((entry) => [entry.preset, entry]));
  for (const canvasEntry of canvas.cardSignatures) {
    const webglEntry = webglByPreset.get(canvasEntry.preset);
    assert(webglEntry && webglEntry.material === canvasEntry.material,
      `paired cellular projection missing preset ${canvasEntry.preset}`);
    assert(Number.isInteger(canvasEntry.flatSignature)
        && Number.isInteger(canvasEntry.styledSignature)
        && Number.isInteger(webglEntry.flatSignature)
        && Number.isInteger(webglEntry.styledSignature)
        && Number.isInteger(canvasEntry.responseSignature)
        && Number.isInteger(webglEntry.responseSignature),
    `paired cellular signatures missing preset ${canvasEntry.preset}`);
    const responseRatio = canvasEntry.backingRgbRms
      / Math.max(0.01, webglEntry.backingRgbRms);
    // Canvas styles in display-byte space while WebGL applies the same bounded
    // motif before its linear-to-display transfer. Compare a broad bounded
    // amplitude here and use the normalized spatial profile below for shape.
    assert(responseRatio >= 0.50 && responseRatio <= 2.0,
      `Canvas/WebGL LIFE preset ${canvasEntry.preset} backing response diverged (${canvasEntry.backingRgbRms}/${webglEntry.backingRgbRms})`);
    const profileDistance = Math.max(...canvasEntry.backingResponseProfile.map(
      (value, index) => Math.abs(value - webglEntry.backingResponseProfile[index]),
    ));
    assert(profileDistance <= 0.12,
      `Canvas/WebGL LIFE preset ${canvasEntry.preset} spatial response diverged (${profileDistance})`);
  }
}

function assertPairedSensorGraphics(results) {
  const canvas = results.find((result) => result.backend === 'canvas2d')?.sensorGraphics;
  const webgl = results.find((result) => result.backend === 'webgl')?.sensorGraphics;
  if (!canvas || !webgl) return;
  assert(canvas.cards === 7 && webgl.cards === 7,
    `paired sensor graphics atlas is incomplete (${canvas.cards}/${webgl.cards})`);
  for (const result of [canvas, webgl]) {
    assert(new Set(result.cardSignatures.map(
      ({ backingResponseSignature }) => backingResponseSignature,
    )).size === 7,
    `sensor motif responses are not distinct in all seven cards (${JSON.stringify(result.cardSignatures)})`);
    assert(result.cardSignatures.every(({ backingRepeatRgbPeak }) => backingRepeatRgbPeak === 0),
      `sensor backing off→on→off sequence was not exact (${JSON.stringify(result.cardSignatures)})`);
  }
  const webglByMaterial = new Map(webgl.cardSignatures.map((entry) => [entry.material, entry]));
  for (const canvasEntry of canvas.cardSignatures) {
    const webglEntry = webglByMaterial.get(canvasEntry.material);
    assert(webglEntry && webglEntry.code === canvasEntry.code,
      `paired sensor projection missing ${canvasEntry.code}/${canvasEntry.material}`);
    assert(Number.isInteger(canvasEntry.flatSignature)
        && Number.isInteger(canvasEntry.styledSignature)
        && Number.isInteger(webglEntry.flatSignature)
        && Number.isInteger(webglEntry.styledSignature)
        && Number.isInteger(canvasEntry.responseSignature)
        && Number.isInteger(webglEntry.responseSignature),
    `paired sensor signatures missing ${canvasEntry.code}`);
    const responseRatio = canvasEntry.backingRgbRms
      / Math.max(0.01, webglEntry.backingRgbRms);
    // Canvas applies the morphology in display-byte space while WebGL applies
    // it before transfer to display bytes. Keep amplitude broad, and use the
    // normalized 4x4 response profile below as the morphology parity proof.
    assert(responseRatio >= 0.20 && responseRatio <= 5.0,
      `Canvas/WebGL sensor ${canvasEntry.code} backing response diverged (${canvasEntry.backingRgbRms}/${webglEntry.backingRgbRms})`);
    const profileDistance = Math.max(...canvasEntry.backingResponseProfile.map(
      (value, index) => Math.abs(value - webglEntry.backingResponseProfile[index]),
    ));
    assert(profileDistance <= 0.12,
      `Canvas/WebGL sensor ${canvasEntry.code} spatial response diverged (${profileDistance})`);
  }
}

