// E67 is authored before HDR bloom, so a directly guarded Fire/contact or
// Fire/wall pixel can still receive a few final-composite bytes from a nearby
// eligible body pixel. Keep that optical spill explicit and tightly bounded;
// disjoint owners, sparse Fire, alpha/support, and repeated-off captures stay
// byte-exact.
const FIRE_FLAME_COMPOSITE_SPILL_PEAK = 8;
const FIRE_FLAME_TOPOLOGY_BLOOM_PEAK = 3;

/**
 * E67 measures exact-Fire thermal depth and upward-flow flame shaping while
 * preserving one byte-identical semantic scene in still and moving forms.
 */
async function auditFireFlameVfxExperiment(cdp, mode, dpr) {
  const requestedScale = renderScaleArgument === undefined
    ? undefined : Number(renderScaleArgument);
  const requestedScales = requestedScale === undefined
    ? VOLUME_VFX_SCALES : requestedScale < 8 ? [requestedScale] : [];
  const scales = [];
  for (const scale of requestedScales) {
    const movingOff = await navigateFireFlameVfxState(cdp, mode, scale, 'moving', false, 'movingOff');
    const movingOn = await navigateFireFlameVfxState(cdp, mode, scale, 'moving', true, 'movingOn');
    const movingRepeat = await navigateFireFlameVfxState(cdp, mode, scale, 'moving', false, 'movingRepeat');
    const stillOff = await navigateFireFlameVfxState(cdp, mode, scale, 'still', false, 'stillOff');
    const stillOn = await navigateFireFlameVfxState(cdp, mode, scale, 'still', true, 'stillOn');
    const stillRepeat = await navigateFireFlameVfxState(cdp, mode, scale, 'still', false, 'stillRepeat');
    const variants = { movingOff, movingOn, movingRepeat, stillOff, stillOn, stillRepeat };
    // Persist visual evidence before numerical assertions so a failed
    // calibration run still leaves inspectable off/on/repeat captures.
    const screenshots = screenshotRequest
      ? await writeFireFlameVfxScreenshots(screenshotRequest, scale, variants)
      : undefined;
    const fixture = movingOff.fixture;
    assert(Object.values(variants).every((variant) =>
      JSON.stringify(variant.fixture) === JSON.stringify(fixture)),
    `E67 ${scale}x fixture metadata changed`);

    for (const [label, variant] of Object.entries(variants)) {
      const enabled = label === 'movingOn' || label === 'stillOn';
      assertGeometry(variant.geometry, `E67 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E67 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline?.fireFlameVfx === (enabled ? 'active' : 'inactive')
        && variant.hdrPipeline?.volumeVfx === 'inactive'
        && variant.hdrPipeline?.liquidBodyVfx === 'inactive'
        && variant.hdrPipeline?.liquidSurfaceVfx === 'inactive'
        && variant.hdrPipeline?.waterCurvatureVfx === 'inactive'
        && variant.hdrPipeline?.gasBodyVfx === 'inactive'
        && variant.hdrPipeline?.gasMotionVfx === 'inactive'
        && variant.hdrPipeline?.powderBodyVfx === 'inactive'
        && variant.hdrPipeline?.powderLightVfx === 'inactive',
      `E67 ${label} ${scale}x selector state resolved incorrectly (${JSON.stringify(
        variant.hdrPipeline,
      )})`);
      assertFireFlameFixtureState(
        variant.fixtureState, fixture, label.startsWith('moving') ? 'moving' : 'still',
        `E67 ${label} ${scale}x`,
      );
    }

    for (const [leftName, rightName] of [
      ['movingOff', 'movingOn'], ['movingOff', 'movingRepeat'],
      ['stillOff', 'stillOn'], ['stillOff', 'stillRepeat'], ['movingOff', 'stillOff'],
    ]) {
      const left = variants[leftName];
      const right = variants[rightName];
      assertCanvasRectsEqual(left.geometry.canvas, right.geometry.canvas,
        `E67 ${scale}x ${leftName}/${rightName} CSS geometry`);
      assert(JSON.stringify(left.geometry.backing) === JSON.stringify(right.geometry.backing),
        `E67 ${scale}x ${leftName}/${rightName} backing geometry changed`);
      assertHdrVfxSemanticEquality(left.semantic, right.semantic,
        `E67 ${scale}x ${leftName}/${rightName}`);
      assert(left.fixtureState.materialHash === right.fixtureState.materialHash
        && left.fixtureState.temperatureHash === right.fixtureState.temperatureHash
        && left.fixtureState.wallHash === right.fixtureState.wallHash
        && JSON.stringify(left.fixtureState.materialCounts)
          === JSON.stringify(right.fixtureState.materialCounts)
        && JSON.stringify(left.fixtureState.temperatureCounts)
          === JSON.stringify(right.fixtureState.temperatureCounts),
      `E67 ${scale}x ${leftName}/${rightName} changed material/temperature/wall state (${JSON.stringify({
        left: left.fixtureState, right: right.fixtureState,
      })})`);
      const sameVelocityPlane = leftName.startsWith('moving') === rightName.startsWith('moving');
      if (sameVelocityPlane) {
        assertVolumeVfxBackingInvariant(left.backing, right.backing,
          `E67 ${scale}x ${leftName}/${rightName}`);
        assertVolumeVfxRawAlphaInvariant(left.rawControls, right.rawControls,
          `E67 ${scale}x ${leftName}/${rightName}`);
        assert(left.fixtureState.velocityHash === right.fixtureState.velocityHash
          && left.fixtureState.renderedVelocityHash === right.fixtureState.renderedVelocityHash,
        `E67 ${scale}x ${leftName}/${rightName} changed packed velocity bytes`);
      } else {
        // Native velocity already participates in the generic Energy carrier's
        // subpixel alpha before E67. Across the deliberately different still
        // and moving fixtures require identical support/topology, not an
        // invented equality of their baseline fractional alpha.
        assert(left.backing.width === right.backing.width
          && left.backing.height === right.backing.height
          && left.backing.supportSignature === right.backing.supportSignature
          && left.backing.supported === right.backing.supported,
        `E67 ${scale}x still/moving velocity changed framebuffer support (${JSON.stringify({
          left: left.backing, right: right.backing,
        })})`);
      }
    }
    assert(movingOff.fixtureState.velocityHash === fixture.expected.movingVelocityHash
      && stillOff.fixtureState.velocityHash === fixture.expected.stillVelocityHash
      && movingOff.fixtureState.velocityHash !== stillOff.fixtureState.velocityHash
      && movingOff.fixtureState.nonzeroVelocityCells === fixture.expected.movingVelocityCells
      && stillOff.fixtureState.nonzeroVelocityCells === 0,
    `E67 ${scale}x still/moving fixture did not isolate Fire velocity (${JSON.stringify({
      moving: movingOff.fixtureState, still: stillOff.fixtureState,
    })})`);
    assert(movingOff.capture.capture.data === movingRepeat.capture.capture.data,
      `E67 ${scale}x moving repeated-off full framebuffer was not byte-exact`);
    assert(stillOff.capture.capture.data === stillRepeat.capture.capture.data,
      `E67 ${scale}x still repeated-off full framebuffer was not byte-exact`);
    assertFireFlameRawControlInvariant(movingOff.rawControls, movingOn.rawControls,
      `E67 ${scale}x moving protected controls`);
    assertVolumeVfxRawControlInvariant(movingOff.rawControls, movingRepeat.rawControls,
      `E67 ${scale}x moving repeated controls`);
    assertFireFlameRawControlInvariant(stillOff.rawControls, stillOn.rawControls,
      `E67 ${scale}x still protected controls`);
    assertVolumeVfxRawControlInvariant(stillOff.rawControls, stillRepeat.rawControls,
      `E67 ${scale}x still repeated controls`);

    const regions = fireFlameVfxRegions(fixture);
    const compare = async (off, on, repeat, phase) => {
      const raw = await sampleBackdropRefractionRegions(cdp, {
        straight: off.capture.capture.data,
        refracted: on.capture.capture.data,
        repeatedStraight: repeat.capture.capture.data,
      }, regions, off.capture.canvasRect);
      const responses = raw.map((sample, index) => {
        const meanRgbRms = Math.hypot(...sample.responseRgb) / Math.sqrt(3);
        return {
          ...sample, ...regions[index], phase,
          spatialRgbRms: round(Math.sqrt(Math.max(0,
            sample.rgbRms ** 2 - meanRgbRms ** 2)), 3),
        };
      });
      const targets = responses.filter((sample) => sample.role === 'target');
      const controls = responses.filter((sample) => sample.role === 'control');
      const compositeSpillControls = responses.filter((sample) => sample.role === 'composite-spill');
      const references = responses.filter((sample) => sample.role === 'reference');
      const topologyControls = responses.filter((sample) => sample.role === 'topology');
      const inRange = (value, bounds) => value >= bounds[0] && value <= bounds[1];
      const targetByName = Object.fromEntries(targets.map((sample) => [sample.name, sample]));
      const targetNames = ['hotCore', 'coolPocket', 'velocityTongue'];
      assert(targetNames.every((name) => {
        const sample = targetByName[name];
        const envelopeName = name === 'velocityTongue' ? `${phase}Tongue` : name;
        const bounds = FIRE_FLAME_VFX_TARGET_ENVELOPES[scale]?.[envelopeName];
        // The HDR shoulder can trade a little saturated red for green/blue as
        // a hot orange body approaches yellow-white. Require positive total
        // exposure and both whitening channels rather than misclassifying that
        // useful chroma shift as a darkening response. The cool pocket remains
        // strictly absorptive in every channel.
        const signedChannels = name === 'coolPocket'
          ? sample?.responseRgb.every((value) => value < 0)
          : sample?.signedMean > 0 && sample?.responseRgb[1] > 0
            && sample?.responseRgb[2] > 0 && sample?.responseRgb[0] > -12;
        return sample && bounds && signedChannels
          && inRange(sample.rgbRms, bounds.rgb)
          && inRange(sample.spatialRgbRms, bounds.spatial)
          && inRange(sample.rgbPeak, bounds.peak)
          && inRange(sample.coverage, bounds.coverage)
          && inRange(sample.signedMean, bounds.signed)
          && inRange(sample.responseMicroContrast, bounds.micro)
          && sample.responseRgb.every((value, index) => inRange(value, bounds.channels[index]))
          && sample.repeatRgbPeak === 0;
      }), `E67 ${scale}x ${phase} response escaped calibrated target ranges (${JSON.stringify(
        targets,
      )})`);
      if (phase === 'still') {
        const tongue = targetByName.velocityTongue;
        assert(tongue && tongue.repeatRgbPeak === 0,
          `E67 ${scale}x still tongue was not repeat-stable (${JSON.stringify(tongue)})`);
      }
      assert(controls.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
        `E67 ${scale}x ${phase} escaped an exact control (${JSON.stringify(controls)})`);
      assert(compositeSpillControls.every((sample) =>
        sample.rgbPeak <= FIRE_FLAME_COMPOSITE_SPILL_PEAK && sample.repeatRgbPeak === 0),
      `E67 ${scale}x ${phase} exceeded bounded HDR contact/wall spill (${JSON.stringify(
        compositeSpillControls,
      )})`);
      assert(references.every((sample) => sample.repeatRgbPeak === 0),
        `E67 ${scale}x ${phase} thermal/velocity references were not repeat-stable (${JSON.stringify(
          references,
        )})`);
      // Transparent authored voids keep zero semantic support, but the normal
      // HDR compositor may cast a tiny optical bloom into that empty page
      // footprint. Bound it independently from material/contact spill so an
      // accidental body fill or broad glow cannot hide behind repeatability.
      assert(topologyControls.every((sample) =>
        sample.rgbPeak <= FIRE_FLAME_TOPOLOGY_BLOOM_PEAK && sample.repeatRgbPeak === 0),
      `E67 ${scale}x ${phase} topology controls exceeded bounded void bloom (${JSON.stringify(
          topologyControls,
        )})`);
      return { targets, references, protectedControls: controls.length,
        boundedCompositeSpill: {
          controls: compositeSpillControls.length,
          peak: Math.max(0, ...compositeSpillControls.map((sample) => sample.rgbPeak)),
          repeatPeak: Math.max(0, ...compositeSpillControls.map((sample) => sample.repeatRgbPeak)),
        },
        boundedTopologyBloom: {
          controls: topologyControls.length,
          peak: Math.max(0, ...topologyControls.map((sample) => sample.rgbPeak)),
          repeatPeak: Math.max(0, ...topologyControls.map((sample) => sample.repeatRgbPeak)),
        } };
    };
    const moving = await compare(movingOff, movingOn, movingRepeat, 'moving');
    const still = await compare(stillOff, stillOn, stillRepeat, 'still');
    const movingTongue = moving.targets.find((target) => target.name === 'velocityTongue');
    const stillTongue = still.targets.find((target) => target.name === 'velocityTongue');
    assert(movingTongue.rgbRms >= stillTongue.rgbRms + 0.05
      && movingTongue.signedMean >= stillTongue.signedMean + 0.01,
    `E67 ${scale}x upward velocity did not strengthen its tongue (${JSON.stringify({
      moving: movingTongue, still: stillTongue,
    })})`);
    scales.push({
      scale, backing: movingOff.geometry.backing, alphaSupport: movingOff.backing,
      fixtureState: movingOff.fixtureState, moving, still,
      ...(screenshots ? { screenshots } : {}),
    });
  }

  let crossScale;
  if (scales.length === VOLUME_VFX_SCALES.length
    && scales.every(({ scale }, index) => scale === VOLUME_VFX_SCALES[index])) {
    const responseByName = (phase, name) => scales.map(({ [phase]: response }) =>
      response.targets.find((target) => target.name === name));
    const spread = (samples, read) => Math.max(...samples.map(read)) - Math.min(...samples.map(read));
    crossScale = Object.fromEntries([
      ...['moving', 'still'].flatMap((phase) => ['hotCore', 'coolPocket'].map((name) => [phase, name])),
      ['moving', 'velocityTongue'], ['still', 'velocityTongue'],
    ].map(([phase, name]) => {
      const samples = responseByName(phase, name);
      return [`${phase}:${name}`, {
        rgbRms: round(spread(samples, (sample) => sample.rgbRms), 3),
        spatialRgbRms: round(spread(samples, (sample) => sample.spatialRgbRms), 3),
        coverage: round(spread(samples, (sample) => sample.coverage), 3),
        signedMean: round(spread(samples, (sample) => sample.signedMean), 3),
        microContrast: round(spread(samples, (sample) => sample.responseMicroContrast), 3),
        peak: spread(samples, (sample) => sample.rgbPeak),
      }];
    }));
    assert(Object.values(crossScale).every((entry) => entry.rgbRms <= 0.15
      && entry.spatialRgbRms <= 0.20 && entry.coverage <= 0.06
      && entry.signedMean <= 0.12 && entry.microContrast <= 0.12 && entry.peak <= 2),
    `E67 response drifted across 1x/2x/4x (${JSON.stringify(crossScale)})`);
  }
  const trueEightX = renderScaleArgument === undefined || renderScaleArgument === '8'
    ? await auditEightXFireFlameVfxExclusion(cdp, dpr)
    : undefined;
  return { scales, calibratedEnvelopes: true,
    ...(crossScale ? { crossScale } : {}), ...(trueEightX ? { trueEightX } : {}) };
}

async function writeFireFlameVfxScreenshots(source, scale, variants) {
  const paths = {};
  for (const [variant, capture] of Object.entries(variants)) {
    paths[variant] = variantScreenshotPath(source, `fire-flame-${scale}x-${variant}`);
    await writeFile(paths[variant], Buffer.from(capture.capture.capture.data, 'base64'));
  }
  return paths;
}

function fireFlameVfxRegions(fixture) {
  const centre = (rect) => ({ x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 });
  const point = (name, entry, extra = {}) => ({
    name, x: entry.x, y: entry.y, radius: 0.35, role: 'control', ...extra,
  });
  const { body } = fixture;
  return [
    { name: 'hotCore', role: 'target', ...rectRegion(body.hotCore) },
    { name: 'coolPocket', role: 'target', ...rectRegion(body.coolPocket) },
    { name: 'velocityTongue', role: 'target',
      x: body.velocityTongue.x + body.velocityTongue.width / 2,
      y: body.velocityTongue.y + body.velocityTongue.height / 2,
      radiusX: 14, radiusY: 14 },
    { name: 'straightNeutral', role: 'reference', ...rectRegion(body.straightNeutral) },
    { name: 'baseFire', role: 'reference', x: body.base.x + 14,
      y: body.base.y + body.base.height - 14, radiusX: 8, radiusY: 8 },
    point('thinFireStrand', centre(fixture.sparse.strand)),
    point('isolatedFire', fixture.sparse.isolated),
    ...Object.entries(fixture.protectedControls).map(([name, control]) =>
      point(name, control.probe)),
    ...Object.entries(fixture.contacts).flatMap(([name, contact]) => [
      point(`${name}Fire`, contact.fireProbe, { role: 'composite-spill' }),
      point(`${name}Other`, contact.otherProbe, { role: 'composite-spill' }),
    ]),
    point('nativeWall', fixture.wallCoexistence.wallProbe, { role: 'composite-spill' }),
    point('wallClear', fixture.wallCoexistence.clearProbe, { role: 'reference' }),
    point('authoredHole', centre(body.authoredHole), { role: 'topology' }),
    point('openChannel', centre(body.openChannel), { role: 'topology' }),
    point('guardedBlank', centre(fixture.guardedBlank)),
  ];
}

function fireFlameRawControlPoints(fixture) {
  return fireFlameVfxRegions(fixture)
    .filter(({ role }) => role === 'control' || role === 'composite-spill')
    .map(({ name, x, y }) => ({ name, x: Math.floor(x), y: Math.floor(y) }));
}

function assertFireFlameFixtureState(state, fixture, mode, label) {
  const expectedVelocityHash = mode === 'moving'
    ? fixture.expected.movingVelocityHash : fixture.expected.stillVelocityHash;
  assert(state.mode === mode
    && state.mainBodyFireCells === fixture.expected.mainBodyFireCells
    && state.materialCounts.fire === fixture.expected.fireCells
    && state.materialCounts.energy === fixture.expected.energyCells
    && state.materialCounts.plasma === fixture.expected.plasmaCells
    && state.materialCounts.lava === fixture.expected.lavaCells
    && state.materialCounts.smoke === fixture.expected.smokeCells
    && state.materialCounts.metal === fixture.expected.metalCells
    && state.wallCells === fixture.expected.wallCells
    && state.nonzeroVelocityCells === (mode === 'moving' ? fixture.expected.movingVelocityCells : 0)
    && JSON.stringify(state.temperatureCounts) === JSON.stringify(fixture.expected.temperatureCounts)
    && state.materialHash === fixture.expected.materialHash
    && state.temperatureHash === fixture.expected.temperatureHash
    && state.wallHash === fixture.expected.wallHash
    && state.velocityHash === expectedVelocityHash
    && state.renderedVelocityHash === expectedVelocityHash
    && state.velocityStagingMismatches === 0 && state.velocityOwnershipExact
    && state.wallFireCoexistence && state.wallPatternExact
    && state.authoredVoidsExact && state.sparseExact && state.protectedControlsExact
    && state.contactsExact && state.guardedBlankExact,
  `${label}: fixture state was not exact (${JSON.stringify(state)})`);
}

async function sampleFireFlameVfxFixtureState(cdp, mode) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit?.temperature !== 'function' || typeof audit?.velocity !== 'function'
      || typeof audit?.renderedVelocity !== 'function' || typeof audit?.wall !== 'function'
      || typeof audit?.fireFlameVfxFixture !== 'function') {
      throw new Error('E67 material/temperature/wall/velocity audit API unavailable');
    }
    const fixture = audit.fireFlameVfxFixture();
    const inRect = (x, y, rect) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const hashByte = (hash, value) => Math.imul(hash ^ (value & 255), 16777619) >>> 0;
    let materialHash = 2166136261, temperatureHash = 2166136261, wallHash = 2166136261;
    let velocityHash = 2166136261, renderedVelocityHash = 2166136261;
    let mainBodyFireCells = 0, wallCells = 0, nonzeroVelocityCells = 0;
    let velocityStagingMismatches = 0, velocityOwnershipExact = true;
    let wallFireCoexistence = true, wallPatternExact = true;
    const materialCounts = { fire: 0, energy: 0, plasma: 0, lava: 0, smoke: 0, metal: 0 };
    const temperatures = new Map();
    for (let y = 0; y < ${WORLD_HEIGHT}; y++) for (let x = 0; x < ${WORLD_WIDTH}; x++) {
      const material = audit.cell(x, y), temperature = audit.temperature(x, y), wall = audit.wall(x, y);
      const velocity = audit.velocity(x, y), rendered = audit.renderedVelocity(x, y);
      materialHash = hashByte(materialHash, material);
      temperatureHash = hashByte(temperatureHash, temperature);
      temperatureHash = hashByte(temperatureHash, temperature >>> 8);
      wallHash = hashByte(wallHash, wall);
      velocityHash = hashByte(hashByte(velocityHash, velocity[0]), velocity[1]);
      renderedVelocityHash = hashByte(hashByte(renderedVelocityHash, rendered[0]), rendered[1]);
      temperatures.set(temperature, (temperatures.get(temperature) ?? 0) + 1);
      mainBodyFireCells += Number(inRect(x, y, fixture.body.bounds) && material === fixture.material);
      materialCounts.fire += Number(material === fixture.material);
      materialCounts.energy += Number(material === fixture.protectedControls.energy.material);
      materialCounts.plasma += Number(material === fixture.protectedControls.plasma.material);
      materialCounts.lava += Number(material === fixture.protectedControls.lava.material);
      materialCounts.smoke += Number(material === fixture.protectedControls.smoke.material);
      materialCounts.metal += Number(material === fixture.contacts.fireMetal.otherMaterial);
      wallCells += Number(wall !== 0);
      nonzeroVelocityCells += Number(velocity[0] !== 0 || velocity[1] !== 0);
      velocityStagingMismatches += Number(
        velocity[0] !== rendered[0] || velocity[1] !== rendered[1]
      );
      const velocityOwned = ${JSON.stringify(mode)} === 'moving'
        && material === fixture.material && inRect(x, y, fixture.body.velocityTongue);
      const expectedX = velocityOwned ? fixture.body.velocityTongue.velocity.x : 0;
      const expectedY = velocityOwned ? fixture.body.velocityTongue.velocity.y : 0;
      velocityOwnershipExact = velocityOwnershipExact
        && velocity[0] === expectedX && velocity[1] === expectedY
        && rendered[0] === expectedX && rendered[1] === expectedY;
      if (wall !== 0) wallFireCoexistence = wallFireCoexistence && material === fixture.material;
      if (inRect(x, y, fixture.wallCoexistence.region)) {
        const blockX = Math.floor((x - fixture.wallCoexistence.region.x) / fixture.wallCoexistence.blockSize);
        const blockY = Math.floor((y - fixture.wallCoexistence.region.y) / fixture.wallCoexistence.blockSize);
        const expectedWall = (blockX + blockY) % 2 === fixture.wallCoexistence.occupiedParity
          ? fixture.conductiveWall : 0;
        wallPatternExact = wallPatternExact && wall === expectedWall;
      }
    }
    const emptyRect = (rect) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (audit.cell(x, y) !== 0) return false;
      }
      return true;
    };
    const authoredVoidsExact = emptyRect(fixture.body.authoredHole)
      && emptyRect(fixture.body.openChannel);
    const sparseExact = audit.cell(fixture.sparse.strand.x, fixture.sparse.strand.y) === fixture.material
      && audit.cell(fixture.sparse.isolated.x, fixture.sparse.isolated.y) === fixture.material;
    const protectedControlsExact = Object.values(fixture.protectedControls).every((control) =>
      audit.cell(control.probe.x, control.probe.y) === control.material
      && audit.temperature(control.probe.x, control.probe.y) === control.temperature);
    const contactsExact = Object.values(fixture.contacts).every((contact) =>
      audit.cell(contact.fireProbe.x, contact.fireProbe.y) === fixture.material
      && audit.cell(contact.otherProbe.x, contact.otherProbe.y) === contact.otherMaterial
      && audit.temperature(contact.fireProbe.x, contact.fireProbe.y) === contact.fireTemperature
      && audit.temperature(contact.otherProbe.x, contact.otherProbe.y) === contact.otherTemperature);
    return {
      mode: ${JSON.stringify(mode)}, mainBodyFireCells, materialCounts,
      temperatureCounts: [...temperatures].sort(([left], [right]) => left - right)
        .map(([temperature, cells]) => ({ temperature, cells })),
      materialHash, temperatureHash, wallHash, velocityHash, renderedVelocityHash,
      wallCells, nonzeroVelocityCells, velocityStagingMismatches, velocityOwnershipExact,
      wallFireCoexistence, wallPatternExact, authoredVoidsExact, sparseExact,
      protectedControlsExact, contactsExact, guardedBlankExact: emptyRect(fixture.guardedBlank),
    };
  })()`);
}

async function navigateFireFlameVfxState(cdp, mode, scale, fixtureMode, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    fireFlameVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0',
    waterCurvatureVfx: '0', fireFlameVfx: enabled ? '1' : '0',
    gasBodyVfx: '0', gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0',
    nobleGasPrismVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0',
    rockRoughnessVfx: '0', waterBodyVfx: '0', waterVolumeRecessionVfx: '0', acidBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('scene') === 'render-lab' && parameters.get('inputAudit') === '1'
      && parameters.get('blankAudit') === '1' && parameters.get('fireFlameVfxAudit') === '1'
      && parameters.get('renderScale') === ${JSON.stringify(String(scale))}
      && parameters.get('volumeVfx') === '0'
      && parameters.get('waterCurvatureVfx') === '0'
      && parameters.get('fireFlameVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && typeof window.__ANIFOR_INPUT_AUDIT__?.prepareFireFlameVfxFixture === 'function';
  })()`), 15_000, `E67 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  15_000, `E67 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareFireFlameVfxFixture(${JSON.stringify(fixtureMode)});
    audit.resetView();
    return audit.fireFlameVfxFixture();
  })()`);
  const fixtureState = await waitFor(async () => {
    const candidate = await sampleFireFlameVfxFixtureState(cdp, fixtureMode);
    try {
      assertFireFlameFixtureState(candidate, fixture, fixtureMode,
        `E67 ${label} ${scale}x readiness`);
      return candidate;
    } catch { return undefined; }
  }, 8_000, `E67 ${label} ${scale}x semantic temperature/velocity staging`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('.semantic-field-canvas');
    return canvas ? {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx,
      waterCurvatureVfx: canvas.dataset.waterCurvatureVfx, fireFlameVfx: canvas.dataset.fireFlameVfx,
      gasBodyVfx: canvas.dataset.gasBodyVfx, gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx, powderLightVfx: canvas.dataset.powderLightVfx,
    } : undefined;
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline?.state === 'active'
    && hdrPipeline?.bloomBacking === expectedBloom
    && hdrPipeline?.fireFlameVfx === (enabled ? 'active' : 'inactive'),
  `E67 ${label} ${scale}x HDR/fire-flame state resolved incorrectly (${JSON.stringify(
    hdrPipeline,
  )})`);
  const capture = await waitForStablePageCapture(cdp,
    `E67 ${label} ${scale}x framebuffer`, scale === 4 ? 25_000 : undefined);
  return {
    fixture, fixtureState, capture, geometry: await metrics(cdp),
    semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, fireFlameRawControlPoints(fixture)),
    hdrPipeline,
  };
}

async function auditEightXFireFlameVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'eight-fire-flame',
    fireFlameVfxAudit: '1', renderScale: '8', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0',
    waterCurvatureVfx: '0', fireFlameVfx: '1', gasBodyVfx: '0', gasMotionVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('renderScale') === '8'
      && parameters.get('fireFlameVfxAudit') === '1'
      && parameters.get('fireFlameVfx') === '1'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E67 API'), 'true-8x E67 API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E67', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E67');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E67 geometry')),
    'true-8x E67 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  'true-8x E67 lost exact backing');
  const state = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      fireFlameVfx: canvas.dataset.fireFlameVfx, hdr: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloom: canvas.dataset.bloomBacking ?? null,
    } : undefined;
  })()`);
  assert(state?.renderer === 'semantic-field-webgl' && state.look === 'realistic'
    && state.fireFlameVfx === 'inactive' && state.hdr === 'inactive'
    && state.reason === 'scale-8' && state.bloom === null,
  `true-8x E67 selector/resource exclusion failed: ${JSON.stringify(state)}`);
  const materialPlane = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()');
  assert(materialPlane.occupied === 0,
    `true-8x E67 unexpectedly uploaded its dense fixture: ${JSON.stringify(materialPlane)}`);
  const semanticBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E67 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(timing.source === 'gpu-fence',
    `true-8x E67 did not complete a real GPU fence: ${JSON.stringify(timing)}`);
  const semanticAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(semanticBefore, semanticAfter, 'true-8x E67 GPU completion');
  return { geometry, backend, state, materialPlane, fixtureUploaded: false,
    semanticStable: true, timing };
}

/**
 * E04 atmospheric-body experiment. The broad E02 volume pass and E03 liquid
 * body pass remain explicitly inactive so every response is attributable to
 * the normal-detail gas-body arithmetic.
 */
async function auditGasBodyVfxExperiment(cdp, mode) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateGasBodyVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E04 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E04 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E04 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E04 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E04 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E04 ${scale}x backing geometry changed (${JSON.stringify({
      disabled: disabled.geometry.backing, enabled: enabled.geometry.backing,
      repeat: disabledRepeat.geometry.backing,
    })})`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic,
      `E04 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E04 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E04 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E04 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawControls, enabled.rawControls,
      `E04 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawControls, disabledRepeat.rawControls,
      `E04 ${scale}x disabled/repeated`);
    const rawGas = Object.fromEntries(disabled.rawControls.map((point) => [point.name, point]));
    for (const family of ['smoke', 'fog', 'cflm']) {
      assert(rawGas[`${family}Carrier`]?.rgba[3] > 0
        && rawGas[`${family}Midpoint`]?.rgba[3] > 0
        && rawGas[`${family}Gap`]?.rgba[3] === 0,
      `E04 ${scale}x lost its sparse carrier/midpoint/gap topology (${JSON.stringify(rawGas)})`);
    }

    const responseRegions = [...GAS_BODY_VFX_TARGET_REGIONS, ...GAS_BODY_VFX_CHAIN_CONTROLS];
    const rawResponses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, responseRegions, disabled.capture.canvasRect);
    const responses = rawResponses.map((sample, index) => {
      const region = responseRegions[index];
      const meanRgbRms = Math.hypot(...sample.responseRgb) / Math.sqrt(3);
      return {
        ...sample,
        ...region,
        spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2 - meanRgbRms ** 2)), 3),
      };
    });
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E04 ${scale}x gas-body query was not deterministic (${JSON.stringify(responses)})`);
    const targets = responses.filter((sample) => sample.family);
    assert(targets.every((sample) => sample.rgbRms >= sample.minimumRms
      && sample.spatialRgbRms >= sample.minimumSpatial
      && sample.rgbPeak >= (sample.minimumPeak ?? 1)
      && sample.rgbPeak <= sample.maximumPeak),
    `E04 ${scale}x gas-body response was inert, uniform, or exceeded its RGB budget (${JSON.stringify(targets)})`);
    const controls = responses.filter((sample) => !sample.family);
    assert(controls.every((sample) => sample.rgbPeak <= sample.maximumPeak
      && (sample.maximumCoverage === undefined || sample.coverage <= sample.maximumCoverage)),
      `E04 ${scale}x gas-body response widened a sparse carrier or authored gap (${JSON.stringify(controls)})`);
    assert(targets.some((sample) => sample.signedMean >= 0.20)
      && targets.some((sample) => sample.signedMean <= -0.20),
    `E04 ${scale}x lost its bipolar billow key/fill response (${JSON.stringify(targets)})`);
    for (const family of ['smoke', 'oxygen', 'noble', 'fog', 'cflm']) {
      const core = targets.find((sample) => sample.family === family && sample.zone === 'core');
      const shell = targets.find((sample) => sample.family === family && sample.zone === 'shell');
      assert(core && shell && core.responseSignature !== shell.responseSignature
        && (Math.abs(core.spatialRgbRms - shell.spatialRgbRms) >= 0.15
          || Math.abs(core.signedMean - shell.signedMean) >= 0.15),
      `E04 ${scale}x ${family} lost its shaped core/shell response (${JSON.stringify({ core, shell })})`);
    }
    scales.push({
      scale,
      backing: disabled.geometry.backing,
      alphaSupport: disabled.backing,
      rawControls: disabled.rawControls,
      responses,
    });
  }
  return { scales, trueEightXExcluded: true };
}

/**
 * E07 proves that the velocity-aware gas cue is a strictly RGB-only addition
 * to E04's field-owned atmosphere. The paused render-lab fixture changes only
 * semantic velocity bytes between its directed and still forms; material,
 * walls, atmosphere support, and every protected sparse/control point stay
 * exactly fixed.
 */
async function auditGasMotionVfxExperiment(cdp, mode) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const directedOff = await navigateGasMotionVfxState(cdp, mode, scale, 'directed', false, 'directedOff');
    const directedOn = await navigateGasMotionVfxState(cdp, mode, scale, 'directed', true, 'directedOn');
    const directedRepeat = await navigateGasMotionVfxState(cdp, mode, scale, 'directed', false, 'directedRepeat');
    const reversedOff = await navigateGasMotionVfxState(cdp, mode, scale, 'reversed', false, 'reversedOff');
    const reversedOn = await navigateGasMotionVfxState(cdp, mode, scale, 'reversed', true, 'reversedOn');
    const stillOff = await navigateGasMotionVfxState(cdp, mode, scale, 'still', false, 'stillOff');
    const stillOn = await navigateGasMotionVfxState(cdp, mode, scale, 'still', true, 'stillOn');
    const variants = {
      directedOff, directedOn, directedRepeat, reversedOff, reversedOn, stillOff, stillOn,
    };
    const fixture = directedOff.fixture;
    assert(Object.values(variants).every((variant) => JSON.stringify(variant.fixture) === JSON.stringify(fixture)),
      `E07 ${scale}x fixture metadata changed (${JSON.stringify(Object.fromEntries(
        Object.entries(variants).map(([key, variant]) => [key, variant.fixture]),
      ))})`);
    for (const [label, variant] of Object.entries(variants)) {
      assertGeometry(variant.geometry, `E07 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl', `E07 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E07 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
      assert(variant.hdrPipeline?.volumeVfx === 'inactive' && variant.hdrPipeline?.liquidBodyVfx === 'inactive'
        && variant.hdrPipeline?.liquidSurfaceVfx === 'inactive'
        && variant.hdrPipeline?.gasBodyVfx === 'active' && variant.hdrPipeline?.powderBodyVfx === 'inactive'
        && variant.hdrPipeline?.powderLightVfx === 'inactive'
        && variant.hdrPipeline?.gasMotionVfx === (
          label === 'directedOn' || label === 'reversedOn' || label === 'stillOn'
            ? 'active' : 'inactive'
        ),
      `E07 ${label} ${scale}x selector state resolved incorrectly (${JSON.stringify(variant.hdrPipeline)})`);
      assertGasMotionRawTopology(variant.rawControls, `E07 ${label} ${scale}x`);
    }
    for (const [leftName, rightName] of [
      ['directedOff', 'directedOn'], ['directedOff', 'directedRepeat'],
      ['reversedOff', 'reversedOn'], ['stillOff', 'stillOn'],
      ['directedOff', 'reversedOff'], ['directedOff', 'stillOff'],
    ]) {
      const left = variants[leftName];
      const right = variants[rightName];
      assertCanvasRectsEqual(left.geometry.canvas, right.geometry.canvas,
        `E07 ${scale}x ${leftName}/${rightName} CSS geometry`);
      assert(JSON.stringify(left.geometry.backing) === JSON.stringify(right.geometry.backing),
        `E07 ${scale}x ${leftName}/${rightName} backing geometry changed (${JSON.stringify({
          left: left.geometry.backing, right: right.geometry.backing,
        })})`);
      assertHdrVfxSemanticEquality(left.semantic, right.semantic, `E07 ${scale}x ${leftName}/${rightName}`);
      assertGasMotionAtmosphereEquality(left.atmosphere, right.atmosphere,
        `E07 ${scale}x ${leftName}/${rightName}`);
      // Native particle velocity already contributes to the established gas
      // billow alpha outside E07, so directed and still fixtures may differ in
      // presentation alpha even though their AtmosphereField support is exact.
      // The E07 selector itself remains strictly alpha-invariant: compare full
      // backing and raw probes only within one unchanged velocity plane.
      const velocityPlane = (name) => name.startsWith('directed') ? 'directed'
        : name.startsWith('reversed') ? 'reversed' : 'still';
      const sameVelocityPlane = velocityPlane(leftName) === velocityPlane(rightName);
      if (sameVelocityPlane) {
        assertVolumeVfxBackingInvariant(left.backing, right.backing,
          `E07 ${scale}x ${leftName}/${rightName}`);
        assertVolumeVfxRawAlphaInvariant(left.rawControls, right.rawControls,
          `E07 ${scale}x ${leftName}/${rightName}`);
      }
    }
    assertGasMotionVelocityMetadata(directedOff.velocity, fixture, 'directed', `E07 directedOff ${scale}x`);
    assertGasMotionVelocityMetadata(directedOn.velocity, fixture, 'directed', `E07 directedOn ${scale}x`);
    assertGasMotionVelocityMetadata(directedRepeat.velocity, fixture, 'directed', `E07 directedRepeat ${scale}x`);
    assertGasMotionVelocityMetadata(reversedOff.velocity, fixture, 'reversed', `E07 reversedOff ${scale}x`);
    assertGasMotionVelocityMetadata(reversedOn.velocity, fixture, 'reversed', `E07 reversedOn ${scale}x`);
    assertGasMotionVelocityMetadata(stillOff.velocity, fixture, 'still', `E07 stillOff ${scale}x`);
    assertGasMotionVelocityMetadata(stillOn.velocity, fixture, 'still', `E07 stillOn ${scale}x`);
    assertGasMotionFieldMetadata(directedOff.motion, fixture, 'directed', `E07 directedOff ${scale}x`);
    assertGasMotionFieldMetadata(directedOn.motion, fixture, 'directed', `E07 directedOn ${scale}x`);
    assertGasMotionFieldMetadata(directedRepeat.motion, fixture, 'directed', `E07 directedRepeat ${scale}x`);
    assertGasMotionFieldMetadata(reversedOff.motion, fixture, 'reversed', `E07 reversedOff ${scale}x`);
    assertGasMotionFieldMetadata(reversedOn.motion, fixture, 'reversed', `E07 reversedOn ${scale}x`);
    assertGasMotionFieldMetadata(stillOff.motion, fixture, 'still', `E07 stillOff ${scale}x`);
    assertGasMotionFieldMetadata(stillOn.motion, fixture, 'still', `E07 stillOn ${scale}x`);
    assert(JSON.stringify(directedOff.motion) === JSON.stringify(directedOn.motion)
      && JSON.stringify(directedOff.motion) === JSON.stringify(directedRepeat.motion)
      && JSON.stringify(reversedOff.motion) === JSON.stringify(reversedOn.motion)
      && JSON.stringify(stillOff.motion) === JSON.stringify(stillOn.motion),
    `E07 ${scale}x selector changed the atmosphere-owned motion field (${JSON.stringify({
      directedOff: directedOff.motion, directedOn: directedOn.motion,
      directedRepeat: directedRepeat.motion, reversedOff: reversedOff.motion,
      reversedOn: reversedOn.motion, stillOff: stillOff.motion, stillOn: stillOn.motion,
    })})`);

    const targets = gasMotionTargetRegions(fixture);
    const counterflowTargets = gasMotionCounterflowRegions(fixture);
    const controls = gasMotionControlRegions(fixture);
    const responseRegions = [...targets, ...counterflowTargets, ...controls];
    const directedRawSamples = await sampleBackdropRefractionRegions(cdp, {
      straight: directedOff.capture.capture.data,
      refracted: directedOn.capture.capture.data,
      repeatedStraight: directedRepeat.capture.capture.data,
    }, responseRegions, directedOff.capture.canvasRect);
    const directedSamples = directedRawSamples.map((sample, index) => ({
      ...sample, ...responseRegions[index],
    }));
    const directedTargets = directedSamples.slice(0, targets.length);
    const directedCounterflow = directedSamples.slice(
      targets.length, targets.length + counterflowTargets.length,
    );
    const directedControls = directedSamples.slice(targets.length + counterflowTargets.length);
    assert(directedSamples.every((sample) => sample.repeatRgbPeak === 0),
      `E07 ${scale}x directed off/on/off was not exact (${JSON.stringify(directedSamples)})`);
    assertGasMotionTargetResponse(directedTargets, scale, 'directed');
    assertGasMotionControlResponse(directedControls, scale, 'directed');

    const reversedRawSamples = await sampleBackdropRefractionRegions(cdp, {
      straight: reversedOff.capture.capture.data,
      refracted: reversedOn.capture.capture.data,
      repeatedStraight: reversedOff.capture.capture.data,
    }, responseRegions, reversedOff.capture.canvasRect);
    const reversedSamples = reversedRawSamples.map((sample, index) => ({
      ...sample, ...responseRegions[index],
    }));
    const reversedTargets = reversedSamples.slice(0, targets.length);
    const reversedCounterflow = reversedSamples.slice(
      targets.length, targets.length + counterflowTargets.length,
    );
    const reversedControls = reversedSamples.slice(targets.length + counterflowTargets.length);
    assertGasMotionTargetResponse(reversedTargets, scale, 'reversed');
    assertGasMotionControlResponse(reversedControls, scale, 'reversed');

    const stillSamples = await sampleBackdropRefractionRegions(cdp, {
      straight: stillOff.capture.capture.data,
      refracted: stillOn.capture.capture.data,
      repeatedStraight: stillOff.capture.capture.data,
    }, responseRegions, stillOff.capture.canvasRect);
    assert(stillSamples.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
      `E07 ${scale}x zero-velocity fixture produced a gas-motion RGB response (${JSON.stringify(stillSamples)})`);
    assertGasMotionCounterflowResponse(directedCounterflow, reversedCounterflow, scale);
    assertGasMotionDirectionality(directedTargets, reversedTargets, scale);
    const screenshots = screenshotRequest
      ? await writeGasMotionVfxScreenshots(screenshotRequest, scale, variants)
      : undefined;
    scales.push({
      scale,
      backing: directedOff.geometry.backing,
      alphaSupport: directedOff.backing,
      atmosphereSupport: directedOff.atmosphere,
      rawControls: directedOff.rawControls,
      directedVelocity: directedOff.velocity,
      directedMotion: directedOff.motion,
      targets: directedTargets,
      reversedTargets,
      counterflow: directedCounterflow,
      reversedCounterflow,
      controls: directedControls,
      screenshots,
    });
  }
  return { scales, trueEightXExcluded: true };
}

async function writeGasMotionVfxScreenshots(source, scale, variants) {
  const paths = {};
  for (const [variant, capture] of Object.entries(variants)) {
    paths[variant] = variantScreenshotPath(source, `gas-motion-${scale}x-${variant}`);
    await writeFile(paths[variant], Buffer.from(capture.capture.capture.data, 'base64'));
  }
  return paths;
}

/**
 * E68 is deliberately a child of the already-audited E04/E07 AtmosphereField
 * path.  This route changes only its RGB selector while retaining the same
 * directed, reversed, and still fixture so a CFLM-only flow fold cannot claim
 * support, emission, or velocity ownership.
 */
const CFLM_COLD_FLAME_TOPOLOGY_RGB_PEAK = 48;

async function auditCflmColdFlameVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    if (scale === 8) continue;
    const variants = {};
    for (const fixtureMode of ['directed', 'reversed', 'still']) {
      for (const enabled of [false, true, false]) {
        const key = `${fixtureMode}${enabled ? 'On' : variants[`${fixtureMode}Off`] ? 'Repeat' : 'Off'}`;
        variants[key] = await navigateCflmColdFlameVfxState(
          cdp, mode, scale, fixtureMode, enabled, key,
        );
      }
    }
    const fixture = variants.directedOff.fixture;
    assert(Object.values(variants).every((variant) => JSON.stringify(variant.fixture) === JSON.stringify(fixture)),
      `E68 ${scale}x fixture metadata changed`);
    // Persist visual evidence before calibrated response assertions so a failed
    // tuning run still leaves every directed/reversed/still state inspectable.
    const screenshotBase = screenshotRequest ?? path.join(tmpdir(), 'anifor-e68-cflm-cold-flame.png');
    const screenshots = await writeCflmColdFlameVfxScreenshots(screenshotBase, scale, variants);
    for (const [label, variant] of Object.entries(variants)) {
      assertGeometry(variant.geometry, `E68 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl' && variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.gasBodyVfx === 'active' && variant.hdrPipeline.gasMotionVfx === 'active'
        && variant.hdrPipeline.cflmColdFlameVfx === (label.endsWith('On') ? 'active' : 'inactive'),
      `E68 ${label} ${scale}x selector/HDR state resolved incorrectly (${JSON.stringify(variant.hdrPipeline)})`);
      assertGasMotionRawTopology(variant.rawControls, `E68 ${label} ${scale}x`);
      const fixtureMode = label.startsWith('directed') ? 'directed'
        : label.startsWith('reversed') ? 'reversed' : 'still';
      assertGasMotionVelocityMetadata(
        variant.velocity, fixture, fixtureMode, `E68 ${label} ${scale}x`,
      );
      assertCflmColdFlameVelocityMetadata(
        variant.velocity, fixture, fixtureMode, `E68 ${label} ${scale}x`,
      );
      assertGasMotionFieldMetadata(
        variant.motion, fixture, fixtureMode, `E68 ${label} ${scale}x`,
      );
      assertCflmColdFlameFieldMetadata(
        variant.motion, fixture, fixtureMode, `E68 ${label} ${scale}x`,
      );
    }
    for (const fixtureMode of ['directed', 'reversed', 'still']) {
      const off = variants[`${fixtureMode}Off`];
      const on = variants[`${fixtureMode}On`];
      const repeat = variants[`${fixtureMode}Repeat`];
      for (const [leftName, left, rightName, right] of [
        ['off', off, 'on', on], ['off', off, 'repeat', repeat],
      ]) {
        assertCanvasRectsEqual(left.geometry.canvas, right.geometry.canvas,
          `E68 ${scale}x ${fixtureMode} ${leftName}/${rightName} CSS geometry`);
        assert(JSON.stringify(left.geometry.backing) === JSON.stringify(right.geometry.backing),
          `E68 ${scale}x ${fixtureMode} ${leftName}/${rightName} backing changed`);
        assertHdrVfxSemanticEquality(left.semantic, right.semantic,
          `E68 ${scale}x ${fixtureMode} ${leftName}/${rightName}`);
        assertGasMotionAtmosphereEquality(left.atmosphere, right.atmosphere,
          `E68 ${scale}x ${fixtureMode} ${leftName}/${rightName}`);
        assert(JSON.stringify(left.planes) === JSON.stringify(right.planes),
          `E68 ${scale}x ${fixtureMode} selector changed semantic/emission/velocity/wall planes (${JSON.stringify({ left: left.planes, right: right.planes })})`);
        assertVolumeVfxBackingInvariant(left.backing, right.backing,
          `E68 ${scale}x ${fixtureMode} ${leftName}/${rightName}`);
        assertCflmColdFlameRawControlInvariant(left.rawControls, right.rawControls,
          `E68 ${scale}x ${fixtureMode} ${leftName}/${rightName}`);
      }
      assert(off.capture.capture.data === repeat.capture.capture.data,
        `E68 ${scale}x ${fixtureMode} disabled framebuffer did not restore byte-for-byte`);
    }
    const targetRegions = cflmColdFlameTargetRegions(fixture);
    const controlRegions = cflmColdFlameControlRegions(fixture);
    const regions = [...targetRegions, ...controlRegions];
    const sampleMode = async (fixtureMode) => {
      const off = variants[`${fixtureMode}Off`];
      const on = variants[`${fixtureMode}On`];
      const repeat = variants[`${fixtureMode}Repeat`];
      const samples = await sampleBackdropRefractionRegions(cdp, {
        straight: off.capture.capture.data, refracted: on.capture.capture.data,
        repeatedStraight: repeat.capture.capture.data,
      }, regions, off.capture.canvasRect);
      return samples.map((sample, index) => ({ ...sample, ...regions[index] }));
    };
    const directed = await sampleMode('directed');
    const reversed = await sampleMode('reversed');
    const still = await sampleMode('still');
    const targetCount = targetRegions.length;
    const directedTargets = directed.slice(0, targetCount);
    const reversedTargets = reversed.slice(0, targetCount);
    const stillTargets = still.slice(0, targetCount);
    const directedControls = directed.slice(targetCount);
    const reversedControls = reversed.slice(targetCount);
    const stillControls = still.slice(targetCount);
    const allSamples = [...directed, ...reversed, ...still];
    assert(allSamples.every((sample) => sample.repeatRgbPeak === 0),
      `E68 ${scale}x off/on/off capture was not deterministic (${JSON.stringify(allSamples)})`);
    // Provisional envelopes deliberately leave calibration headroom while
    // rejecting inert, uniform, or runaway additions. The parent fixture pins
    // the selector to coherent CFLM flow, so the still plane must remain raw.
    for (const [name, targets, controls] of [
      ['directed', directedTargets, directedControls], ['reversed', reversedTargets, reversedControls],
    ]) {
      const chroma = targets.map(cflmColdFlameChromaProjection);
      assert(targets.find((sample) => sample.zone === 'core')?.rgbRms >= 0.8
        && targets.filter((sample) => sample.rgbRms >= 0.3).length >= 4
        && targets.every((sample) => sample.rgbPeak <= 64 && sample.rgbRms <= 32)
        && Math.max(...chroma) >= 0.5 && Math.min(...chroma) <= -0.5,
      `E68 ${scale}x ${name} CFLM lacked a bounded broad bipolar body fold (${JSON.stringify({ targets, chroma })})`);
      const exactControls = controls.filter((sample) =>
        sample.name !== 'CFLMHole' && sample.name !== 'CFLMChannel'
          && sample.name !== 'CFLMMetalContactSolid'
          && sample.name !== 'CFLMWaterContactLiquid');
      const topologyControls = controls.filter((sample) =>
        sample.name === 'CFLMHole' || sample.name === 'CFLMChannel');
      const contactControls = controls.filter((sample) =>
        sample.name === 'CFLMMetalContactSolid'
          || sample.name === 'CFLMWaterContactLiquid');
      assert(exactControls.every((sample) => sample.rgbPeak === 0),
        `E68 ${scale}x ${name} changed sparse/foreign/contact/blank controls (${JSON.stringify(exactControls)})`);
      assert(contactControls.every((sample) => sample.rgbPeak <= 1 && sample.rgbRms <= 0.15),
        `E68 ${scale}x ${name} exceeded bounded CFLM contact-side composite spill (${JSON.stringify(contactControls)})`);
      assert(topologyControls.every((sample) =>
        sample.rgbPeak <= CFLM_COLD_FLAME_TOPOLOGY_RGB_PEAK
          && sample.rgbRms <= 16),
        `E68 ${scale}x ${name} exceeded bounded atmosphere-owned hole/channel RGB (${JSON.stringify(topologyControls)})`);
    }
    assert(still.every((sample) => sample.rgbPeak === 0),
      `E68 ${scale}x stationary CFLM unexpectedly received a flow fold (${JSON.stringify(still)})`);
    const reversalPairs = directedTargets.map((directedSample) => {
      const reversedSample = reversedTargets.find((sample) => sample.zone === directedSample.zone);
      const directedChroma = cflmColdFlameChromaProjection(directedSample);
      const reversedChroma = cflmColdFlameChromaProjection(reversedSample);
      return { zone: directedSample.zone, directedChroma, reversedChroma,
        separation: Math.abs(directedChroma - reversedChroma),
        reversed: directedChroma * reversedChroma < 0 };
    });
    assert(reversalPairs.filter((pair) => pair.reversed && pair.separation >= 0.65).length >= 2
      && reversalPairs.reduce((sum, pair) => sum + pair.separation, 0) >= 2.5,
    `E68 ${scale}x reversing CFLM velocity did not reverse the cyan/violet fold (${JSON.stringify(reversalPairs)})`);
    scales.push({ scale, backing: variants.directedOff.geometry.backing, directedTargets,
      reversedTargets, stillTargets, directedControls, reversedControls, stillControls, screenshots });
  }
  let crossScale;
  if (scales.length > 1) {
    const summaries = scales.map((entry) => {
      const primaryZones = new Set(['core', 'left', 'right', 'top', 'bottom']);
      const directed = entry.directedTargets.filter((sample) => primaryZones.has(sample.zone));
      const reversed = entry.reversedTargets.filter((sample) => primaryZones.has(sample.zone));
      const coreDirected = directed.find((sample) => sample.zone === 'core');
      const coreReversed = reversed.find((sample) => sample.zone === 'core');
      const all = [...directed, ...reversed];
      const projections = all.map(cflmColdFlameChromaProjection);
      return { scale: entry.scale,
        bodyRms: all.reduce((sum, sample) => sum + sample.rgbRms, 0) / all.length,
        spectralSpan: Math.max(...projections) - Math.min(...projections),
        directedCoreChroma: cflmColdFlameChromaProjection(coreDirected),
        reversedCoreChroma: cflmColdFlameChromaProjection(coreReversed) };
    });
    const boundedRatio = (values, limit) => Math.max(...values) / Math.min(...values) <= limit;
    assert(summaries.every((entry) => entry.directedCoreChroma >= 0.5
      && entry.reversedCoreChroma <= -0.5)
      && boundedRatio(summaries.map((entry) => entry.bodyRms), 2.75)
      && boundedRatio(summaries.map((entry) => entry.spectralSpan), 2.75),
    `E68 cross-scale CFLM fold drifted in magnitude or core polarity (${JSON.stringify(summaries)})`);
    crossScale = summaries;
  }
  const trueEightX = await auditEightXCflmColdFlameVfxExclusion(cdp, dpr);
  return { scales, crossScale, trueEightXExcluded: true, trueEightX };
}

function cflmColdFlameChromaProjection(sample) {
  return (sample?.responseRgb?.[1] ?? 0) - (sample?.responseRgb?.[0] ?? 0);
}

function assertCflmColdFlameRawControlInvariant(left, right, label) {
  const atmosphereOwnedTopology = new Set(['CFLMHole', 'CFLMChannel']);
  const same = left.length === right.length && left.every((point, index) => {
    const candidate = right[index];
    if (point.name !== candidate.name || point.x !== candidate.x || point.y !== candidate.y
      || point.rgba[3] !== candidate.rgba[3]) return false;
    const peak = Math.max(...point.rgba.slice(0, 3).map((value, channel) =>
      Math.abs(value - candidate.rgba[channel])));
    return atmosphereOwnedTopology.has(point.name)
      ? peak <= CFLM_COLD_FLAME_TOPOLOGY_RGB_PEAK : peak === 0;
  });
  assert(same,
    `${label}: CFLM fold escaped exact controls or bounded field-owned topology RGB (${JSON.stringify({ left, right })})`);
}

async function writeCflmColdFlameVfxScreenshots(source, scale, variants) {
  const paths = {};
  for (const [variant, capture] of Object.entries(variants)) {
    paths[variant] = variantScreenshotPath(source, `cflm-cold-flame-${scale}x-${variant}`);
    await writeFile(paths[variant], Buffer.from(capture.capture.capture.data, 'base64'));
  }
  return paths;
}

async function sampleCflmColdFlamePlanes(cdp) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit?.cell !== 'function' || typeof audit?.wall !== 'function'
      || typeof audit?.velocity !== 'function' || typeof audit?.renderedVelocity !== 'function'
      || typeof audit?.gasIdentityStyle !== 'function'
      || typeof audit?.atmosphereMotion !== 'function'
      || typeof audit?.emissionFieldAlpha !== 'function') {
      throw new Error('E68 semantic/emission/style/motion/velocity audit API unavailable');
    }
    let material = 2166136261, wall = 2166136261, velocity = 2166136261;
    let style = 2166136261, motion = 2166136261, emission = 2166136261;
    let emissionNonzero = 0, emissionSum = 0;
    for (let y = 0; y < audit.height; y++) for (let x = 0; x < audit.width; x++) {
      const mix = (hash, value) => Math.imul(hash ^ (value & 255), 16777619) >>> 0;
      material = mix(material, audit.cell(x, y)); wall = mix(wall, audit.wall(x, y));
      const raw = audit.velocity(x, y), staged = audit.renderedVelocity(x, y);
      velocity = mix(mix(mix(mix(velocity, raw[0]), raw[1]), staged[0]), staged[1]);
      style = mix(style, audit.gasIdentityStyle(x, y));
      const flow = audit.atmosphereMotion(x, y);
      motion = mix(mix(mix(motion, flow[0]), flow[1]), flow[2]);
      const alpha = Math.round(audit.emissionFieldAlpha(x, y));
      emission = mix(emission, alpha); emissionNonzero += Number(alpha !== 0); emissionSum += alpha;
    }
    return { material, wall, velocity, style, motion, emission, emissionNonzero, emissionSum };
  })()`);
}

async function navigateCflmColdFlameVfxState(cdp, mode, scale, fixtureMode, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    gasMotionVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0',
    waterCurvatureVfx: '0', fireFlameVfx: '0', gasBodyVfx: '1', gasMotionVfx: '1',
    cflmColdFlameVfx: enabled ? '1' : '0', powderBodyVfx: '0', powderLightVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0',
    gasCoreDepthVfx: '0', nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0',
    rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('gasMotionVfxAudit') === '1' && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('gasBodyVfx') === '1' && p.get('gasMotionVfx') === '1'
      && p.get('cflmColdFlameVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && typeof window.__ANIFOR_INPUT_AUDIT__?.prepareGasMotionVfxFixture === 'function';
  })()`), 15_000, `E68 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  15_000, `E68 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareGasMotionVfxFixture(${JSON.stringify(fixtureMode)}, true); audit.resetView();
    return audit.gasMotionVfxFixture();
  })()`);
  const velocity = await waitFor(async () => {
    const value = await sampleGasMotionVelocityMetadata(cdp, fixtureMode);
    try { assertGasMotionVelocityMetadata(value, fixture, fixtureMode, `E68 ${label} ${scale}x readiness`); return value; } catch { return undefined; }
  }, 8_000, `E68 ${label} ${scale}x velocity staging`);
  const motion = await waitFor(async () => {
    const value = await sampleGasMotionFieldMetadata(cdp, fixtureMode);
    try { assertGasMotionFieldMetadata(value, fixture, fixtureMode, `E68 ${label} ${scale}x readiness`); return value; } catch { return undefined; }
  }, 8_000, `E68 ${label} ${scale}x atmosphere staging`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('.semantic-field-canvas');
    return canvas ? { state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking, gasBodyVfx: canvas.dataset.gasBodyVfx,
      gasMotionVfx: canvas.dataset.gasMotionVfx, cflmColdFlameVfx: canvas.dataset.cflmColdFlameVfx } : undefined;
  })()`);
  const capture = await waitForStablePageCapture(cdp, `E68 ${label} ${scale}x framebuffer`, scale === 4 ? 25_000 : undefined);
  return { fixture, velocity, motion, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    atmosphere: await sampleGasMotionAtmosphereSupport(cdp), planes: await sampleCflmColdFlamePlanes(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, cflmColdFlameRawControlPoints(fixture),
    ), hdrPipeline };
}

async function auditEightXCflmColdFlameVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({ scene: 'render-lab', inputAudit: '1', blankAudit: '1',
    auditStage: 'eight-cflm-cold-flame', gasMotionVfxAudit: '1', renderScale: '8', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', waterCurvatureVfx: '0',
    fireFlameVfx: '0', gasBodyVfx: '1', gasMotionVfx: '1', cflmColdFlameVfx: '1' });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `new URLSearchParams(location.search).get('cflmColdFlameVfx') === '1'
    && Boolean(window.__ANIFOR_INPUT_AUDIT__)`), remainingDeadlineMs(deadline, 'true-8x E68 API'), 'true-8x E68 API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E68', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E68');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E68 geometry')), 'true-8x E68 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8
    && geometry.outputScale === '8', 'true-8x E68 lost exact backing');
  const state = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? { renderer: canvas.dataset.renderer, cflmColdFlameVfx: canvas.dataset.cflmColdFlameVfx,
      gasBodyVfx: canvas.dataset.gasBodyVfx, gasMotionVfx: canvas.dataset.gasMotionVfx,
      hdr: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason, bloom: canvas.dataset.bloomBacking ?? null } : undefined; })()`);
  assert(state?.renderer === 'semantic-field-webgl' && state.cflmColdFlameVfx === 'inactive'
    && state.gasBodyVfx === 'inactive' && state.gasMotionVfx === 'inactive'
    && state.hdr === 'inactive' && state.reason === 'scale-8' && state.bloom === null,
  `true-8x E68 selector/HDR/resource exclusion failed: ${JSON.stringify(state)}`);
  const materialPlane = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()');
  assert(materialPlane.occupied === 0, `true-8x E68 unexpectedly uploaded its fixture: ${JSON.stringify(materialPlane)}`);
  const semanticBefore = await hdrVfxSemanticDigest(cdp);
  const budget = remainingDeadlineMs(deadline, 'true-8x E68 GPU completion');
  const timing = await auditWebGLPresentationTiming(cdp, 1, Math.min(12_000, budget), budget, 1);
  assert(timing.source === 'gpu-fence', `true-8x E68 did not complete a real GPU fence: ${JSON.stringify(timing)}`);
  assertHdrVfxSemanticEquality(semanticBefore, await hdrVfxSemanticDigest(cdp), 'true-8x E68 GPU completion');
  return { geometry, backend, state, materialPlane, fixtureUploaded: false, semanticStable: true, timing };
}

function gasMotionTargetRegions(fixture) {
  return fixture.cards.flatMap((card) => [
    { name: `${card.code}Core`, code: card.code, zone: 'core', ...rectRegion(card.coreProbe) },
    { name: `${card.code}Left`, code: card.code, zone: 'left', ...rectRegion(card.leftShoulder) },
    { name: `${card.code}Right`, code: card.code, zone: 'right', ...rectRegion(card.rightShoulder) },
    { name: `${card.code}Top`, code: card.code, zone: 'top', ...rectRegion(card.topShoulder) },
    { name: `${card.code}Bottom`, code: card.code, zone: 'bottom', ...rectRegion(card.bottomShoulder) },
  ]);
}

function gasMotionCounterflowRegions(fixture) {
  return [
    { name: 'counterflowLeft', zone: 'left', ...rectRegion(fixture.counterflow.leftProbe) },
    { name: 'counterflowRight', zone: 'right', ...rectRegion(fixture.counterflow.rightProbe) },
  ];
}

function gasMotionControlRegions(fixture) {
  const point = (name, entry) => ({ name, x: entry.x, y: entry.y, radius: 0.35 });
  return [
    ...fixture.cards.flatMap((card) => [
      { name: `${card.code}Hole`, ...rectRegion(card.authoredHole) },
      { name: `${card.code}Channel`, ...rectRegion(card.openChannel) },
    ]),
    { name: 'counterflowHole', ...rectRegion(fixture.counterflow.authoredHole) },
    { name: 'counterflowChannel', ...rectRegion(fixture.counterflow.openChannel) },
    { name: 'stillCore', ...rectRegion(fixture.stillCloud.coreProbe) },
    { name: 'stillHole', ...rectRegion(fixture.stillCloud.authoredHole) },
    ...fixture.sparseChains.flatMap((chain) => [
      point(`${chain.code}CarrierA`, chain.carriers[0]), point(`${chain.code}Midpoint`, chain.midpoint),
      point(`${chain.code}CarrierB`, chain.carriers[1]), point(`${chain.code}Gap`, chain.gap),
      point(`${chain.code}Isolated`, chain.isolated),
    ]),
    { name: 'solidGas', ...rectRegion(fixture.solidContact.gas) },
    { name: 'solid', ...rectRegion(fixture.solidContact.solid) },
    { name: 'liquidGas', ...rectRegion(fixture.liquidContact.gas) },
    { name: 'liquid', ...rectRegion(fixture.liquidContact.liquid) },
    point('nativeWall', fixture.nativeWall),
    { name: 'guardedBlank', ...rectRegion(fixture.guardedBlank) },
  ];
}

function cflmColdFlameTargetRegions(fixture) {
  const edge = (name, rect, zone) => ({ name, code: 'CFLM', zone,
    x: rect.x + rect.width - 3, y: rect.y + rect.height / 2,
    radiusX: 2.25, radiusY: Math.max(0.35, rect.height / 2 - 4.25) });
  const wallGas = fixture.cflmContacts.wall.gas;
  return [
    ...gasMotionTargetRegions(fixture).filter((region) => region.code === 'CFLM'),
    edge('CFLMMetalContactGas', fixture.cflmContacts.metal.gas, 'metal-contact'),
    edge('CFLMWaterContactGas', fixture.cflmContacts.water.gas, 'water-contact'),
    { name: 'CFLMWallBody', code: 'CFLM', zone: 'wall-body',
      x: wallGas.x + 7, y: wallGas.y + wallGas.height / 2,
      radiusX: 3.25, radiusY: Math.max(0.35, wallGas.height / 2 - 5.25) },
  ];
}

function cflmColdFlameControlRegions(fixture) {
  const wall = fixture.cflmContacts.wall.wallAnchor;
  return [
    ...gasMotionControlRegions(fixture),
    { name: 'CFLMMetalContactSolid', ...rectRegion(fixture.cflmContacts.metal.solid) },
    { name: 'CFLMWaterContactLiquid', ...rectRegion(fixture.cflmContacts.water.liquid) },
    { name: 'CFLMNativeWall', x: wall.x + 0.5, y: wall.y + 0.5, radius: 0.35 },
  ];
}

function cflmColdFlameRawControlPoints(fixture) {
  const centre = (name, rect) => ({ name,
    x: Math.floor(rect.x + rect.width / 2), y: Math.floor(rect.y + rect.height / 2) });
  return [
    ...gasMotionRawControlPoints(fixture),
    centre('CFLMMetalContactSolid', fixture.cflmContacts.metal.solid),
    centre('CFLMWaterContactLiquid', fixture.cflmContacts.water.liquid),
    { name: 'CFLMNativeWall', ...fixture.cflmContacts.wall.wallAnchor },
  ];
}

function gasMotionRawControlPoints(fixture) {
  const centre = (name, rect) => ({ name,
    x: Math.floor(rect.x + rect.width / 2), y: Math.floor(rect.y + rect.height / 2) });
  return [
    ...fixture.cards.flatMap((card) => [
      centre(`${card.code}Hole`, card.authoredHole), centre(`${card.code}Channel`, card.openChannel),
    ]),
    centre('counterflowHole', fixture.counterflow.authoredHole),
    centre('counterflowChannel', fixture.counterflow.openChannel),
    centre('stillCore', fixture.stillCloud.coreProbe), centre('stillHole', fixture.stillCloud.authoredHole),
    ...fixture.sparseChains.flatMap((chain) => [
      { name: `${chain.code}CarrierA`, ...chain.carriers[0] }, { name: `${chain.code}Midpoint`, ...chain.midpoint },
      { name: `${chain.code}CarrierB`, ...chain.carriers[1] }, { name: `${chain.code}Gap`, ...chain.gap },
      { name: `${chain.code}Isolated`, ...chain.isolated },
    ]),
    centre('solidGas', fixture.solidContact.gas), centre('solid', fixture.solidContact.solid),
    centre('liquidGas', fixture.liquidContact.gas), centre('liquid', fixture.liquidContact.liquid),
    { name: 'nativeWall', ...fixture.nativeWall }, centre('guardedBlank', fixture.guardedBlank),
  ];
}

function rectRegion(rect) {
  return {
    x: rect.x + rect.width / 2,
    y: rect.y + rect.height / 2,
    radiusX: Math.max(0.35, rect.width / 2 - 0.25),
    radiusY: Math.max(0.35, rect.height / 2 - 0.25),
  };
}

function gasMotionSpatialRgbRms(sample) {
  return Math.sqrt(Math.max(0, sample.rgbRms ** 2
    - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2));
}

function assertGasMotionTargetResponse(targets, scale, mode) {
  assert(targets.every((sample) => sample.rgbPeak <= 6),
    `E07 ${scale}x ${mode} response exceeded its RGB budget (${JSON.stringify(targets)})`);
  for (const code of ['SMKE', 'FOG', 'CFLM']) {
    const family = targets.filter((sample) => sample.code === code);
    const core = family.find((sample) => sample.zone === 'core');
    const coreMinimum = code === 'CFLM' ? 0.40 : 0.65;
    // At 4x the capture kernel averages four times as many presentation pixels;
    // retain the same RMS/body evidence while accepting its expected one-byte
    // reduction in the single-pixel peak statistic.
    const peakMinimum = scale === 4 ? 2 : 3;
    assert(family.length === 5 && core?.rgbRms >= coreMinimum
      && Math.max(...family.map((sample) => sample.rgbPeak)) >= peakMinimum
      && family.filter((sample) => sample.rgbPeak >= 2).length >= 3
      && Math.max(...family.map((sample) => sample.rgbRms)) >= 0.80
      && family.some((sample) => gasMotionSpatialRgbRms(sample) >= 0.15),
    `E07 ${scale}x ${mode} ${code} response was inert or uniform (${JSON.stringify(family)})`);
  }
}

function assertGasMotionControlResponse(controls, scale, mode) {
  // A small hole/channel inside a coherent cloud may already be supported by
  // the shared atmosphere field. E07 is allowed to shade that existing volume;
  // the exact backing/raw-alpha checks above remain the topology authority.
  // Keep it bounded, while the field-cancelled counterflow and all genuinely
  // independent sparse/contact/wall controls remain exact RGB no-ops.
  const isMovingCardVolume = (sample) => /^(?:SMKE|FOG|CFLM)(?:Hole|Channel)$/.test(sample.name);
  const reconstructedVolumes = controls.filter(isMovingCardVolume);
  const strictControls = controls.filter((sample) => !isMovingCardVolume(sample));
  assert(reconstructedVolumes.every((sample) => sample.rgbPeak <= 12 && sample.rgbRms <= 4.25),
    `E07 ${scale}x ${mode} over-lit reconstructed cloud topology (${JSON.stringify(reconstructedVolumes)})`);
  assert(strictControls.every((sample) => sample.rgbPeak === 0),
    `E07 ${scale}x ${mode} escaped a protected sparse/contact/wall control (${JSON.stringify(strictControls)})`);
}

function assertGasMotionRawTopology(points, label) {
  const byName = new Map(points.map((point) => [point.name, point.rgba[3]]));
  for (const code of ['SMKE', 'FOG', 'CFLM']) {
    assert(byName.get(`${code}Gap`) === 0,
      `${label}: ${code} authored sparse gap gained support (${JSON.stringify(points)})`);
    for (const suffix of ['CarrierA', 'Midpoint', 'CarrierB', 'Isolated']) {
      assert((byName.get(`${code}${suffix}`) ?? 0) > 0,
        `${label}: ${code} ${suffix} lost supported topology (${JSON.stringify(points)})`);
    }
  }
  assert((byName.get('stillCore') ?? 0) > 0 && byName.get('guardedBlank') === 0,
    `${label}: still gas or guarded blank topology was invalid (${JSON.stringify(points)})`);
}

function assertGasMotionCounterflowResponse(directed, reversed, scale) {
  const combined = [...directed, ...reversed];
  assert(directed.length === 2 && reversed.length === 2
    && combined.every((sample) => sample.rgbPeak <= 1 && sample.rgbRms <= 0.15
      && Math.abs(sample.signedMean) <= 0.10),
  `E07 ${scale}x counterflow exposed a particle-scale lighting field (${JSON.stringify({ directed, reversed })})`);
}

function assertGasMotionDirectionality(directed, reversed, scale) {
  const target = (samples, code, zone) => samples.find(
    (sample) => sample.code === code && sample.zone === zone,
  );
  const comparisons = [
    { code: 'SMKE', first: 'right', second: 'left', channel: 'luma', expectedSign: 1, minimum: 0.10, reversal: 0.20 },
    { code: 'FOG', first: 'right', second: 'left', channel: 'luma', expectedSign: -1, minimum: 0.10, reversal: 0.20 },
    // CFLM's body is already HDR-bright, so E07 deliberately carries motion
    // through a bipolar cyan/amber shift. Test the red-axis reversal directly;
    // Rec.709 mean can cancel even while that designed hue direction is clear.
    // One-sample 1x output quantizes its smaller reversed shoulder to 0.02;
    // retain the independent 0.06 paired-reversal margin against inert output.
    { code: 'CFLM', first: 'bottom', second: 'top', channel: 0, expectedSign: -1, minimum: 0.015, reversal: 0.06 },
  ].map(({ code, first, second, channel, expectedSign, minimum, reversal }) => {
    const directFirst = target(directed, code, first);
    const directSecond = target(directed, code, second);
    const reverseFirst = target(reversed, code, first);
    const reverseSecond = target(reversed, code, second);
    const response = (sample) => channel === 'luma'
      ? (sample?.signedMean ?? 0) : (sample?.responseRgb?.[channel] ?? 0);
    return {
      code, first, second, channel, expectedSign, minimum, reversal,
      directFirst, directSecond, reverseFirst, reverseSecond,
      directedContrast: response(directFirst) - response(directSecond),
      reversedContrast: response(reverseFirst) - response(reverseSecond),
    };
  });
  assert(comparisons.every((entry) => entry.directFirst && entry.directSecond
    && entry.reverseFirst && entry.reverseSecond
    && entry.directedContrast * entry.expectedSign + 1e-9 >= entry.minimum
    && entry.reversedContrast * entry.expectedSign - 1e-9 <= -entry.minimum
    && (entry.directedContrast - entry.reversedContrast) * entry.expectedSign + 1e-9 >= entry.reversal),
  `E07 ${scale}x reversing velocity did not reverse shoulder contrast (${JSON.stringify(comparisons)})`);
}

function assertGasMotionAtmosphereEquality(left, right, label) {
  assert(left.nonzero === right.nonzero && left.alphaSum === right.alphaSum && left.signature === right.signature,
    `${label}: velocity selector changed AtmosphereField support (${JSON.stringify({ left, right })})`);
}

function assertGasMotionVelocityMetadata(metadata, fixture, mode, label) {
  assert(metadata.mode === mode && metadata.cards.length === fixture.cards.length
    && metadata.counterflow.ownerCells > 0 && metadata.counterflow.backendExact
    && metadata.counterflow.stagedExact
    && metadata.counterflow.holesZero && metadata.counterflow.channelsZero
    && metadata.stillZero && metadata.sparseZero && metadata.contactsZero
    && metadata.wallZero && metadata.blankZero,
  `${label}: protected zero-velocity metadata was invalid (${JSON.stringify(metadata)})`);
  for (const [index, card] of fixture.cards.entries()) {
    const actual = metadata.cards[index];
    const expected = mode === 'directed' ? card.velocity
      : mode === 'reversed' ? { x: -card.velocity.x, y: -card.velocity.y }
        : { x: 0, y: 0 };
    assert(actual?.code === card.code && actual.ownerCells > 0 && actual.uniform
      && actual.stagedUniform
      && actual.velocityCells === (mode === 'still' ? 0 : actual.ownerCells)
      && actual.stagedVelocityCells === (mode === 'still' ? 0 : actual.ownerCells)
      && actual.velocityX === expected.x && actual.velocityY === expected.y
      && actual.stagedVelocityX === expected.x && actual.stagedVelocityY === expected.y
      && actual.holesZero && actual.channelsZero,
    `${label}: ${card.code} velocity metadata was invalid (${JSON.stringify({ actual, expected })})`);
  }
}

function assertCflmColdFlameVelocityMetadata(metadata, fixture, mode, label) {
  const expectedY = mode === 'still' ? 0
    : fixture.cflmContacts.velocity.y * (mode === 'reversed' ? -1 : 1);
  const rects = [
    fixture.cflmContacts.metal.gas,
    fixture.cflmContacts.water.gas,
    fixture.cflmContacts.wall.gas,
  ];
  assert(metadata.cflmContacts?.length === rects.length
    && metadata.cflmContacts.every((entry, index) => {
      const ownerCells = rects[index].width * rects[index].height;
      return entry.ownerCells === ownerCells && entry.uniform && entry.stagedUniform
        && entry.velocityCells === (mode === 'still' ? 0 : ownerCells)
        && entry.stagedVelocityCells === (mode === 'still' ? 0 : ownerCells)
        && entry.velocityX === 0 && entry.velocityY === expectedY
        && entry.stagedVelocityX === 0 && entry.stagedVelocityY === expectedY;
    }),
  `${label}: exact CFLM contact velocity metadata was invalid (${JSON.stringify(metadata.cflmContacts)})`);
}

function assertGasMotionFieldMetadata(metadata, fixture, mode, label) {
  assert(metadata.mode === mode && metadata.cards.length === fixture.cards.length
    && metadata.counterflow.every((sample) => sample.identity > 0
      && sample.flow[0] === 0 && sample.flow[1] === 0 && sample.flow[2] === 0)
    && metadata.still.identity > 0
    && metadata.still.flow[0] === 0 && metadata.still.flow[1] === 0
    && metadata.still.flow[2] === 0
    && metadata.protected.every((flow) => flow[0] === 0 && flow[1] === 0 && flow[2] === 0),
  `${label}: protected atmosphere motion metadata was invalid (${JSON.stringify(metadata)})`);
  for (const [index, card] of fixture.cards.entries()) {
    const actual = metadata.cards[index];
    const direction = mode === 'reversed' ? -1 : 1;
    const expected = mode === 'still'
      ? [0, 0, 0]
      : [card.velocity.x * direction, card.velocity.y * direction, 255];
    assert(actual?.code === card.code && actual.identity > 0
      && actual.flow[0] === expected[0] && actual.flow[1] === expected[1]
      && actual.flow[2] === expected[2],
    `${label}: ${card.code} atmosphere flow was invalid (${JSON.stringify({ actual, expected })})`);
  }
}

function assertCflmColdFlameFieldMetadata(metadata, fixture, mode, label) {
  const direction = mode === 'reversed' ? -1 : 1;
  const expected = mode === 'still'
    ? [0, 0, 0]
    : [fixture.cflmContacts.velocity.x * direction,
      fixture.cflmContacts.velocity.y * direction, 255];
  assert(metadata.cflmContacts?.length === 3
    && metadata.cflmContacts.every((entry) => entry.identity > 0
      && entry.flow[0] === expected[0] && entry.flow[1] === expected[1]
      && entry.flow[2] === expected[2]),
  `${label}: exact CFLM contact atmosphere motion was invalid (${JSON.stringify({
    contacts: metadata.cflmContacts, expected,
  })})`);
}

async function sampleGasMotionFieldMetadata(cdp, mode) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit?.atmosphereMotion !== 'function'
      || typeof audit?.gasIdentityStyle !== 'function') {
      throw new Error('E07 atmosphere motion audit API unavailable');
    }
    const fixture = audit.gasMotionVfxFixture();
    const centre = (rect) => ({
      x: Math.floor(rect.x + rect.width / 2),
      y: Math.floor(rect.y + rect.height / 2),
    });
    const samplePoint = (point) => {
      return { point, identity: audit.gasIdentityStyle(point.x, point.y),
        flow: audit.atmosphereMotion(point.x, point.y) };
    };
    const sample = (rect) => samplePoint(centre(rect));
    return {
      mode: ${JSON.stringify(mode)},
      cards: fixture.cards.map((card) => ({ code: card.code, ...sample(card.coreProbe) })),
      cflmContacts: [
        { code: 'metal', ...sample(fixture.cflmContacts.metal.gas) },
        { code: 'water', ...sample(fixture.cflmContacts.water.gas) },
        { code: 'wall', ...samplePoint({
          x: fixture.cflmContacts.wall.gas.x + 7,
          y: Math.floor(fixture.cflmContacts.wall.gas.y
            + fixture.cflmContacts.wall.gas.height / 2),
        }) },
      ],
      counterflow: [sample(fixture.counterflow.leftProbe), sample(fixture.counterflow.rightProbe)],
      still: sample(fixture.stillCloud.coreProbe),
      protected: [
        sample(fixture.solidContact.gas).flow, sample(fixture.liquidContact.gas).flow,
        audit.atmosphereMotion(fixture.nativeWall.x, fixture.nativeWall.y),
        sample(fixture.guardedBlank).flow,
        ...fixture.sparseChains.flatMap((chain) => [
          audit.atmosphereMotion(chain.carriers[0].x, chain.carriers[0].y),
          audit.atmosphereMotion(chain.midpoint.x, chain.midpoint.y),
          audit.atmosphereMotion(chain.gap.x, chain.gap.y),
          audit.atmosphereMotion(chain.isolated.x, chain.isolated.y),
        ]),
      ],
    };
  })()`);
}

async function sampleGasMotionVelocityMetadata(cdp, mode) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    if (typeof audit?.velocity !== 'function') throw new Error('E07 velocity audit API unavailable');
    const fixture = audit.gasMotionVfxFixture();
    const velocityAt = (x, y) => audit.velocity(x, y);
    const stagedAt = (x, y) => audit.renderedVelocity(x, y);
    const zeroRect = (rect) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        const velocity = velocityAt(x, y);
        if (velocity[0] !== 0 || velocity[1] !== 0) return false;
      }
      return true;
    };
    const stagedZeroRect = (rect) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        const velocity = stagedAt(x, y);
        if (velocity[0] !== 0 || velocity[1] !== 0) return false;
      }
      return true;
    };
    const zeroPoint = (point) => {
      const velocity = velocityAt(point.x, point.y);
      const staged = stagedAt(point.x, point.y);
      return velocity[0] === 0 && velocity[1] === 0
        && staged[0] === 0 && staged[1] === 0;
    };
    const summarizeExactRect = (rect, material) => {
      let ownerCells = 0, velocityCells = 0, stagedVelocityCells = 0;
      let velocityX = 0, velocityY = 0, stagedVelocityX = 0, stagedVelocityY = 0;
      let uniform = true, stagedUniform = true;
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) continue;
          ownerCells++;
          const velocity = velocityAt(x, y), staged = stagedAt(x, y);
          if (velocity[0] !== 0 || velocity[1] !== 0) velocityCells++;
          if (staged[0] !== 0 || staged[1] !== 0) stagedVelocityCells++;
          if (ownerCells === 1) {
            velocityX = velocity[0]; velocityY = velocity[1];
            stagedVelocityX = staged[0]; stagedVelocityY = staged[1];
          } else {
            uniform = uniform && velocity[0] === velocityX && velocity[1] === velocityY;
            stagedUniform = stagedUniform
              && staged[0] === stagedVelocityX && staged[1] === stagedVelocityY;
          }
        }
      }
      return { ownerCells, velocityCells, stagedVelocityCells, velocityX, velocityY,
        stagedVelocityX, stagedVelocityY, uniform, stagedUniform };
    };
    const cflmMaterial = fixture.cards.find((card) => card.code === 'CFLM')?.material;
    if (!Number.isInteger(cflmMaterial)) throw new Error('E68 CFLM fixture owner unavailable');
    return {
      mode: ${JSON.stringify(mode)},
      cards: fixture.cards.map((card) => {
        let ownerCells = 0;
        let velocityCells = 0;
        let velocityX = 0;
        let velocityY = 0;
        let uniform = true;
        let stagedVelocityCells = 0;
        let stagedVelocityX = 0;
        let stagedVelocityY = 0;
        let stagedUniform = true;
        for (let y = card.body.y; y < card.body.y + card.body.height; y++) {
          for (let x = card.body.x; x < card.body.x + card.body.width; x++) {
            if (audit.cell(x, y) !== card.material) continue;
            ownerCells++;
            const velocity = velocityAt(x, y);
            if (velocity[0] !== 0 || velocity[1] !== 0) velocityCells++;
            if (ownerCells === 1) { velocityX = velocity[0]; velocityY = velocity[1]; }
            else uniform = uniform && velocity[0] === velocityX && velocity[1] === velocityY;
            const staged = stagedAt(x, y);
            if (staged[0] !== 0 || staged[1] !== 0) stagedVelocityCells++;
            if (ownerCells === 1) {
              stagedVelocityX = staged[0]; stagedVelocityY = staged[1];
            } else {
              stagedUniform = stagedUniform
                && staged[0] === stagedVelocityX && staged[1] === stagedVelocityY;
            }
          }
        }
        return { code: card.code, ownerCells, velocityCells, velocityX, velocityY, uniform,
          stagedVelocityCells, stagedVelocityX, stagedVelocityY, stagedUniform,
          holesZero: zeroRect(card.authoredHole), channelsZero: zeroRect(card.openChannel) };
      }),
      counterflow: (() => {
        let ownerCells = 0;
        let backendExact = true;
        let stagedExact = true;
        const direction = ${JSON.stringify(mode)} === 'reversed' ? -1 : 1;
        for (let y = fixture.counterflow.body.y;
          y < fixture.counterflow.body.y + fixture.counterflow.body.height; y++) {
          for (let x = fixture.counterflow.body.x;
            x < fixture.counterflow.body.x + fixture.counterflow.body.width; x++) {
            if (audit.cell(x, y) !== fixture.counterflow.material) continue;
            ownerCells++;
            const expected = ${JSON.stringify(mode)} === 'still' ? 0
              : (((x + y) & 1) === 0 ? 1 : -1)
                * fixture.counterflow.velocityMagnitude * direction;
            const backend = velocityAt(x, y);
            const staged = stagedAt(x, y);
            backendExact = backendExact && backend[0] === expected && backend[1] === 0;
            stagedExact = stagedExact && staged[0] === expected && staged[1] === 0;
          }
        }
        return { ownerCells, backendExact, stagedExact,
          holesZero: zeroRect(fixture.counterflow.authoredHole)
            && stagedZeroRect(fixture.counterflow.authoredHole),
          channelsZero: zeroRect(fixture.counterflow.openChannel)
            && stagedZeroRect(fixture.counterflow.openChannel) };
      })(),
      cflmContacts: [
        { code: 'metal', ...summarizeExactRect(
          fixture.cflmContacts.metal.gas, cflmMaterial,
        ) },
        { code: 'water', ...summarizeExactRect(
          fixture.cflmContacts.water.gas, cflmMaterial,
        ) },
        { code: 'wall', ...summarizeExactRect(
          fixture.cflmContacts.wall.gas, cflmMaterial,
        ) },
      ],
      stillZero: zeroRect(fixture.stillCloud.body) && stagedZeroRect(fixture.stillCloud.body),
      sparseZero: fixture.sparseChains.every((chain) => chain.carriers.every(zeroPoint)
        && zeroPoint(chain.midpoint) && zeroPoint(chain.gap) && zeroPoint(chain.isolated)),
      contactsZero: zeroRect(fixture.solidContact.gas) && stagedZeroRect(fixture.solidContact.gas)
        && zeroRect(fixture.solidContact.solid) && stagedZeroRect(fixture.solidContact.solid)
        && zeroRect(fixture.liquidContact.gas) && stagedZeroRect(fixture.liquidContact.gas)
        && zeroRect(fixture.liquidContact.liquid) && stagedZeroRect(fixture.liquidContact.liquid),
      wallZero: zeroPoint(fixture.nativeWall),
      blankZero: zeroRect(fixture.guardedBlank) && stagedZeroRect(fixture.guardedBlank),
    };
  })()`);
}

async function sampleGasMotionAtmosphereSupport(cdp) {
  return evaluate(cdp, `(() => {
    const support = window.__ANIFOR_INPUT_AUDIT__?.atmosphereSupportAudit?.();
    if (!support || !Number.isInteger(support.nonzero) || !Number.isInteger(support.alphaSum)
      || !Number.isInteger(support.signature)) throw new Error('E07 atmosphere support audit unavailable');
    return support;
  })()`);
}

async function navigateGasMotionVfxState(cdp, mode, scale, fixtureMode, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    gasMotionVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0',
    gasBodyVfx: '1', gasMotionVfx: enabled ? '1' : '0', cflmColdFlameVfx: '0',
    powderBodyVfx: '0', powderLightVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('scene') === 'render-lab' && parameters.get('inputAudit') === '1'
      && parameters.get('blankAudit') === '1' && parameters.get('auditStage') === 'blank'
      && parameters.get('gasMotionVfxAudit') === '1' && parameters.get('renderScale') === ${JSON.stringify(String(scale))}
      && parameters.get('renderLook') === 'realistic' && parameters.get('volumeVfx') === '0'
      && parameters.get('liquidBodyVfx') === '0' && parameters.get('liquidSurfaceVfx') === '0'
      && parameters.get('gasBodyVfx') === '1'
      && parameters.get('gasMotionVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && parameters.get('cflmColdFlameVfx') === '0'
      && parameters.get('powderBodyVfx') === '0' && parameters.get('powderLightVfx') === '0'
      && parameters.get('nobleGasBillowVfx') === '0'
      && parameters.get('smokeSoftnessVfx') === '0'
      && parameters.get('smokeBillowDepthVfx') === '0'
      && parameters.get('plasmaCoreVfx') === '0'
      && typeof window.__ANIFOR_INPUT_AUDIT__?.prepareGasMotionVfxFixture === 'function';
  })()`), 15_000, `E07 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  15_000, `E07 ${label} ${scale}x backend`);
  await assertFocusedOrganicSubsurfaceVfxInactive(cdp, `E07 ${label} ${scale}x`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareGasMotionVfxFixture(${JSON.stringify(fixtureMode)});
    audit.resetView();
    return audit.gasMotionVfxFixture();
  })()`);
  // Fixture preparation may race a just-promoted presenter: backend bytes are
  // synchronous, while the invalidated semantic texture is published on the
  // next presentation refresh. Wait for the actual staged bytes so a capture
  // can never silently exercise the stationary texture.
  const velocity = await waitFor(async () => {
    const candidate = await sampleGasMotionVelocityMetadata(cdp, fixtureMode);
    try {
      assertGasMotionVelocityMetadata(
        candidate, fixture, fixtureMode, `E07 ${label} ${scale}x readiness`,
      );
      return candidate;
    } catch { return undefined; }
  }, 8_000, `E07 ${label} ${scale}x velocity staging`);
  const motion = await waitFor(async () => {
    const candidate = await sampleGasMotionFieldMetadata(cdp, fixtureMode);
    try {
      assertGasMotionFieldMetadata(
        candidate, fixture, fixtureMode, `E07 ${label} ${scale}x atmosphere readiness`,
      );
      return candidate;
    } catch { return undefined; }
  }, 8_000, `E07 ${label} ${scale}x atmosphere motion staging`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('.semantic-field-canvas');
    return canvas ? {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx,
      gasBodyVfx: canvas.dataset.gasBodyVfx, gasMotionVfx: canvas.dataset.gasMotionVfx,
      cflmColdFlameVfx: canvas.dataset.cflmColdFlameVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx, powderLightVfx: canvas.dataset.powderLightVfx,
      nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      smokeSoftnessVfx: canvas.dataset.smokeSoftnessVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
    } : undefined;
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline?.state === 'active'
    && hdrPipeline?.bloomBacking === expectedBloom && hdrPipeline?.volumeVfx === 'inactive'
    && hdrPipeline?.liquidBodyVfx === 'inactive' && hdrPipeline?.liquidSurfaceVfx === 'inactive'
    && hdrPipeline?.gasBodyVfx === 'active'
    && hdrPipeline?.powderBodyVfx === 'inactive' && hdrPipeline?.powderLightVfx === 'inactive'
    && hdrPipeline?.nobleGasBillowVfx === 'inactive'
    && hdrPipeline?.smokeSoftnessVfx === 'inactive'
    && hdrPipeline?.smokeBillowDepthVfx === 'inactive'
    && hdrPipeline?.cflmColdFlameVfx === 'inactive'
    && hdrPipeline?.gasMotionVfx === (enabled ? 'active' : 'inactive'),
  `E07 ${label} ${scale}x HDR/gas-motion state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  // Repeated 2448x1536 PNG transfer can exceed the legacy 20-second window
  // after several HDR navigations even when the GPU frame itself completed.
  // Keep this bounded and preserve the exact two-capture stability contract.
  const capture = await waitForStablePageCapture(
    cdp, `E07 ${label} ${scale}x framebuffer`, scale === 4 ? 30_000 : undefined,
  );
  return {
    fixture, velocity, motion, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    atmosphere: await sampleGasMotionAtmosphereSupport(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, gasMotionRawControlPoints(fixture)), hdrPipeline,
  };
}

/**
 * E05 powder crown/facet gate. The established body-depth and mesostrata
 * layers remain enabled as the accepted baseline; only the new normal-detail
 * RGB layer changes here. Grains and Local are captured independently as exact
 * reference modes, while the paused fixture's semantic digest protects the
 * notched columns, holes, ledges, and mixed wet powder.
 */
async function auditPowderBodyVfxExperiment(cdp, mode) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      const variant = await navigatePowderBodyVfxState(cdp, mode, scale, enabled, key);
      variant.references = await capturePowderBodyVfxReferenceStyles(cdp, scale, key);
      captures[key] = variant;
    }
    const { disabled, enabled, disabledRepeat } = captures;
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E05 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E05 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E05 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E05 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E05 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E05 ${scale}x backing geometry changed (${JSON.stringify({
      disabled: disabled.geometry.backing, enabled: enabled.geometry.backing,
      repeat: disabledRepeat.geometry.backing,
    })})`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic,
      `E05 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E05 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E05 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E05 ${scale}x disabled/repeated`);
    assertVolumeVfxRawControlInvariant(disabled.rawControls, enabled.rawControls,
      `E05 ${scale}x disabled/enabled`);
    assertVolumeVfxRawControlInvariant(disabled.rawControls, disabledRepeat.rawControls,
      `E05 ${scale}x disabled/repeated`);

    const responseRegions = [...POWDER_BODY_VFX_TARGET_REGIONS, ...POWDER_BODY_VFX_CONTROL_REGIONS];
    const rawResponses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, responseRegions, disabled.capture.canvasRect);
    const responses = rawResponses.map((sample, index) => {
      const region = responseRegions[index];
      const meanRgbRms = Math.hypot(...sample.responseRgb) / Math.sqrt(3);
      return {
        ...sample,
        ...region,
        spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2 - meanRgbRms ** 2)), 3),
      };
    });
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E05 ${scale}x powder-body query was not deterministic (${JSON.stringify(responses)})`);
    const targets = responses.filter((sample) => sample.family);
    assert(targets.every((sample) => sample.rgbRms >= sample.minimumRms
      && sample.spatialRgbRms >= sample.minimumSpatial
      && sample.rgbPeak >= (sample.minimumPeak ?? 1)
      && sample.rgbPeak <= sample.maximumPeak
      && (sample.minimumSignedMean === undefined
        || sample.signedMean >= sample.minimumSignedMean)
      && (sample.maximumSignedMean === undefined
        || sample.signedMean <= sample.maximumSignedMean)),
    `E05 ${scale}x powder-body response was inert, uniform, or exceeded its RGB budget (${JSON.stringify(targets)})`);
    const controls = responses.filter((sample) => !sample.family);
    assert(controls.every((sample) => sample.rgbPeak <= sample.maximumPeak),
      `E05 ${scale}x powder-body response escaped a hole, fine structure, isolated grain, or wet mixed control (${JSON.stringify(controls)})`);
    assert(targets.some((sample) => sample.signedMean >= 0.05)
      && targets.some((sample) => sample.signedMean <= -0.05),
    `E05 ${scale}x powder-body response lost its bipolar crown/core relation (${JSON.stringify(targets)})`);
    for (const family of ['clay', 'concrete']) {
      const crown = targets.find((sample) => sample.family === family && sample.zone === 'crown');
      const core = targets.find((sample) => sample.family === family && sample.zone === 'core');
      assert(crown && core && crown.responseSignature !== core.responseSignature
        && (Math.abs(crown.spatialRgbRms - core.spatialRgbRms) >= 0.01
          || Math.abs(crown.signedMean - core.signedMean) >= 0.05),
      `E05 ${scale}x ${family} lost its shaped crown/core response (${JSON.stringify({ crown, core })})`);
    }

    // Reuse the already captured off/on/off images. This proves that macro
    // body relief has not traded away the stable material grain cadence.
    const microchroma = await samplePowderBodyVfxMicrochroma(cdp, {
      disabled: disabled.capture.capture.data,
      enabled: enabled.capture.capture.data,
      disabledRepeat: disabledRepeat.capture.capture.data,
    }, POWDER_BODY_VFX_TARGET_REGIONS);
    assert(microchroma.every((sample) => sample.samples >= POWDER_BODY_VFX_MICROCHROMA.minimumSamples
      && sample.disabled >= POWDER_BODY_VFX_MICROCHROMA.minimumBaseline
      && sample.retention >= POWDER_BODY_VFX_MICROCHROMA.minimumRetention
      && sample.retention <= POWDER_BODY_VFX_MICROCHROMA.maximumRetention
      && sample.repeatDelta <= POWDER_BODY_VFX_MICROCHROMA.maximumRepeatDelta),
    `E05 ${scale}x powder-body VFX damped or destabilized internal grain microchroma (${JSON.stringify({
      limits: POWDER_BODY_VFX_MICROCHROMA, microchroma,
    })})`);

    const references = {};
    for (const style of ['grains', 'local']) {
      const samples = await sampleBackdropRefractionRegions(cdp, {
        straight: disabled.references[style].capture.data,
        refracted: enabled.references[style].capture.data,
        repeatedStraight: disabledRepeat.references[style].capture.data,
      }, POWDER_BODY_VFX_REFERENCE_REGIONS, disabled.references[style].canvasRect);
      assert(samples.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
        `E05 ${scale}x powder-body VFX escaped the ${style} reference mode (${JSON.stringify(samples)})`);
      references[style] = samples;
    }

    const screenshots = screenshotRequest ? await writePowderBodyVfxScreenshots(
      screenshotRequest, scale, captures,
    ) : undefined;
    scales.push({
      scale,
      backing: disabled.geometry.backing,
      alphaSupport: disabled.backing,
      rawControls: disabled.rawControls,
      responses,
      microchroma,
      references,
      screenshots,
    });
  }
  return { scales, trueEightXExcluded: true };
}

/**
 * E06 keeps E02 volume and E05 settled-body optics as its fixed baseline, then
 * toggles only the dry Smooth-powder local-light recomposition. The dedicated
 * paused fixture makes source colour, air gaps, holes, fine structures, and
 * wet suspension exact semantic controls rather than incidental render-lab
 * neighbours.
 */
async function auditPowderLightVfxExperiment(cdp, mode) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      const variant = await navigatePowderLightVfxState(cdp, mode, scale, enabled, key);
      variant.references = await capturePowderBodyVfxReferenceStyles(cdp, scale, `E06 ${key}`);
      captures[key] = variant;
    }
    const { disabled, enabled, disabledRepeat } = captures;
    // Persist comparison captures before evaluating visual thresholds so a
    // failed experimental gate still leaves concrete evidence for tuning.
    const screenshots = screenshotRequest ? await writePowderLightVfxScreenshots(
      screenshotRequest, scale, captures,
    ) : undefined;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E06 ${scale}x fixture metadata changed (${JSON.stringify({
      disabled: fixture, enabled: enabled.fixture, repeat: disabledRepeat.fixture,
    })})`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E06 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E06 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E06 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
      assert(variant.hdrPipeline?.volumeVfx === 'active' && variant.hdrPipeline?.powderBodyVfx === 'active'
        && variant.hdrPipeline?.liquidBodyVfx === 'inactive'
        && variant.hdrPipeline?.liquidSurfaceVfx === 'inactive'
        && variant.hdrPipeline?.gasBodyVfx === 'inactive'
        && variant.hdrPipeline?.translucentEdgeVfx === 'inactive'
        && variant.hdrPipeline?.powderLightVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E06 ${label} ${scale}x did not retain its fixed E02/E05 baseline (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E06 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E06 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E06 ${scale}x backing geometry changed (${JSON.stringify({
      disabled: disabled.geometry.backing, enabled: enabled.geometry.backing, repeat: disabledRepeat.geometry.backing,
    })})`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E06 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E06 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing, `E06 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing, `E06 ${scale}x disabled/repeated`);
    assertVolumeVfxRawControlInvariant(disabled.rawControls, enabled.rawControls,
      `E06 ${scale}x disabled/enabled`);
    assertVolumeVfxRawControlInvariant(disabled.rawControls, disabledRepeat.rawControls,
      `E06 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.stability) === JSON.stringify(enabled.stability)
      && JSON.stringify(disabled.stability) === JSON.stringify(disabledRepeat.stability),
    `E06 ${scale}x powder readiness changed across an RGB selector (${JSON.stringify({
      disabled: disabled.stability, enabled: enabled.stability, repeat: disabledRepeat.stability,
    })})`);

    const targets = powderLightTargetRegions(fixture);
    const controls = powderLightControlRegions(fixture);
    const rawResponses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const responses = rawResponses.map((sample, index) => ({
      ...sample,
      ...(index < targets.length ? targets[index] : controls[index - targets.length]),
      spatialRgbRms: round(Math.sqrt(Math.max(0,
        sample.rgbRms ** 2 - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2,
      )), 3),
    }));
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E06 ${scale}x powder-light query was not deterministic (${JSON.stringify(responses)})`);
    const targetResponses = responses.filter((sample) => sample.lit);
    assert(targetResponses.every((sample) => sample.rgbRms >= 0.04 && sample.spatialRgbRms >= 0.02
      && sample.rgbPeak >= 3 && sample.rgbPeak <= 10),
    `E06 ${scale}x powder-light response was inert, uniform, or exceeded its RGB budget (${JSON.stringify(targetResponses)})`);
    const controlResponses = responses.filter((sample) => !sample.family);
    assert(controlResponses.every((sample) => sample.rgbPeak === 0),
      `E06 ${scale}x powder-light escaped an exact source/gap/hole/fine/wet control (${JSON.stringify(controlResponses)})`);
    for (const family of ['sand', 'clay', 'concrete']) {
      const warm = targetResponses.find((sample) => sample.family === family && sample.zone === 'warm');
      const cool = targetResponses.find((sample) => sample.family === family && sample.zone === 'cool');
      const core = responses.find((sample) => sample.family === family && sample.zone === 'core');
      assert(warm && cool && core
        && warm.responseRgb[0] > warm.responseRgb[2]
        && cool.responseRgb[2] > cool.responseRgb[0]
        && core.rgbPeak === 0 && warm.rgbRms > core.rgbRms && cool.rgbRms > core.rgbRms
        && warm.responseSignature !== cool.responseSignature
        && (warm.responseSignature !== core.responseSignature || cool.responseSignature !== core.responseSignature),
      `E06 ${scale}x ${family} lost its warm/cool local transport or dark-core separation (${JSON.stringify({ warm, cool, core })})`);
    }
    const microchroma = await samplePowderBodyVfxMicrochroma(cdp, {
      disabled: disabled.capture.capture.data,
      enabled: enabled.capture.capture.data,
      disabledRepeat: disabledRepeat.capture.capture.data,
    }, targets);
    // Local coloured light may strengthen or gently compress the grain cadence
    // after display tonemapping. Keep both directions inside three percent;
    // this remains a strict guard against the historic whole-body smoothing
    // while accommodating high-detail CSS downsampling of the coloured slope.
    assert(microchroma.every((sample) => sample.samples >= 16 && sample.disabled >= 0.05
      && sample.retention >= 0.97 && sample.retention <= 1.03 && sample.repeatDelta <= 0.001),
    `E06 ${scale}x powder-light VFX damped or destabilized internal grain microchroma (${JSON.stringify(microchroma)})`);

    const references = {};
    const referenceRegions = powderLightReferenceRegions(fixture);
    for (const style of ['grains', 'local']) {
      const samples = await sampleBackdropRefractionRegions(cdp, {
        straight: disabled.references[style].capture.data,
        refracted: enabled.references[style].capture.data,
        repeatedStraight: disabledRepeat.references[style].capture.data,
      }, referenceRegions, disabled.references[style].canvasRect);
      assert(samples.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
        `E06 ${scale}x powder-light VFX escaped the ${style} reference mode (${JSON.stringify(samples)})`);
      references[style] = samples;
    }
    scales.push({
      scale, backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      rawControls: disabled.rawControls, stability: disabled.stability,
      responses, microchroma, references, screenshots,
    });
  }
  return { scales, trueEightXExcluded: true };
}

/**
 * E09 keeps every prior volume/body selector inactive and measures only the
 * proposed settled Smooth Powder/Solid contact depth. The fixture itself is
 * semantic-only; this gate owns the off -> on -> off query navigation.
 */
async function auditPowderSolidContactVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      const variant = await navigatePowderSolidContactVfxState(cdp, mode, scale, enabled, key);
      // E09 is strictly a Smooth-only contact layer. Reuse the established
      // style capture helper for every state, then require its complete
      // Grains/Local framebuffer to remain byte-identical across off/on/off.
      variant.references = await capturePowderBodyVfxReferenceStyles(cdp, scale, `E09 ${key}`);
      captures[key] = variant;
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E09 ${scale}x fixture metadata changed (${JSON.stringify({
      disabled: fixture, enabled: enabled.fixture, repeat: disabledRepeat.fixture,
    })})`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E09 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E09 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E09 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E09 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E09 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E09 ${scale}x backing geometry changed (${JSON.stringify({
      disabled: disabled.geometry.backing, enabled: enabled.geometry.backing,
      repeat: disabledRepeat.geometry.backing,
    })})`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E09 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E09 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing, `E09 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing, `E09 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E09 ${scale}x changed an exact raw control owner (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls, repeat: disabledRepeat.rawControls,
    })})`);
    assert(JSON.stringify(disabled.rgbDigest) === JSON.stringify(disabledRepeat.rgbDigest)
      && disabled.capture.capture.data === disabledRepeat.capture.capture.data,
    `E09 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = powderSolidContactTargetRegions(fixture);
    const controls = powderSolidContactControlRegions(fixture);
    const rawResponses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const responses = rawResponses.map((sample, index) => ({
      ...sample,
      ...(index < targets.length ? targets[index] : controls[index - targets.length]),
      spatialRgbRms: round(Math.sqrt(Math.max(0,
        sample.rgbRms ** 2 - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2,
      )), 3),
    }));
    // Preserve the diagnostic comparison even when a proposed shader branch
    // is still inert, so a focused failure can be inspected without relaxing
    // any assertion below.
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writePowderSolidContactVfxScreenshots(screenshotRequest, disabled, enabled)
      : undefined;
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E09 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    const targetResponses = responses.filter((sample) => sample.target);
    // Accepted 1x/2x/4x measurements keep the one-cell grounding readable and
    // scale-stable: a restrained absorptive response, never a heavy outline.
    assert(targetResponses.every((sample) => sample.rgbRms >= 0.7 && sample.rgbRms <= 1.8
      && sample.spatialRgbRms >= 0.65 && sample.spatialRgbRms <= 1.7
      && sample.rgbPeak >= 3 && sample.rgbPeak <= 8
      && sample.coverage >= 0.12 && sample.coverage <= 0.17
      && sample.signedMean <= -0.25 && sample.signedMean >= -0.7),
    `E09 ${scale}x settled Powder/Solid seam response lost its bounded absorptive scale parity (${JSON.stringify(responses)})`);
    const controlResponses = responses.filter((sample) => !sample.target);
    assert(controlResponses.every((sample) => sample.rgbPeak === 0),
      `E09 ${scale}x escaped a moving/fine/isolated/wet/wall/unlike/air or solid-side control (${JSON.stringify(controlResponses)})`);
    const references = {};
    for (const style of ['grains', 'local']) {
      const disabledReference = disabled.references[style].capture.data;
      const enabledReference = enabled.references[style].capture.data;
      const repeatReference = disabledRepeat.references[style].capture.data;
      assert(enabledReference === disabledReference && enabledReference === repeatReference,
        `E09 ${scale}x escaped its exact ${style} style exclusion`);
      references[style] = { byteExact: true, bytes: Buffer.byteLength(disabledReference, 'base64') };
    }
    scales.push({
      scale,
      backing: disabled.geometry.backing,
      alphaSupport: disabled.backing,
      rawControls: disabled.rawControls,
      responses,
      references,
      exactRepeatedOff: true,
      screenshots,
    });
  }
  const trueEightX = await auditEightXPowderSolidContactVfxExclusion(cdp, dpr);
  return { scales, trueEightXExcluded: true, trueEightX };
}

async function navigatePowderSolidContactVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    powderSolidContactVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '0', sootyPowderBodyVfx: '0', powderLightVfx: '0',
    powderSolidContactVfx: enabled ? '1' : '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('scene') === 'render-lab' && parameters.get('inputAudit') === '1'
      && parameters.get('blankAudit') === '1' && parameters.get('auditStage') === 'blank'
      && parameters.get('powderSolidContactVfxAudit') === '1'
      && parameters.get('renderScale') === ${JSON.stringify(String(scale))}
      && parameters.get('renderLook') === 'realistic'
      && parameters.get('volumeVfx') === '0' && parameters.get('liquidBodyVfx') === '0'
      && parameters.get('liquidSurfaceVfx') === '0' && parameters.get('gasBodyVfx') === '0'
      && parameters.get('gasMotionVfx') === '0' && parameters.get('powderBodyVfx') === '0'
      && parameters.get('powderLightVfx') === '0'
      && parameters.get('powderSolidContactVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && parameters.get('plasmaCoreVfx') === '0'
      && typeof window.__ANIFOR_INPUT_AUDIT__?.preparePowderSolidContactVfxAudit === 'function'
      && typeof window.__ANIFOR_INPUT_AUDIT__?.powderSolidContactVfxFixture === 'function';
  })()`), 15_000, `E09 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  15_000, `E09 ${label} ${scale}x backend`);
  await assertFocusedOrganicSubsurfaceVfxInactive(cdp, `E09 ${label} ${scale}x`);
  const fixture = await evaluate(cdp, `(async () => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    // RenderLab has a live velocity plane, so a new powder owner begins at
    // stability zero. Drive seven distinct presentation opportunities rather
    // than synchronously coalescing fixture writes into one first frame.
    for (let pass = 0; pass < 7; pass++) {
      audit.preparePowderSolidContactVfxAudit();
      await new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 70)));
    }
    return audit.powderSolidContactVfxFixture();
  })()`);
  await waitFor(() => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = audit.powderSolidContactVfxFixture();
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (audit.cell(x, y) !== material) return false;
      }
      return true;
    };
    const moving = fixture.moving;
    const movingVelocity = audit.velocity(moving.probe.x, moving.probe.y);
    const expectedTargetStability = ${enabled ? 254 : 255};
    const contactStateReady = fixture.targets.every((target) => (
      audit.presentationAuxiliary(target.seam.x, target.seam.y) === expectedTargetStability
    ));
    // The categorical marker belongs only to fully settled bulk Powder/Solid
    // contact. Movement, one-cell structures, and native-wall coexistence must
    // remain ordinary stability bytes and are exact framebuffer no-ops below.
    const contactMarkerExcluded = [
      moving.probe, fixture.fine.probe, fixture.isolated.powder, fixture.wall.probe,
    ].every((probe) => audit.presentationAuxiliary(probe.x, probe.y) !== 254);
    return fixture.targets.every((target) => exactRect(target.powder, target.powderMaterial)
        && exactRect(target.solid, target.solidMaterial))
      && exactRect(moving.powder, 1) && audit.cell(moving.solid.x, moving.solid.y) !== 0
      && movingVelocity[0] === moving.velocity[0] && movingVelocity[1] === moving.velocity[1]
      && audit.cell(fixture.fine.powder.x, fixture.fine.powder.y) !== 0
      && audit.cell(fixture.isolated.powder.x, fixture.isolated.powder.y) === 1
      && audit.cell(fixture.wet.probe.x, fixture.wet.probe.y) === 1
      && audit.wall(fixture.wall.wallPoint.x, fixture.wall.wallPoint.y) === fixture.conductiveWall
      && audit.cell(fixture.wall.wallPoint.x, fixture.wall.wallPoint.y) !== 0
      && audit.wall(fixture.wall.probe.x, fixture.wall.probe.y) === fixture.conductiveWall
      && audit.cell(fixture.unlikePowder.seam.x, fixture.unlikePowder.seam.y) !== 0
      && audit.cell(fixture.airGap.probe.x, fixture.airGap.probe.y) === 0
      && contactStateReady && contactMarkerExcluded;
  })()`), 15_000, `E09 ${label} ${scale}x fixture`);
  await sleep(350);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx, gasBodyVfx: canvas.dataset.gasBodyVfx,
      gasMotionVfx: canvas.dataset.gasMotionVfx, powderBodyVfx: canvas.dataset.powderBodyVfx,
      powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
    } : undefined;
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline?.state === 'active'
    && hdrPipeline?.bloomBacking === expectedBloom && hdrPipeline?.volumeVfx === 'inactive'
    && hdrPipeline?.liquidBodyVfx === 'inactive' && hdrPipeline?.liquidSurfaceVfx === 'inactive'
    && hdrPipeline?.gasBodyVfx === 'inactive' && hdrPipeline?.gasMotionVfx === 'inactive'
    && hdrPipeline?.powderBodyVfx === 'inactive' && hdrPipeline?.powderLightVfx === 'inactive'
    && hdrPipeline?.powderSolidContactVfx === (enabled ? 'active' : 'inactive'),
  `E09 ${label} ${scale}x HDR/selector state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E09 ${label} ${scale}x framebuffer`, scale === 4 ? 20_000 : undefined,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    rgbDigest: await sampleLiquidSurfaceVfxCanvasRgbDigest(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, powderSolidContactRawControlPoints(fixture)),
    hdrPipeline,
  };
}

function powderSolidContactTargetRegions(fixture) {
  return fixture.targets.map((target) => ({
    name: `${target.code.toLowerCase()}PowderBand`, target: true,
    x: target.powder.x + target.powder.width / 2, y: target.seam.y - 2,
    radiusX: target.powder.width / 2 - 8, radiusY: 2.5,
  }));
}

function powderSolidContactControlRegions(fixture) {
  const point = (name, candidate) => ({ name, x: candidate.x, y: candidate.y, radius: 0.35 });
  return [
    ...fixture.targets.map((target) => ({
      name: `${target.code.toLowerCase()}SolidSide`, x: target.seam.x,
      y: target.solid.y + 7, radiusX: 10, radiusY: 1.5,
    })),
    point('moving', fixture.moving.probe), point('fine', fixture.fine.probe),
    point('isolated', fixture.isolated.powder), point('wet', fixture.wet.probe),
    point('coLocatedWall', fixture.wall.probe), point('unlikePowder', fixture.unlikePowder.seam),
    point('airGap', fixture.airGap.probe),
  ];
}

function powderSolidContactRawControlPoints(fixture) {
  return [
    ...fixture.targets.map((target) => ({ name: `${target.code}SolidSide`,
      x: target.seam.x, y: target.solid.y + 7 })),
    { name: 'moving', ...fixture.moving.probe }, { name: 'fine', ...fixture.fine.probe },
    { name: 'isolated', ...fixture.isolated.powder }, { name: 'wet', ...fixture.wet.probe },
    { name: 'coLocatedWall', ...fixture.wall.probe },
    { name: 'unlikePowder', ...fixture.unlikePowder.seam }, { name: 'airGap', ...fixture.airGap.probe },
  ];
}

async function writePowderSolidContactVfxScreenshots(source, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, 'e09-off'),
    on: variantScreenshotPath(source, 'e09-on'),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXPowderSolidContactVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-powder-solid-contact', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '0', sootyPowderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '1', organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('renderScale') === '8' && parameters.get('auditStage') === 'eight-powder-solid-contact'
      && parameters.get('powderSolidContactVfx') === '1' && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E09 input audit API'), 'true-8x E09 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E09', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E09');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined, 45_000, 'true-8x E09 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8
    && geometry.outputScale === '8',
  `true-8x E09 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx,
      wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
    } : undefined;
  })()`);
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && isolation.powderSolidContactVfx === 'inactive' && isolation.organicSubsurfaceVfx === 'inactive'
    && isolation.wetSedimentVfx === 'inactive' && isolation.gasLightVfx === 'inactive',
  `true-8x E09 isolation failed (${JSON.stringify(isolation)})`);
  const timing = await auditWebGLPresentationTiming(cdp, 1, 12_000, 30_000, 1);
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence' || timing.source === 'gpu-finish',
    `true-8x E09 did not complete GPU work (${JSON.stringify(timing)})`);
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`, isolation, timing };
}

/**
 * E11 is a narrowly gated RGB-only organic solid subsurface treatment. The
 * paused fixture combines WAX with native-state PLNT owners, then fences all
 * phase, state, wall, topology, and deep-core controls before screenshots.
 */
async function auditOrganicSubsurfaceVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateOrganicSubsurfaceVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E11 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E11 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E11 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E11 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E11 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E11 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E11 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E11 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E11 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing, `E11 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing, `E11 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E11 ${scale}x changed an exact protected raw control`);
    assert(JSON.stringify(disabled.depth) === JSON.stringify(enabled.depth)
      && JSON.stringify(disabled.depth) === JSON.stringify(disabledRepeat.depth),
    `E11 ${scale}x solid-depth auxiliary bands changed across a presentation selector`);
    assert(JSON.stringify(disabled.rgbDigest) === JSON.stringify(disabledRepeat.rgbDigest)
      && disabled.capture.capture.data === disabledRepeat.capture.capture.data,
    `E11 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = organicSubsurfaceVfxTargetRegions(fixture);
    const controls = organicSubsurfaceVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeOrganicSubsurfaceVfxScreenshots(screenshotRequest, disabled, enabled)
      : undefined;
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E11 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    // These envelopes freeze the accepted 2026-08-05 1x/2x/4x calibration.
    // Keep the broad-body cards spatially partial and the single-cell native
    // state discriminator fully covered; a generic positive-response check can
    // silently admit either a body-wide grade or a nearly invisible effect.
    const calibratedTargetBounds = {
      WAXEdgeBand: { rgbRms: [2.3, 2.9], rgbPeak: [4, 7], coverage: [0.6, 0.78], signedMean: [2, 2.5] },
      WAXDepthBand: { rgbRms: [2.65, 3.05], rgbPeak: [5, 7], coverage: [0.8, 0.93], signedMean: [2.55, 2.95] },
      WAXFadeTip: { rgbRms: [0.7, 1.6], rgbPeak: [1, 2], coverage: [0, 1], signedMean: [0.6, 1.9] },
      PLNTHydratedTreeEdgeBand: {
        rgbRms: [1.7, 2.3], rgbPeak: [3, 5], coverage: [0.55, 0.8], signedMean: [1.55, 2.2],
      },
      PLNTHydratedTreeDepthBand: {
        rgbRms: [1.75, 2.2], rgbPeak: [3, 5], coverage: [0.62, 0.82], signedMean: [1.7, 2.15],
      },
      PLNTHydratedTreeFadeTip: {
        rgbRms: [0.6, 1.2], rgbPeak: [1, 2], coverage: [0, 1], signedMean: [0.15, 1.3],
      },
      PLNTHydratedNonTree: {
        rgbRms: [2.45, 3], rgbPeak: [2, 4], coverage: [0.95, 1], signedMean: [2.5, 3.1],
      },
    };
    assert(targetResponses.length === Object.keys(calibratedTargetBounds).length
      && targetResponses.every((sample) => {
        const bounds = calibratedTargetBounds[sample.name];
        return bounds
          && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
          && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
          && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
          && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1];
      }),
    `E11 ${scale}x organic target response left its calibrated envelope (${JSON.stringify(targetResponses)})`);
    const targetByName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    for (const owner of ['WAX', 'PLNTHydratedTree']) {
      assert(targetByName[`${owner}DepthBand`].rgbRms
        >= targetByName[`${owner}FadeTip`].rgbRms * 1.5,
      `E11 ${scale}x ${owner} depth fade lost its body-to-byte-66 falloff (${JSON.stringify(targetResponses)})`);
    }
    // The authoritative Molten-Wax centre is byte-exact in raw WebGL readback.
    // At 2x Chrome can quantize one blue byte on the broad page-level card
    // crop while reporting zero response coverage; keep that compositor-only
    // allowance narrower than a single perceptible pixel response.
    assert(controlResponses.every((sample) => sample.rgbPeak === 0
      || (scale === 2 && sample.name === 'moltenWax' && sample.rgbPeak <= 1
        && sample.rgbRms <= 0.05 && sample.coverage === 0)),
      `E11 ${scale}x escaped a dry/zero/foreign/wall/topology/deep-core control (${JSON.stringify(controlResponses)})`);
    scales.push({
      scale, backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      rawControls: disabled.rawControls, depth: disabled.depth, responses,
      exactRepeatedOff: true, screenshots,
    });
  }
  const trueEightX = await auditEightXOrganicSubsurfaceVfxExclusion(cdp, dpr);
  return { scales, trueEightXExcluded: true, trueEightX };
}

async function navigateOrganicSubsurfaceVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    organicSubsurfaceVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: enabled ? '1' : '0', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('scene') === 'render-lab' && parameters.get('inputAudit') === '1'
      && parameters.get('blankAudit') === '1' && parameters.get('auditStage') === 'blank'
      && parameters.get('organicSubsurfaceVfxAudit') === '1'
      && parameters.get('renderScale') === ${JSON.stringify(String(scale))}
      && parameters.get('renderLook') === 'realistic'
      && ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx',
        'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx', 'wetSedimentVfx', 'gasLightVfx', 'plasmaCoreVfx']
        .every((name) => parameters.get(name) === '0')
      && parameters.get('organicSubsurfaceVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && typeof window.__ANIFOR_INPUT_AUDIT__?.prepareOrganicSubsurfaceVfxAudit === 'function'
      && typeof window.__ANIFOR_INPUT_AUDIT__?.organicSubsurfaceVfxFixture === 'function';
  })()`), 15_000, `E11 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  15_000, `E11 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(async () => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setTranslucentLensShell(false);
    audit.setTranslucentFieldTransmission(false);
    audit.setSolidOpticalDepth(true);
    for (let pass = 0; pass < 7; pass++) {
      audit.prepareOrganicSubsurfaceVfxAudit();
      await new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 70)));
    }
    return audit.organicSubsurfaceVfxFixture();
  })()`);
  await waitFor(() => evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = audit.organicSubsurfaceVfxFixture();
    const exactRect = (rect, material, state) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (audit.cell(x, y) !== material || audit.presentationState(x, y) !== state) return false;
      }
      return true;
    };
    const emptyRect = (rect) => exactRect(rect, 0, 0);
    const allDepth = (rect, predicate) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (!predicate(audit.presentationAuxiliary(x, y))) return false;
      }
      return true;
    };
    const panesReady = fixture.panes.every((pane) => {
      let bodyExact = true;
      for (let y = pane.body.y; y < pane.body.y + pane.body.height; y++) for (let x = pane.body.x; x < pane.body.x + pane.body.width; x++) {
        const empty = (x >= pane.authoredHole.x && x < pane.authoredHole.x + pane.authoredHole.width
          && y >= pane.authoredHole.y && y < pane.authoredHole.y + pane.authoredHole.height)
          || (x >= pane.openNotch.x && x < pane.openNotch.x + pane.openNotch.width
            && y >= pane.openNotch.y && y < pane.openNotch.y + pane.openNotch.height);
        bodyExact = bodyExact && audit.cell(x, y) === (empty ? 0 : pane.material)
          && audit.presentationState(x, y) === (empty ? 0 : pane.presentationState);
      }
      return bodyExact && emptyRect(pane.authoredHole) && emptyRect(pane.openNotch)
        && exactRect(pane.attachedLine, pane.material, pane.presentationState)
        && audit.cell(pane.isolated.x, pane.isolated.y) === pane.material
        && audit.presentationState(pane.isolated.x, pane.isolated.y) === pane.presentationState
        && allDepth(pane.firstInnerLayer, (depth) => depth === 6)
        && allDepth(pane.edgeBand, (depth) => depth > 6 && depth <= 30)
        && allDepth(pane.depthBand, (depth) => depth > 30 && depth <= 66)
        && audit.presentationAuxiliary(pane.fadeTip.x, pane.fadeTip.y) === 66
        && allDepth(pane.deepCore, (depth) => depth >= 72);
    });
    const exactControl = (control) => exactRect(control.body, control.material, control.presentationState);
    const controls = fixture.controls;
    const depthQualifiedNoOps = [controls.activeDryPlant, controls.hydratedNoPresentPlant]
      .every((control) => {
        const depth = audit.presentationAuxiliary(control.probe.x, control.probe.y);
        return depth > 6 && depth < 72;
      });
    return panesReady
      && Object.entries(controls).filter(([name]) => name !== 'guardedBlank')
        .every(([, control]) => exactControl(control))
      && emptyRect(controls.guardedBlank)
      && fixture.directUnlikeSeams.every((seam) => exactControl(seam.left) && exactControl(seam.right)
        && audit.presentationAuxiliary(seam.leftBoundaryProbe.x, seam.leftBoundaryProbe.y) === 0)
      && audit.wall(controls.waxWall.probe.x, controls.waxWall.probe.y) === fixture.conductiveWall
      && audit.wall(controls.plantWall.probe.x, controls.plantWall.probe.y) === fixture.conductiveWall
      && depthQualifiedNoOps;
  })()`), 20_000, `E11 ${label} ${scale}x fixture/state/depth hydration`);
  await sleep(350);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx, gasBodyVfx: canvas.dataset.gasBodyVfx,
      gasMotionVfx: canvas.dataset.gasMotionVfx, powderBodyVfx: canvas.dataset.powderBodyVfx,
      powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx,
      wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx,
    } : undefined;
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline?.state === 'active'
    && hdrPipeline?.bloomBacking === expectedBloom
    && ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx',
      'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx', 'wetSedimentVfx', 'gasLightVfx', 'plasmaCoreVfx']
      .every((name) => hdrPipeline[name] === 'inactive')
    && hdrPipeline?.organicSubsurfaceVfx === (enabled ? 'active' : 'inactive'),
  `E11 ${label} ${scale}x HDR/selector state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E11 ${label} ${scale}x framebuffer`, scale === 4 ? 20_000 : undefined,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    rgbDigest: await sampleLiquidSurfaceVfxCanvasRgbDigest(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, organicSubsurfaceVfxRawControlPoints(fixture)),
    depth: await organicSubsurfaceVfxDepthDigest(cdp, fixture), hdrPipeline,
  };
}

function organicSubsurfaceVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({ name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2), radiusY: Math.max(0.35, candidate.height / 2 - 0.2) });
  const wax = fixture.panes.find((pane) => pane.code === 'WAX');
  const treePlant = fixture.panes.find((pane) => pane.code === 'PLNT');
  assert(wax && treePlant, 'E11 fixture lacks WAX/hydrated tree PLNT target panes');
  return [
    rect('WAXEdgeBand', wax.edgeBand), rect('WAXDepthBand', wax.depthBand),
    { name: 'WAXFadeTip', target: true, x: wax.fadeTip.x + 0.5, y: wax.fadeTip.y + 0.5, radius: 0 },
    rect('PLNTHydratedTreeEdgeBand', treePlant.edgeBand),
    rect('PLNTHydratedTreeDepthBand', treePlant.depthBand),
    { name: 'PLNTHydratedTreeFadeTip', target: true,
      x: treePlant.fadeTip.x + 0.5, y: treePlant.fadeTip.y + 0.5, radius: 0 },
    { name: 'PLNTHydratedNonTree', target: true,
      x: fixture.controls.hydratedNonTreePlant.probe.x + 0.5,
      y: fixture.controls.hydratedNonTreePlant.probe.y + 0.5, radius: 0 },
  ];
}

function organicSubsurfaceVfxControlRegions(fixture) {
  const point = (name, candidate) => ({ name, x: candidate.x + 0.5, y: candidate.y + 0.5, radius: 0 });
  const rect = (name, candidate) => ({ name, x: candidate.x + candidate.width / 2,
    y: candidate.y + candidate.height / 2, radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2) });
  return [
    ...fixture.panes.flatMap((pane) => [
      rect(`${pane.code}FirstLayer`, pane.firstInnerLayer), rect(`${pane.code}Hole`, pane.authoredHole),
      rect(`${pane.code}Notch`, pane.openNotch), rect(`${pane.code}Line`, pane.attachedLine),
      point(`${pane.code}Isolated`, pane.isolated), rect(`${pane.code}DeepCore`, pane.deepCore),
    ]),
    ...fixture.directUnlikeSeams.map((seam, index) => point(`unlikeSeam${index}`, seam.leftBoundaryProbe)),
    ...Object.entries(fixture.controls).flatMap(([name, control]) => (
      name === 'hydratedNonTreePlant' ? [] : name === 'guardedBlank'
        ? [rect(name, control)] : [rect(name, control.body)
        ])),
  ];
}

function organicSubsurfaceVfxRawControlPoints(fixture) {
  const rectPoint = (name, rect) => ({ name, x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2) });
  return [
    ...fixture.panes.flatMap((pane) => [
      rectPoint(`${pane.code}FirstLayer`, pane.firstInnerLayer), rectPoint(`${pane.code}Hole`, pane.authoredHole),
      rectPoint(`${pane.code}Notch`, pane.openNotch), rectPoint(`${pane.code}Line`, pane.attachedLine),
      { name: `${pane.code}Isolated`, ...pane.isolated }, rectPoint(`${pane.code}DeepCore`, pane.deepCore),
    ]),
    ...fixture.directUnlikeSeams.map((seam, index) => ({ name: `unlikeSeam${index}`, ...seam.leftBoundaryProbe })),
    ...Object.entries(fixture.controls).flatMap(([name, control]) => (
      name === 'hydratedNonTreePlant' ? [] : [name === 'guardedBlank'
        ? rectPoint(name, control) : { name, ...control.probe }
      ])),
  ];
}

async function writeOrganicSubsurfaceVfxScreenshots(source, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, 'e11-off'),
    on: variantScreenshotPath(source, 'e11-on'),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function organicSubsurfaceVfxDepthDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const sample = (rect) => {
      let min = 255; let max = 0;
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        const value = audit.presentationAuxiliary(x, y); min = Math.min(min, value); max = Math.max(max, value);
      }
      return { min, max };
    };
    const controls = ${JSON.stringify(fixture.controls)};
    return {
      panes: ${JSON.stringify(fixture.panes)}.map((pane) => ({ code: pane.code,
      firstInnerLayer: sample(pane.firstInnerLayer), edgeBand: sample(pane.edgeBand),
      depthBand: sample(pane.depthBand), deepCore: sample(pane.deepCore),
      })),
      activeDryPlant: {
        body: sample(controls.activeDryPlant.body),
        probe: audit.presentationAuxiliary(controls.activeDryPlant.probe.x, controls.activeDryPlant.probe.y),
      },
      hydratedNoPresentPlant: {
        body: sample(controls.hydratedNoPresentPlant.body),
        probe: audit.presentationAuxiliary(
          controls.hydratedNoPresentPlant.probe.x, controls.hydratedNoPresentPlant.probe.y,
        ),
      },
    };
  })()`);
}

async function auditEightXOrganicSubsurfaceVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-organic-subsurface', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '1', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('renderScale') === '8' && parameters.get('auditStage') === 'eight-organic-subsurface'
      && parameters.get('organicSubsurfaceVfx') === '1' && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E11 input audit API'), 'true-8x E11 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E11', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E11');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined, 45_000, 'true-8x E11 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8
    && geometry.outputScale === '8', `true-8x E11 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx,
      wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
    } : undefined;
  })()`);
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && isolation.organicSubsurfaceVfx === 'inactive' && isolation.wetSedimentVfx === 'inactive' && isolation.gasLightVfx === 'inactive',
  `true-8x E11 isolation failed (${JSON.stringify(isolation)})`);
  const timing = await auditWebGLPresentationTiming(cdp, 1, 12_000, 30_000, 1);
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence' || timing.source === 'gpu-finish',
    `true-8x E11 did not complete GPU work (${JSON.stringify(timing)})`);
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`, isolation, timing };
}

/** E12: exact Sand/Clay/Concrete wet-sediment RGB over the existing shared field. */
async function auditWetSedimentVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateWetSedimentVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture),
    `E12 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E12 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl', `E12 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E12 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E12 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E12 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E12 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E12 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E12 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing, `E12 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing, `E12 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.suspension) === JSON.stringify(enabled.suspension)
      && JSON.stringify(disabled.suspension) === JSON.stringify(disabledRepeat.suspension),
    `E12 ${scale}x selector changed the shared suspension field`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E12 ${scale}x changed an exact protected raw control`);
    assert(JSON.stringify(disabled.rgbDigest) === JSON.stringify(disabledRepeat.rgbDigest)
      && disabled.capture.capture.data === disabledRepeat.capture.capture.data,
    `E12 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = wetSedimentVfxTargetRegions(disabled.fixture);
    const controls = wetSedimentVfxControlRegions(disabled.fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const acceptedTargets = [
      { name: 'SAND', rms: [1.55, 2.00], peak: [5, 7], coverage: [0.32, 0.46], mean: [0.55, 1.35] },
      { name: 'CLAY', rms: [1.55, 1.90], peak: [5, 7], coverage: [0.30, 0.38], mean: [0.70, 1.40] },
      { name: 'CONC', rms: [1.35, 1.52], peak: [4, 5], coverage: [0.22, 0.30], mean: [0.55, 1.10] },
    ];
    assert(targetResponses.length === acceptedTargets.length
      && targetResponses.every((sample, index) => {
        const accepted = acceptedTargets[index];
        return sample.name === accepted.name
          && sample.rgbRms >= accepted.rms[0] && sample.rgbRms <= accepted.rms[1]
          && sample.rgbPeak >= accepted.peak[0] && sample.rgbPeak <= accepted.peak[1]
          && sample.coverage >= accepted.coverage[0] && sample.coverage <= accepted.coverage[1]
          && sample.signedMean >= accepted.mean[0] && sample.signedMean <= accepted.mean[1];
      }),
    `E12 ${scale}x wet-mineral key/fill response escaped its accepted visual bounds (${JSON.stringify(targetResponses)})`);
    // Exact raw world samples above prove the Empty holes remain unchanged.
    // Their broad page regions include the antialiased body fringe, where the
    // changed neighbouring sediment can quantize one composed RGB byte.
    assert(controlResponses.every((sample) => sample.repeatRgbPeak === 0
      && (sample.rgbPeak === 0 || (sample.name.endsWith('Hole')
        && sample.rgbPeak <= 2 && sample.rgbRms <= 0.20 && sample.coverage <= 0.01))),
      `E12 ${scale}x escaped a dry/moving/foreign/wall/fine/Local/Grains/gap control (${JSON.stringify(controlResponses)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E12 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    const phaseParity = await wetSedimentVfxPhaseParity(cdp, disabled.fixture, disabled, enabled);
    assert(phaseParity.every((sample) => sample.disabled.leftCount > 100 && sample.disabled.rightCount > 100
      && sample.enabled.leftCount > 100 && sample.enabled.rightCount > 100
      && sample.enabled.distance >= 0 && sample.enabled.distance <= 1.20
      && sample.enabled.rawDistance >= 0 && sample.enabled.rawDistance <= 36
      && sample.enabled.distance <= sample.disabled.distance + 0.25),
    `E12 ${scale}x did not retain bounded aqueous/powder chroma convergence (${JSON.stringify(phaseParity)})`);
    const powderStyleControls = await wetSedimentVfxPowderStyleControls(cdp, mode, scale, disabled.fixture);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeWetSedimentVfxScreenshots(screenshotRequest, disabled, enabled) : undefined;
    scales.push({
      scale, backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      suspension: disabled.suspension, rawControls: disabled.rawControls,
      responses, phaseParity, powderStyleControls, exactRepeatedOff: true, screenshots,
    });
  }
  const trueEightX = await auditEightXWetSedimentVfxExclusion(cdp, dpr);
  return { scales, trueEightXExcluded: true, trueEightX };
}

async function navigateWetSedimentVfxState(cdp, mode, scale, enabled, label, powderStyle = 'smooth') {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    wetSedimentVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0', gasMotionVfx: '0',
    powderBodyVfx: '0', sootyPowderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: enabled ? '1' : '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search);
    return parameters.get('scene') === 'render-lab' && parameters.get('inputAudit') === '1'
      && parameters.get('blankAudit') === '1' && parameters.get('auditStage') === 'blank'
      && parameters.get('wetSedimentVfxAudit') === '1'
      && parameters.get('renderScale') === ${JSON.stringify(String(scale))}
      && parameters.get('renderLook') === 'realistic'
      && ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx',
        'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx',
        'organicSubsurfaceVfx', 'gasLightVfx', 'plasmaCoreVfx'].every((name) => parameters.get(name) === '0')
      && parameters.get('wetSedimentVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && typeof window.__ANIFOR_INPUT_AUDIT__?.prepareWetSedimentVfxAudit === 'function'
      && typeof window.__ANIFOR_INPUT_AUDIT__?.wetSedimentVfxFixture === 'function'
      && typeof window.__ANIFOR_INPUT_AUDIT__?.suspensionAt === 'function'
      && typeof window.__ANIFOR_INPUT_AUDIT__?.suspensionSupportAudit === 'function';
  })()`), 15_000, `E12 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  15_000, `E12 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareWetSedimentVfxAudit();
    audit.setPowderRenderStyle(${JSON.stringify(powderStyle)});
    return audit.wetSedimentVfxFixture();
  })()`);
  for (let pass = 0; pass < 7; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp, `(() => {
      const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
      return current?.dynamicSequence > ${before.dynamicSequence} ? current : false;
    })()`), scale === 4 ? 15_000 : 5_000,
    `E12 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => wetSedimentVfxFixtureReady(cdp, fixture), 20_000,
    `E12 ${label} ${scale}x fixture/suspension hydration`);
  const suspension = await wetSedimentVfxSuspensionDigest(cdp, fixture);
  assert(suspension.summary.active && suspension.summary.nonzero > 0 && suspension.summary.alphaSum > 0,
    `E12 ${label} ${scale}x did not hydrate the shared suspension field (${JSON.stringify(suspension)})`);
  const expectedOwnerRgb = { SAND: [215, 170, 104], CLAY: [184, 121, 85], CONC: [134, 131, 125] };
  assert(suspension.positive.every((sample) => sample.rgba[3] > 0
      && sample.rgba.slice(0, 3).every((channel, index) => channel === expectedOwnerRgb[sample.name]?.[index]))
    && suspension.rejected.every((sample) => sample.rgba[3] === 0)
    && suspension.liveRejected.every((sample) => sample.rgba[3] > 0),
  `E12 ${label} ${scale}x suspension ownership field drifted (${JSON.stringify(suspension)})`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline, bloomBacking: canvas.dataset.bloomBacking,
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx, gasBodyVfx: canvas.dataset.gasBodyVfx,
      gasMotionVfx: canvas.dataset.gasMotionVfx, powderBodyVfx: canvas.dataset.powderBodyVfx,
      powderLightVfx: canvas.dataset.powderLightVfx, powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx, wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx,
    } : undefined;
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline?.state === 'active'
    && hdrPipeline?.bloomBacking === expectedBloom
    && ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx', 'powderBodyVfx',
      'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx', 'organicSubsurfaceVfx', 'gasLightVfx', 'plasmaCoreVfx']
      .every((name) => hdrPipeline[name] === 'inactive')
    && hdrPipeline?.wetSedimentVfx === (enabled ? 'active' : 'inactive'),
  `E12 ${label} ${scale}x HDR/selector state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(cdp, `E12 ${label} ${scale}x framebuffer`, scale === 4 ? 20_000 : undefined);
  return {
    fixture, suspension, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp), rgbDigest: await sampleLiquidSurfaceVfxCanvasRgbDigest(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, wetSedimentVfxRawControlPoints(fixture)), hdrPipeline,
  };
}

async function wetSedimentVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = ${JSON.stringify(fixture)};
    const inRect = (point, rect) => point.x >= rect.x && point.x < rect.x + rect.width
      && point.y >= rect.y && point.y < rect.y + rect.height;
    const cards = fixture.cards.every((card) => {
      let body = true;
      for (let y = card.body.y; y < card.body.y + card.body.height; y++) for (let x = card.body.x; x < card.body.x + card.body.width; x++) {
        const empty = inRect({ x, y }, card.authoredHole) || inRect({ x, y }, card.openNotch);
        const material = audit.cell(x, y);
        body = body && (empty ? material === 0 : material === 2 || material === card.material);
      }
      return body && audit.cell(card.powderProbe.x, card.powderProbe.y) === card.material
        && audit.cell(card.waterProbe.x, card.waterProbe.y) === 2
        && audit.cell(card.fineColumn.x, card.fineColumn.y) === card.material;
    });
    const moving = fixture.movingWetSand;
    const velocity = audit.velocity(moving.powderProbe.x, moving.powderProbe.y);
    const waterVelocity = audit.velocity(moving.waterProbe.x, moving.waterProbe.y);
    return cards && fixture.dry.every((control) => audit.cell(control.probe.x, control.probe.y) === control.material)
      && audit.cell(moving.powderProbe.x, moving.powderProbe.y) === 1
      && velocity[0] === moving.velocity[0] && velocity[1] === moving.velocity[1]
      && audit.cell(moving.waterProbe.x, moving.waterProbe.y) === 2
      && waterVelocity[0] === 0 && waterVelocity[1] === 0
      && audit.cell(fixture.oil.body.x + 2, fixture.oil.body.y + 2) !== 0
      && audit.cell(fixture.lava.body.x + 2, fixture.lava.body.y + 2) !== 0
      && audit.cell(fixture.foreignSalt.powderProbe.x, fixture.foreignSalt.powderProbe.y) !== 0
      && audit.wall(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.conductiveWall
      && audit.cell(fixture.fineColumn.column.x, fixture.fineColumn.column.y) === 1
      && audit.cell(fixture.isolated.point.x, fixture.isolated.point.y) === 1
      && audit.cell(fixture.gap.gapProbe.x, fixture.gap.gapProbe.y) === 0
      && audit.cell(fixture.guardedBlank.x, fixture.guardedBlank.y) === 0;
  })()`);
}

async function wetSedimentVfxPowderStyleControls(cdp, mode, scale, fixture) {
  const result = [];
  const targets = wetSedimentVfxTargetRegions(fixture);
  for (const style of ['local', 'grains']) {
    const off = await navigateWetSedimentVfxState(cdp, mode, scale, false, `${style}-off`, style);
    const on = await navigateWetSedimentVfxState(cdp, mode, scale, true, `${style}-on`, style);
    const samples = await sampleBackdropRefractionRegions(cdp, {
      straight: off.capture.capture.data, refracted: on.capture.capture.data,
      repeatedStraight: off.capture.capture.data,
    }, targets, off.capture.canvasRect);
    assert(samples.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
      `E12 ${scale}x ${style} powder style was not an exact no-op (${JSON.stringify(samples)})`);
    result.push({ style, samples, exactNoop: true });
  }
  return result;
}

async function wetSedimentVfxSuspensionDigest(cdp, fixture) {
  const positive = fixture.cards.map((card) => ({ name: card.code, ...card.fieldProbe }));
  const rejected = [
    { name: 'oil', ...fixture.oil.fieldProbe }, { name: 'lava', ...fixture.lava.fieldProbe },
    { name: 'unlikeAqueous', ...fixture.unlikeAqueous.fieldProbe }, { name: 'nativeWall', ...fixture.nativeWall.fieldProbe },
  ];
  const liveRejected = [
    { name: 'movingWetSand', ...fixture.movingWetSand.fieldProbe }, { name: 'foreignSalt', ...fixture.foreignSalt.fieldProbe },
  ];
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const sample = (point) => ({ ...point, rgba: Array.from(audit.suspensionAt(point.x, point.y)) });
    return { summary: audit.suspensionSupportAudit(), positive: ${JSON.stringify(positive)}.map(sample),
      rejected: ${JSON.stringify(rejected)}.map(sample), liveRejected: ${JSON.stringify(liveRejected)}.map(sample) };
  })()`);
}

function wetSedimentVfxTargetRegions(fixture) {
  return fixture.cards.map((card) => ({ name: card.code, target: true,
    x: card.aggregateBody.x + card.aggregateBody.width / 2, y: card.aggregateBody.y + card.aggregateBody.height / 2,
    radiusX: card.aggregateBody.width / 2 - 1, radiusY: card.aggregateBody.height / 2 - 1 }));
}

function wetSedimentVfxControlRegions(fixture) {
  const point = (name, candidate) => ({ name, x: candidate.x + 0.5, y: candidate.y + 0.5, radius: 0 });
  const rect = (name, candidate) => ({ name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2), radiusY: Math.max(0.35, candidate.height / 2 - 0.2) });
  return [
    ...fixture.cards.flatMap((card) => [rect(`${card.code}Hole`, card.authoredHole), rect(`${card.code}Notch`, card.openNotch), rect(`${card.code}Fine`, card.fineColumn)]),
    ...fixture.dry.map((control) => point(`dry${control.material}`, control.probe)),
    rect('movingWetSand', fixture.movingWetSand.aggregateBody), point('oil', fixture.oil.fieldProbe), point('lava', fixture.lava.fieldProbe),
    point('unlikeAqueous', fixture.unlikeAqueous.fieldProbe), point('foreignSalt', fixture.foreignSalt.powderProbe),
    point('nativeWall', fixture.nativeWall.fieldProbe), point('fineColumn', fixture.fineColumn.column), point('isolated', fixture.isolated.point),
    point('authoredGap', fixture.gap.gapProbe), rect('guardedBlank', fixture.guardedBlank),
  ];
}

function wetSedimentVfxRawControlPoints(fixture) {
  const point = (name, candidate) => ({ name, x: Math.floor(candidate.x), y: Math.floor(candidate.y) });
  const rectPoint = (name, rect) => point(name, { x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2) });
  return [
    ...fixture.cards.flatMap((card) => [rectPoint(`${card.code}Hole`, card.authoredHole), rectPoint(`${card.code}Notch`, card.openNotch), rectPoint(`${card.code}Fine`, card.fineColumn)]),
    ...fixture.dry.map((control) => point(`dry${control.material}`, control.probe)),
    point('movingWetSand', fixture.movingWetSand.powderProbe),
    point('stationaryMovingWater', fixture.movingWetSand.waterProbe),
    point('oil', fixture.oil.fieldProbe), point('lava', fixture.lava.fieldProbe),
    point('unlikeAqueous', fixture.unlikeAqueous.fieldProbe), point('foreignSalt', fixture.foreignSalt.powderProbe),
    point('nativeWall', fixture.nativeWall.fieldProbe), point('fineColumn', fixture.fineColumn.column), point('isolated', fixture.isolated.point),
    point('authoredGap', fixture.gap.gapProbe), rectPoint('guardedBlank', fixture.guardedBlank),
  ];
}

async function wetSedimentVfxPhaseParity(cdp, fixture, disabled, enabled) {
  const result = [];
  for (const card of fixture.cards) {
    const region = { left: card.aggregateBody.x, top: card.aggregateBody.y,
      right: card.aggregateBody.x + card.aggregateBody.width, bottom: card.aggregateBody.y + card.aggregateBody.height };
    const cells = await captureMaterialCells(cdp, region, card.material, 2);
    result.push({ code: card.code,
      disabled: await sampleMaterialPhaseContrast(cdp, disabled.capture.capture.data, disabled.capture.canvasRect, cells, card.material, 2),
      enabled: await sampleMaterialPhaseContrast(cdp, enabled.capture.capture.data, enabled.capture.canvasRect, cells, card.material, 2) });
  }
  return result;
}

async function writeWetSedimentVfxScreenshots(source, disabled, enabled) {
  const paths = { off: variantScreenshotPath(source, 'e12-wet-sediment-off'), on: variantScreenshotPath(source, 'e12-wet-sediment-on') };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXWetSedimentVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({ scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-wet-sediment', renderLook: 'realistic', volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0',
    gasBodyVfx: '0', gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '1', gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0' });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => { const parameters = new URLSearchParams(location.search);
    return parameters.get('renderScale') === '8' && parameters.get('auditStage') === 'eight-wet-sediment'
      && parameters.get('wetSedimentVfx') === '1' && Boolean(window.__ANIFOR_INPUT_AUDIT__); })()`),
  remainingDeadlineMs(deadline, 'true-8x E12 input audit API'), 'true-8x E12 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E12', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E12');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined, 45_000, 'true-8x E12 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
    `true-8x E12 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? { renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking ?? null, wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx } : undefined; })()`);
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic' && isolation.state === 'inactive'
    && isolation.reason === 'scale-8' && isolation.bloomBacking === null && isolation.wetSedimentVfx === 'inactive'
    && isolation.gasLightVfx === 'inactive',
  `true-8x E12 isolation failed (${JSON.stringify(isolation)})`);
  const timing = await auditWebGLPresentationTiming(cdp, 1, 12_000, 30_000, 1);
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence' || timing.source === 'gpu-finish',
    `true-8x E12 did not complete GPU work (${JSON.stringify(timing)})`);
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`, isolation, timing };
}

const GAS_LIGHT_VFX_ACCEPTANCE = Object.freeze({
  SMKE: Object.freeze({
    rgbRms: [0.95, 1.30], chromaRms: [0.45, 0.72], signedMean: [0.70, 1.05],
    rgbPeak: [2, 3],
  }),
  FOG: Object.freeze({
    rgbRms: [1.45, 1.90], chromaRms: [0.35, 0.68], signedMean: [1.25, 1.80],
    rgbPeak: [2, 4], coverage: [0.45, 0.72],
  }),
});

/** E13: bounded Smoke/FOG shoulder lighting over the already-owned gas field. */
async function auditGasLightVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateGasLightVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture), `E13 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E13 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl', `E13 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active', `E13 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas, `E13 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas, `E13 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing), `E13 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E13 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E13 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing, `E13 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing, `E13 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls), `E13 ${scale}x changed an exact protected raw control`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data, `E13 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = gasLightVfxTargetRegions(disabled.fixture);
    const controls = gasLightVfxControlRegions(disabled.fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data, refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const byName = Object.fromEntries(responses.map((sample) => [sample.name, sample]));
    for (const code of ['SMKE', 'FOG']) {
      const lit = byName[`${code}Lit`];
      const unlit = byName[`${code}Unlit`];
      const core = byName[`${code}Core`];
      const acceptance = GAS_LIGHT_VFX_ACCEPTANCE[code];
      assert(lit?.rgbPeak >= acceptance.rgbPeak[0] && lit.rgbPeak <= acceptance.rgbPeak[1]
        && lit.rgbRms >= acceptance.rgbRms[0] && lit.rgbRms <= acceptance.rgbRms[1]
        && lit.chromaRms >= acceptance.chromaRms[0] && lit.chromaRms <= acceptance.chromaRms[1]
        && lit.signedMean >= acceptance.signedMean[0] && lit.signedMean <= acceptance.signedMean[1]
        && (!acceptance.coverage
          || (lit.coverage >= acceptance.coverage[0] && lit.coverage <= acceptance.coverage[1]))
        && lit.rgbRms > (unlit?.rgbRms ?? Infinity) && lit.rgbRms > (core?.rgbRms ?? Infinity),
      `E13 ${scale}x ${code} escaped its calibrated spectral shoulder bounds (${JSON.stringify({ acceptance, lit, unlit, core })})`);
      assert(unlit?.rgbPeak === 0 && core?.rgbPeak === 0,
        `E13 ${scale}x ${code} lit a protected unlit/deep core (${JSON.stringify({ unlit, core })})`);
    }
    assert(byName.SMKELit.responseRgb[0] >= byName.SMKELit.responseRgb[1] + 0.50
      && byName.SMKELit.responseRgb[1] >= byName.SMKELit.responseRgb[2] + 0.12,
    `E13 ${scale}x Smoke lost its warm absorption order (${JSON.stringify(byName.SMKELit)})`);
    assert(byName.FOGLit.responseRgb[1] >= byName.FOGLit.responseRgb[0] + 0.18
      && byName.FOGLit.responseRgb[2] >= byName.FOGLit.responseRgb[0] + 0.12,
    `E13 ${scale}x FOG lost its cool forward-scatter order (${JSON.stringify(byName.FOGLit)})`);
    assert(byName.SMKELit?.responseSignature !== byName.FOGLit?.responseSignature
      && JSON.stringify(byName.SMKELit?.responseRgb) !== JSON.stringify(byName.FOGLit?.responseRgb),
    `E13 ${scale}x Smoke and FOG shoulders lost species-distinct RGB response (${JSON.stringify({ smoke: byName.SMKELit, fog: byName.FOGLit })})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0), `E13 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    const protectedControls = responses.slice(targets.length);
    assert(protectedControls.every((sample) => sample.rgbPeak === 0),
      `E13 ${scale}x escaped sparse/gap/contact/wall/hole/channel/blank or protected-gas controls (${JSON.stringify(protectedControls)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeGasLightVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({ scale, backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      rawControls: disabled.rawControls, responses, exactRepeatedOff: true, screenshots });
  }
  for (const code of ['SMKE', 'FOG']) {
    const lit = scales.map(({ responses }) => responses.find(({ name }) => name === `${code}Lit`));
    const spread = (values) => Math.max(...values) - Math.min(...values);
    assert(spread(lit.map(({ rgbRms }) => rgbRms)) <= 0.20
      && spread(lit.map(({ chromaRms }) => chromaRms)) <= 0.20
      && spread(lit.map(({ signedMean }) => signedMean)) <= 0.22
      && [0, 1, 2].every((channel) => spread(lit.map(({ responseRgb }) => responseRgb[channel])) <= 0.25),
    `E13 ${code} spectral shoulder drifted with render scale (${JSON.stringify(lit)})`);
  }
  const trueEightX = await auditEightXGasLightVfxExclusion(cdp, dpr);
  return { scales, trueEightXExcluded: true, trueEightX };
}

async function navigateGasLightVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank', gasLightVfxAudit: '1',
    renderScale: String(scale), renderLook: 'realistic', volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0',
    gasBodyVfx: '1', gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: enabled ? '1' : '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
    return parameters.get('gasLightVfxAudit') === '1' && parameters.get('renderScale') === ${JSON.stringify(String(scale))}
      && parameters.get('renderLook') === 'realistic' && parameters.get('gasLightVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasMotionVfx', 'powderBodyVfx',
        'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx',
        'gasCoreDepthVfx', 'nobleGasBillowVfx', 'smokeSoftnessVfx', 'smokeBillowDepthVfx', 'plasmaCoreVfx']
        .every((name) => parameters.get(name) === '0')
      && parameters.get('gasBodyVfx') === '1'
      && typeof audit?.prepareGasLightVfxFixture === 'function' && typeof audit?.gasLightVfxFixture === 'function';
  })()`), 15_000, `E13 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`), 15_000,
    `E13 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => { const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareGasLightVfxFixture(); return audit.gasLightVfxFixture(); })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
      scale === 4 ? 15_000 : 5_000, `E13 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => gasLightVfxFixtureReady(cdp, fixture), 20_000, `E13 ${label} ${scale}x fixture hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? { look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline, bloomBacking: canvas.dataset.bloomBacking,
      gasLightVfx: canvas.dataset.gasLightVfx, volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx, gasBodyVfx: canvas.dataset.gasBodyVfx, gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx, powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx, translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx, wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx, plasmaCoreVfx: canvas.dataset.plasmaCoreVfx,
      nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      smokeSoftnessVfx: canvas.dataset.smokeSoftnessVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
      solidBodyVfx: canvas.dataset.solidBodyVfx, platinumBodyVfx: canvas.dataset.platinumBodyVfx } : undefined; })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline?.state === 'active' && hdrPipeline?.bloomBacking === expectedBloom
    && hdrPipeline?.gasBodyVfx === 'active'
    && ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasMotionVfx', 'powderBodyVfx', 'powderLightVfx',
      'powderSolidContactVfx', 'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx',
      'nobleGasBillowVfx', 'smokeSoftnessVfx', 'smokeBillowDepthVfx', 'plasmaCoreVfx']
      .every((name) => hdrPipeline[name] === 'inactive')
    && hdrPipeline?.gasCoreDepthVfx === 'inactive' && hdrPipeline?.gasLightVfx === (enabled ? 'active' : 'inactive'),
  `E13 ${label} ${scale}x HDR/selector state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(cdp, `E13 ${label} ${scale}x framebuffer`, scale === 4 ? 20_000 : undefined);
  return { fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp), rawControls: await sampleVolumeVfxRawWorldPixels(cdp, gasLightVfxRawControlPoints(fixture)), hdrPipeline };
}

async function gasLightVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => { const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    if (typeof audit.gasIdentityStyle !== 'function') throw new Error('E13 gas identity style accessor unavailable');
    const inRect = (point, rect) => point.x >= rect.x && point.x < rect.x + rect.width && point.y >= rect.y && point.y < rect.y + rect.height;
    const centre = (rect) => ({ x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2) });
    const cards = fixture.cards.every((card) => {
      for (let y = card.body.y; y < card.body.y + card.body.height; y++) for (let x = card.body.x; x < card.body.x + card.body.width; x++) {
        const empty = inRect({ x, y }, card.authoredHole) || inRect({ x, y }, card.openChannel);
        if (audit.cell(x, y) !== (empty ? 0 : card.material)) return false;
      }
      return audit.cell(card.emitter.x + 1, card.emitter.y + 1) === card.emitter.material;
    });
    const protectedGases = fixture.protectedGases.every((card) => audit.cell(card.probe.x, card.probe.y) === card.material
      && audit.cell(card.emitter.x + 1, card.emitter.y + 1) === card.emitter.material);
    const chains = fixture.sparseChains.every((chain) => chain.carriers.every((point) => audit.cell(point.x, point.y) === chain.material)
      && audit.cell(chain.midpoint.x, chain.midpoint.y) === 0 && audit.cell(chain.gap.x, chain.gap.y) === 0
      && audit.cell(chain.isolated.x, chain.isolated.y) === chain.material);
    const styles = fixture.cards.every((card) => {
      const expected = card.code === 'SMKE' ? 1 : 10;
      return audit.gasIdentityStyle(centre(card.litShoulder).x, centre(card.litShoulder).y) === expected
        && audit.gasIdentityStyle(centre(card.unlitShoulder).x, centre(card.unlitShoulder).y) === expected
        && audit.gasIdentityStyle(centre(card.deepCore).x, centre(card.deepCore).y) === expected;
    }) && fixture.protectedGases.every((card) => {
      const style = audit.gasIdentityStyle(card.probe.x, card.probe.y);
      return style !== 1 && style !== 10;
    }) && audit.gasIdentityStyle(fixture.solidContact.gasProbe.x, fixture.solidContact.gasProbe.y) === 0
      && audit.gasIdentityStyle(fixture.liquidContact.gasProbe.x, fixture.liquidContact.gasProbe.y) === 0
      && audit.gasIdentityStyle(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === 0;
    return cards && protectedGases && chains
      && audit.cell(fixture.solidContact.gasProbe.x, fixture.solidContact.gasProbe.y) === fixture.cards[0].material
      && audit.cell(fixture.liquidContact.gasProbe.x, fixture.liquidContact.gasProbe.y) === fixture.cards[1].material
      && audit.cell(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.cards[0].material
      && audit.wall(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.conductiveWall
      && audit.cell(fixture.guardedBlank.x, fixture.guardedBlank.y) === 0 && styles;
  })()`);
}

function gasLightVfxTargetRegions(fixture) {
  return fixture.cards.flatMap((card) => [
    { name: `${card.code}Lit`, target: true, x: card.litShoulder.x + card.litShoulder.width / 2, y: card.litShoulder.y + card.litShoulder.height / 2, radius: 3 },
    { name: `${card.code}Unlit`, target: true, x: card.unlitShoulder.x + card.unlitShoulder.width / 2, y: card.unlitShoulder.y + card.unlitShoulder.height / 2, radius: 3 },
    { name: `${card.code}Core`, target: true, x: card.deepCore.x + card.deepCore.width / 2, y: card.deepCore.y + card.deepCore.height / 2, radius: 3 },
  ]);
}

function gasLightVfxControlRegions(fixture) {
  const point = (name, candidate) => ({ name, x: candidate.x + 0.5, y: candidate.y + 0.5, radius: 0 });
  const rect = (name, candidate) => ({ name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2), radiusY: Math.max(0.35, candidate.height / 2 - 0.2) });
  return [
    ...fixture.cards.flatMap((card) => [rect(`${card.code}Hole`, card.authoredHole), rect(`${card.code}Channel`, card.openChannel)]),
    ...fixture.protectedGases.map((card) => point(`protected${card.code}`, card.probe)),
    ...fixture.sparseChains.flatMap((chain) => [point(`${chain.code}Carrier`, chain.carriers[0]), point(`${chain.code}Midpoint`, chain.midpoint), point(`${chain.code}Gap`, chain.gap), point(`${chain.code}Isolated`, chain.isolated)]),
    point('solidContact', fixture.solidContact.gasProbe), point('liquidContact', fixture.liquidContact.gasProbe),
    point('nativeWall', fixture.nativeWall.wallAnchor), rect('guardedBlank', fixture.guardedBlank),
  ];
}

function gasLightVfxRawControlPoints(fixture) {
  const point = (name, candidate) => ({ name, x: Math.floor(candidate.x), y: Math.floor(candidate.y) });
  const rectPoint = (name, rect) => point(name, { x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2) });
  return [
    ...fixture.cards.flatMap((card) => [rectPoint(`${card.code}Hole`, card.authoredHole), rectPoint(`${card.code}Channel`, card.openChannel)]),
    ...fixture.cards.flatMap((card) => [rectPoint(`${card.code}Unlit`, card.unlitShoulder), rectPoint(`${card.code}Core`, card.deepCore)]),
    ...fixture.protectedGases.map((card) => point(`protected${card.code}`, card.probe)),
    ...fixture.sparseChains.flatMap((chain) => [point(`${chain.code}Carrier`, chain.carriers[0]), point(`${chain.code}Midpoint`, chain.midpoint), point(`${chain.code}Gap`, chain.gap), point(`${chain.code}Isolated`, chain.isolated)]),
    point('solidContact', fixture.solidContact.gasProbe), point('liquidContact', fixture.liquidContact.gasProbe),
    point('nativeWall', fixture.nativeWall.wallAnchor), rectPoint('guardedBlank', fixture.guardedBlank),
  ];
}

async function writeGasLightVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e13-gas-light-${scale}x-off`),
    on: variantScreenshotPath(source, `e13-gas-light-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXGasLightVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({ scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8', auditStage: 'eight-gas-light',
    renderLook: 'realistic', volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1', gasMotionVfx: '0',
    powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0', organicSubsurfaceVfx: '0',
    wetSedimentVfx: '0', gasLightVfx: '1', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0' });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => { const p = new URLSearchParams(location.search); return p.get('renderScale') === '8'
    && p.get('auditStage') === 'eight-gas-light' && p.get('gasLightVfx') === '1'
    && p.get('liquidSolidMeniscusVfx') === '0' && p.get('nobleGasBillowVfx') === '0'
    && p.get('smokeSoftnessVfx') === '0' && p.get('smokeBillowDepthVfx') === '0'
    && Boolean(window.__ANIFOR_INPUT_AUDIT__); })()`),
  remainingDeadlineMs(deadline, 'true-8x E13 input audit API'), 'true-8x E13 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E13', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E13');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined, 45_000, 'true-8x E13 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
    `true-8x E13 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas'); return canvas ? {
    renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
    bloomBacking: canvas.dataset.bloomBacking ?? null, gasLightVfx: canvas.dataset.gasLightVfx,
    liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx,
    nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
    smokeSoftnessVfx: canvas.dataset.smokeSoftnessVfx,
    smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx } : undefined; })()`);
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic' && isolation.state === 'inactive'
    && isolation.reason === 'scale-8' && isolation.bloomBacking === null && isolation.gasLightVfx === 'inactive'
    && isolation.liquidSolidMeniscusVfx === 'inactive'
    && isolation.nobleGasBillowVfx === 'inactive'
    && isolation.smokeSoftnessVfx === 'inactive'
    && isolation.smokeBillowDepthVfx === 'inactive',
  `true-8x E13 isolation failed (${JSON.stringify(isolation)})`);
  const timing = await auditWebGLPresentationTiming(cdp, 1, 12_000, 30_000, 1);
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence' || timing.source === 'gpu-finish',
    `true-8x E13 did not complete GPU work (${JSON.stringify(timing)})`);
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`, isolation, timing };
}

/** E14: exact liquid-side ordinary-solid contact optics over existing fields. */
const LIQUID_SOLID_MENISCUS_VFX_ACCEPTANCE = {
  1: {
    WATR_METL_horizontal: { rgbRms: [2.8, 4.8], chromaRms: [0.9, 2.8], rgbPeak: [8, 16], signedMean: [-3.5, -1.7] },
    OIL_GLAS_horizontal: { rgbRms: [0.8, 1.9], chromaRms: [0.6, 1.8], rgbPeak: [3, 8], signedMean: [-0.9, -0.1] },
    ACID_BRCK_horizontal: { rgbRms: [1.2, 2.7], chromaRms: [0.9, 2.4], rgbPeak: [4, 10], signedMean: [-0.7, -0.03] },
    WATR_METL_vertical: { rgbRms: [2.5, 4.6], chromaRms: [1.0, 2.6], rgbPeak: [7, 14], signedMean: [-3.4, -1.6] },
    OIL_GLAS_vertical: { rgbRms: [0.85, 2.0], chromaRms: [0.55, 1.7], rgbPeak: [3, 8], signedMean: [-0.95, -0.12] },
    ACID_BRCK_vertical: { rgbRms: [2.5, 4.8], chromaRms: [1.8, 4.0], rgbPeak: [7, 15], signedMean: [-1.4, -0.12] },
  },
  2: {
    WATR_METL_horizontal: { rgbRms: [2.4, 4.3], chromaRms: [1.1, 2.6], rgbPeak: [8, 15], signedMean: [-2.5, -0.8] },
    OIL_GLAS_horizontal: { rgbRms: [0.7, 1.7], chromaRms: [0.5, 1.5], rgbPeak: [3, 7], signedMean: [-0.7, -0.05] },
    ACID_BRCK_horizontal: { rgbRms: [1.2, 2.6], chromaRms: [0.9, 2.3], rgbPeak: [4, 10], signedMean: [-0.6, -0.02] },
    WATR_METL_vertical: { rgbRms: [1.0, 2.4], chromaRms: [0.45, 1.5], rgbPeak: [3, 9], signedMean: [-1.5, -0.25] },
    OIL_GLAS_vertical: { rgbRms: [0.75, 1.8], chromaRms: [0.5, 1.5], rgbPeak: [3, 8], signedMean: [-0.8, -0.05] },
    ACID_BRCK_vertical: { rgbRms: [2.4, 4.7], chromaRms: [1.7, 3.8], rgbPeak: [8, 15], signedMean: [-1.1, -0.08] },
  },
  4: {
    WATR_METL_horizontal: { rgbRms: [2.3, 4.1], chromaRms: [1.0, 2.5], rgbPeak: [7, 14], signedMean: [-2.4, -0.75] },
    OIL_GLAS_horizontal: { rgbRms: [0.7, 1.7], chromaRms: [0.5, 1.5], rgbPeak: [3, 7], signedMean: [-0.65, -0.03] },
    ACID_BRCK_horizontal: { rgbRms: [1.1, 2.5], chromaRms: [0.8, 2.2], rgbPeak: [4, 10], signedMean: [-0.55, -0.01] },
    WATR_METL_vertical: { rgbRms: [0.45, 1.45], chromaRms: [0.2, 0.9], rgbPeak: [2, 6], signedMean: [-0.9, -0.08] },
    OIL_GLAS_vertical: { rgbRms: [0.75, 1.8], chromaRms: [0.5, 1.5], rgbPeak: [3, 8], signedMean: [-0.8, -0.05] },
    ACID_BRCK_vertical: { rgbRms: [1.6, 3.6], chromaRms: [1.2, 3.0], rgbPeak: [5, 12], signedMean: [-0.8, -0.04] },
  },
};

async function auditLiquidSolidMeniscusVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateLiquidSolidMeniscusVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture),
    `E14 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E14 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl', `E14 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E14 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E14 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E14 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E14 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E14 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E14 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing, `E14 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing, `E14 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E14 ${scale}x changed an exact protected raw control`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E14 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = liquidSolidMeniscusVfxTargetRegions(disabled.fixture);
    const controls = liquidSolidMeniscusVfxControlRegions(disabled.fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data, refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeLiquidSolidMeniscusVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    const accepted = LIQUID_SOLID_MENISCUS_VFX_ACCEPTANCE[scale];
    assert(targetResponses.length === 6 && targetResponses.every((sample) => {
      const bounds = accepted[sample.name];
      return bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1];
    }),
    `E14 ${scale}x liquid-side contact response escaped calibrated bounds (${JSON.stringify({
      targets: targetResponses, liquidFieldSupport: disabled.liquidFieldSupport,
    })})`);
    const waterResponses = targetResponses.filter((sample) => sample.name.startsWith('WATR_'));
    const oilResponses = targetResponses.filter((sample) => sample.name.startsWith('OIL_'));
    const acidResponses = targetResponses.filter((sample) => sample.name.startsWith('ACID_'));
    assert(waterResponses.every((sample) => sample.responseRgb[0] < -0.25
      && sample.responseRgb[1] < -0.30
      && Math.abs(sample.responseRgb[1]) > Math.abs(sample.responseRgb[2]) + 0.15)
      && oilResponses.every((sample) => sample.responseRgb[2] < -0.45
        && Math.abs(sample.responseRgb[2]) > Math.abs(sample.responseRgb[1]) * 1.25)
      && acidResponses.every((sample) => sample.responseRgb[0] < -0.75
        && sample.responseRgb[1] >= 0.02 && sample.responseRgb[2] < -0.65),
    `E14 ${scale}x lost Water/Oil/Acid optical-family separation (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.every((sample) => sample.name === 'mixedTripleContact'
      ? (scale === 1 ? sample.rgbPeak <= 1 : sample.rgbPeak === 0)
      : sample.rgbPeak === 0),
      `E14 ${scale}x escaped deep-core/air/foreign/topology/wall controls (${JSON.stringify(controlResponses)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E14 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    scales.push({ scale, backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      rawControls: disabled.rawControls, responses, exactRepeatedOff: true, screenshots });
  }
  const trueEightX = await auditEightXLiquidSolidMeniscusVfxExclusion(cdp, dpr);
  return { scales, trueEightXExcluded: true, trueEightX };
}

async function navigateLiquidSolidMeniscusVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    liquidSolidMeniscusVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '1', liquidSurfaceVfx: '0', gasBodyVfx: '0', gasMotionVfx: '0',
    powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0', gasCoreDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0', acidBodyVfx: '0',
    liquidSolidMeniscusVfx: enabled ? '1' : '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const parameters = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
    return parameters.get('liquidSolidMeniscusVfxAudit') === '1'
      && parameters.get('renderScale') === ${JSON.stringify(String(scale))}
      && parameters.get('renderLook') === 'realistic' && parameters.get('liquidBodyVfx') === '1'
      && parameters.get('liquidSolidMeniscusVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && ['volumeVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx', 'powderBodyVfx',
        'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx', 'organicSubsurfaceVfx',
        'wetSedimentVfx', 'gasLightVfx', 'gasCoreDepthVfx', 'plasmaCoreVfx'].every((name) => parameters.get(name) === '0')
      && typeof audit?.prepareLiquidSolidMeniscusVfxFixture === 'function'
      && typeof audit?.liquidSolidMeniscusVfxFixture === 'function';
  })()`), 15_000, `E14 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  15_000, `E14 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(async () => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setLiquidOpticalDepth(true);
    for (let pass = 0; pass < 7; pass++) {
      audit.prepareLiquidSolidMeniscusVfxFixture();
      await new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 70)));
    }
    return audit.liquidSolidMeniscusVfxFixture();
  })()`);
  try {
    await waitFor(() => liquidSolidMeniscusVfxFixtureReady(cdp, fixture), 20_000,
      `E14 ${label} ${scale}x fixture/liquid-depth hydration`);
  } catch (error) {
    const diagnostics = await liquidSolidMeniscusVfxFixtureDiagnostics(cdp, fixture);
    throw new Error(`${error instanceof Error ? error.message : error}; ${JSON.stringify(diagnostics)}`);
  }
  const liquidFieldSupport = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    return fixture.cards.map((card) => ({ name: card.code + '_' + card.orientation,
      contact: audit.liquidFieldAlpha(card.liquidContactProbe.x, card.liquidContactProbe.y),
      core: audit.liquidFieldAlpha(card.deepCoreProbe.x, card.deepCoreProbe.y) }));
  })()`);
  const hdrPipeline = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline, bloomBacking: canvas.dataset.bloomBacking,
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx, liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx,
      gasBodyVfx: canvas.dataset.gasBodyVfx, gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx, powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx, translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx, wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx,
      solidBodyVfx: canvas.dataset.solidBodyVfx,
      platinumBodyVfx: canvas.dataset.platinumBodyVfx,
    } : undefined; })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline?.state === 'active'
    && hdrPipeline?.bloomBacking === expectedBloom && hdrPipeline?.liquidBodyVfx === 'active'
    && ['volumeVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx', 'powderBodyVfx',
      'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx', 'organicSubsurfaceVfx',
      'wetSedimentVfx', 'gasLightVfx', 'gasCoreDepthVfx', 'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx'].every((name) => hdrPipeline[name] === 'inactive')
    && hdrPipeline?.liquidSolidMeniscusVfx === (enabled ? 'active' : 'inactive'),
  `E14 ${label} ${scale}x HDR/selector state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(cdp,
    `E14 ${label} ${scale}x framebuffer`, scale === 4 ? 20_000 : undefined);
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, liquidSolidMeniscusVfxRawControlPoints(fixture)),
    hdrPipeline, liquidFieldSupport,
  };
}

async function liquidSolidMeniscusVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (audit.cell(x, y) !== material) return false;
      }
      return true;
    };
    const cards = fixture.cards.every((card) => exactRect(card.liquid, card.liquidMaterial)
      && exactRect(card.solid, card.solidMaterial) && exactRect(card.airMeniscus, card.liquidMaterial)
      && audit.cell(card.liquidContactProbe.x, card.liquidContactProbe.y) === card.liquidMaterial
      && audit.cell(card.solidContactProbe.x, card.solidContactProbe.y) === card.solidMaterial
      && audit.cell(card.deepCoreProbe.x, card.deepCoreProbe.y) === card.liquidMaterial
      && audit.presentationAuxiliary(card.liquidContactProbe.x, card.liquidContactProbe.y) > 0
      && audit.presentationAuxiliary(card.deepCoreProbe.x, card.deepCoreProbe.y) > 0
      && audit.liquidFieldAlpha(card.liquidContactProbe.x, card.liquidContactProbe.y) >= 96
      && audit.liquidFieldAlpha(card.deepCoreProbe.x, card.deepCoreProbe.y) >= 160);
    const controls = fixture.ownerControls;
    return cards
      && audit.cell(fixture.unlikeLiquidSeam.leftProbe.x, fixture.unlikeLiquidSeam.leftProbe.y) === 2
      && audit.cell(fixture.unlikeLiquidSeam.rightProbe.x, fixture.unlikeLiquidSeam.rightProbe.y) === 8
      && exactRect(fixture.nativeWall.liquid, 2)
      && audit.wall(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.conductiveWall
      && exactRect(fixture.lava, 11)
      && exactRect(fixture.powderContact.liquid, 2) && exactRect(fixture.powderContact.powder, 1)
      && exactRect(fixture.gasContact.liquid, 2) && exactRect(fixture.gasContact.gas, 5)
      && exactRect(fixture.strand, 2) && exactRect(fixture.droplet, 2)
      && exactRect(fixture.perforatedLiquid.authoredHole, 0) && exactRect(fixture.perforatedLiquid.openChannel, 0)
      && exactRect(controls.traitLike, 2) && exactRect(controls.traitLike.owner, 126)
      && audit.cell(controls.traitLike.liquidProbe.x, controls.traitLike.liquidProbe.y) === 2
      && exactRect(controls.emissive, 2) && exactRect(controls.emissive.owner, 4)
      && audit.cell(controls.emissive.liquidProbe.x, controls.emissive.liquidProbe.y) === 2
      && exactRect(fixture.mixedTripleContact.liquid, 2)
      && exactRect(fixture.mixedTripleContact.solid, 23)
      && exactRect(fixture.mixedTripleContact.foreign, 5)
      && audit.cell(fixture.mixedTripleContact.liquidProbe.x,
        fixture.mixedTripleContact.liquidProbe.y) === 2
      && exactRect(fixture.guardedBlank, 0);
  })()`);
}

async function liquidSolidMeniscusVfxFixtureDiagnostics(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    return {
      liquidFieldMethod: typeof audit?.liquidFieldAlpha,
      cards: fixture.cards.map((card) => ({ name: card.code + '_' + card.orientation,
        liquid: audit.cell(card.liquidContactProbe.x, card.liquidContactProbe.y),
        solid: audit.cell(card.solidContactProbe.x, card.solidContactProbe.y),
        auxiliaryContact: audit.presentationAuxiliary(card.liquidContactProbe.x, card.liquidContactProbe.y),
        auxiliaryCore: audit.presentationAuxiliary(card.deepCoreProbe.x, card.deepCoreProbe.y),
        fieldContact: audit.liquidFieldAlpha?.(card.liquidContactProbe.x, card.liquidContactProbe.y),
        fieldCore: audit.liquidFieldAlpha?.(card.deepCoreProbe.x, card.deepCoreProbe.y) })),
      seam: [audit.cell(fixture.unlikeLiquidSeam.leftProbe.x, fixture.unlikeLiquidSeam.leftProbe.y),
        audit.cell(fixture.unlikeLiquidSeam.rightProbe.x, fixture.unlikeLiquidSeam.rightProbe.y)],
      triple: [audit.cell(fixture.mixedTripleContact.liquidProbe.x, fixture.mixedTripleContact.liquidProbe.y),
        audit.cell(fixture.mixedTripleContact.solid.x, fixture.mixedTripleContact.solid.y),
        audit.cell(fixture.mixedTripleContact.foreign.x, fixture.mixedTripleContact.foreign.y)],
    };
  })()`);
}

function liquidSolidMeniscusVfxTargetRegions(fixture) {
  return fixture.cards.map((card) => ({ name: `${card.code}_${card.orientation}`, target: true,
    x: card.liquidContactProbe.x + 0.5, y: card.liquidContactProbe.y + 0.5,
    radiusX: card.orientation === 'horizontal' ? 18 : 2, radiusY: card.orientation === 'horizontal' ? 2 : 18 }));
}

function liquidSolidMeniscusVfxControlRegions(fixture) {
  const point = (name, candidate) => ({ name, x: candidate.x + 0.5, y: candidate.y + 0.5, radius: 0 });
  const rect = (name, candidate) => ({ name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2), radiusY: Math.max(0.35, candidate.height / 2 - 0.2) });
  return [
    ...fixture.cards.flatMap((card) => [point(`${card.code}_${card.orientation}_deepCore`, card.deepCoreProbe),
      point(`${card.code}_${card.orientation}_solidSide`, card.orientation === 'horizontal'
        ? { x: card.solidContactProbe.x, y: card.solidContactProbe.y + 2 }
        : { x: card.solidContactProbe.x + 2, y: card.solidContactProbe.y }),
      rect(`${card.code}_${card.orientation}_air`, card.airMeniscus)]),
    point('unlikeLiquidSeamLeft', fixture.unlikeLiquidSeam.leftProbe),
    point('unlikeLiquidSeamRight', fixture.unlikeLiquidSeam.rightProbe),
    rect('nativeWallBody', fixture.nativeWall.liquid), point('nativeWall', fixture.nativeWall.wallAnchor),
    rect('lava', fixture.lava), point('powderContact', fixture.powderContact.liquidProbe),
    point('gasContact', fixture.gasContact.liquidProbe), rect('strand', fixture.strand), rect('droplet', fixture.droplet),
    rect('authoredHole', fixture.perforatedLiquid.authoredHole),
    point('authoredHoleLip', { x: fixture.perforatedLiquid.authoredHole.x - 1,
      y: fixture.perforatedLiquid.authoredHole.y + Math.floor(fixture.perforatedLiquid.authoredHole.height / 2) }),
    rect('openChannel', fixture.perforatedLiquid.openChannel),
    point('openChannelLip', { x: fixture.perforatedLiquid.openChannel.x - 1,
      y: fixture.perforatedLiquid.openChannel.y + fixture.perforatedLiquid.openChannel.height - 1 }),
    rect('traitLike', fixture.ownerControls.traitLike),
    point('traitLikeProbe', fixture.ownerControls.traitLike.liquidProbe),
    rect('emissive', fixture.ownerControls.emissive),
    point('emissiveProbe', fixture.ownerControls.emissive.liquidProbe),
    point('mixedTripleContact', fixture.mixedTripleContact.liquidProbe),
    rect('guardedBlank', fixture.guardedBlank),
  ];
}

function liquidSolidMeniscusVfxRawControlPoints(fixture) {
  const rectPoint = (name, rect) => ({ name, x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2) });
  return [
    ...fixture.cards.flatMap((card) => [{ name: `${card.code}_${card.orientation}_deepCore`, ...card.deepCoreProbe },
      { name: `${card.code}_${card.orientation}_solidSide`, ...card.solidContactProbe },
      rectPoint(`${card.code}_${card.orientation}_air`, card.airMeniscus)]),
    { name: 'unlikeLiquidSeamLeft', ...fixture.unlikeLiquidSeam.leftProbe },
    { name: 'unlikeLiquidSeamRight', ...fixture.unlikeLiquidSeam.rightProbe },
    { name: 'nativeWall', ...fixture.nativeWall.wallAnchor },
    rectPoint('nativeWallBody', fixture.nativeWall.liquid),
    rectPoint('lava', fixture.lava), { name: 'powderContact', ...fixture.powderContact.liquidProbe },
    { name: 'gasContact', ...fixture.gasContact.liquidProbe }, rectPoint('strand', fixture.strand),
    rectPoint('droplet', fixture.droplet), rectPoint('authoredHole', fixture.perforatedLiquid.authoredHole),
    { name: 'authoredHoleLip', x: fixture.perforatedLiquid.authoredHole.x - 1,
      y: fixture.perforatedLiquid.authoredHole.y + Math.floor(fixture.perforatedLiquid.authoredHole.height / 2) },
    rectPoint('openChannel', fixture.perforatedLiquid.openChannel),
    { name: 'openChannelLip', x: fixture.perforatedLiquid.openChannel.x - 1,
      y: fixture.perforatedLiquid.openChannel.y + fixture.perforatedLiquid.openChannel.height - 1 },
    { name: 'traitLikeProbe', ...fixture.ownerControls.traitLike.liquidProbe },
    { name: 'emissiveProbe', ...fixture.ownerControls.emissive.liquidProbe },
    { name: 'mixedTripleContact', ...fixture.mixedTripleContact.liquidProbe },
    rectPoint('guardedBlank', fixture.guardedBlank),
  ];
}

async function writeLiquidSolidMeniscusVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e14-liquid-solid-meniscus-${scale}x-off`),
    on: variantScreenshotPath(source, `e14-liquid-solid-meniscus-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXLiquidSolidMeniscusVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8', auditStage: 'eight-liquid-solid-meniscus',
    renderLook: 'realistic', volumeVfx: '0', liquidBodyVfx: '1', liquidSurfaceVfx: '0', gasBodyVfx: '0', gasMotionVfx: '0',
    powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '1', gasCoreDepthVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0', acidBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => { const p = new URLSearchParams(location.search); return p.get('renderScale') === '8'
    && p.get('auditStage') === 'eight-liquid-solid-meniscus' && p.get('liquidSolidMeniscusVfx') === '1'
    && Boolean(window.__ANIFOR_INPUT_AUDIT__); })()`),
  remainingDeadlineMs(deadline, 'true-8x E14 input audit API'), 'true-8x E14 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E14', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E14');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined, 45_000, 'true-8x E14 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
    `true-8x E14 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas'); return canvas ? {
    renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
    reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking ?? null,
    liquidBodyVfx: canvas.dataset.liquidBodyVfx, liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx,
  } : undefined; })()`);
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && isolation.liquidBodyVfx === 'inactive' && isolation.liquidSolidMeniscusVfx === 'inactive',
  `true-8x E14 isolation failed (${JSON.stringify(isolation)})`);
  const timing = await auditWebGLPresentationTiming(cdp, 1, 12_000, 30_000, 1);
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence' || timing.source === 'gpu-finish',
    `true-8x E14 did not complete GPU work (${JSON.stringify(timing)})`);
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`, isolation, timing };
}

/** E37: exact Metal-side Water contact spectrum over the E03/E14/E17 stack. */
const METAL_WATER_CONTACT_VFX_ACCEPTANCE = Object.freeze({
  1: Object.freeze({
    WATR_METL_horizontal_Metal: Object.freeze({
      rgbRms: Object.freeze([0.75, 1.2]), chromaRms: Object.freeze([0.75, 1.2]),
      rgbPeak: Object.freeze([2, 3]), coverage: Object.freeze([0, 0.02]),
      responseRgb: Object.freeze([
        Object.freeze([0.6, 1.05]), Object.freeze([-0.05, 0.25]), Object.freeze([-1.25, -0.75]),
      ]),
    }),
    WATR_METL_vertical_Metal: Object.freeze({
      rgbRms: Object.freeze([0.7, 1.1]), chromaRms: Object.freeze([0.7, 1.15]),
      rgbPeak: Object.freeze([2, 3]), coverage: Object.freeze([0, 0.02]),
      responseRgb: Object.freeze([
        Object.freeze([0.65, 1.1]), Object.freeze([0, 0.35]), Object.freeze([-1.3, -0.8]),
      ]),
    }),
  }),
  2: Object.freeze({
    WATR_METL_horizontal_Metal: Object.freeze({
      rgbRms: Object.freeze([0.9, 1.25]), chromaRms: Object.freeze([0.92, 1.25]),
      rgbPeak: Object.freeze([2, 3]), coverage: Object.freeze([0, 0.02]),
      responseRgb: Object.freeze([
        Object.freeze([0.65, 1.15]), Object.freeze([0, 0.5]), Object.freeze([-1.1, -0.55]),
      ]),
    }),
    WATR_METL_vertical_Metal: Object.freeze({
      rgbRms: Object.freeze([0.65, 1]), chromaRms: Object.freeze([0.65, 1]),
      rgbPeak: Object.freeze([2, 3]), coverage: Object.freeze([0, 0.02]),
      responseRgb: Object.freeze([
        Object.freeze([0.5, 0.95]), Object.freeze([-0.05, 0.4]), Object.freeze([-0.85, -0.4]),
      ]),
    }),
  }),
  4: Object.freeze({
    WATR_METL_horizontal_Metal: Object.freeze({
      rgbRms: Object.freeze([0.4, 0.75]), chromaRms: Object.freeze([0.4, 0.8]),
      rgbPeak: Object.freeze([1, 2]), coverage: Object.freeze([0, 0.02]),
      responseRgb: Object.freeze([
        Object.freeze([0.3, 0.7]), Object.freeze([-0.05, 0.3]), Object.freeze([-0.6, -0.2]),
      ]),
    }),
    WATR_METL_vertical_Metal: Object.freeze({
      rgbRms: Object.freeze([0.8, 1.25]), chromaRms: Object.freeze([0.82, 1.3]),
      rgbPeak: Object.freeze([2, 3]), coverage: Object.freeze([0, 0.02]),
      responseRgb: Object.freeze([
        Object.freeze([0.55, 1.1]), Object.freeze([0, 0.55]), Object.freeze([-1.1, -0.55]),
      ]),
    }),
  }),
});

async function auditMetalWaterContactVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateMetalWaterContactVfxState(
        cdp, mode, scale, enabled, key,
      );
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture),
    `E37 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E37 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E37 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active',
        `E37 ${label} ${scale}x HDR pipeline was not active (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E37 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E37 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E37 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic,
      `E37 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E37 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E37 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E37 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E37 ${scale}x changed an exact protected raw control`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E37 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = metalWaterContactVfxTargetRegions(disabled.fixture);
    const controls = metalWaterContactVfxControlRegions(disabled.fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const scaleBounds = METAL_WATER_CONTACT_VFX_ACCEPTANCE[scale];
    assert(targetResponses.length === 2 && targetResponses.every((sample) => {
      const bounds = scaleBounds?.[sample.name];
      return bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0]
        && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        // The accepted edge is intentionally near-luminance-neutral; coverage
        // can remain zero while the signed warm/cool spectrum is plainly present.
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.responseRgb.every((channel, index) => (
          channel >= bounds.responseRgb[index][0] && channel <= bounds.responseRgb[index][1]
        ));
    }),
    `E37 ${scale}x Metal-side Water contact response escaped its frozen per-scale spectrum (${JSON.stringify(targetResponses)})`);
    // Stable-page capture resampling may carry one byte into these exact
    // adjacent probes. The raw semantic/world controls above remain byte exact;
    // keep this allowance scale-specific so a new filtered footprint cannot hide.
    const oneByteNeighbourControls = new Set(scale === 1
      ? ['WATR_METL_horizontal_liquidSide', 'mixedTripleSolid']
      : ['mixedTripleSolid']);
    assert(controlResponses.every((sample) => oneByteNeighbourControls.has(sample.name)
      ? sample.rgbPeak <= 1 : sample.rgbPeak === 0),
      `E37 ${scale}x escaped liquid/foreign/deep/topology/raw controls (${JSON.stringify(controlResponses)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E37 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeMetalWaterContactVfxScreenshots(
        screenshotRequest, scale, disabled, enabled,
      ) : undefined;
    scales.push({
      scale, backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      rawControls: disabled.rawControls, targetResponses, controlResponses,
      responses, exactRepeatedOff: true, screenshots,
    });
  }
  let crossScaleConsistency;
  if (requestedScales.length === VOLUME_VFX_SCALES.length
    && requestedScales.every((scale, index) => scale === VOLUME_VFX_SCALES[index])) {
    const names = [
      'WATR_METL_horizontal_Metal', 'WATR_METL_vertical_Metal',
    ];
    const targetRatios = names.map((name) => {
      const strengths = scales.map((entry) => (
        entry.targetResponses.find((sample) => sample.name === name)?.rgbRms ?? 0
      ));
      return { name, strengths, ratio: Math.max(...strengths) / Math.min(...strengths) };
    });
    const orientationRatios = scales.map((entry) => {
      const strengths = entry.targetResponses.map(({ rgbRms }) => rgbRms);
      return { scale: entry.scale, ratio: Math.max(...strengths) / Math.min(...strengths) };
    });
    assert(targetRatios.every(({ ratio }) => Number.isFinite(ratio) && ratio <= 2.2)
      && orientationRatios.every(({ ratio }) => Number.isFinite(ratio) && ratio <= 2.2),
    `E37 Metal/Water contact strength drifted across scale or orientation (${JSON.stringify({
      targetRatios, orientationRatios,
    })})`);
    crossScaleConsistency = { targetRatios, orientationRatios, maximumRatio: 2.2 };
  }
  const dependencyProbes = await auditMetalWaterContactVfxDependencies(cdp, mode);
  const trueEightX = await auditEightXMetalWaterContactVfxExclusion(cdp, dpr);
  return {
    acceptance: METAL_WATER_CONTACT_VFX_ACCEPTANCE,
    scales, crossScaleConsistency, dependencyProbes, trueEightXExcluded: true, trueEightX,
  };
}

async function navigateMetalWaterContactVfxState(
  cdp, mode, scale, enabled, label, {
    waterMetalTransmission = false,
    waterMetalSeparation = false,
    waterMetalFresnelSpectrum = false,
    rawControlPoints = metalWaterContactVfxRawControlPoints,
  } = {},
) {
  const query = metalWaterContactVfxQuery({
    scale, enabled, auditStage: 'blank', liquidBody: true,
    liquidSolidMeniscus: true, solidBody: true, waterMetalTransmission, waterMetalSeparation,
    waterMetalFresnelSpectrum,
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const pageTimeout = scale === 4 ? 90_000 : scale === 2 ? 45_000 : 20_000;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
    return p.get('metalWaterContactVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('liquidBodyVfx') === '1'
      && p.get('liquidSolidMeniscusVfx') === '1' && p.get('solidBodyVfx') === '1'
      && p.get('metalWaterContactVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && p.get('waterMetalTransmissionVfx') === ${JSON.stringify(waterMetalTransmission ? '1' : '0')}
      && p.get('waterMetalSeparationVfx') === ${JSON.stringify(waterMetalSeparation ? '1' : '0')}
      && p.get('waterMetalFresnelSpectrumVfx') === ${JSON.stringify(waterMetalFresnelSpectrum ? '1' : '0')}
      && typeof audit?.prepareLiquidSolidMeniscusVfxFixture === 'function'
      && typeof audit?.liquidSolidMeniscusVfxFixture === 'function';
  })()`), pageTimeout, `E37 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  pageTimeout, `E37 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(async () => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.setLiquidOpticalDepth(true); audit.setSolidOpticalDepth(true);
    for (let pass = 0; pass < 7; pass++) {
      audit.prepareLiquidSolidMeniscusVfxFixture();
      await new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 70)));
    }
    return audit.liquidSolidMeniscusVfxFixture();
  })()`);
  try {
    await waitFor(() => metalWaterContactVfxFixtureReady(cdp, fixture), 20_000,
      `E37 ${label} ${scale}x fixture hydration`);
  } catch (error) {
    const diagnostics = await liquidSolidMeniscusVfxFixtureDiagnostics(cdp, fixture);
    throw new Error(`${error instanceof Error ? error.message : error}; ${JSON.stringify(diagnostics)}`);
  }
  const hdrPipeline = await metalWaterContactVfxPipelineState(cdp);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  const inactive = metalWaterContactVfxInactiveSelectorNames().filter(
    (name) => name !== 'waterMetalTransmissionVfx' || !waterMetalTransmission,
  ).filter(
    (name) => name !== 'waterMetalSeparationVfx' || !waterMetalSeparation,
  ).filter(
    (name) => name !== 'waterMetalFresnelSpectrumVfx' || !waterMetalFresnelSpectrum,
  );
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.liquidBodyVfx === 'active'
    && hdrPipeline.liquidSolidMeniscusVfx === 'active' && hdrPipeline.solidBodyVfx === 'active'
    && hdrPipeline.metalWaterContactVfx === (enabled ? 'active' : 'inactive')
    && hdrPipeline.waterMetalTransmissionVfx === (waterMetalTransmission ? 'active' : 'inactive')
    && hdrPipeline.waterMetalSeparationVfx === (waterMetalSeparation ? 'active' : 'inactive')
    && hdrPipeline.waterMetalFresnelSpectrumVfx === (waterMetalFresnelSpectrum ? 'active' : 'inactive')
    && inactive.every((name) => hdrPipeline[name] === 'inactive'),
  `E37 ${label} ${scale}x HDR/selector state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(cdp,
    `E37 ${label} ${scale}x framebuffer`, scale === 4 ? 120_000 : undefined, 1);
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, rawControlPoints(fixture),
    ),
    hdrPipeline,
  };
}

async function metalWaterContactVfxFixtureReady(cdp, fixture) {
  if (!await liquidSolidMeniscusVfxFixtureReady(cdp, fixture)) return false;
  return evaluate(cdp, `(() => {
    const fixture = ${JSON.stringify(fixture)}; const control = fixture.oilMetalControl;
    if (!control) return true;
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const exactRect = (rect, material) => {
      if (!rect) return false;
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    const liquidProbe = control.liquidContactProbe ?? control.liquidProbe;
    const solidProbe = control.solidContactProbe ?? control.solidProbe;
    const liquidMaterial = control.liquid.material ?? control.liquidMaterial ?? 8;
    const solidMaterial = control.solid.material ?? control.solidMaterial ?? 23;
    return exactRect(control.liquid, liquidMaterial)
      && exactRect(control.solid, solidMaterial)
      && liquidProbe && solidProbe
      && audit.cell(liquidProbe.x, liquidProbe.y) === liquidMaterial
      && audit.cell(solidProbe.x, solidProbe.y) === solidMaterial;
  })()`);
}

function metalWaterContactVfxQuery({
  scale, enabled, auditStage, liquidBody, liquidSolidMeniscus, solidBody,
  waterMetalTransmission = false,
  waterMetalSeparation = false,
  waterMetalFresnelSpectrum = false,
}) {
  return new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage,
    metalWaterContactVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: liquidBody ? '1' : '0', liquidSurfaceVfx: '0',
    gasBodyVfx: '0', gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0',
    powderSolidContactVfx: '0', translucentEdgeVfx: '0', organicSubsurfaceVfx: '0',
    wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: liquidSolidMeniscus ? '1' : '0',
    metalWaterContactVfx: enabled ? '1' : '0',
    // E37 explicitly freezes its children in input-audit mode. Focused routes
    // opt into exactly the child currently under measurement.
    waterMetalTransmissionVfx: waterMetalTransmission ? '1' : '0', gasCoreDepthVfx: '0',
    waterMetalSeparationVfx: waterMetalSeparation ? '1' : '0',
    waterMetalSeparationVfxAudit: waterMetalSeparation ? '1' : '0',
    // Every E37/E56/E76 fixture URL explicitly fences the E78 child unless
    // its own focused route opts in. This preserves the frozen parent rails.
    waterMetalFresnelSpectrumVfx: waterMetalFresnelSpectrum ? '1' : '0',
    waterMetalFresnelSpectrumVfxAudit: waterMetalFresnelSpectrum ? '1' : '0',
    nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: solidBody ? '1' : '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0',
    botanicalMesostructureVfx: '0', botanicalPigmentVfx: '0', plantLaminaVfx: '0',
    plantLobeDepthVfx: '0', plantCanopyMassVfx: '0', woodBarkReliefVfx: '0',
    woodTanninVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0',
    rockMesostructureVfx: '0', rockWeatheredFacetVfx: '0', waterBodyVfx: '0',
    waterVolumeRecessionVfx: '0',
  });
}

function metalWaterContactVfxInactiveSelectorNames() {
  return [
    'volumeVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx', 'powderBodyVfx',
    'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx',
    'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx', 'gasCoreDepthVfx',
    'waterMetalTransmissionVfx', 'waterMetalSeparationVfx', 'waterMetalFresnelSpectrumVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
    'smokeBillowDepthVfx', 'plasmaCoreVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
    'botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx',
    'plantLaminaVfx', 'plantLobeDepthVfx', 'plantCanopyMassVfx', 'woodBarkReliefVfx',
    'woodTanninVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
    'rockMesostructureVfx', 'waterBodyVfx', 'waterVolumeRecessionVfx',
  ];
}

async function metalWaterContactVfxPipelineState(cdp, timeoutMs) {
  return evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    const names = ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx',
      'gasMotionVfx', 'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx',
      'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx',
      'liquidSolidMeniscusVfx', 'metalWaterContactVfx', 'waterMetalTransmissionVfx', 'waterMetalSeparationVfx', 'waterMetalFresnelSpectrumVfx', 'gasCoreDepthVfx',
      'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
      'smokeBillowDepthVfx', 'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx',
      'ceramicGlazeVfx', 'botanicalBodyVfx', 'botanicalMesostructureVfx',
      'botanicalPigmentVfx', 'plantLaminaVfx', 'plantLobeDepthVfx',
      'plantCanopyMassVfx', 'woodBarkReliefVfx', 'woodTanninVfx', 'glassBodyVfx',
      'oilBodyVfx', 'rockRoughnessVfx', 'rockMesostructureVfx', 'waterBodyVfx',
      'waterVolumeRecessionVfx'];
    return canvas ? { renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      ...Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])) } : undefined;
  })()`, timeoutMs);
}

function metalWaterContactVfxStrip(name, probe, orientation) {
  return {
    name, x: probe.x + 0.5, y: probe.y + 0.5,
    radiusX: orientation === 'horizontal' ? 18 : 0.45,
    radiusY: orientation === 'horizontal' ? 0.45 : 18,
  };
}

function metalWaterContactVfxTargetRegions(fixture) {
  return fixture.cards.filter((card) => card.code === 'WATR_METL').map((card) => (
    metalWaterContactVfxStrip(
      `${card.code}_${card.orientation}_Metal`, card.solidContactProbe, card.orientation,
    )
  ));
}

function metalWaterContactVfxControlRegions(fixture) {
  const point = (name, candidate, radius = 0) => ({
    name, x: candidate.x + 0.5, y: candidate.y + 0.5, radius,
  });
  const rect = (name, candidate) => ({
    name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  const controls = fixture.cards.flatMap((card) => {
    const solidCore = card.orientation === 'horizontal'
      ? { x: card.solidContactProbe.x, y: card.solidContactProbe.y + 12 }
      : { x: card.solidContactProbe.x + 12, y: card.solidContactProbe.y };
    return [
      metalWaterContactVfxStrip(
        `${card.code}_${card.orientation}_liquidSide`,
        card.liquidContactProbe, card.orientation,
      ),
      ...(card.code === 'WATR_METL' ? [] : [metalWaterContactVfxStrip(
        `${card.code}_${card.orientation}_solidSide`,
        card.solidContactProbe, card.orientation,
      )]),
      point(`${card.code}_${card.orientation}_liquidCore`, card.deepCoreProbe, 1),
      point(`${card.code}_${card.orientation}_solidCore`, solidCore, 1),
      rect(`${card.code}_${card.orientation}_air`, card.airMeniscus),
    ];
  });
  if (fixture.oilMetalControl) {
    controls.push(
      metalWaterContactVfxStrip(
        'OIL_METL_control_liquidSide', fixture.oilMetalControl.liquidContactProbe, 'horizontal',
      ),
      metalWaterContactVfxStrip(
        'OIL_METL_control_solidSide', fixture.oilMetalControl.solidContactProbe, 'horizontal',
      ),
    );
  }
  controls.push(
    point('unlikeLiquidSeamLeft', fixture.unlikeLiquidSeam.leftProbe),
    point('unlikeLiquidSeamRight', fixture.unlikeLiquidSeam.rightProbe),
    rect('nativeWallBody', fixture.nativeWall.liquid),
    point('nativeWall', fixture.nativeWall.wallAnchor), rect('lava', fixture.lava),
    point('powderContact', fixture.powderContact.liquidProbe),
    point('gasContact', fixture.gasContact.liquidProbe), rect('strand', fixture.strand),
    rect('droplet', fixture.droplet), rect('authoredHole', fixture.perforatedLiquid.authoredHole),
    point('authoredHoleLip', {
      x: fixture.perforatedLiquid.authoredHole.x - 1,
      y: fixture.perforatedLiquid.authoredHole.y
        + Math.floor(fixture.perforatedLiquid.authoredHole.height / 2),
    }),
    rect('openChannel', fixture.perforatedLiquid.openChannel),
    point('openChannelLip', {
      x: fixture.perforatedLiquid.openChannel.x - 1,
      y: fixture.perforatedLiquid.openChannel.y + fixture.perforatedLiquid.openChannel.height - 1,
    }),
    rect('traitLike', fixture.ownerControls.traitLike),
    point('traitLikeProbe', fixture.ownerControls.traitLike.liquidProbe),
    rect('emissive', fixture.ownerControls.emissive),
    point('emissiveProbe', fixture.ownerControls.emissive.liquidProbe),
    point('mixedTripleLiquid', fixture.mixedTripleContact.liquidProbe),
    point('mixedTripleSolid', {
      x: fixture.mixedTripleContact.solid.x,
      y: fixture.mixedTripleContact.solid.y + fixture.mixedTripleContact.solid.height - 1,
    }),
    rect('guardedBlank', fixture.guardedBlank),
  );
  return controls;
}

function metalWaterContactVfxRawControlPoints(fixture) {
  const rectPoint = (name, candidate) => ({
    name, x: candidate.x + Math.floor(candidate.width / 2),
    y: candidate.y + Math.floor(candidate.height / 2),
  });
  const points = liquidSolidMeniscusVfxRawControlPoints(fixture)
    .filter(({ name }) => !/^WATR_METL_.*_solidSide$/.test(name));
  for (const card of fixture.cards) {
    const solidCore = card.orientation === 'horizontal'
      ? { x: card.solidContactProbe.x, y: card.solidContactProbe.y + 12 }
      : { x: card.solidContactProbe.x + 12, y: card.solidContactProbe.y };
    points.push(
      { name: `${card.code}_${card.orientation}_liquidSide`, ...card.liquidContactProbe },
      { name: `${card.code}_${card.orientation}_solidCore`, ...solidCore },
    );
  }
  points.push({
    name: 'mixedTripleSolid', x: fixture.mixedTripleContact.solid.x,
    y: fixture.mixedTripleContact.solid.y + fixture.mixedTripleContact.solid.height - 1,
  });
  if (fixture.oilMetalControl) {
    points.push(
      { name: 'OIL_METL_control_liquidSide', ...fixture.oilMetalControl.liquidContactProbe },
      { name: 'OIL_METL_control_solidSide', ...fixture.oilMetalControl.solidContactProbe },
      rectPoint('OIL_METL_control_liquidCore', fixture.oilMetalControl.liquid),
      rectPoint('OIL_METL_control_solidCore', fixture.oilMetalControl.solid),
    );
  }
  return points;
}

async function writeMetalWaterContactVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e37-metal-water-contact-${scale}x-off`),
    on: variantScreenshotPath(source, `e37-metal-water-contact-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditMetalWaterContactVfxDependencies(cdp, mode) {
  const definitions = [
    { name: 'all-parents-on', liquidBody: true, liquidSolidMeniscus: true,
      solidBody: true, enabled: true },
    { name: 'solid-parent-off', liquidBody: true, liquidSolidMeniscus: true,
      solidBody: false, enabled: true },
    { name: 'meniscus-parent-off', liquidBody: true, liquidSolidMeniscus: false,
      solidBody: true, enabled: true },
    { name: 'liquid-grandparent-off', liquidBody: false, liquidSolidMeniscus: true,
      solidBody: true, enabled: true },
  ];
  const probes = [];
  for (const definition of definitions) {
    const query = metalWaterContactVfxQuery({
      scale: 2, auditStage: `e37-dependency-${definition.name}`, ...definition,
    });
    await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
    await waitFor(() => evaluate(cdp, `(() => {
      const p = new URLSearchParams(location.search);
      return p.get('metalWaterContactVfxAudit') === '1'
        && p.get('auditStage') === ${JSON.stringify(`e37-dependency-${definition.name}`)}
        && p.get('renderScale') === '2' && Boolean(window.__ANIFOR_INPUT_AUDIT__);
    })()`), 30_000, `E37 ${definition.name} dependency page`);
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
    30_000, `E37 ${definition.name} dependency backend`);
    const state = await metalWaterContactVfxPipelineState(cdp);
    const expectedLiquidBody = definition.liquidBody ? 'active' : 'inactive';
    const expectedMeniscus = definition.liquidBody && definition.liquidSolidMeniscus
      ? 'active' : 'inactive';
    const expectedSolidBody = definition.solidBody ? 'active' : 'inactive';
    const expectedChild = definition.enabled && expectedMeniscus === 'active'
      && expectedSolidBody === 'active' ? 'active' : 'inactive';
    assert(state?.renderer === 'semantic-field-webgl' && state.look === 'realistic'
      && state.state === 'active' && state.bloomBacking === `${WORLD_WIDTH}x${WORLD_HEIGHT}`
      && state.liquidBodyVfx === expectedLiquidBody
      && state.liquidSolidMeniscusVfx === expectedMeniscus
      && state.solidBodyVfx === expectedSolidBody
      && state.metalWaterContactVfx === expectedChild
      && state.waterMetalTransmissionVfx === 'inactive'
      && state.waterMetalSeparationVfx === 'inactive',
    `E37 ${definition.name} dependency resolved incorrectly (${JSON.stringify({
      definition, expectedLiquidBody, expectedMeniscus, expectedSolidBody, expectedChild, state,
    })})`);
    probes.push({ name: definition.name, liquidBodyVfx: state.liquidBodyVfx,
      liquidSolidMeniscusVfx: state.liquidSolidMeniscusVfx,
      solidBodyVfx: state.solidBodyVfx, metalWaterContactVfx: state.metalWaterContactVfx,
      waterMetalTransmissionVfx: state.waterMetalTransmissionVfx,
      waterMetalSeparationVfx: state.waterMetalSeparationVfx });
  }
  return probes;
}

async function auditEightXMetalWaterContactVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = metalWaterContactVfxQuery({
    scale: 8, enabled: true, auditStage: 'eight-metal-water-contact',
    liquidBody: true, liquidSolidMeniscus: true, solidBody: true,
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8' && p.get('auditStage') === 'eight-metal-water-contact'
      && p.get('metalWaterContactVfxAudit') === '1' && p.get('liquidBodyVfx') === '1'
      && p.get('liquidSolidMeniscusVfx') === '1' && p.get('solidBodyVfx') === '1'
      && p.get('metalWaterContactVfx') === '1' && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E37 input audit API'),
  'true-8x E37 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E37', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E37');
  const promotionFence = 'signaled';
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E37 geometry')),
    'true-8x E37 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E37 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await metalWaterContactVfxPipelineState(
    cdp, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E37 isolation')),
  );
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.liquidBodyVfx === 'inactive'
    && isolation.liquidSolidMeniscusVfx === 'inactive' && isolation.solidBodyVfx === 'inactive'
    && isolation.metalWaterContactVfx === 'inactive'
    && isolation.waterMetalTransmissionVfx === 'inactive'
    && isolation.waterMetalSeparationVfx === 'inactive',
  `true-8x E37 isolation failed (${JSON.stringify(isolation)})`);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E37 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence'
    || timing.source === 'gpu-finish',
  `true-8x E37 did not complete GPU work (${JSON.stringify(timing)})`);
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotionFence, isolation, timing,
  };
}

/** E56: exact Water-side transmission over E37's clean Metal/Water contact. */
const WATER_METAL_TRANSMISSION_VFX_ACCEPTANCE = Object.freeze({
  1: Object.freeze({
    WATR_METL_horizontal_Water: Object.freeze({
      rgbRms: [7.2, 8.2], chromaRms: [6.9, 7.9], rgbPeak: [17, 20], coverage: [0.10, 0.18],
      red: [3.8, 4.6], green: [-1.5, -0.7], blue: [-12.2, -11.0],
    }),
    WATR_METL_vertical_Water: Object.freeze({
      rgbRms: [6.5, 7.6], chromaRms: [6.2, 7.3], rgbPeak: [13, 16], coverage: [0, 0.06],
      red: [3.6, 4.6], green: [-1.6, -0.7], blue: [-11.8, -10.4],
    }),
  }),
  2: Object.freeze({
    WATR_METL_horizontal_Water: Object.freeze({
      rgbRms: [6.5, 7.6], chromaRms: [6.3, 7.4], rgbPeak: [17, 21], coverage: [0.02, 0.10],
      red: [2.6, 3.5], green: [-1.0, -0.2], blue: [-8.7, -7.3],
    }),
    WATR_METL_vertical_Water: Object.freeze({
      rgbRms: [2.9, 3.8], chromaRms: [2.8, 3.7], rgbPeak: [7, 10], coverage: [0, 0.03],
      red: [1.2, 1.8], green: [-0.6, 0], blue: [-4.3, -3.3],
    }),
  }),
  4: Object.freeze({
    WATR_METL_horizontal_Water: Object.freeze({
      rgbRms: [5.9, 7.0], chromaRms: [5.8, 6.8], rgbPeak: [14, 18], coverage: [0.02, 0.12],
      red: [2.4, 3.3], green: [-0.8, 0], blue: [-7.9, -6.6],
    }),
    WATR_METL_vertical_Water: Object.freeze({
      rgbRms: [1.7, 2.4], chromaRms: [1.5, 2.3], rgbPeak: [4, 7], coverage: [0, 0.02],
      red: [0.6, 1.1], green: [-0.7, -0.1], blue: [-2.7, -1.9],
    }),
  }),
});

async function auditWaterMetalTransmissionVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      // E56 always retains E03/E14/E17/E37. Only the child selector changes.
      captures[key] = await navigateMetalWaterContactVfxState(
        cdp, mode, scale, true, key, {
          waterMetalTransmission: enabled,
          // Freeze E76 while retaining E56's accepted reference envelope.
          waterMetalSeparation: false,
          rawControlPoints: waterMetalTransmissionVfxRawControlPoints,
        },
      );
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture),
    `E56 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E56 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E56 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.liquidBodyVfx === 'active'
        && variant.hdrPipeline.liquidSolidMeniscusVfx === 'active'
        && variant.hdrPipeline.solidBodyVfx === 'active'
        && variant.hdrPipeline.metalWaterContactVfx === 'active'
        && variant.hdrPipeline.waterMetalTransmissionVfx === (label === 'enabled' ? 'active' : 'inactive')
        && variant.hdrPipeline.waterMetalSeparationVfx === 'inactive',
      `E56 ${label} ${scale}x parent/child selector state resolved incorrectly (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E56 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E56 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E56 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic,
      `E56 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E56 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E56 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E56 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E56 ${scale}x changed an exact protected raw control`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E56 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = waterMetalTransmissionVfxTargetRegions(disabled.fixture);
    const controls = waterMetalTransmissionVfxControlRegions(disabled.fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    // Persist requested evidence before applying the calibration envelope so a
    // rejected visual experiment still leaves an inspectable off/on pair.
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeWaterMetalTransmissionVfxScreenshots(
        screenshotRequest, scale, disabled, enabled,
      ) : undefined;
    const bounds = WATER_METAL_TRANSMISSION_VFX_ACCEPTANCE[scale];
    assert(targetResponses.length === 2 && targetResponses.every((sample) => {
      const targetBounds = bounds[sample.name];
      const [red, green, blue] = sample.responseRgb;
      return targetBounds
        && sample.rgbRms >= targetBounds.rgbRms[0] && sample.rgbRms <= targetBounds.rgbRms[1]
        && sample.chromaRms >= targetBounds.chromaRms[0]
        && sample.chromaRms <= targetBounds.chromaRms[1]
        && sample.rgbPeak >= targetBounds.rgbPeak[0] && sample.rgbPeak <= targetBounds.rgbPeak[1]
        && sample.coverage >= targetBounds.coverage[0] && sample.coverage <= targetBounds.coverage[1]
        && red >= targetBounds.red[0] && red <= targetBounds.red[1]
        && green >= targetBounds.green[0] && green <= targetBounds.green[1]
        && blue >= targetBounds.blue[0] && blue <= targetBounds.blue[1]
        && red > green && blue < 0;
    }), `E56 ${scale}x Water-side response escaped its calibrated envelope (${JSON.stringify(targetResponses)})`);
    // The fitted page raster assigns the shared interface pixel to both narrow
    // visual strips even though the exact Metal world pixels above remain byte
    // identical. Likewise, the mixed-triple probe can include one neighbouring
    // clean-contact compositor pixel. Keep those two presentation adjacencies
    // finite while every material core, foreign pair, wall, trait, emission,
    // topology, hole/channel, powder, and gas control remains exactly flat.
    assert(controlResponses.every((sample) => {
      if (/^WATR_METL_.*_Metal$/.test(sample.name)) {
        return sample.rgbPeak <= 24 && sample.coverage <= 0.40;
      }
      if (scale === 1 && sample.name === 'mixedTripleLiquid') return sample.rgbPeak <= 2;
      if (sample.name === 'mixedTripleSolid') return sample.rgbPeak <= 10;
      return sample.rgbPeak === 0;
    }),
    `E56 ${scale}x escaped exact Water/Glass/Oil/Metal/topology controls (${JSON.stringify(controlResponses)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E56 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    scales.push({
      scale, backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      rawControls: disabled.rawControls, targetResponses, controlResponses, responses,
      exactRepeatedOff: true, screenshots,
    });
  }
  let crossScaleConsistency;
  if (scales.length === VOLUME_VFX_SCALES.length) {
    const names = ['WATR_METL_horizontal_Water', 'WATR_METL_vertical_Water'];
    const targetRatios = names.map((name) => {
      const strengths = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name)?.rgbRms ?? 0);
      return { name, strengths, ratio: Math.max(...strengths) / Math.max(0.001, Math.min(...strengths)) };
    });
    const orientationRatios = scales.map((entry) => {
      const strengths = entry.targetResponses.map(({ rgbRms }) => rgbRms);
      return { scale: entry.scale, ratio: Math.max(...strengths) / Math.max(0.001, Math.min(...strengths)) };
    });
    assert(targetRatios.every(({ ratio }) => Number.isFinite(ratio) && ratio <= 4)
      && orientationRatios.every(({ ratio }) => Number.isFinite(ratio) && ratio <= 4),
    `E56 Water/Metal transmission drifted across scale/orientation (${JSON.stringify({ targetRatios, orientationRatios })})`);
    crossScaleConsistency = { targetRatios, orientationRatios, maximumRatio: 4 };
  }
  const dependencyProbes = await auditWaterMetalTransmissionVfxDependencies(cdp, mode);
  const trueEightX = await auditEightXWaterMetalTransmissionVfxExclusion(cdp, dpr);
  return {
    acceptance: WATER_METAL_TRANSMISSION_VFX_ACCEPTANCE,
    scales, crossScaleConsistency, dependencyProbes, trueEightXExcluded: true, trueEightX,
  };
}

function waterMetalTransmissionVfxTargetRegions(fixture) {
  return fixture.cards.filter((card) => card.code === 'WATR_METL').map((card) => ({
    name: `${card.code}_${card.orientation}_Water`,
    // The presentation contour is centred on the cell boundary, while the
    // exact semantic probe is centred half a cell inside Water. Bias this
    // visual-only sampling strip one quarter-cell toward Metal so both raster
    // orientations include the same boundary pixel without entering the
    // separately audited Metal cell centre.
    x: card.liquidContactProbe.x + 0.5 + (card.orientation === 'vertical' ? 0.75 : 0),
    y: card.liquidContactProbe.y + 0.5 + (card.orientation === 'horizontal' ? 0.25 : 0),
    radiusX: card.orientation === 'horizontal' ? 18 : 0.70,
    radiusY: card.orientation === 'horizontal' ? 0.70 : 18,
    auditRect: true,
  }));
}

function waterMetalTransmissionVfxControlRegions(fixture) {
  const controls = metalWaterContactVfxControlRegions(fixture)
    .filter(({ name }) => !/^WATR_METL_.*_liquidSide$/.test(name));
  for (const card of fixture.cards.filter((candidate) => candidate.code === 'WATR_METL')) {
    controls.push(metalWaterContactVfxStrip(
      `${card.code}_${card.orientation}_Metal`, card.solidContactProbe, card.orientation,
    ));
  }
  return controls;
}

function waterMetalTransmissionVfxRawControlPoints(fixture) {
  const points = metalWaterContactVfxRawControlPoints(fixture)
    .filter(({ name }) => !/^WATR_METL_.*_liquidSide$/.test(name));
  for (const card of fixture.cards.filter((candidate) => candidate.code === 'WATR_METL')) {
    points.push({ name: `${card.code}_${card.orientation}_Metal`, ...card.solidContactProbe });
  }
  return points;
}

