const PLANT_CANOPY_FOLIAGE_VFX_ANCESTRY = Object.freeze([
  'botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx',
  'plantLaminaVfx', 'plantLobeDepthVfx', 'plantCanopyMassVfx',
  'plantCanopyTissueVfx', 'plantCanopyInterlockVfx', 'plantCanopyHierarchyVfx',
]);

/** E71: calibrated exact-state PLNT foliage volume, strictly subordinate to E58. */
async function auditPlantCanopyFoliageVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigatePlantCanopyFoliageVfxState(
        cdp, mode, scale, enabled, key, key !== 'disabled',
      );
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture),
    `E71 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E71 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl' && variant.hdrPipeline?.state === 'active'
        && PLANT_CANOPY_FOLIAGE_VFX_ANCESTRY.every(
          (name) => variant.hdrPipeline[name] === 'active',
        )
        && Object.values(variant.hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
        && variant.hdrPipeline.plantCanopyFoliageVfx
          === (label === 'enabled' ? 'active' : 'inactive'),
      `E71 ${label} ${scale}x ancestry/isolation/selector state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
      assertBotanicalBodyVfxLifecycleDigest(variant.lifecycleDigest, `E71 ${label} ${scale}x`);
      assertPlantLaminaVfxTargetDigest(variant.targetDigest, scale);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E71 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E71 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E71 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E71 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E71 ${scale}x disabled/repeated`);
    assertPlantCanopyInterlockBackingInvariant(disabled.backing, enabled.backing,
      `E71 ${scale}x disabled/enabled`, false);
    assertPlantCanopyInterlockBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E71 ${scale}x disabled/repeated`, true);
    for (const field of ['walls', 'lifecycleDigest', 'auxiliaryDigest', 'targetDigest', 'rawControls']) {
      assert(JSON.stringify(disabled[field]) === JSON.stringify(enabled[field])
        && JSON.stringify(disabled[field]) === JSON.stringify(disabledRepeat[field]),
      `E71 ${scale}x changed protected ${field}`);
    }
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E71 ${scale}x repeated off framebuffer was not byte exact`);
    const { targets, controls } = plantLaminaVfxRegions(disabled.fixture);
    const sampled = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data, refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = sampled.slice(0, targets.length).map((sample) => ({ ...sample,
      spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2
        - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2)), 3) }));
    const controlResponses = sampled.slice(targets.length);
    const frequency = await sampleBotanicalMesostructureFrequency(cdp, {
      disabled: disabled.capture.capture.data, enabled: enabled.capture.capture.data,
      disabledRepeat: disabledRepeat.capture.capture.data,
    }, targets, 'E71');
    const appearance = await samplePlantCanopyMassAppearance(cdp, {
      disabled: disabled.capture.capture.data, enabled: enabled.capture.capture.data,
    }, targets);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writePlantCanopyFoliageVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    assertPlantCanopyFoliageVfxResponses(targetResponses, scale);
    const controlAllowance = (sample) => (
      PLANT_CANOPY_FOLIAGE_VFX_ACCEPTANCE
        .composedResponseControlPeak[scale]?.[sample.name] ?? 0
    );
    assert(controlResponses.length === controls.length
      && controlResponses.every((sample) => sample.rgbPeak <= controlAllowance(sample)
        && sample.repeatRgbPeak === 0),
    `E71 ${scale}x changed a protected composed control (${JSON.stringify(controlResponses)})`);
    assertPlantCanopyFoliageVfxFrequency(frequency, scale);
    assertPlantCanopyFoliageVfxAppearance(appearance, scale);
    scales.push({ scale, targetResponses, controlResponses, frequency, appearance, screenshots,
      semantic: disabled.semantic, backing: disabled.backing, lifecycleDigest: disabled.lifecycleDigest,
      auxiliaryDigest: disabled.auxiliaryDigest, rawControls: disabled.rawControls,
      exactRepeatedOff: true });
  }
  if (scales.length > 1) assertPlantCanopyFoliageVfxCrossScale(scales);
  return {
    calibration: 'frozen', acceptance: PLANT_CANOPY_FOLIAGE_VFX_ACCEPTANCE,
    scales, trueEightXExcluded: true,
    trueEightX: await auditEightXPlantCanopyFoliageVfxExclusion(cdp, dpr),
  };
}

function assertPlantCanopyFoliageVfxResponses(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && new Set(samples.map(({ name }) => name)).size === 2
    && samples.every((sample) => {
      const bounds = PLANT_CANOPY_FOLIAGE_VFX_ACCEPTANCE.targets[sample?.name]?.response;
      return sample && bounds && inRange(sample.rgbRms, bounds.rgbRms)
      && inRange(sample.chromaRms, bounds.chromaRms)
      && inRange(sample.spatialRgbRms, bounds.spatialRgbRms)
      && inRange(sample.rgbPeak, bounds.rgbPeak)
      && inRange(sample.coverage, bounds.coverage)
      && inRange(sample.signedMean, bounds.signedMean)
      && inRange(sample.meanBiasRatio, bounds.meanBiasRatio)
      && inRange(sample.positiveMean, bounds.positiveMean)
      && inRange(sample.negativeMean, bounds.negativeMean)
      && inRange(sample.bipolarBalance, bounds.bipolarBalance)
      && inRange(sample.responseMicroContrast, bounds.responseMicroContrast)
      && inRange(sample.responseRgb[0], bounds.red)
      && inRange(sample.responseRgb[1], bounds.green)
      && inRange(sample.responseRgb[2], bounds.blue)
      && sample.repeatRgbPeak === 0;
    }),
  `E71 ${scale}x foliage response escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyFoliageVfxFrequency(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && samples.every((sample) => {
    const bounds = PLANT_CANOPY_FOLIAGE_VFX_ACCEPTANCE.targets[sample?.name]?.frequency;
    return sample?.code === 'PLNT' && bounds && inRange(sample.mesoRgbRms, bounds.mesoRgbRms)
    && inRange(sample.cellRgbRms, bounds.cellRgbRms)
    && inRange(sample.mesoShare, bounds.mesoShare)
    && sample.mesoRgbRms >= sample.cellRgbRms * 1.5
    && inRange(sample.positiveCoverage, bounds.positiveCoverage)
    && inRange(sample.negativeCoverage, bounds.negativeCoverage)
    && inRange(sample.mesoMeanBiasRatio, bounds.mesoMeanBiasRatio)
    && inRange(sample.downsampleRetention, bounds.downsampleRetention)
    && inRange(sample.gradientRatio, bounds.gradientRatio)
    && inRange(sample.rgbPeak, bounds.rgbPeak)
    && sample.ySegmentMesoRgbRms?.length === 3
    && sample.ySegmentMesoRgbRms.every((value, index) => inRange(
      value, bounds.ySegmentMesoRgbRms[index],
    ))
    && sample.repeatRgbPeak === 0;
  }), `E71 ${scale}x foliage frequency escaped its frozen macro/meso envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyFoliageVfxAppearance(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && samples.every((sample) => {
    const bounds = PLANT_CANOPY_FOLIAGE_VFX_ACCEPTANCE.targets[sample?.name]?.appearance;
    const darkSeamGain = sample?.enabled.darkSeamFraction - sample?.disabled.darkSeamFraction;
    const strongSeamGain = sample?.enabled.strongSeamFraction - sample?.disabled.strongSeamFraction;
    const localContrastGain = sample?.enabled.localContrastRms - sample?.disabled.localContrastRms;
    const meanLumaGain = sample?.enabled.meanLuma - sample?.disabled.meanLuma;
    const lumaStdDevGain = sample?.enabled.lumaStdDev - sample?.disabled.lumaStdDev;
    const macroGain = sample?.enabled.macroP90P10 - sample?.disabled.macroP90P10;
    return sample?.code === 'PLNT' && bounds
      && sample.uniqueSamplePixels === sample.width * sample.height
      && inRange(sample.enabled.darkSeamFraction, bounds.enabledDarkSeam)
      && inRange(sample.enabled.strongSeamFraction, bounds.enabledStrongSeam)
      && inRange(darkSeamGain, bounds.darkSeamGain)
      && inRange(strongSeamGain, bounds.strongSeamGain)
      && inRange(sample.enabled.localContrastRms, bounds.enabledLocalContrastRms)
      && inRange(localContrastGain, bounds.localContrastGain)
      && inRange(sample.localContrastRetention, bounds.localContrastRetention)
      && inRange(sample.enabled.lumaStdDev, bounds.enabledLumaStdDev)
      && inRange(sample.enabled.macroP90P10, bounds.enabledMacro)
      && inRange(meanLumaGain, bounds.meanLumaGain)
      && inRange(lumaStdDevGain, bounds.lumaStdDevGain)
      && inRange(macroGain, bounds.macroGain);
  }), `E71 ${scale}x foliage appearance escaped its frozen volume envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyFoliageVfxCrossScale(scales) {
  const bounds = PLANT_CANOPY_FOLIAGE_VFX_ACCEPTANCE.spread;
  const spread = (values) => Math.max(...values) - Math.min(...values);
  for (const name of ['PLNTLeft', 'PLNTRight']) {
    const responses = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
    const frequency = scales.map((entry) => entry.frequency.find((sample) => sample.name === name));
    const appearance = scales.map((entry) => entry.appearance.find((sample) => sample.name === name));
    assert(responses.every(Boolean) && frequency.every(Boolean) && appearance.every(Boolean)
      && spread(responses.map((sample) => sample.rgbRms)) <= bounds.rgbRms
      && spread(responses.map((sample) => sample.chromaRms)) <= bounds.chromaRms
      && spread(responses.map((sample) => sample.spatialRgbRms)) <= bounds.spatialRgbRms
      && spread(responses.map((sample) => sample.rgbPeak)) <= bounds.rgbPeak
      && spread(responses.map((sample) => sample.coverage)) <= bounds.coverage
      && spread(responses.map((sample) => sample.signedMean)) <= bounds.signedMean
      && spread(responses.map((sample) => sample.meanBiasRatio)) <= bounds.meanBiasRatio
      && spread(responses.map((sample) => sample.bipolarBalance)) <= bounds.bipolarBalance
      && spread(responses.map((sample) => sample.responseMicroContrast)) <= bounds.responseMicroContrast
      && spread(frequency.map((sample) => sample.mesoRgbRms)) <= bounds.mesoRgbRms
      && spread(frequency.map((sample) => sample.cellRgbRms)) <= bounds.cellRgbRms
      && spread(frequency.map((sample) => sample.mesoShare)) <= bounds.mesoShare
      && spread(frequency.map((sample) => sample.positiveCoverage)) <= bounds.positiveCoverage
      && spread(frequency.map((sample) => sample.negativeCoverage)) <= bounds.negativeCoverage
      && spread(frequency.map((sample) => sample.mesoMeanBiasRatio)) <= bounds.mesoMeanBiasRatio
      && spread(frequency.map((sample) => sample.downsampleRetention)) <= bounds.downsampleRetention
      && spread(frequency.map((sample) => sample.gradientRatio)) <= bounds.gradientRatio
      && [0, 1, 2].every((index) => spread(frequency.map(
        (sample) => sample.ySegmentMesoRgbRms[index],
      )) <= bounds.ySegmentMesoRgbRms)
      && spread(appearance.map((sample) => sample.enabled.localContrastRms))
        <= bounds.enabledLocalContrastRms
      && spread(appearance.map((sample) => sample.enabled.localContrastRms
        - sample.disabled.localContrastRms)) <= bounds.localContrastGain
      && spread(appearance.map((sample) => sample.localContrastRetention))
        <= bounds.localContrastRetention
      && spread(appearance.map((sample) => sample.enabled.darkSeamFraction))
        <= bounds.enabledDarkSeam
      && spread(appearance.map((sample) => sample.enabled.strongSeamFraction))
        <= bounds.enabledStrongSeam
      && spread(appearance.map((sample) => sample.enabled.darkSeamFraction
        - sample.disabled.darkSeamFraction)) <= bounds.darkSeamGain
      && spread(appearance.map((sample) => sample.enabled.strongSeamFraction
        - sample.disabled.strongSeamFraction)) <= bounds.strongSeamGain
      && spread(appearance.map((sample) => sample.enabled.lumaStdDev)) <= bounds.enabledLumaStdDev
      && spread(appearance.map((sample) => sample.enabled.macroP90P10)) <= bounds.enabledMacro
      && spread(appearance.map((sample) => sample.enabled.meanLuma
        - sample.disabled.meanLuma)) <= bounds.meanLumaGain
      && spread(appearance.map((sample) => sample.enabled.lumaStdDev
        - sample.disabled.lumaStdDev)) <= bounds.lumaStdDevGain
      && spread(appearance.map((sample) => sample.enabled.macroP90P10
        - sample.disabled.macroP90P10)) <= bounds.macroGain,
    `E71 ${name} changed excessively across normal output scales (${JSON.stringify({ responses, frequency, appearance })})`);
  }
}

async function navigatePlantCanopyFoliageVfxState(
  cdp, mode, scale, enabled, label, reuseHydratedPage,
) {
  const owned = new Set([...PLANT_CANOPY_FOLIAGE_VFX_ANCESTRY, 'plantCanopyFoliageVfx']);
  const isolatedSelectors = STEAM_CONDENSATE_VFX_ISOLATED_SELECTORS.filter(
    (name) => !owned.has(name),
  );
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    // Retain E58's marker because the inherited botanical fixture still uses
    // that audit route; E71's own marker identifies the child experiment.
    plantCanopyHierarchyVfxAudit: '1', plantCanopyFoliageVfxAudit: '1',
    renderScale: String(scale), renderLook: 'realistic',
    ...Object.fromEntries(isolatedSelectors.map((name) => [name, '0'])),
    botanicalBodyVfx: '1', botanicalMesostructureVfx: '1', botanicalPigmentVfx: '1',
    plantLaminaVfx: '1', plantLobeDepthVfx: '1', plantCanopyMassVfx: '1',
    plantCanopyTissueVfx: '1', plantCanopyInterlockVfx: '1', plantCanopyHierarchyVfx: '1',
    plantCanopyFoliageVfx: enabled ? '1' : '0',
  });
  let fixture;
  if (reuseHydratedPage) {
    fixture = await evaluate(cdp, `(() => {
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      if (new URLSearchParams(location.search).get('plantCanopyFoliageVfxAudit') !== '1'
        || audit?.backend().backend !== 'webgl'
        || typeof audit?.setPlantCanopyFoliageVfx !== 'function') return undefined;
      audit.setPlantCanopyFoliageVfx(${JSON.stringify(enabled)});
      return audit.botanicalBodyVfxFixture?.();
    })()`);
    assert(fixture, `E71 ${label} ${scale}x could not reuse hydrated PLNT fixture`);
  } else {
    await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
    await waitFor(() => evaluate(cdp, `(() => {
      const p = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
      return p.get('plantCanopyFoliageVfxAudit') === '1'
        && p.get('plantCanopyHierarchyVfxAudit') === '1'
        && p.get('renderScale') === ${JSON.stringify(String(scale))}
        && p.get('plantCanopyFoliageVfx') === ${JSON.stringify(enabled ? '1' : '0')}
        && ${JSON.stringify(PLANT_CANOPY_FOLIAGE_VFX_ANCESTRY)}.every((name) => p.get(name) === '1')
        && ${JSON.stringify(isolatedSelectors)}.every((name) => p.get(name) === '0')
        && typeof audit?.setPlantCanopyFoliageVfx === 'function'
        && typeof audit?.prepareBotanicalBodyVfxFixture === 'function';
    })()`), scale === 4 ? 90_000 : 45_000, `E71 ${label} ${scale}x page`);
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
    scale === 4 ? 90_000 : 45_000, `E71 ${label} ${scale}x backend`);
    fixture = await evaluate(cdp, `(() => {
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      audit.prepareBotanicalBodyVfxFixture(); return audit.botanicalBodyVfxFixture();
    })()`);
    for (let pass = 0; pass < 7; pass++) {
      const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
      await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
      await waitFor(() => evaluate(cdp,
        `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
      scale === 4 ? 15_000 : 5_000, `E71 ${label} ${scale}x stability ${pass + 1}`);
    }
  }
  await waitFor(() => botanicalBodyVfxFixtureReady(cdp, fixture),
    20_000, `E71 ${label} ${scale}x fixture hydration`);
  await waitFor(() => evaluate(cdp,
    `document.querySelector('canvas.semantic-field-canvas')?.dataset.plantCanopyFoliageVfx === ${JSON.stringify(enabled ? 'active' : 'inactive')}`),
  20_000, `E71 ${label} ${scale}x selector`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const ancestry = ${JSON.stringify(PLANT_CANOPY_FOLIAGE_VFX_ANCESTRY)};
    const isolated = ${JSON.stringify(isolatedSelectors)};
    return {
      state: canvas.dataset.hdrPipeline, bloomBacking: canvas.dataset.bloomBacking,
      ...Object.fromEntries(ancestry.map((name) => [name, canvas.dataset[name]])),
      plantCanopyFoliageVfx: canvas.dataset.plantCanopyFoliageVfx,
      isolatedSelectors: Object.fromEntries(isolated.map((name) => [name, canvas.dataset[name]])),
    };
  })()`);
  const { targets } = plantLaminaVfxRegions(fixture);
  return {
    fixture, hdrPipeline, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    walls: await botanicalBodyVfxWallDigest(cdp),
    targetDigest: await plantLaminaVfxTargetDigest(cdp, targets),
    lifecycleDigest: await botanicalBodyVfxLifecycleDigest(cdp, fixture),
    auxiliaryDigest: await botanicalMesostructureVfxAuxiliaryDigest(cdp, fixture),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp, true, targets),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, plantLaminaVfxRawControlPoints(fixture)),
    capture: await captureSettledPage(
      cdp, `E71 ${label} ${scale}x completed framebuffer`, 450, false, false, false,
      scale === 4 ? 60_000 : 30_000,
    ),
  };
}

async function writePlantCanopyFoliageVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e71-plant-canopy-foliage-${scale}x-off`),
    on: variantScreenshotPath(source, `e71-plant-canopy-foliage-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXPlantCanopyFoliageVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-plant-canopy-foliage', plantCanopyHierarchyVfxAudit: '1',
    plantCanopyFoliageVfxAudit: '1', renderLook: 'realistic',
    botanicalBodyVfx: '1', botanicalMesostructureVfx: '1', botanicalPigmentVfx: '1',
    plantLaminaVfx: '1', plantLobeDepthVfx: '1', plantCanopyMassVfx: '1',
    plantCanopyTissueVfx: '1', plantCanopyInterlockVfx: '1', plantCanopyHierarchyVfx: '1',
    plantCanopyFoliageVfx: '1',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8' && p.get('auditStage') === 'eight-plant-canopy-foliage'
      && p.get('plantCanopyFoliageVfxAudit') === '1'
      && p.get('plantCanopyFoliageVfx') === '1' && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E71 input audit API'),
  'true-8x E71 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E71', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E71');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E71 geometry')),
    'true-8x E71 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E71 lost exact 4896x3072 backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    const names = [...${JSON.stringify(PLANT_CANOPY_FOLIAGE_VFX_ANCESTRY)}, 'plantCanopyFoliageVfx'];
    return canvas ? {
      renderer: canvas.dataset.renderer, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking ?? null,
      ...Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])),
    } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E71 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.state === 'inactive'
    && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && [...PLANT_CANOPY_FOLIAGE_VFX_ANCESTRY, 'plantCanopyFoliageVfx']
      .every((name) => isolation[name] === 'inactive'),
  `true-8x E71 ancestry/selector/HDR exclusion failed (${JSON.stringify(isolation)})`);
  const stateBefore = await hdrVfxSemanticDigest(cdp);
  const budget = remainingDeadlineMs(deadline, 'true-8x E71 GPU completion');
  const timing = await auditWebGLPresentationTiming(cdp, 1, Math.min(12_000, budget), budget, 1);
  assert(['gpu-fence', 'gpu-query', 'gpu-finish'].includes(timing.source),
    `true-8x E71 did not complete GPU work (${JSON.stringify(timing)})`);
  const stateAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(stateBefore, stateAfter, 'true-8x E71 GPU completion');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8' && geometry.backend.backend === 'webgl',
    selectorExcluded: true, resourcesExcluded: isolation.bloomBacking === null,
    semanticStable: true, isolation, timing,
  };
}

/** E58: exact-state PLNT canopy hierarchy, strictly subordinate to E55. */
async function auditPlantCanopyHierarchyVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigatePlantCanopyHierarchyVfxState(
        cdp, mode, scale, enabled, key, key !== 'disabled',
      );
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture),
    `E58 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E58 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl' && variant.hdrPipeline?.state === 'active'
        && ['botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx',
          'plantLaminaVfx', 'plantLobeDepthVfx', 'plantCanopyMassVfx',
          'plantCanopyTissueVfx', 'plantCanopyInterlockVfx'].every((name) => variant.hdrPipeline[name] === 'active')
        && variant.hdrPipeline.plantCanopyHierarchyVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E58 ${label} ${scale}x ancestry/selector state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
      assertBotanicalBodyVfxLifecycleDigest(variant.lifecycleDigest, `E58 ${label} ${scale}x`);
    }
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E58 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E58 ${scale}x disabled/repeated`);
    assertPlantCanopyInterlockBackingInvariant(disabled.backing, enabled.backing,
      `E58 ${scale}x disabled/enabled`, false);
    assertPlantCanopyInterlockBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E58 ${scale}x disabled/repeated`, true);
    for (const field of ['walls', 'lifecycleDigest', 'auxiliaryDigest', 'targetDigest', 'rawControls']) {
      assert(JSON.stringify(disabled[field]) === JSON.stringify(enabled[field])
        && JSON.stringify(disabled[field]) === JSON.stringify(disabledRepeat[field]),
      `E58 ${scale}x changed protected ${field}`);
    }
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E58 ${scale}x repeated off framebuffer was not byte exact`);
    const { targets, controls } = plantLaminaVfxRegions(disabled.fixture);
    const sampled = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data, refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = sampled.slice(0, targets.length).map((sample) => ({ ...sample,
      spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2
        - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2)), 3) }));
    const controlResponses = sampled.slice(targets.length);
    const frequency = await sampleBotanicalMesostructureFrequency(cdp, {
      disabled: disabled.capture.capture.data, enabled: enabled.capture.capture.data,
      disabledRepeat: disabledRepeat.capture.capture.data,
    }, targets, 'E58');
    const appearance = await samplePlantCanopyMassAppearance(cdp, {
      disabled: disabled.capture.capture.data, enabled: enabled.capture.capture.data,
    }, targets);
    // Keep screenshots ahead of numeric assertions so a future visual drift
    // leaves reviewable evidence even when it correctly fails the gate.
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writePlantCanopyHierarchyVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    assertPlantCanopyHierarchyVfxResponses(targetResponses, scale);
    const controlAllowance = (sample) => (
      PLANT_CANOPY_HIERARCHY_VFX_ACCEPTANCE
        .composedResponseControlPeak[scale]?.[sample.name] ?? 0
    );
    assert(controlResponses.length === controls.length
      && controlResponses.every((sample) => sample.rgbPeak <= controlAllowance(sample)
        && sample.repeatRgbPeak <= controlAllowance(sample)),
    `E58 ${scale}x changed a protected composed control (${JSON.stringify(controlResponses)})`);
    assertPlantCanopyHierarchyVfxFrequency(frequency, scale);
    assertPlantCanopyHierarchyVfxAppearance(appearance, scale);
    scales.push({ scale, targetResponses, controlResponses, frequency, appearance, screenshots,
      semantic: disabled.semantic, backing: disabled.backing, lifecycleDigest: disabled.lifecycleDigest,
      auxiliaryDigest: disabled.auxiliaryDigest, rawControls: disabled.rawControls, exactRepeatedOff: true });
  }
  if (scales.length > 1) assertPlantCanopyHierarchyVfxCrossScale(scales);
  return { calibration: 'frozen', acceptance: PLANT_CANOPY_HIERARCHY_VFX_ACCEPTANCE,
    scales, trueEightXExcluded: true, trueEightX: await auditEightXPlantCanopyHierarchyVfxExclusion(cdp, dpr) };
}

function assertPlantCanopyHierarchyVfxResponses(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && new Set(samples.map(({ name }) => name)).size === 2
    && samples.every((sample) => {
      const bounds = PLANT_CANOPY_HIERARCHY_VFX_ACCEPTANCE.targets[sample?.name]?.response;
      return sample && bounds
        && inRange(sample.rgbRms, bounds.rgbRms)
        && inRange(sample.chromaRms, bounds.chromaRms)
        && inRange(sample.spatialRgbRms, bounds.spatialRgbRms)
        && inRange(sample.rgbPeak, bounds.rgbPeak)
        && inRange(sample.coverage, bounds.coverage)
        && inRange(sample.signedMean, bounds.signedMean)
        && inRange(sample.meanBiasRatio, bounds.meanBiasRatio)
        && inRange(sample.positiveMean, bounds.positiveMean)
        && inRange(sample.negativeMean, bounds.negativeMean)
        && inRange(sample.bipolarBalance, bounds.bipolarBalance)
        && inRange(sample.responseMicroContrast, bounds.responseMicroContrast)
        && inRange(sample.responseRgb[0], bounds.red)
        && inRange(sample.responseRgb[1], bounds.green)
        && inRange(sample.responseRgb[2], bounds.blue)
        && sample.repeatRgbPeak === 0;
    }),
  `E58 ${scale}x PLNT hierarchy response escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyHierarchyVfxFrequency(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && samples.every((sample) => {
    const bounds = PLANT_CANOPY_HIERARCHY_VFX_ACCEPTANCE.targets[sample?.name]?.frequency;
    return sample?.code === 'PLNT' && bounds
      && inRange(sample.mesoRgbRms, bounds.mesoRgbRms)
      && inRange(sample.cellRgbRms, bounds.cellRgbRms)
      && inRange(sample.mesoShare, bounds.mesoShare)
      && inRange(sample.positiveCoverage, bounds.positiveCoverage)
      && inRange(sample.negativeCoverage, bounds.negativeCoverage)
      && inRange(sample.mesoMeanBiasRatio, bounds.mesoMeanBiasRatio)
      && inRange(sample.downsampleRetention, bounds.downsampleRetention)
      && inRange(sample.gradientRatio, bounds.gradientRatio)
      && inRange(sample.rgbPeak, bounds.rgbPeak)
      && sample.ySegmentMesoRgbRms?.length === 3
      && sample.ySegmentMesoRgbRms.every((value, index) => inRange(
        value, bounds.ySegmentMesoRgbRms[index],
      ))
      && sample.repeatRgbPeak === 0;
  }), `E58 ${scale}x PLNT hierarchy frequency escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyHierarchyVfxAppearance(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && samples.every((sample) => {
    const bounds = PLANT_CANOPY_HIERARCHY_VFX_ACCEPTANCE.targets[sample?.name]?.appearance;
    const darkSeamGain = sample?.enabled.darkSeamFraction - sample?.disabled.darkSeamFraction;
    const strongSeamGain = sample?.enabled.strongSeamFraction - sample?.disabled.strongSeamFraction;
    const localContrastGain = sample?.enabled.localContrastRms - sample?.disabled.localContrastRms;
    const lumaStdDevGain = sample?.enabled.lumaStdDev - sample?.disabled.lumaStdDev;
    const macroGain = sample?.enabled.macroP90P10 - sample?.disabled.macroP90P10;
    const meanLumaGain = sample?.enabled.meanLuma - sample?.disabled.meanLuma;
    return sample?.code === 'PLNT' && bounds
      && sample.uniqueSamplePixels === sample.width * sample.height
      && inRange(sample.enabled.darkSeamFraction, bounds.enabledDarkSeam)
      && inRange(sample.enabled.strongSeamFraction, bounds.enabledStrongSeam)
      && inRange(darkSeamGain, bounds.darkSeamGain)
      && inRange(strongSeamGain, bounds.strongSeamGain)
      && inRange(sample.enabled.localContrastRms, bounds.enabledLocalContrastRms)
      && inRange(localContrastGain, bounds.localContrastGain)
      && inRange(sample.localContrastRetention, bounds.localContrastRetention)
      && inRange(sample.enabled.lumaStdDev, bounds.enabledLumaStdDev)
      && inRange(lumaStdDevGain, bounds.lumaStdDevGain)
      && inRange(sample.enabled.macroP90P10, bounds.enabledMacro)
      && inRange(macroGain, bounds.macroGain)
      && inRange(meanLumaGain, bounds.meanLumaGain);
  }), `E58 ${scale}x PLNT hierarchy appearance escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyHierarchyVfxCrossScale(scales) {
  const bounds = PLANT_CANOPY_HIERARCHY_VFX_ACCEPTANCE.spread;
  const spread = (values) => Math.max(...values) - Math.min(...values);
  for (const name of ['PLNTLeft', 'PLNTRight']) {
    const responses = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
    const frequency = scales.map((entry) => entry.frequency.find((sample) => sample.name === name));
    const appearance = scales.map((entry) => entry.appearance.find((sample) => sample.name === name));
    assert(responses.every(Boolean) && frequency.every(Boolean) && appearance.every(Boolean)
      && spread(responses.map((sample) => sample.rgbRms)) <= bounds.rgbRms
      && spread(responses.map((sample) => sample.chromaRms)) <= bounds.chromaRms
      && spread(responses.map((sample) => sample.spatialRgbRms)) <= bounds.spatialRgbRms
      && spread(responses.map((sample) => sample.rgbPeak)) <= bounds.rgbPeak
      && spread(responses.map((sample) => sample.coverage)) <= bounds.coverage
      && spread(responses.map((sample) => sample.signedMean)) <= bounds.signedMean
      && spread(responses.map((sample) => sample.meanBiasRatio)) <= bounds.meanBiasRatio
      && spread(responses.map((sample) => sample.bipolarBalance)) <= bounds.bipolarBalance
      && spread(responses.map((sample) => sample.responseMicroContrast)) <= bounds.responseMicroContrast
      && spread(frequency.map((sample) => sample.mesoRgbRms)) <= bounds.mesoRgbRms
      && spread(frequency.map((sample) => sample.cellRgbRms)) <= bounds.cellRgbRms
      && spread(frequency.map((sample) => sample.mesoShare)) <= bounds.mesoShare
      && spread(frequency.map((sample) => sample.positiveCoverage)) <= bounds.positiveCoverage
      && spread(frequency.map((sample) => sample.negativeCoverage)) <= bounds.negativeCoverage
      && spread(frequency.map((sample) => sample.mesoMeanBiasRatio)) <= bounds.mesoMeanBiasRatio
      && spread(frequency.map((sample) => sample.downsampleRetention)) <= bounds.downsampleRetention
      && spread(frequency.map((sample) => sample.gradientRatio)) <= bounds.gradientRatio
      && [0, 1, 2].every((index) => spread(frequency.map(
        (sample) => sample.ySegmentMesoRgbRms[index],
      )) <= bounds.ySegmentMesoRgbRms)
      && spread(appearance.map((sample) => sample.enabled.localContrastRms))
        <= bounds.enabledLocalContrastRms
      && spread(appearance.map((sample) => sample.enabled.localContrastRms
        - sample.disabled.localContrastRms)) <= bounds.localContrastGain
      && spread(appearance.map((sample) => sample.localContrastRetention))
        <= bounds.localContrastRetention
      && spread(appearance.map((sample) => sample.enabled.darkSeamFraction)) <= bounds.enabledDarkSeam
      && spread(appearance.map((sample) => sample.enabled.strongSeamFraction)) <= bounds.enabledStrongSeam
      && spread(appearance.map((sample) => sample.enabled.darkSeamFraction
        - sample.disabled.darkSeamFraction)) <= bounds.darkSeamGain
      && spread(appearance.map((sample) => sample.enabled.strongSeamFraction
        - sample.disabled.strongSeamFraction)) <= bounds.strongSeamGain
      && spread(appearance.map((sample) => sample.enabled.meanLuma
        - sample.disabled.meanLuma)) <= bounds.meanLumaGain
      && spread(appearance.map((sample) => sample.enabled.lumaStdDev
        - sample.disabled.lumaStdDev)) <= bounds.lumaStdDevGain
      && spread(appearance.map((sample) => sample.enabled.macroP90P10
        - sample.disabled.macroP90P10)) <= bounds.macroGain,
    `E58 ${name} changed excessively across normal output scales (${JSON.stringify({ responses, frequency, appearance })})`);
  }
}

async function navigatePlantCanopyHierarchyVfxState(cdp, mode, scale, enabled, label, reuseHydratedPage) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    plantCanopyHierarchyVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0', gasMotionVfx: '0',
    powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0',
    gasCoreDepthVfx: '0', nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0', botanicalBodyVfx: '1', botanicalMesostructureVfx: '1',
    botanicalPigmentVfx: '1', plantLaminaVfx: '1', plantLobeDepthVfx: '1', plantCanopyMassVfx: '1',
    plantCanopyTissueVfx: '1', plantCanopyInterlockVfx: '1', plantCanopyHierarchyVfx: enabled ? '1' : '0',
    woodBarkReliefVfx: '0', woodTanninVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0',
    rockRoughnessVfx: '0', rockMesostructureVfx: '0', waterBodyVfx: '0',
  });
  let fixture;
  if (reuseHydratedPage) {
    const reused = await evaluate(cdp, `(() => { const audit = window.__ANIFOR_INPUT_AUDIT__;
      if (new URLSearchParams(location.search).get('plantCanopyHierarchyVfxAudit') !== '1'
        || audit?.backend().backend !== 'webgl' || typeof audit?.setPlantCanopyHierarchyVfx !== 'function') return undefined;
      audit.setPlantCanopyHierarchyVfx(${JSON.stringify(enabled)}); return audit.botanicalBodyVfxFixture?.(); })()`);
    assert(reused, `E58 ${label} ${scale}x could not reuse hydrated PLNT fixture`); fixture = reused;
  } else {
    await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
    await waitFor(() => evaluate(cdp, `(() => { const p = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
      return p.get('plantCanopyHierarchyVfxAudit') === '1' && p.get('renderScale') === ${JSON.stringify(String(scale))}
        && p.get('plantCanopyHierarchyVfx') === ${JSON.stringify(enabled ? '1' : '0')}
        && typeof audit?.setPlantCanopyHierarchyVfx === 'function' && typeof audit?.prepareBotanicalBodyVfxFixture === 'function'; })()`),
    scale === 4 ? 90_000 : 45_000, `E58 ${label} ${scale}x page`);
    await waitFor(() => evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
      scale === 4 ? 90_000 : 45_000, `E58 ${label} ${scale}x backend`);
    fixture = await evaluate(cdp, `(() => { const audit = window.__ANIFOR_INPUT_AUDIT__;
      audit.prepareBotanicalBodyVfxFixture(); return audit.botanicalBodyVfxFixture(); })()`);
    for (let pass = 0; pass < 7; pass++) {
      const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
      await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
      await waitFor(() => evaluate(cdp, `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
        scale === 4 ? 15_000 : 5_000, `E58 ${label} ${scale}x stability ${pass + 1}`);
    }
  }
  await waitFor(() => botanicalBodyVfxFixtureReady(cdp, fixture), 20_000, `E58 ${label} ${scale}x fixture hydration`);
  await waitFor(() => evaluate(cdp, `document.querySelector('canvas.semantic-field-canvas')?.dataset.plantCanopyHierarchyVfx === ${JSON.stringify(enabled ? 'active' : 'inactive')}`),
    20_000, `E58 ${label} ${scale}x in-place selector`);
  const hdrPipeline = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas'); if (!canvas) return undefined;
    const names = ['botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx', 'plantLaminaVfx',
      'plantLobeDepthVfx', 'plantCanopyMassVfx', 'plantCanopyTissueVfx', 'plantCanopyInterlockVfx', 'plantCanopyHierarchyVfx'];
    return { state: canvas.dataset.hdrPipeline, bloomBacking: canvas.dataset.bloomBacking,
      ...Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])) }; })()`);
  const { targets } = plantLaminaVfxRegions(fixture);
  return { fixture, hdrPipeline, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    walls: await botanicalBodyVfxWallDigest(cdp), targetDigest: await plantLaminaVfxTargetDigest(cdp, targets),
    lifecycleDigest: await botanicalBodyVfxLifecycleDigest(cdp, fixture), auxiliaryDigest: await botanicalMesostructureVfxAuxiliaryDigest(cdp, fixture),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp, true, targets),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, plantLaminaVfxRawControlPoints(fixture)),
    capture: await captureSettledPage(cdp, `E58 ${label} ${scale}x completed framebuffer`, 450, false, false, false, scale === 4 ? 60_000 : 30_000) };
}

async function writePlantCanopyHierarchyVfxScreenshots(source, scale, disabled, enabled) {
  const paths = { off: variantScreenshotPath(source, `e58-plant-canopy-hierarchy-${scale}x-off`),
    on: variantScreenshotPath(source, `e58-plant-canopy-hierarchy-${scale}x-on`) };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64')); return paths;
}

async function auditEightXPlantCanopyHierarchyVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({ scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-plant-canopy-hierarchy', plantCanopyHierarchyVfxAudit: '1', renderLook: 'realistic',
    botanicalBodyVfx: '1', botanicalMesostructureVfx: '1', botanicalPigmentVfx: '1', plantLaminaVfx: '1',
    plantLobeDepthVfx: '1', plantCanopyMassVfx: '1', plantCanopyTissueVfx: '1', plantCanopyInterlockVfx: '1', plantCanopyHierarchyVfx: '1' });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` }); const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => { const p = new URLSearchParams(location.search); return p.get('renderScale') === '8'
    && p.get('plantCanopyHierarchyVfxAudit') === '1' && p.get('plantCanopyHierarchyVfx') === '1' && Boolean(window.__ANIFOR_INPUT_AUDIT__); })()`),
  remainingDeadlineMs(deadline, 'true-8x E58 input audit API'), 'true-8x E58 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E58', deadline); assertEightXWebGLBackend(backend, 'true-8x E58');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E58 geometry')), 'true-8x E58 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
    `true-8x E58 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas'); const names = [
    'botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx', 'plantLaminaVfx',
    'plantLobeDepthVfx', 'plantCanopyMassVfx', 'plantCanopyTissueVfx', 'plantCanopyInterlockVfx',
    'plantCanopyHierarchyVfx']; return canvas ? {
    state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking ?? null,
    ...Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])) } : undefined; })()`);
  assert(isolation?.state === 'inactive' && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && ['botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx', 'plantLaminaVfx',
      'plantLobeDepthVfx', 'plantCanopyMassVfx', 'plantCanopyTissueVfx', 'plantCanopyInterlockVfx',
      'plantCanopyHierarchyVfx'].every((name) => isolation[name] === 'inactive'),
  `true-8x E58/HDR exclusion failed (${JSON.stringify(isolation)})`);
  const budget = remainingDeadlineMs(deadline, 'true-8x E58 GPU completion');
  const timing = await auditWebGLPresentationTiming(cdp, 1, Math.min(12_000, budget), budget, 1);
  assert(timing.source === 'gpu-fence' || timing.source === 'gpu-query' || timing.source === 'gpu-finish',
    `true-8x E58 did not complete GPU work (${JSON.stringify(timing)})`);
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`, promotionFence: 'signaled', isolation, timing };
}

/** E55: exact-state PLNT canopy interlock, strictly subordinate to E53. */
async function auditPlantCanopyInterlockVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigatePlantCanopyMassVfxState(
        cdp, mode, scale, enabled, key, true, true, key !== 'disabled',
      );
    }
    const { disabled, enabled, disabledRepeat } = captures;
    assert(JSON.stringify(disabled.fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(disabled.fixture) === JSON.stringify(disabledRepeat.fixture),
    `E55 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E55 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl'
        && variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.botanicalBodyVfx === 'active'
        && variant.hdrPipeline.botanicalMesostructureVfx === 'active'
        && variant.hdrPipeline.botanicalPigmentVfx === 'active'
        && variant.hdrPipeline.plantLaminaVfx === 'active'
        && variant.hdrPipeline.plantLobeDepthVfx === 'active'
        && variant.hdrPipeline.plantCanopyMassVfx === 'active'
        && variant.hdrPipeline.plantCanopyTissueVfx === 'active'
        && variant.hdrPipeline.plantCanopyInterlockVfx
          === (label === 'enabled' ? 'active' : 'inactive'),
      `E55 ${label} ${scale}x parent/selector state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
      assertBotanicalBodyVfxLifecycleDigest(variant.lifecycleDigest, `E55 ${label} ${scale}x`);
      assertPlantLaminaVfxTargetDigest(variant.targetDigest, scale);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E55 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E55 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E55 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E55 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E55 ${scale}x disabled/repeated`);
    assertPlantCanopyInterlockBackingInvariant(
      disabled.backing, enabled.backing, `E55 ${scale}x disabled/enabled`, false,
    );
    assertPlantCanopyInterlockBackingInvariant(
      disabled.backing, disabledRepeat.backing, `E55 ${scale}x disabled/repeated`, true,
    );
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls),
    `E55 ${scale}x changed native-wall topology`);
    assert(JSON.stringify(disabled.lifecycleDigest) === JSON.stringify(enabled.lifecycleDigest)
      && JSON.stringify(disabled.lifecycleDigest) === JSON.stringify(disabledRepeat.lifecycleDigest),
    `E55 ${scale}x changed native PLNT lifecycle state`);
    assert(JSON.stringify(disabled.auxiliaryDigest) === JSON.stringify(enabled.auxiliaryDigest)
      && JSON.stringify(disabled.auxiliaryDigest) === JSON.stringify(disabledRepeat.auxiliaryDigest),
    `E55 ${scale}x changed scoped solid-depth/contact auxiliary evidence`);
    assert(JSON.stringify(disabled.targetDigest) === JSON.stringify(enabled.targetDigest)
      && JSON.stringify(disabled.targetDigest) === JSON.stringify(disabledRepeat.targetDigest),
    `E55 ${scale}x changed exact PLNT target semantics, state, or depth`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E55 ${scale}x changed an exact protected raw control`);
    const { targets, controls } = plantLaminaVfxRegions(disabled.fixture);
    const sampled = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const responses = sampled.map((sample) => {
      const meanRgbRms = Math.hypot(...sample.responseRgb) / Math.sqrt(3);
      return { ...sample,
        spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2 - meanRgbRms ** 2)), 3) };
    });
    const byName = Object.fromEntries(responses.map((sample) => [sample.name, sample]));
    const targetResponses = targets.map(({ name }) => byName[name]);
    const controlResponses = controls.map(({ name }) => byName[name]);
    const controlAllowance = (sample) => (
      PLANT_CANOPY_INTERLOCK_VFX_ACCEPTANCE
        .composedResponseControlPeak[scale]?.[sample.name] ?? 0
    );
    assertPlantCanopyInterlockVfxResponses(targetResponses, scale);
    assert(controlResponses.length === 34
      && new Set(controlResponses.map(({ name }) => name)).size === 34
      && controlResponses.every((sample) => sample
        && sample.rgbPeak <= controlAllowance(sample)
        && sample.repeatRgbPeak <= controlAllowance(sample)),
    `E55 ${scale}x escaped a Wood/lifecycle/topology/contact/wall/foreign-owner control (${JSON.stringify(controlResponses)})`);
    assert(targetResponses.every((sample) => sample.repeatRgbPeak === 0)
      && controlResponses.every((sample) => sample.repeatRgbPeak <= controlAllowance(sample)),
      `E55 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);

    const frequency = await sampleBotanicalMesostructureFrequency(cdp, {
      disabled: disabled.capture.capture.data,
      enabled: enabled.capture.capture.data,
      disabledRepeat: disabledRepeat.capture.capture.data,
    }, targets, 'E55');
    assertPlantCanopyInterlockVfxFrequency(frequency, scale);
    const appearance = await samplePlantCanopyMassAppearance(cdp, {
      disabled: disabled.capture.capture.data,
      enabled: enabled.capture.capture.data,
    }, targets);
    assertPlantCanopyInterlockVfxAppearance(appearance, scale);
    const lifecycleSamples = await samplePageRegions(
      cdp, enabled.capture.capture.data, botanicalBodyVfxLifecycleRegions(disabled.fixture),
      undefined, undefined, enabled.capture.canvasRect,
    );
    const lifecycleAppearance = assertBotanicalBodyVfxLifecycleColors(lifecycleSamples, scale, 'E55');
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writePlantCanopyInterlockVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, backing: disabled.geometry.backing, targetDigest: disabled.targetDigest,
      auxiliaryDigest: disabled.auxiliaryDigest, lifecycleDigest: disabled.lifecycleDigest,
      walls: disabled.walls, rawControls: disabled.rawControls, targetResponses,
      controlResponses, frequency, appearance, lifecycleSamples, lifecycleAppearance,
      repeatedTargetPeak: Math.max(...targetResponses.map((sample) => sample.repeatRgbPeak)),
      repeatedControlPagePeak: Math.max(...controlResponses.map((sample) => sample.repeatRgbPeak)),
      screenshots,
    });
  }
  if (scales.length > 1) assertPlantCanopyInterlockVfxCrossScale(scales);
  const trueEightX = await auditEightXPlantCanopyMassVfxExclusion(cdp, dpr, false, true);
  return {
    calibration: 'frozen', acceptance: PLANT_CANOPY_INTERLOCK_VFX_ACCEPTANCE,
    scales, trueEightXExcluded: true, trueEightX,
  };
}

function assertPlantCanopyInterlockVfxResponses(samples, scale) {
  assert(samples.length === 2 && new Set(samples.map(({ name }) => name)).size === 2
    && samples.every((sample) => {
      const bounds = PLANT_CANOPY_INTERLOCK_VFX_ACCEPTANCE.targets[sample?.name]?.response;
      const inRange = (value, range) => Number.isFinite(value)
        && value >= range[0] && value <= range[1];
      return sample && bounds
        && inRange(sample.rgbRms, bounds.rgbRms)
        && inRange(sample.chromaRms, bounds.chromaRms)
        && inRange(sample.spatialRgbRms, bounds.spatialRgbRms)
        && inRange(sample.rgbPeak, bounds.rgbPeak)
        && inRange(sample.coverage, bounds.coverage)
        && inRange(sample.signedMean, bounds.signedMean)
        && inRange(sample.meanBiasRatio, bounds.meanBiasRatio)
        && inRange(sample.positiveMean, bounds.positiveMean)
        && inRange(sample.negativeMean, bounds.negativeMean)
        && inRange(sample.bipolarBalance, bounds.bipolarBalance)
        && inRange(sample.responseMicroContrast, bounds.responseMicroContrast)
        && inRange(sample.responseRgb[0], bounds.red)
        && inRange(sample.responseRgb[1], bounds.green)
        && inRange(sample.responseRgb[2], bounds.blue)
        && sample.repeatRgbPeak === 0;
    }),
  `E55 ${scale}x PLNT interlock response escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyInterlockVfxFrequency(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && samples.every((sample) => {
    const bounds = PLANT_CANOPY_INTERLOCK_VFX_ACCEPTANCE.targets[sample?.name]?.frequency;
    return sample?.code === 'PLNT' && bounds
      && inRange(sample.mesoRgbRms, bounds.mesoRgbRms)
      && inRange(sample.cellRgbRms, bounds.cellRgbRms)
      && inRange(sample.mesoShare, bounds.mesoShare)
      && inRange(sample.positiveCoverage, bounds.positiveCoverage)
      && inRange(sample.negativeCoverage, bounds.negativeCoverage)
      && inRange(sample.mesoMeanBiasRatio, bounds.mesoMeanBiasRatio)
      && inRange(sample.downsampleRetention, bounds.downsampleRetention)
      && inRange(sample.gradientRatio, bounds.gradientRatio)
      && inRange(sample.rgbPeak, bounds.rgbPeak)
      && sample.ySegmentMesoRgbRms?.length === 3
      && sample.ySegmentMesoRgbRms.every((value, index) => inRange(
        value, bounds.ySegmentMesoRgbRms[index],
      ))
      && sample.repeatRgbPeak === 0;
  }), `E55 ${scale}x PLNT interlock frequency escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyInterlockVfxAppearance(samples, scale) {
  const inRange = (value, range) => Number.isFinite(value)
    && value >= range[0] && value <= range[1];
  assert(samples.length === 2 && samples.every((sample) => {
    const bounds = PLANT_CANOPY_INTERLOCK_VFX_ACCEPTANCE.targets[sample?.name]?.appearance;
    const darkSeamGain = sample?.enabled.darkSeamFraction - sample?.disabled.darkSeamFraction;
    const strongSeamGain = sample?.enabled.strongSeamFraction - sample?.disabled.strongSeamFraction;
    const localContrastGain = sample?.enabled.localContrastRms - sample?.disabled.localContrastRms;
    const lumaStdDevGain = sample?.enabled.lumaStdDev - sample?.disabled.lumaStdDev;
    const macroGain = sample?.enabled.macroP90P10 - sample?.disabled.macroP90P10;
    const meanLumaGain = sample?.enabled.meanLuma - sample?.disabled.meanLuma;
    return sample?.code === 'PLNT' && bounds
      && sample.uniqueSamplePixels === sample.width * sample.height
      && inRange(sample.enabled.darkSeamFraction, bounds.enabledDarkSeam)
      && inRange(sample.enabled.strongSeamFraction, bounds.enabledStrongSeam)
      && inRange(darkSeamGain, bounds.darkSeamGain)
      && inRange(strongSeamGain, bounds.strongSeamGain)
      && inRange(sample.enabled.localContrastRms, bounds.enabledLocalContrastRms)
      && inRange(localContrastGain, bounds.localContrastGain)
      && inRange(sample.localContrastRetention, bounds.localContrastRetention)
      && inRange(sample.enabled.lumaStdDev, bounds.enabledLumaStdDev)
      && inRange(lumaStdDevGain, bounds.lumaStdDevGain)
      && inRange(sample.enabled.macroP90P10, bounds.enabledMacro)
      && inRange(macroGain, bounds.macroGain)
      && inRange(meanLumaGain, bounds.meanLumaGain);
  }), `E55 ${scale}x PLNT interlock appearance escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyInterlockVfxCrossScale(scales) {
  const bounds = PLANT_CANOPY_INTERLOCK_VFX_ACCEPTANCE.spread;
  const spread = (values) => Math.max(...values) - Math.min(...values);
  for (const name of ['PLNTLeft', 'PLNTRight']) {
    const responses = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
    const frequency = scales.map((entry) => entry.frequency.find((sample) => sample.name === name));
    const appearance = scales.map((entry) => entry.appearance.find((sample) => sample.name === name));
    assert(responses.every(Boolean) && frequency.every(Boolean) && appearance.every(Boolean)
      && spread(responses.map((sample) => sample.rgbRms)) <= bounds.rgbRms
      && spread(responses.map((sample) => sample.chromaRms)) <= bounds.chromaRms
      && spread(responses.map((sample) => sample.spatialRgbRms)) <= bounds.spatialRgbRms
      && spread(responses.map((sample) => sample.rgbPeak)) <= bounds.rgbPeak
      && spread(responses.map((sample) => sample.coverage)) <= bounds.coverage
      && spread(responses.map((sample) => sample.signedMean)) <= bounds.signedMean
      && spread(responses.map((sample) => sample.meanBiasRatio)) <= bounds.meanBiasRatio
      && spread(responses.map((sample) => sample.bipolarBalance)) <= bounds.bipolarBalance
      && spread(responses.map((sample) => sample.responseMicroContrast)) <= bounds.responseMicroContrast
      && spread(frequency.map((sample) => sample.mesoRgbRms)) <= bounds.mesoRgbRms
      && spread(frequency.map((sample) => sample.cellRgbRms)) <= bounds.cellRgbRms
      && spread(frequency.map((sample) => sample.mesoShare)) <= bounds.mesoShare
      && spread(frequency.map((sample) => sample.positiveCoverage)) <= bounds.positiveCoverage
      && spread(frequency.map((sample) => sample.negativeCoverage)) <= bounds.negativeCoverage
      && spread(frequency.map((sample) => sample.mesoMeanBiasRatio)) <= bounds.mesoMeanBiasRatio
      && spread(frequency.map((sample) => sample.downsampleRetention)) <= bounds.downsampleRetention
      && spread(frequency.map((sample) => sample.gradientRatio)) <= bounds.gradientRatio
      && [0, 1, 2].every((index) => spread(frequency.map(
        (sample) => sample.ySegmentMesoRgbRms[index],
      )) <= bounds.ySegmentMesoRgbRms)
      && spread(appearance.map((sample) => sample.enabled.localContrastRms))
        <= bounds.enabledLocalContrastRms
      && spread(appearance.map((sample) => sample.enabled.localContrastRms
        - sample.disabled.localContrastRms)) <= bounds.localContrastGain
      && spread(appearance.map((sample) => sample.localContrastRetention)) <= bounds.localContrastRetention
      && spread(appearance.map((sample) => sample.enabled.darkSeamFraction)) <= bounds.enabledDarkSeam
      && spread(appearance.map((sample) => sample.enabled.strongSeamFraction)) <= bounds.enabledStrongSeam
      && spread(appearance.map((sample) => sample.enabled.darkSeamFraction
        - sample.disabled.darkSeamFraction)) <= bounds.darkSeamGain
      && spread(appearance.map((sample) => sample.enabled.strongSeamFraction
        - sample.disabled.strongSeamFraction)) <= bounds.strongSeamGain
      && spread(appearance.map((sample) => sample.enabled.meanLuma
        - sample.disabled.meanLuma)) <= bounds.meanLumaGain
      && spread(appearance.map((sample) => sample.enabled.lumaStdDev
        - sample.disabled.lumaStdDev)) <= bounds.lumaStdDevGain
      && spread(appearance.map((sample) => sample.enabled.macroP90P10
        - sample.disabled.macroP90P10)) <= bounds.macroGain,
    `E55 ${name} changed excessively across normal output scales (${JSON.stringify({ responses, frequency, appearance })})`);
  }
}

function assertPlantCanopyInterlockBackingInvariant(left, right, label, requireRepeatedRgb) {
  const comparableRegions = left.regionDigests?.length === 2
    && right.regionDigests?.length === 2
    && left.regionDigests.every((region, index) => {
      const other = right.regionDigests[index];
      return region.name === other?.name && region.width === other.width && region.height === other.height
        && region.alphaSignature === other.alphaSignature
        && region.supportSignature === other.supportSignature
        && region.alphaSum === other.alphaSum && region.supported === other.supported
        && (!requireRepeatedRgb || region.rgbaSignature === other.rgbaSignature);
    });
  assert(left.width === right.width && left.height === right.height
    && left.supportSignature === right.supportSignature && left.supported === right.supported
    && comparableRegions,
  `${label}: E55 changed whole-world support or owned PLNT alpha/repeated RGB (${JSON.stringify({
    left, right, requireRepeatedRgb,
  })})`);
}

async function navigatePlantCanopyMassVfxState(
  cdp, mode, scale, enabled, label, tissueExperiment = false, interlockExperiment = false,
  reuseHydratedPage = false,
) {
  const experiment = interlockExperiment ? 'E55' : (tissueExperiment ? 'E53' : 'E36');
  const canopyMassEnabled = tissueExperiment || interlockExperiment ? '1' : (enabled ? '1' : '0');
  const canopyTissueEnabled = interlockExperiment ? '1' : (tissueExperiment && enabled ? '1' : '0');
  const canopyInterlockEnabled = interlockExperiment && enabled ? '1' : '0';
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    plantCanopyMassVfxAudit: tissueExperiment || interlockExperiment ? '0' : '1',
    plantCanopyTissueVfxAudit: interlockExperiment ? '0' : (tissueExperiment ? '1' : '0'),
    plantCanopyInterlockVfxAudit: interlockExperiment ? '1' : '0',
    renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0',
    nobleGasPrismVfx: '0', smokeSoftnessVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '1',
    botanicalMesostructureVfx: '1', botanicalPigmentVfx: '1', plantLaminaVfx: '1',
    plantLobeDepthVfx: '1', plantCanopyMassVfx: canopyMassEnabled,
    plantCanopyTissueVfx: canopyTissueEnabled,
    plantCanopyInterlockVfx: canopyInterlockEnabled,
    plantCanopyHierarchyVfx: '0',
    woodBarkReliefVfx: '0', woodTanninVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0',
    rockRoughnessVfx: '0', rockMesostructureVfx: '0', waterBodyVfx: '0',
  });
  let fixture;
  if (reuseHydratedPage) {
    assert(interlockExperiment && mode === 'webgl',
      `${experiment} ${label} ${scale}x requested unsupported in-place reuse`);
    const reused = await evaluate(cdp, `(() => {
      const p = new URLSearchParams(location.search);
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      if (p.get('plantCanopyInterlockVfxAudit') !== '1'
        || p.get('renderScale') !== ${JSON.stringify(String(scale))}
        || audit?.backend().backend !== 'webgl'
        || typeof audit?.setPlantCanopyInterlockVfx !== 'function'
        || typeof audit?.botanicalBodyVfxFixture !== 'function') return undefined;
      audit.setPlantCanopyInterlockVfx(${JSON.stringify(enabled)});
      return { fixture: audit.botanicalBodyVfxFixture(), backend: audit.backend().backend };
    })()`);
    assert(reused?.backend === 'webgl' && reused.fixture,
      `${experiment} ${label} ${scale}x could not reuse its hydrated WebGL fixture`);
    fixture = reused.fixture;
    await waitFor(() => evaluate(cdp, `(() => {
      const canvas = document.querySelector('canvas.semantic-field-canvas');
      return canvas?.dataset.plantCanopyInterlockVfx
        === ${JSON.stringify(enabled ? 'active' : 'inactive')};
    })()`), 20_000, `${experiment} ${label} ${scale}x in-place selector`);
  } else {
    await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
    await waitFor(() => evaluate(cdp, `(() => {
      const p = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
      return p.get('plantCanopyMassVfxAudit') === ${JSON.stringify(tissueExperiment || interlockExperiment ? '0' : '1')}
        && p.get('plantCanopyTissueVfxAudit') === ${JSON.stringify(interlockExperiment ? '0' : (tissueExperiment ? '1' : '0'))}
        && p.get('plantCanopyInterlockVfxAudit') === ${JSON.stringify(interlockExperiment ? '1' : '0')}
        && p.get('renderScale') === ${JSON.stringify(String(scale))}
        && p.get('renderLook') === 'realistic' && p.get('botanicalBodyVfx') === '1'
        && p.get('botanicalMesostructureVfx') === '1' && p.get('botanicalPigmentVfx') === '1'
        && p.get('plantLaminaVfx') === '1' && p.get('plantLobeDepthVfx') === '1'
        && p.get('plantCanopyMassVfx') === ${JSON.stringify(canopyMassEnabled)}
        && p.get('plantCanopyTissueVfx') === ${JSON.stringify(canopyTissueEnabled)}
        && p.get('plantCanopyInterlockVfx') === ${JSON.stringify(canopyInterlockEnabled)}
        && p.get('plantCanopyHierarchyVfx') === '0'
        && p.get('woodBarkReliefVfx') === '0' && p.get('woodTanninVfx') === '0'
        && ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx',
          'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx',
          'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx', 'liquidSolidMeniscusVfx',
          'gasCoreDepthVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
          'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
          'woodBarkReliefVfx', 'woodTanninVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
          'rockMesostructureVfx', 'waterBodyVfx'].every((name) => p.get(name) === '0')
        && typeof audit?.prepareBotanicalBodyVfxFixture === 'function'
        && typeof audit?.botanicalBodyVfxFixture === 'function'
        && (!${JSON.stringify(interlockExperiment)}
          || typeof audit?.setPlantCanopyInterlockVfx === 'function');
    })()`), scale === 4 ? 90_000 : scale === 2 ? 45_000 : 20_000,
    `${experiment} ${label} ${scale}x page`);
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
    scale === 4 ? 90_000 : scale === 2 ? 45_000 : 20_000,
    `${experiment} ${label} ${scale}x backend`);
    fixture = await evaluate(cdp, `(() => {
      const audit = window.__ANIFOR_INPUT_AUDIT__;
      audit.prepareBotanicalBodyVfxFixture(); return audit.botanicalBodyVfxFixture();
    })()`);
  }
  if (interlockExperiment && !reuseHydratedPage) {
    // The fixture includes settled Sand contact controls. A paused RenderLab
    // does not advance their caller-owned temporal-stability bytes on its own,
    // so finish the canonical seven refreshes before taking the causal baseline.
    for (let pass = 0; pass < 7; pass++) {
      const before = await evaluate(cdp,
        'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
      await evaluate(cdp,
        'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
      await waitFor(() => evaluate(cdp, `(() => {
        const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
        return current?.dynamicSequence > ${before.dynamicSequence} ? current : false;
      })()`), scale === 4 ? 15_000 : 5_000,
      `${experiment} ${label} ${scale}x stability pass ${pass + 1}`);
    }
  }
  await waitFor(() => botanicalBodyVfxFixtureReady(cdp, fixture), 20_000,
    `${experiment} ${label} ${scale}x fixture hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    const names = ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx',
      'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx',
      'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx', 'liquidSolidMeniscusVfx',
      'gasCoreDepthVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
      'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
      'botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx',
      'plantLaminaVfx', 'plantLobeDepthVfx', 'plantCanopyMassVfx', 'plantCanopyTissueVfx',
      'plantCanopyInterlockVfx', 'plantCanopyHierarchyVfx',
      'woodBarkReliefVfx',
      'woodTanninVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
      'rockMesostructureVfx', 'waterBodyVfx'];
    return canvas ? { look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      bloomBacking: canvas.dataset.bloomBacking,
      ...Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])) } : undefined;
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  const siblings = [
    'volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx',
    'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx',
    'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx', 'liquidSolidMeniscusVfx',
    'gasCoreDepthVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
    'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
    'woodBarkReliefVfx', 'woodTanninVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
    'rockMesostructureVfx', 'waterBodyVfx',
  ];
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.botanicalBodyVfx === 'active'
    && hdrPipeline.botanicalMesostructureVfx === 'active'
    && hdrPipeline.botanicalPigmentVfx === 'active' && hdrPipeline.plantLaminaVfx === 'active'
    && hdrPipeline.plantLobeDepthVfx === 'active'
    && hdrPipeline.plantCanopyMassVfx === (canopyMassEnabled === '1' ? 'active' : 'inactive')
    && hdrPipeline.plantCanopyTissueVfx === (canopyTissueEnabled === '1' ? 'active' : 'inactive')
    && hdrPipeline.plantCanopyInterlockVfx === (canopyInterlockEnabled === '1' ? 'active' : 'inactive')
    && hdrPipeline.plantCanopyHierarchyVfx === 'inactive'
    && siblings.every((name) => hdrPipeline[name] === 'inactive'),
  `${experiment} ${label} ${scale}x HDR/selector state resolved incorrectly (${JSON.stringify(hdrPipeline)})`);
  const indicator = await evaluate(cdp, `(() => {
    const nodes = [...document.querySelectorAll('.field-indicator')];
    for (const node of nodes) node.style.visibility = 'hidden';
    return { count: nodes.length, hidden: nodes.every((node) => getComputedStyle(node).visibility === 'hidden') };
  })()`);
  assert(indicator.count > 0 && indicator.hidden,
    `${experiment} ${label} ${scale}x did not hide only the field indicator overlay`);
  // E55 owns no animated carrier. Its focused matrix toggles one live uniform
  // on one hydrated page per scale, then follows the renderer's completed-
  // presentation contract. This avoids comparing unrelated Sand/field rebuilds
  // while retaining direct and composed off -> on -> off evidence.
  const capture = interlockExperiment && mode === 'webgl'
    ? await captureSettledPage(
      cdp, `${experiment} ${label} ${scale}x completed framebuffer`, 450,
      false, false, false, scale === 4 ? 60_000 : 30_000,
    )
    : await waitForStablePageCapture(cdp, `${experiment} ${label} ${scale}x framebuffer`,
      scale === 4 ? 120_000 : scale === 2 ? 30_000 : 15_000, 1);
  const { targets } = plantLaminaVfxRegions(fixture);
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    walls: await botanicalBodyVfxWallDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(
      cdp, interlockExperiment && mode === 'webgl', interlockExperiment ? targets : [],
    ),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, plantLaminaVfxRawControlPoints(fixture)),
    lifecycleDigest: await botanicalBodyVfxLifecycleDigest(cdp, fixture),
    auxiliaryDigest: await botanicalMesostructureVfxAuxiliaryDigest(cdp, fixture),
    targetDigest: await plantLaminaVfxTargetDigest(cdp, targets), hdrPipeline,
  };
}

function assertPlantCanopyMassVfxResponses(samples, scale) {
  assert(samples.length === 2 && new Set(samples.map(({ name }) => name)).size === 2
    && samples.every((sample) => {
      const bounds = PLANT_CANOPY_MASS_VFX_ACCEPTANCE.targets[sample?.name]?.response;
      return sample && bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1]
        && sample.spatialRgbRms >= bounds.spatialRgbRms[0] && sample.spatialRgbRms <= bounds.spatialRgbRms[1]
        && sample.responseMicroContrast >= bounds.responseMicroContrast[0]
        && sample.responseMicroContrast <= bounds.responseMicroContrast[1]
        && sample.meanBiasRatio >= bounds.meanBiasRatio[0] && sample.meanBiasRatio <= bounds.meanBiasRatio[1]
        && sample.bipolarBalance >= bounds.bipolarBalance[0] && sample.bipolarBalance <= bounds.bipolarBalance[1]
        && sample.responseRgb[0] >= bounds.red[0] && sample.responseRgb[0] <= bounds.red[1]
        && sample.responseRgb[1] >= bounds.green[0] && sample.responseRgb[1] <= bounds.green[1]
        && sample.responseRgb[2] >= bounds.blue[0] && sample.responseRgb[2] <= bounds.blue[1]
        && sample.repeatRgbPeak === 0;
    }),
  `E36 ${scale}x PLNT canopy-mass response escaped its frozen envelope (${JSON.stringify(samples)})`);
}

function assertPlantCanopyMassVfxFrequency(samples, scale) {
  assert(samples.length === 2 && new Set(samples.map(({ name }) => name)).size === 2
    && samples.every(({ code }) => code === 'PLNT'),
  `E36 ${scale}x frequency targets were incomplete (${JSON.stringify(samples)})`);
  for (const sample of samples) {
    const bounds = PLANT_CANOPY_MASS_VFX_ACCEPTANCE.targets[sample.name]?.frequency;
    assert(bounds && sample.mesoRgbRms >= bounds.mesoRgbRms[0] && sample.mesoRgbRms <= bounds.mesoRgbRms[1]
      && sample.cellRgbRms >= bounds.cellRgbRms[0] && sample.cellRgbRms <= bounds.cellRgbRms[1]
      && sample.mesoShare >= bounds.mesoShare[0] && sample.mesoShare <= bounds.mesoShare[1]
      && sample.positiveCoverage >= bounds.positiveCoverage[0]
      && sample.positiveCoverage <= bounds.positiveCoverage[1]
      && sample.negativeCoverage >= bounds.negativeCoverage[0]
      && sample.negativeCoverage <= bounds.negativeCoverage[1]
      && sample.mesoMeanBiasRatio >= bounds.mesoMeanBiasRatio[0]
      && sample.mesoMeanBiasRatio <= bounds.mesoMeanBiasRatio[1]
      && sample.downsampleRetention >= bounds.downsampleRetention[0]
      && sample.downsampleRetention <= bounds.downsampleRetention[1]
      && sample.gradientRatio >= bounds.gradientRatio[0] && sample.gradientRatio <= bounds.gradientRatio[1]
      && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
      && sample.repeatRgbPeak === 0,
    `E36 ${scale}x ${sample.name} canopy-mass frequency was absent or unbounded (${JSON.stringify(sample)})`);
  }
}

function assertPlantCanopyMassVfxCrossScale(scales) {
  const bounds = PLANT_CANOPY_MASS_VFX_ACCEPTANCE.spread;
  const spread = (values) => Math.max(...values) - Math.min(...values);
  for (const name of ['PLNTLeft', 'PLNTRight']) {
    const responses = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
    const frequency = scales.map((entry) => entry.frequency.find((sample) => sample.name === name));
    const appearance = scales.map((entry) => entry.appearance.find((sample) => sample.name === name));
    assert(responses.every(Boolean) && frequency.every(Boolean) && appearance.every(Boolean)
      && spread(responses.map((sample) => sample.rgbRms)) <= bounds.rgbRms
      && spread(responses.map((sample) => sample.chromaRms)) <= bounds.chromaRms
      && spread(responses.map((sample) => sample.coverage)) <= bounds.coverage
      && spread(responses.map((sample) => sample.rgbPeak)) <= bounds.rgbPeak
      && spread(responses.map((sample) => sample.signedMean)) <= bounds.signedMean
      && spread(responses.map((sample) => sample.spatialRgbRms)) <= bounds.spatialRgbRms
      && spread(responses.map((sample) => sample.responseMicroContrast)) <= bounds.responseMicroContrast
      && spread(frequency.map((sample) => sample.mesoRgbRms)) <= bounds.mesoRgbRms
      && spread(frequency.map((sample) => sample.cellRgbRms)) <= bounds.cellRgbRms
      && spread(frequency.map((sample) => sample.downsampleRetention)) <= bounds.downsampleRetention
      && spread(frequency.map((sample) => sample.gradientRatio)) <= bounds.gradientRatio
      && spread(appearance.map((sample) => sample.disabled.darkSeamFraction))
        <= bounds.appearanceDisabledDarkSeam
      && spread(appearance.map((sample) => sample.enabled.darkSeamFraction))
        <= bounds.appearanceEnabledDarkSeam
      && spread(appearance.map((sample) => sample.disabled.strongSeamFraction))
        <= bounds.appearanceDisabledStrongSeam
      && spread(appearance.map((sample) => sample.enabled.strongSeamFraction))
        <= bounds.appearanceEnabledStrongSeam
      && spread(appearance.map((sample) => sample.seamRetention))
        <= bounds.appearanceSeamRetention
      && spread(appearance.map((sample) => sample.enabled.macroP90P10))
        <= bounds.appearanceEnabledMacro
      && spread(appearance.map((sample) => sample.enabled.macroP90P10
        - sample.disabled.macroP90P10)) <= bounds.appearanceMacroGain
      && spread(appearance.map((sample) => sample.enabled.lumaStdDev))
        <= bounds.appearanceEnabledLumaStdDev
      && spread(appearance.map((sample) => sample.enabled.localContrastRms))
        <= bounds.appearanceLocalContrastRms
      && spread(appearance.map((sample) => sample.localContrastRetention))
        <= bounds.appearanceLocalContrastRetention
      && spread(appearance.map((sample) => sample.enabled.meanLuma
        - sample.disabled.meanLuma)) <= bounds.appearanceMeanLumaGain,
    `E36 ${name} response drifted beyond its frozen cross-scale envelope`);
  }
}

/**
 * Measures the shipped PLNT body rather than only the E36 difference image.
 * A seven-cell local mean catches the rejected E26 cellular seam network;
 * a fifteen-cell mean retains the intended broad front/rear canopy hierarchy.
 */
async function samplePlantCanopyMassAppearance(cdp, screenshots, regions) {
  return evaluate(cdp, `(async () => {
    const sources = ${JSON.stringify(Object.fromEntries(
    Object.entries(screenshots).map(([name, data]) => [name, `data:image/png;base64,${data}`]),
  ))};
    const images = {};
    let imageWidth = 0; let imageHeight = 0;
    for (const [name, source] of Object.entries(sources)) {
      const image = new Image(); image.src = source; await image.decode();
      if (imageWidth && (image.naturalWidth !== imageWidth || image.naturalHeight !== imageHeight)) {
        throw new Error('E36 appearance screenshot geometry mismatch');
      }
      imageWidth = image.naturalWidth; imageHeight = image.naturalHeight;
      const copy = document.createElement('canvas'); copy.width = imageWidth; copy.height = imageHeight;
      const context = copy.getContext('2d', { willReadFrequently: true });
      if (!context) throw new Error('E36 appearance sampler unavailable');
      context.drawImage(image, 0, 0);
      images[name] = context.getImageData(0, 0, imageWidth, imageHeight).data;
    }
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const viewport = window.visualViewport;
    const pageScaleX = imageWidth / Math.max(1, viewport?.width ?? innerWidth);
    const pageScaleY = imageHeight / Math.max(1, viewport?.height ?? innerHeight);
    const offsetX = viewport?.offsetLeft ?? 0; const offsetY = viewport?.offsetTop ?? 0;
    const fixed = (value) => Math.round(value * 10000) / 10000;
    const percentile = (values, fraction) => {
      const sorted = [...values].sort((left, right) => left - right);
      return sorted[Math.max(0, Math.min(sorted.length - 1,
        Math.floor((sorted.length - 1) * fraction)))];
    };
    const statistics = (luma, width, height) => {
      const stride = width + 1; const integral = new Float64Array(stride * (height + 1));
      let sum = 0; let squared = 0;
      for (let y = 0; y < height; y++) {
        let row = 0;
        for (let x = 0; x < width; x++) {
          const value = luma[y * width + x]; row += value; sum += value; squared += value * value;
          integral[(y + 1) * stride + x + 1] = integral[y * stride + x + 1] + row;
        }
      }
      const areaMean = (x0, y0, x1, y1) => {
        const total = integral[y1 * stride + x1] - integral[y0 * stride + x1]
          - integral[y1 * stride + x0] + integral[y0 * stride + x0];
        return total / Math.max(1, (x1 - x0) * (y1 - y0));
      };
      let seams = 0; let strongSeams = 0; let localSquared = 0; let interior = 0;
      for (let y = 3; y < height - 3; y++) for (let x = 3; x < width - 3; x++) {
        const value = luma[y * width + x];
        const local = areaMean(x - 3, y - 3, x + 4, y + 4);
        const drop = local - value;
        seams += Number(drop >= 5); strongSeams += Number(drop >= 8);
        localSquared += drop * drop; interior++;
      }
      const broad = [];
      for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
        broad.push(areaMean(
          Math.max(0, x - 7), Math.max(0, y - 7),
          Math.min(width, x + 8), Math.min(height, y + 8),
        ));
      }
      const mean = sum / luma.length;
      return {
        meanLuma: fixed(mean),
        lumaStdDev: fixed(Math.sqrt(Math.max(0, squared / luma.length - mean * mean))),
        darkSeamFraction: fixed(seams / Math.max(1, interior)),
        strongSeamFraction: fixed(strongSeams / Math.max(1, interior)),
        localContrastRms: fixed(Math.sqrt(localSquared / Math.max(1, interior))),
        macroP90P10: fixed(percentile(broad, 0.90) - percentile(broad, 0.10)),
      };
    };
    return ${JSON.stringify(regions)}.map((region) => {
      const width = region.worldWidth; const height = region.worldHeight;
      const positions = new Uint32Array(width * height * 2);
      const sampledPixels = new Set();
      for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
        const worldX = region.worldX + x; const worldY = region.worldY + y;
        if (audit.cell(worldX, worldY) !== 10 || audit.wall(worldX, worldY) !== 0) {
          throw new Error('E36 appearance sampler escaped exact wall-free PLNT support');
        }
        const screen = audit.worldToScreen(worldX + 0.5, worldY + 0.5);
        const pixelX = Math.max(0, Math.min(imageWidth - 1,
          Math.floor((screen.x - offsetX) * pageScaleX)));
        const pixelY = Math.max(0, Math.min(imageHeight - 1,
          Math.floor((screen.y - offsetY) * pageScaleY)));
        const positionOffset = (y * width + x) * 2;
        positions[positionOffset] = pixelX; positions[positionOffset + 1] = pixelY;
        sampledPixels.add(pixelY * imageWidth + pixelX);
      }
      if (sampledPixels.size !== width * height) {
        throw new Error('E36 appearance sampler aliased adjacent world-cell centres');
      }
      const planes = {};
      for (const [name, pixels] of Object.entries(images)) {
        const luma = new Float64Array(width * height);
        for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
          const positionOffset = (y * width + x) * 2;
          const pixelX = positions[positionOffset]; const pixelY = positions[positionOffset + 1];
          const sourceOffset = (pixelY * imageWidth + pixelX) * 4;
          luma[y * width + x] = pixels[sourceOffset] * 0.2126
            + pixels[sourceOffset + 1] * 0.7152 + pixels[sourceOffset + 2] * 0.0722;
        }
        planes[name] = statistics(luma, width, height);
      }
      return {
        name: region.name, code: region.code, side: region.side, width, height,
        uniqueSamplePixels: sampledPixels.size,
        disabled: planes.disabled, enabled: planes.enabled,
        seamRetention: fixed(planes.enabled.darkSeamFraction
          / Math.max(0.0001, planes.disabled.darkSeamFraction)),
        localContrastRetention: fixed(planes.enabled.localContrastRms
          / Math.max(0.0001, planes.disabled.localContrastRms)),
      };
    });
  })()`);
}

function assertPlantCanopyMassAppearance(samples, scale) {
  assert(samples.length === 2 && new Set(samples.map(({ name }) => name)).size === 2
    && samples.every((sample) => {
      const bounds = PLANT_CANOPY_MASS_VFX_ACCEPTANCE.targets[sample?.name]?.appearance;
      const macroGain = sample?.enabled.macroP90P10 - sample?.disabled.macroP90P10;
      const meanLumaGain = sample?.enabled.meanLuma - sample?.disabled.meanLuma;
      return sample?.code === 'PLNT' && bounds
        && sample.uniqueSamplePixels === sample.width * sample.height
        && sample.disabled.darkSeamFraction >= bounds.disabledDarkSeam[0]
        && sample.disabled.darkSeamFraction <= bounds.disabledDarkSeam[1]
        && sample.disabled.strongSeamFraction >= bounds.disabledStrongSeam[0]
        && sample.disabled.strongSeamFraction <= bounds.disabledStrongSeam[1]
        && sample.enabled.darkSeamFraction >= bounds.enabledDarkSeam[0]
        && sample.enabled.darkSeamFraction <= bounds.enabledDarkSeam[1]
        && sample.enabled.strongSeamFraction >= bounds.enabledStrongSeam[0]
        && sample.enabled.strongSeamFraction <= bounds.enabledStrongSeam[1]
        && sample.seamRetention >= bounds.seamRetention[0]
        && sample.seamRetention <= bounds.seamRetention[1]
        && sample.enabled.macroP90P10 >= bounds.enabledMacro[0]
        && sample.enabled.macroP90P10 <= bounds.enabledMacro[1]
        && macroGain >= bounds.macroGain[0] && macroGain <= bounds.macroGain[1]
        && sample.enabled.lumaStdDev >= bounds.enabledLumaStdDev[0]
        && sample.enabled.lumaStdDev <= bounds.enabledLumaStdDev[1]
        && sample.enabled.localContrastRms >= bounds.enabledLocalContrastRms[0]
        && sample.enabled.localContrastRms <= bounds.enabledLocalContrastRms[1]
        && sample.localContrastRetention >= bounds.localContrastRetention[0]
        && sample.localContrastRetention <= bounds.localContrastRetention[1]
        && meanLumaGain >= bounds.meanLumaGain[0] && meanLumaGain <= bounds.meanLumaGain[1];
    }),
  `E36 ${scale}x did not replace cellular seams with a frozen broad canopy body (${JSON.stringify(samples)})`);
}

async function writePlantCanopyMassVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e36-plant-canopy-mass-${scale}x-off`),
    on: variantScreenshotPath(source, `e36-plant-canopy-mass-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

