/** E48: exact native Snow snowpack optics over E05's settled Smooth proof. */
async function auditSnowpackBodyVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      const variant = await navigateSnowpackBodyVfxState(cdp, mode, scale, enabled, key);
      variant.references = await capturePowderBodyVfxReferenceStyles(cdp, scale, key, 'E48');
      captures[key] = variant;
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E48 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E48 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E48 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.powderBodyVfx === 'active'
        && variant.hdrPipeline.sootyPowderBodyVfx === 'inactive'
        && variant.hdrPipeline.thermiteBodyVfx === 'inactive'
        && variant.hdrPipeline.snowpackBodyVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E48 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E48 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E48 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E48 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E48 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E48 ${scale}x disabled/repeated`);
    assert(disabled.semantic.occupied === fixture.expected.occupiedCells,
      `E48 ${scale}x occupied-cell cardinality drifted (${JSON.stringify(disabled.semantic)})`);
    assert(JSON.stringify(disabled.materialPlane) === JSON.stringify(enabled.materialPlane)
      && JSON.stringify(disabled.materialPlane) === JSON.stringify(disabledRepeat.materialPlane)
      && disabled.materialPlane.occupied === fixture.expected.occupiedCells
      && disabled.materialPlane.materialCounts[fixture.target.material] === fixture.expected.snowCells
      && disabled.materialPlane.materialCounts[2] === fixture.expected.waterCells
      && disabled.materialPlane.materialCounts[23] === fixture.expected.metalCells
      && Object.values(fixture.materialControls).every((entry) => (
        disabled.materialPlane.materialCounts[entry.material]
          === fixture.expected.cellsPerMaterialControl
      )),
    `E48 ${scale}x changed exact material-plane cardinalities (${JSON.stringify({
      occupied: disabled.materialPlane.occupied,
      snow: disabled.materialPlane.materialCounts[fixture.target.material],
      water: disabled.materialPlane.materialCounts[2],
      metal: disabled.materialPlane.materialCounts[23],
    })})`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E48 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E48 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied === fixture.expected.wallCells
      && disabled.walls.expectedOccupied === fixture.expected.wallCells
      && disabled.walls.mismatches === 0 && disabled.walls.matterMismatches === 0,
    `E48 ${scale}x changed native-wall topology (${JSON.stringify(disabled.walls)})`);
    assert(JSON.stringify(disabled.velocity) === JSON.stringify(enabled.velocity)
      && JSON.stringify(disabled.velocity) === JSON.stringify(disabledRepeat.velocity)
      && disabled.velocity.cells === fixture.expected.movingVelocityCells
      && disabled.velocity.expectedCells === fixture.expected.movingVelocityCells
      && disabled.velocity.mismatches === 0,
    `E48 ${scale}x changed authored Snow velocity (${JSON.stringify(disabled.velocity)})`);
    assert(JSON.stringify(disabled.auxiliary) === JSON.stringify(enabled.auxiliary)
      && JSON.stringify(disabled.auxiliary) === JSON.stringify(disabledRepeat.auxiliary),
    `E48 ${scale}x changed powder stability auxiliary state (${JSON.stringify(disabled.auxiliary)})`);
    assert(Object.values(disabled.auxiliary.stable).every((range) => (
      range.min === 255 && range.max === 255
    )) && disabled.auxiliary.moving.min < 255 && disabled.auxiliary.moving.max < 255,
    `E48 ${scale}x lost settled-body or moving-region stability proof (${JSON.stringify(disabled.auxiliary)})`);
    assert(JSON.stringify(disabled.suspension) === JSON.stringify(enabled.suspension)
      && JSON.stringify(disabled.suspension) === JSON.stringify(disabledRepeat.suspension),
    `E48 ${scale}x changed Snow/Water suspension support (${JSON.stringify(disabled.suspension)})`);
    const suspendedSnow = disabled.suspension.find(({ name }) => name === 'SuspendedSnow');
    const suspensionWater = disabled.suspension.find(({ name }) => name === 'SuspensionWater');
    assert(suspendedSnow?.cell === fixture.target.material && suspendedSnow.rgba[3] > 0
      && suspendedSnow.liquidAlpha > 0 && suspensionWater?.cell === 2
      && suspensionWater.rgba[3] > 0 && suspensionWater.liquidAlpha > 0,
    `E48 ${scale}x did not establish genuine Snow/Water suspension support (${JSON.stringify(disabled.suspension)})`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E48 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E48 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E48 ${scale}x changed an exact raw topology/material/contact control (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls,
    })})`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E48 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = snowpackBodyVfxTargetRegions(fixture);
    const controls = snowpackBodyVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length).map((sample) => ({
      ...sample,
      spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2
        - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2)), 3),
    }));
    const controlResponses = responses.slice(targets.length);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E48 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    assert(targetResponses.every((sample) => [
      sample.rgbRms, sample.chromaRms, sample.rgbPeak, sample.coverage,
      sample.signedMean, sample.spatialRgbRms,
    ].every(Number.isFinite)
      && sample.rgbRms >= SNOWPACK_BODY_VFX_RESPONSE_LIMITS.minimumRgbRms
      && sample.rgbRms <= SNOWPACK_BODY_VFX_RESPONSE_LIMITS.maximumRgbRms
      && sample.rgbPeak <= SNOWPACK_BODY_VFX_RESPONSE_LIMITS.maximumRgbPeak
      && sample.coverage >= SNOWPACK_BODY_VFX_RESPONSE_LIMITS.minimumCoverage),
    `E48 ${scale}x Snowpack response was absent or unbounded (${JSON.stringify(targetResponses)})`);
    const byName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    // Calming the dark/light flake carrier can raise a pocket's net mean even
    // while the retained macro lobe remains locally absorptive. Require that
    // differentiated negative lobe directly instead of inventing a net-dark
    // grade that the renderer does not promise.
    assert(byName.SNOWCrown.signedMean > byName.SNOWPocket.signedMean + 0.50
      && byName.SNOWPocket.negativeMean >= 0.50
      && byName.SNOWWholeBody.positiveMean >= 0.01
      && byName.SNOWWholeBody.negativeMean >= 0.01
      && byName.SNOWCore.responseSignature !== byName.SNOWCrown.responseSignature
      && byName.SNOWCore.responseSignature !== byName.SNOWPocket.responseSignature,
    `E48 ${scale}x lost broad differentiated snow crown/pocket relief (${JSON.stringify(byName)})`);
    assert(controlResponses.length === controls.length
      && controlResponses.every((sample) => sample.rgbPeak
        <= (SNOWPACK_BODY_VFX_CONTROL_PEAK[sample.name] ?? 0)),
    `E48 ${scale}x escaped a named topology/material/contact control (${JSON.stringify(controlResponses)})`);

    const acceptedEnvelope = SNOWPACK_BODY_VFX_ACCEPTED_SCALE_ENVELOPES[scale];
    const inAcceptedRange = (value, range) => Number.isFinite(value)
      && value >= range[0] && value <= range[1];
    assert(acceptedEnvelope && targetResponses.every((sample) => {
      const range = acceptedEnvelope.targets[sample.name];
      return range
        && inAcceptedRange(sample.rgbRms, range.rgbRms)
        && inAcceptedRange(sample.chromaRms, range.chromaRms)
        && inAcceptedRange(sample.rgbPeak, range.rgbPeak)
        && inAcceptedRange(sample.coverage, range.coverage)
        && inAcceptedRange(sample.signedMean, range.signedMean)
        && inAcceptedRange(sample.spatialRgbRms, range.spatialRgbRms);
    }), `E48 ${scale}x escaped its accepted displayed-body envelope (${JSON.stringify({
      acceptedEnvelope: acceptedEnvelope?.targets, targetResponses,
    })})`);

    const textureRegions = snowpackBodyVfxTextureRegions(fixture);
    const texture = {};
    for (const [name, variant] of Object.entries(captures)) {
      texture[name] = await samplePageRegions(
        cdp, variant.capture.capture.data, textureRegions,
        undefined, undefined, variant.capture.canvasRect,
      );
    }
    const textureResponse = texture.disabled.map((baseline, index) => {
      const current = texture.enabled[index];
      const repeated = texture.disabledRepeat[index];
      assert(current?.name === baseline.name && repeated?.name === baseline.name,
        `E48 ${scale}x reordered Snow texture regions`);
      return {
        name: baseline.name,
        disabledMicro: baseline.microContrast,
        enabledMicro: current.microContrast,
        microRetention: round(current.microContrast / Math.max(0.001, baseline.microContrast), 4),
        disabledMacro: baseline.macroLumaRange,
        enabledMacro: current.macroLumaRange,
        macroRetention: round(current.macroLumaRange / Math.max(0.001, baseline.macroLumaRange), 4),
        enabledLumaStdDev: current.lumaStdDev,
        supportRecall: current.supportRecall,
        clippedFraction: current.clippedFraction,
        repeatExact: JSON.stringify(baseline) === JSON.stringify(repeated),
      };
    });
    assert(textureResponse.every((sample) => sample.disabledMicro
      >= SNOWPACK_BODY_VFX_TEXTURE_LIMITS.minimumBaselineMicro
      && sample.enabledMicro >= SNOWPACK_BODY_VFX_TEXTURE_LIMITS.minimumEnabledMicro
      && sample.microRetention >= SNOWPACK_BODY_VFX_TEXTURE_LIMITS.minimumMicroRetention
      && sample.microRetention <= SNOWPACK_BODY_VFX_TEXTURE_LIMITS.maximumMicroRetention
      && sample.enabledMacro >= SNOWPACK_BODY_VFX_TEXTURE_LIMITS.minimumEnabledMacro
      && sample.macroRetention >= SNOWPACK_BODY_VFX_TEXTURE_LIMITS.minimumMacroRetention
      && sample.enabledLumaStdDev >= 1.0 && sample.supportRecall === 1
      && sample.clippedFraction <= SNOWPACK_BODY_VFX_TEXTURE_LIMITS.maximumClippedFraction
      && sample.repeatExact),
    `E48 ${scale}x did not calm dense Snow while retaining macro relief (${JSON.stringify({
      limits: SNOWPACK_BODY_VFX_TEXTURE_LIMITS, textureResponse,
    })})`);
    assert(textureResponse.every((sample) => {
      const range = acceptedEnvelope.textures[sample.name];
      return range
        && inAcceptedRange(sample.enabledMicro, range.enabledMicro)
        && inAcceptedRange(sample.microRetention, range.microRetention)
        && inAcceptedRange(sample.enabledMacro, range.enabledMacro)
        && inAcceptedRange(sample.macroRetention, range.macroRetention)
        && inAcceptedRange(sample.enabledLumaStdDev, range.enabledLumaStdDev);
    }), `E48 ${scale}x escaped its accepted displayed-texture envelope (${JSON.stringify({
      acceptedEnvelope: acceptedEnvelope.textures, textureResponse,
    })})`);

    const references = {};
    const referenceRegions = snowpackBodyVfxReferenceRegions(fixture);
    for (const style of ['grains', 'local']) {
      const samples = await sampleBackdropRefractionRegions(cdp, {
        straight: disabled.references[style].capture.data,
        refracted: enabled.references[style].capture.data,
        repeatedStraight: disabledRepeat.references[style].capture.data,
      }, referenceRegions, disabled.references[style].canvasRect);
      assert(samples.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
        `E48 ${scale}x escaped the exact ${style} reference mode (${JSON.stringify(samples)})`);
      references[style] = samples;
    }
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeSnowpackBodyVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      walls: disabled.walls, velocity: disabled.velocity, auxiliary: disabled.auxiliary,
      suspension: disabled.suspension, rawControls: disabled.rawControls,
      targetResponses, controlResponses, textureResponse, references,
      exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E48 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls)
        && JSON.stringify(reference.velocity) === JSON.stringify(sample.velocity)
        && JSON.stringify(reference.auxiliary) === JSON.stringify(sample.auxiliary)
        && JSON.stringify(reference.suspension) === JSON.stringify(sample.suspension),
      `E48 ${sample.scale}x changed exact fixture state across output scales`);
      for (const baseline of reference.textureResponse) {
        const current = sample.textureResponse.find(({ name }) => name === baseline.name);
        assert(current && Math.abs(current.microRetention - baseline.microRetention) <= 0.30
          && Math.abs(current.macroRetention - baseline.macroRetention) <= 0.55,
        `E48 ${baseline.name} texture response drifted at ${sample.scale}x (${JSON.stringify({
          reference: baseline, current,
        })})`);
      }
    }
  }
  const trueEightX = await auditEightXSnowpackBodyVfxExclusion(cdp, dpr);
  return {
    calibration: 'e48-relational-1x-4x',
    textureLimits: SNOWPACK_BODY_VFX_TEXTURE_LIMITS,
    responseLimits: SNOWPACK_BODY_VFX_RESPONSE_LIMITS,
    acceptedScaleEnvelopes: SNOWPACK_BODY_VFX_ACCEPTED_SCALE_ENVELOPES,
    controlPeakCaps: SNOWPACK_BODY_VFX_CONTROL_PEAK,
    scales, trueEightXExcluded: true, trueEightX,
  };
}

async function navigateSnowpackBodyVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    snowpackBodyVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '1', sootyPowderBodyVfx: '0',
    thermiteBodyVfx: '0', snowpackBodyVfx: enabled ? '1' : '0',
    quartzMesostructureVfx: '0', c4BodyVfx: '0', bglaBodyVfx: '0',
    powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', metalWaterContactVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    radioactiveSolidBodyVfx: '0', iszsCrystallineVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', botanicalMesostructureVfx: '0',
    botanicalPigmentVfx: '0', plantLaminaVfx: '0', plantLobeDepthVfx: '0',
    plantCanopyMassVfx: '0', woodBarkReliefVfx: '0', woodTanninVfx: '0',
    glassBodyVfx: '0', acidBodyVfx: '0', deutBodyVfx: '0', oilBodyVfx: '0',
    oilVolumeFinishVfx: '0', rockRoughnessVfx: '0', rockMesostructureVfx: '0',
    waterBodyVfx: '0', hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = ${JSON.stringify(SNOWPACK_BODY_VFX_ISOLATED_SELECTORS)};
    return p.get('snowpackBodyVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('powderBodyVfx') === '1'
      && p.get('snowpackBodyVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareSnowpackBodyVfxFixture === 'function'
      && typeof audit?.snowpackBodyVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E48 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E48 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareSnowpackBodyVfxFixture(); audit.setPowderRenderStyle('smooth');
    return audit.snowpackBodyVfxFixture();
  })()`);
  // Seven independently observed refreshes settle the broad body at byte 255
  // while the authored-velocity control remains below the stability threshold.
  for (let pass = 0; pass < 7; pass++) {
    const before = await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp, `(() => {
      const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
      return current?.dynamicSequence > ${before.dynamicSequence} ? current : false;
    })()`), scale === 4 ? 15_000 : 5_000,
    `E48 ${label} ${scale}x stability pass ${pass + 1}`);
  }
  await waitFor(() => snowpackBodyVfxFixtureReady(cdp, fixture), 20_000,
    `E48 ${label} ${scale}x fixture/stability hydration`);
  await sleep(350);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const isolated = ${JSON.stringify(SNOWPACK_BODY_VFX_ISOLATED_SELECTORS)};
    return {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      sootyPowderBodyVfx: canvas.dataset.sootyPowderBodyVfx,
      thermiteBodyVfx: canvas.dataset.thermiteBodyVfx,
      snowpackBodyVfx: canvas.dataset.snowpackBodyVfx,
      isolatedSelectors: Object.fromEntries(isolated.map((name) => [name, canvas.dataset[name]])),
    };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.powderBodyVfx === 'active'
    && hdrPipeline.sootyPowderBodyVfx === 'inactive'
    && hdrPipeline.thermiteBodyVfx === 'inactive'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
    && hdrPipeline.snowpackBodyVfx === (enabled ? 'active' : 'inactive'),
  `E48 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  return {
    fixture,
    capture: await waitForStablePageCapture(
      cdp, `E48 ${label} ${scale}x framebuffer`,
      scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000,
    ),
    geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    materialPlane: await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()'),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    walls: await snowpackBodyVfxWallDigest(cdp, fixture),
    velocity: await snowpackBodyVfxVelocityDigest(cdp, fixture),
    auxiliary: await snowpackBodyVfxAuxiliaryDigest(cdp, fixture),
    suspension: await snowpackBodyVfxSuspensionDigest(cdp, fixture),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, snowpackBodyVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, snowpackBodyVfxRawControlPoints(fixture),
    ),
    hdrPipeline,
  };
}

const SNOWPACK_BODY_VFX_ISOLATED_SELECTORS = Object.freeze([
  'volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasBodyVfx', 'gasMotionVfx',
  'sootyPowderBodyVfx', 'thermiteBodyVfx', 'quartzMesostructureVfx', 'c4BodyVfx',
  'bglaBodyVfx',
  'powderLightVfx', 'powderSolidContactVfx',
  'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx',
  'liquidSolidMeniscusVfx', 'metalWaterContactVfx', 'gasCoreDepthVfx',
  'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
  'smokeBillowDepthVfx', 'plasmaCoreVfx', 'solidBodyVfx',
  'radioactiveSolidBodyVfx', 'iszsCrystallineVfx', 'platinumBodyVfx',
  'ceramicGlazeVfx', 'botanicalBodyVfx', 'botanicalMesostructureVfx',
  'botanicalPigmentVfx', 'plantLaminaVfx', 'plantLobeDepthVfx',
  'plantCanopyMassVfx', 'woodBarkReliefVfx', 'woodTanninVfx', 'glassBodyVfx',
  'acidBodyVfx', 'deutBodyVfx', 'oilBodyVfx', 'oilVolumeFinishVfx',
  'rockRoughnessVfx', 'rockMesostructureVfx', 'waterBodyVfx',
  'hydrogenBodyVfx', 'carbonDioxideBodyVfx',
]);

async function snowpackBodyVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = ${JSON.stringify(fixture)};
    if (fixture?.version !== 1 || fixture.world?.width !== audit.width
      || fixture.world?.height !== audit.height || fixture.target?.material !== 18) return false;
    const inside = (rect, x, y) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    const exactAuxiliary = (rect, predicate) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (!predicate(audit.presentationAuxiliary(x, y))) return false;
        }
      }
      return true;
    };
    const target = fixture.target;
    for (let y = target.body.y; y < target.body.y + target.body.height; y++) {
      for (let x = target.body.x; x < target.body.x + target.body.width; x++) {
        const empty = inside(target.authoredHole, x, y) || inside(target.openChannel, x, y);
        if (audit.cell(x, y) !== (empty ? 0 : target.material)) return false;
      }
    }
    if (![target.core, target.crown, target.pocket].every((rect) => (
      exactRect(rect, target.material) && exactAuxiliary(rect, (value) => value === 255)
    ))) return false;
    const wall = target.wallCoexistence;
    for (let y = wall.region.y; y < wall.region.y + wall.region.height; y++) {
      for (let x = wall.region.x; x < wall.region.x + wall.region.width; x++) {
        const blockX = Math.floor((x - wall.region.x) / wall.blockSize);
        const blockY = Math.floor((y - wall.region.y) / wall.blockSize);
        const expected = (blockX + blockY) % 2 === wall.occupiedParity
          ? fixture.conductiveWall : 0;
        if (audit.cell(x, y) !== target.material || audit.wall(x, y) !== expected) return false;
      }
    }
    if (!exactRect(fixture.fineTopology.column, target.material)
      || !exactRect(fixture.fineTopology.line, target.material)
      || audit.cell(fixture.fineTopology.isolated.x, fixture.fineTopology.isolated.y)
        !== target.material) return false;
    const moving = fixture.movingControl;
    if (!exactRect(moving, target.material)
      || !exactAuxiliary(moving, (value) => value < 255)) return false;
    for (let y = moving.y; y < moving.y + moving.height; y++) {
      for (let x = moving.x; x < moving.x + moving.width; x++) {
        const velocity = audit.velocity(x, y);
        if (velocity[0] !== moving.velocityX || velocity[1] !== moving.velocityY) return false;
      }
    }
    const suspension = fixture.suspensionControl;
    const snow = new Set(suspension.snowPoints.map((point) => point.x + ',' + point.y));
    for (let y = suspension.region.y; y < suspension.region.y + suspension.region.height; y++) {
      for (let x = suspension.region.x; x < suspension.region.x + suspension.region.width; x++) {
        if (audit.cell(x, y) !== (snow.has(x + ',' + y) ? target.material : 2)) return false;
      }
    }
    const boundary = (entry) => exactRect(entry.snow, target.material)
      && exactRect(entry.other, entry.otherMaterial);
    const digest = audit.materialPlaneDigest();
    return Object.values(fixture.materialControls).every((entry) => exactRect(entry, entry.material))
      && Object.values(fixture.contacts).every(boundary)
      && audit.cell(suspension.snowProbe.x, suspension.snowProbe.y) === target.material
      && audit.cell(suspension.waterProbe.x, suspension.waterProbe.y) === 2
      && exactRect(fixture.guardedBlank, 0)
      && digest.occupied === fixture.expected.occupiedCells
      && digest.materialCounts[target.material] === fixture.expected.snowCells
      && digest.materialCounts[2] === fixture.expected.waterCells
      && digest.materialCounts[23] === fixture.expected.metalCells
      && JSON.stringify(fixture.powderStyleMatrix) === JSON.stringify([
        { style: 'smooth', expectation: 'target' },
        { style: 'local', expectation: 'exact-no-op' },
        { style: 'grains', expectation: 'exact-no-op' },
      ]);
  })()`);
}

async function snowpackBodyVfxWallDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const pattern = fixture.target.wallCoexistence;
    let occupied = 0; let expectedOccupied = 0; let mismatches = 0; let matterMismatches = 0;
    for (let y = pattern.region.y; y < pattern.region.y + pattern.region.height; y++) {
      for (let x = pattern.region.x; x < pattern.region.x + pattern.region.width; x++) {
        const blockX = Math.floor((x - pattern.region.x) / pattern.blockSize);
        const blockY = Math.floor((y - pattern.region.y) / pattern.blockSize);
        const expected = (blockX + blockY) % 2 === pattern.occupiedParity
          ? fixture.conductiveWall : 0;
        occupied += Number(audit.wall(x, y) === fixture.conductiveWall);
        expectedOccupied += Number(expected === fixture.conductiveWall);
        mismatches += Number(audit.wall(x, y) !== expected);
        matterMismatches += Number(audit.cell(x, y) !== fixture.target.material);
      }
    }
    return { occupied, expectedOccupied, mismatches, matterMismatches,
      wallProbe: audit.wall(pattern.wallProbe.x, pattern.wallProbe.y),
      clearProbe: audit.wall(pattern.clearProbe.x, pattern.clearProbe.y) };
  })()`);
}

async function snowpackBodyVfxVelocityDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const rect = ${JSON.stringify(fixture.movingControl)};
    let cells = 0; let mismatches = 0; let minimumX = 127; let maximumX = -128;
    let minimumY = 127; let maximumY = -128;
    for (let y = rect.y; y < rect.y + rect.height; y++) {
      for (let x = rect.x; x < rect.x + rect.width; x++) {
        const velocity = audit.velocity(x, y); cells++;
        minimumX = Math.min(minimumX, velocity[0]); maximumX = Math.max(maximumX, velocity[0]);
        minimumY = Math.min(minimumY, velocity[1]); maximumY = Math.max(maximumY, velocity[1]);
        mismatches += Number(velocity[0] !== rect.velocityX || velocity[1] !== rect.velocityY);
      }
    }
    return { cells, expectedCells: rect.width * rect.height, mismatches,
      range: [minimumX, maximumX, minimumY, maximumY] };
  })()`);
}

async function snowpackBodyVfxAuxiliaryDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const range = (rect) => {
      let min = 255; let max = 0;
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          const value = audit.presentationAuxiliary(x, y);
          min = Math.min(min, value); max = Math.max(max, value);
        }
      }
      return { min, max };
    };
    return { stable: { core: range(fixture.target.core), crown: range(fixture.target.crown),
      pocket: range(fixture.target.pocket) }, moving: range(fixture.movingControl) };
  })()`);
}

async function snowpackBodyVfxSuspensionDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    return [
      { name: 'SuspendedSnow', material: fixture.target.material,
        point: fixture.suspensionControl.snowProbe },
      { name: 'SuspensionWater', material: 2, point: fixture.suspensionControl.waterProbe },
    ].map((entry) => ({ name: entry.name, material: entry.material,
      cell: audit.cell(entry.point.x, entry.point.y),
      rgba: audit.suspensionAt(entry.point.x, entry.point.y),
      liquidAlpha: audit.liquidFieldAlpha(entry.point.x, entry.point.y) }));
  })()`);
}

function snowpackBodyVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  return [
    rect('SNOWWholeBody', fixture.target.body),
    rect('SNOWCrown', fixture.target.crown),
    rect('SNOWPocket', fixture.target.pocket),
    rect('SNOWCore', fixture.target.core),
  ];
}

function snowpackBodyVfxTextureRegions(fixture) {
  return snowpackBodyVfxTargetRegions(fixture)
    .filter(({ name }) => name !== 'SNOWWholeBody')
    .map((region) => ({ ...region,
      support: { kind: 'semantic', materials: [fixture.target.material] } }));
}

function snowpackBodyVfxReferenceRegions(fixture) {
  return snowpackBodyVfxTargetRegions(fixture).map(({ target: _target, ...region }) => region);
}

function snowpackBodyVfxControlRegions(fixture) {
  const point = (name, candidate) => ({
    name, x: Math.floor(candidate.x) + 0.5, y: Math.floor(candidate.y) + 0.5, radius: 0,
  });
  const center = (name, rect) => point(name, {
    x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2),
  });
  const controls = [
    center('SNOWHole', fixture.target.authoredHole),
    center('SNOWOpenChannel', fixture.target.openChannel),
    center('FineColumn', fixture.fineTopology.column),
    center('FineLine', fixture.fineTopology.line),
    point('Isolated', fixture.fineTopology.isolated),
    center('Moving', fixture.movingControl),
    point('NativeWallOccupied', fixture.target.wallCoexistence.wallProbe),
    point('NativeWallClear', fixture.target.wallCoexistence.clearProbe),
  ];
  for (const [name, rect] of Object.entries(fixture.materialControls)) {
    controls.push(center(`Material${name[0].toUpperCase()}${name.slice(1)}`, rect));
  }
  controls.push(
    point('SuspendedSnow', fixture.suspensionControl.snowProbe),
    point('SuspensionWater', fixture.suspensionControl.waterProbe),
    point('SnowMetal', fixture.contacts.metal.snowProbe),
    point('Metal', fixture.contacts.metal.otherProbe),
    point('SnowWater', fixture.contacts.water.snowProbe),
    point('Water', fixture.contacts.water.otherProbe),
    center('GuardedBlank', fixture.guardedBlank),
  );
  return controls;
}

function snowpackBodyVfxAllRawPoints(fixture) {
  return [
    ...snowpackBodyVfxTargetRegions(fixture).map(({ name, x, y }) => ({
      name, x: Math.floor(x), y: Math.floor(y),
    })),
    ...snowpackBodyVfxRawControlPoints(fixture),
  ];
}

function snowpackBodyVfxRawControlPoints(fixture) {
  return snowpackBodyVfxControlRegions(fixture).map(({ name, x, y }) => ({
    name, x: Math.floor(x), y: Math.floor(y),
  }));
}

async function writeSnowpackBodyVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e48-snowpack-body-${scale}x-off`),
    on: variantScreenshotPath(source, `e48-snowpack-body-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXSnowpackBodyVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-snowpack-body', snowpackBodyVfxAudit: '1', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '1', sootyPowderBodyVfx: '0',
    thermiteBodyVfx: '0', snowpackBodyVfx: '1', quartzMesostructureVfx: '0',
    c4BodyVfx: '0', bglaBodyVfx: '0',
    powderLightVfx: '0',
    powderSolidContactVfx: '0', translucentEdgeVfx: '0', organicSubsurfaceVfx: '0',
    wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0',
    metalWaterContactVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0',
    nobleGasPrismVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0', radioactiveSolidBodyVfx: '0',
    iszsCrystallineVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0',
    botanicalBodyVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0',
    rockRoughnessVfx: '0', rockMesostructureVfx: '0', waterBodyVfx: '0',
    acidBodyVfx: '0', hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8' && p.get('auditStage') === 'eight-snowpack-body'
      && p.get('powderBodyVfx') === '1' && p.get('snowpackBodyVfx') === '1'
      && p.get('sootyPowderBodyVfx') === '0' && p.get('thermiteBodyVfx') === '0'
      && p.get('quartzMesostructureVfx') === '0'
      && p.get('c4BodyVfx') === '0'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E48 input audit API'),
  'true-8x E48 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E48', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E48');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E48 geometry')),
    'true-8x E48 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E48 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      sootyPowderBodyVfx: canvas.dataset.sootyPowderBodyVfx,
      thermiteBodyVfx: canvas.dataset.thermiteBodyVfx,
      snowpackBodyVfx: canvas.dataset.snowpackBodyVfx,
      quartzMesostructureVfx: canvas.dataset.quartzMesostructureVfx,
      c4BodyVfx: canvas.dataset.c4BodyVfx,
      bglaBodyVfx: canvas.dataset.bglaBodyVfx,
    } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E48 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.powderBodyVfx === 'inactive'
    && isolation.sootyPowderBodyVfx === 'inactive'
    && isolation.thermiteBodyVfx === 'inactive'
    && isolation.snowpackBodyVfx === 'inactive'
    && isolation.quartzMesostructureVfx === 'inactive'
    && isolation.c4BodyVfx === 'inactive'
    && isolation.bglaBodyVfx === 'inactive',
  `true-8x E48 isolation failed (${JSON.stringify(isolation)})`);
  // E48 owns no compact-shader path. Avoid uploading the dense fixture here:
  // this tail proves selector/resource exclusion on one already-fenced 8x frame.
  const stateBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E48 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E48 did not complete GPU work (${JSON.stringify(timing)})`);
  const stateAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(stateBefore, stateAfter, 'true-8x E48 GPU completion');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8'
      && geometry.backend.backend === 'webgl',
    selectorExcluded: true, resourcesIdentical: isolation.bloomBacking === null,
    semanticStable: true, isolation, timing,
  };
}

// E50's accepted 1x/2x/4x SwiftShader matrix freezes a pressed C4/PLEX body:
// retain roughly 42--44% of the original cell-frequency variation while the
// broad moulded relief remains legible and unclipped. These ranges keep useful
// compositor headroom without allowing the exact-C4 branch to become inert,
// revert to salt-and-pepper grain, or wash into a flat plastic slab.
const C4_BODY_VFX_TEXTURE_LIMITS = Object.freeze({
  minimumBaselineMicro: 12.0,
  minimumEnabledMicro: 5.0,
  maximumEnabledMicro: 9.0,
  minimumMicroRetention: 0.40,
  maximumMicroRetention: 0.46,
  minimumEnabledMacro: 8.0,
  maximumEnabledMacro: 30.0,
  minimumMacroRetention: 0.40,
  maximumMacroRetention: 1.20,
  minimumEnabledLumaStdDev: 5.8,
  maximumEnabledLumaStdDev: 10.2,
  maximumClippedFraction: 0,
});
const C4_BODY_VFX_RESPONSE_LIMITS = Object.freeze({
  minimumRgbRms: 7.5,
  maximumRgbRms: 13.0,
  maximumRgbPeak: 65,
  minimumCoverage: 0.70,
});
const C4_BODY_VFX_TARGET_ENVELOPES = Object.freeze({
  C4WholeBody: Object.freeze({
    rgbRms: [7.6, 12.2], chromaRms: [3.8, 6.6], rgbPeak: [38, 63],
    coverage: [0.70, 0.80], signedMean: [1.1, 2.7], spatialRgbRms: [7.2, 11.8],
  }),
  C4Crown: Object.freeze({
    rgbRms: [8.1, 12.9], chromaRms: [4.0, 7.1], rgbPeak: [24, 50],
    coverage: [0.83, 0.93], signedMean: [1.2, 5.0], spatialRgbRms: [7.5, 12.1],
  }),
  C4Pocket: Object.freeze({
    rgbRms: [8.0, 12.3], chromaRms: [4.3, 7.2], rgbPeak: [27, 46],
    coverage: [0.84, 0.92], signedMean: [-0.7, 2.8], spatialRgbRms: [7.6, 12.0],
  }),
  C4Core: Object.freeze({
    rgbRms: [8.0, 12.9], chromaRms: [4.0, 7.3], rgbPeak: [34, 56],
    coverage: [0.84, 0.93], signedMean: [-0.8, 1.9], spatialRgbRms: [7.6, 12.7],
  }),
});

// Raw RGBA remains exact for every control. Only the clear half of the native
// wall checker may gain one page-compositor byte beside an eligible C4 body.
const C4_BODY_VFX_CONTROL_PEAK = Object.freeze({ NativeWallClear: 1 });

const C4_BODY_VFX_CROSS_SCALE_LIMITS = Object.freeze({
  maximumMicroRetentionDrift: 0.03,
  maximumMacroRetentionDrift: 0.32,
});

const C4_BODY_VFX_ISOLATED_SELECTORS = Object.freeze([
  ...SNOWPACK_BODY_VFX_ISOLATED_SELECTORS.filter((name) => name !== 'c4BodyVfx'),
  'snowpackBodyVfx',
]);

const BGLA_BODY_VFX_ISOLATED_SELECTORS = Object.freeze([
  ...C4_BODY_VFX_ISOLATED_SELECTORS.filter((name) => name !== 'bglaBodyVfx'),
  'c4BodyVfx', 'soapBodyVfx', 'bglaClusterVfx',
]);

const BGLA_CLUSTER_VFX_ISOLATED_SELECTORS = Object.freeze(
  BGLA_BODY_VFX_ISOLATED_SELECTORS.filter((name) => (
    name !== 'bglaBodyVfx' && name !== 'bglaClusterVfx'
  )),
);

// The clear half of the native wall checker is still authoritative BGLA, so
// the page compositor may carry a tiny eligible-body response there. Every
// other named topology/material/contact control remains exact.
const BGLA_BODY_VFX_CONTROL_PEAK = Object.freeze({ WallClear: 2 });

// Accepted normal-WebGL E52 envelope. BGLA keeps its cell-scale splinters;
// this child adds broad cool shard-pack relief instead of erasing grain.
const BGLA_BODY_VFX_TARGET_ENVELOPES = Object.freeze({
  BGLACore: Object.freeze({
    rgbRms: [4.2, 5.2], chromaRms: [2.3, 3.0], rgbPeak: [20, 30],
    coverage: [0.34, 0.44], signedMean: [1.3, 1.9], spatialRgbRms: [2.9, 3.7],
  }),
  BGLACrown: Object.freeze({
    rgbRms: [7.7, 9.2], chromaRms: [3.1, 4.1], rgbPeak: [19, 31],
    coverage: [0.79, 0.90], signedMean: [5.2, 6.4], spatialRgbRms: [3.6, 4.7],
  }),
  BGLAPocket: Object.freeze({
    rgbRms: [2.0, 2.8], chromaRms: [2.0, 2.7], rgbPeak: [6, 13],
    coverage: [0.04, 0.12], signedMean: [-0.70, -0.15], spatialRgbRms: [0.75, 1.25],
  }),
});

const BGLA_BODY_VFX_TEXTURE_LIMITS = Object.freeze({
  minimumBaselineMicro: 8.0,
  minimumEnabledMicro: 8.0,
  maximumEnabledMicro: 14.0,
  minimumMicroRetention: 0.90,
  maximumMicroRetention: 1.15,
  minimumEnabledMacro: 9.0,
  maximumEnabledMacro: 36.0,
  minimumMacroRetention: 0.90,
  maximumMacroRetention: 2.10,
  minimumEnabledLumaStdDev: 8.3,
  maximumEnabledLumaStdDev: 15.0,
});

const BGLA_BODY_VFX_CROSS_SCALE_LIMITS = Object.freeze({
  maximumRgbRmsDrift: 0.20,
  maximumChromaRmsDrift: 0.15,
  maximumCoverageDrift: 0.04,
  maximumSignedMeanDrift: 0.15,
  maximumSpatialRgbRmsDrift: 0.20,
  maximumMicroRetentionDrift: 0.04,
  maximumMacroRetentionDrift: 0.60,
});

/** E52: exact BGLA settled crystalline shard-pack, subordinate to E05 Smooth. */
async function auditBglaBodyVfxExperiment(cdp, mode, dpr) {
  if (Number(renderScaleArgument) === 8) {
    return {
      scales: [], trueEightXExcluded: true,
      trueEightX: await auditEightXBglaBodyVfxExclusion(cdp, dpr),
    };
  }
  const normalScales = renderScaleArgument === undefined ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  const scales = [];
  for (const scale of normalScales) {
    assert([1, 2, 4].includes(scale), 'E52 normal matrix requires 1x/2x/4x');
    const frames = {};
    for (const enabled of [false, true, false]) {
      const name = enabled ? 'on' : frames.off ? 'offRepeat' : 'off';
      frames[name] = await navigateBglaBodyVfxState(cdp, mode, scale, enabled, name);
      frames[name].references = await capturePowderBodyVfxReferenceStyles(
        cdp, scale, name, 'E52',
      );
    }
    const { off, on, offRepeat } = frames;
    assert(JSON.stringify(off.fixture) === JSON.stringify(on.fixture)
      && JSON.stringify(off.fixture) === JSON.stringify(offRepeat.fixture),
    'E52 fixture metadata changed');
    assert(off.capture.capture.data === offRepeat.capture.capture.data,
      'E52 repeated-off framebuffer changed');
    for (const frame of [off, on, offRepeat]) {
      assertGeometry(frame.geometry, 'E52 ' + scale + 'x', scale);
      assert(frame.geometry.backend.backend === 'webgl'
        && frame.pipeline.state === 'active'
        && frame.pipeline.powderBodyVfx === 'active'
        && frame.pipeline.bglaBodyVfx === (frame === on ? 'active' : 'inactive')
        && Object.values(frame.pipeline.isolatedSelectors)
          .every((state) => state === 'inactive'),
      'E52 selector/backend state changed: ' + JSON.stringify(frame.pipeline));
    }
    assertHdrVfxSemanticEquality(off.semantic, on.semantic, 'E52 off/on');
    assertHdrVfxSemanticEquality(off.semantic, offRepeat.semantic, 'E52 off/repeat');
    assertVolumeVfxBackingInvariant(off.backing, on.backing, 'E52 off/on');
    assertVolumeVfxBackingInvariant(off.backing, offRepeat.backing, 'E52 off/repeat');
    assertBglaBodyVfxMaterialPlane(off.materialPlane, off.fixture, `E52 ${scale}x`);
    assert(JSON.stringify(off.materialPlane) === JSON.stringify(on.materialPlane)
      && JSON.stringify(off.materialPlane) === JSON.stringify(offRepeat.materialPlane),
    `E52 ${scale}x changed exact material-plane cardinalities`);
    assert(JSON.stringify(off.digest) === JSON.stringify(on.digest)
      && JSON.stringify(off.digest) === JSON.stringify(offRepeat.digest) && off.digest.ok,
    'E52 changed a protected BGLA fixture control: ' + JSON.stringify(off.digest));
    for (const name of ['walls', 'velocity', 'auxiliary', 'wet', 'state']) {
      assert(JSON.stringify(off[name]) === JSON.stringify(on[name])
        && JSON.stringify(off[name]) === JSON.stringify(offRepeat[name]),
      `E52 ${scale}x changed ${name} fixture state`);
    }
    assert(off.walls.occupied === off.fixture.expected.wallCells
      && off.walls.mismatches === 0 && off.walls.matterMismatches === 0
      && off.velocity.cells === off.fixture.expected.movingVelocityCells
      && off.velocity.mismatches === 0
      && Object.values(off.auxiliary.stable).every(({ min, max }) => min === 255 && max === 255)
      && off.auxiliary.moving.min < 255 && off.auxiliary.moving.max < 255
      && off.wet.bgla === off.fixture.expected.suspensionBglaCells
      && off.wet.water === off.fixture.expected.suspensionWaterCells && off.wet.other === 0
      && off.wet.bgla === off.wet.water * 2 && off.wet.mismatches === 0
      && off.wet.bglaProbe === 44 && off.wet.waterProbe === 2
      && off.state.nonZero === off.state.expectedNonZero,
    `E52 ${scale}x lost wall/velocity/auxiliary/wet/state contract (${JSON.stringify({
      walls: off.walls, velocity: off.velocity, auxiliary: off.auxiliary, wet: off.wet, state: off.state,
    })})`);
    assertVolumeVfxRawAlphaInvariant(off.rawAll, on.rawAll, `E52 ${scale}x off/on`);
    assertVolumeVfxRawAlphaInvariant(off.rawAll, offRepeat.rawAll, `E52 ${scale}x off/repeat`);
    assert(JSON.stringify(off.rawControls) === JSON.stringify(on.rawControls)
      && JSON.stringify(off.rawControls) === JSON.stringify(offRepeat.rawControls),
    `E52 ${scale}x changed a raw topology/material/contact control`);
    const targets = bglaBodyVfxTargetRegions(off.fixture);
    const controls = bglaBodyVfxControlRegions(off.fixture);
    const samples = await sampleBackdropRefractionRegions(cdp, {
      straight: off.capture.capture.data, refracted: on.capture.capture.data,
      repeatedStraight: offRepeat.capture.capture.data,
    }, [...targets, ...controls], off.capture.canvasRect);
    const targetResponses = samples.slice(0, targets.length).map((sample) => ({
      ...sample,
      spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2
        - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2)), 3),
    }));
    const controlResponses = samples.slice(targets.length);
    assert(samples.every((sample) => sample.repeatRgbPeak === 0),
      'E52 off/on/off was not deterministic: ' + JSON.stringify(samples));
    assert(targetResponses.every((sample) => {
      const envelope = BGLA_BODY_VFX_TARGET_ENVELOPES[sample.name];
      return envelope
        && sample.rgbRms >= envelope.rgbRms[0] && sample.rgbRms <= envelope.rgbRms[1]
        && sample.chromaRms >= envelope.chromaRms[0]
        && sample.chromaRms <= envelope.chromaRms[1]
        && sample.rgbPeak >= envelope.rgbPeak[0] && sample.rgbPeak <= envelope.rgbPeak[1]
        && sample.coverage >= envelope.coverage[0] && sample.coverage <= envelope.coverage[1]
        && sample.signedMean >= envelope.signedMean[0]
        && sample.signedMean <= envelope.signedMean[1]
        && sample.spatialRgbRms >= envelope.spatialRgbRms[0]
        && sample.spatialRgbRms <= envelope.spatialRgbRms[1];
    }), 'E52 escaped the accepted BGLA target envelope: ' + JSON.stringify({
      envelopes: BGLA_BODY_VFX_TARGET_ENVELOPES, targetResponses,
    }));
    const target = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(target.BGLACrown.signedMean > target.BGLAPocket.signedMean + 5.5
      && target.BGLACrown.positiveMean >= 5.6
      && target.BGLAPocket.negativeMean >= 0.55
      && target.BGLACore.positiveMean >= 1.8 && target.BGLACore.negativeMean >= 0.28
      && target.BGLACore.responseSignature !== target.BGLACrown.responseSignature
      && target.BGLACore.responseSignature !== target.BGLAPocket.responseSignature,
    'E52 core/crown/pocket separation changed: ' + JSON.stringify(target));
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (BGLA_BODY_VFX_CONTROL_PEAK[sample.name] ?? 0)),
    'E52 leaked into a protected BGLA control: ' + JSON.stringify(controlResponses));
    const texture = {};
    for (const [name, frame] of Object.entries(frames)) {
      texture[name] = await samplePageRegions(cdp, frame.capture.capture.data,
        bglaBodyVfxTextureRegions(off.fixture), undefined, undefined, frame.capture.canvasRect);
    }
    const textureResponse = texture.off.map((baseline, index) => {
      const current = texture.on[index], repeated = texture.offRepeat[index];
      assert(current?.name === baseline.name && repeated?.name === baseline.name,
        `E52 ${scale}x reordered BGLA texture regions`);
      return { name: baseline.name, disabledMicro: baseline.microContrast,
        enabledMicro: current.microContrast,
        microRetention: round(current.microContrast / Math.max(0.001, baseline.microContrast), 4),
        disabledMacro: baseline.macroLumaRange, enabledMacro: current.macroLumaRange,
        macroRetention: round(current.macroLumaRange / Math.max(0.001, baseline.macroLumaRange), 4),
        enabledLumaStdDev: current.lumaStdDev,
        supportRecall: current.supportRecall, clippedFraction: current.clippedFraction,
        repeatExact: JSON.stringify(baseline) === JSON.stringify(repeated) };
    });
    assert(textureResponse.every((sample) => sample.disabledMicro
      >= BGLA_BODY_VFX_TEXTURE_LIMITS.minimumBaselineMicro
      && sample.enabledMicro >= BGLA_BODY_VFX_TEXTURE_LIMITS.minimumEnabledMicro
      && sample.enabledMicro <= BGLA_BODY_VFX_TEXTURE_LIMITS.maximumEnabledMicro
      && sample.microRetention >= BGLA_BODY_VFX_TEXTURE_LIMITS.minimumMicroRetention
      && sample.microRetention <= BGLA_BODY_VFX_TEXTURE_LIMITS.maximumMicroRetention
      && sample.enabledMacro >= BGLA_BODY_VFX_TEXTURE_LIMITS.minimumEnabledMacro
      && sample.enabledMacro <= BGLA_BODY_VFX_TEXTURE_LIMITS.maximumEnabledMacro
      && sample.macroRetention >= BGLA_BODY_VFX_TEXTURE_LIMITS.minimumMacroRetention
      && sample.macroRetention <= BGLA_BODY_VFX_TEXTURE_LIMITS.maximumMacroRetention
      && sample.enabledLumaStdDev >= BGLA_BODY_VFX_TEXTURE_LIMITS.minimumEnabledLumaStdDev
      && sample.enabledLumaStdDev <= BGLA_BODY_VFX_TEXTURE_LIMITS.maximumEnabledLumaStdDev
      && sample.supportRecall === 1 && sample.clippedFraction === 0 && sample.repeatExact),
    `E52 ${scale}x lost splinter detail or bounded shard-pack relief (${JSON.stringify({
      limits: BGLA_BODY_VFX_TEXTURE_LIMITS, textureResponse,
    })})`);
    const references = {};
    for (const style of ['grains', 'local']) {
      const referenceResponses = await sampleBackdropRefractionRegions(cdp, {
        straight: off.references[style].capture.data,
        refracted: on.references[style].capture.data,
        repeatedStraight: offRepeat.references[style].capture.data,
      }, targets, off.references[style].canvasRect);
      assert(referenceResponses.every((sample) => (
        sample.rgbPeak === 0 && sample.repeatRgbPeak === 0
      )), `E52 escaped the exact ${style} reference mode: ${JSON.stringify(referenceResponses)}`);
      references[style] = referenceResponses;
    }
    const screenshots = screenshotRequest
      ? await writeBglaBodyVfxScreenshots(screenshotRequest, scale, off, on)
      : undefined;
    scales.push({ scale, geometry: off.geometry, semantic: off.semantic, materialPlane: off.materialPlane,
      walls: off.walls, velocity: off.velocity, auxiliary: off.auxiliary, wet: off.wet, state: off.state,
      rawControls: off.rawControls, targets: targetResponses, controls: controlResponses,
      textureResponse, digest: off.digest, references, screenshots, exactRepeatedOff: true });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const current of scales.filter(({ scale }) => scale !== reference.scale)) {
      // Raw framebuffer probe bytes legitimately quantize with backing scale;
      // their exact off/on/off invariants are asserted within each scale above.
      assertCanvasRectsEqual(reference.geometry.canvas, current.geometry.canvas,
        `E52 ${reference.scale}x/${current.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(current.semantic)
        && JSON.stringify(reference.materialPlane) === JSON.stringify(current.materialPlane)
        && JSON.stringify(reference.walls) === JSON.stringify(current.walls)
        && JSON.stringify(reference.velocity) === JSON.stringify(current.velocity)
        && JSON.stringify(reference.auxiliary) === JSON.stringify(current.auxiliary)
        && JSON.stringify(reference.wet) === JSON.stringify(current.wet)
        && JSON.stringify(reference.state) === JSON.stringify(current.state),
      `E52 ${current.scale}x changed exact fixture state across scales`);
      for (const baseline of reference.targets) {
        const sample = current.targets.find(({ name }) => name === baseline.name);
        assert(sample
          && Math.abs(sample.rgbRms - baseline.rgbRms)
            <= BGLA_BODY_VFX_CROSS_SCALE_LIMITS.maximumRgbRmsDrift
          && Math.abs(sample.chromaRms - baseline.chromaRms)
            <= BGLA_BODY_VFX_CROSS_SCALE_LIMITS.maximumChromaRmsDrift
          && Math.abs(sample.coverage - baseline.coverage)
            <= BGLA_BODY_VFX_CROSS_SCALE_LIMITS.maximumCoverageDrift
          && Math.abs(sample.signedMean - baseline.signedMean)
            <= BGLA_BODY_VFX_CROSS_SCALE_LIMITS.maximumSignedMeanDrift
          && Math.abs(sample.spatialRgbRms - baseline.spatialRgbRms)
            <= BGLA_BODY_VFX_CROSS_SCALE_LIMITS.maximumSpatialRgbRmsDrift,
        `E52 ${baseline.name} response drifted at ${current.scale}x (${JSON.stringify({
          reference: baseline, current: sample,
        })})`);
      }
      for (const baseline of reference.textureResponse) {
        const sample = current.textureResponse.find(({ name }) => name === baseline.name);
        assert(sample
          && Math.abs(sample.microRetention - baseline.microRetention)
            <= BGLA_BODY_VFX_CROSS_SCALE_LIMITS.maximumMicroRetentionDrift
          && Math.abs(sample.macroRetention - baseline.macroRetention)
            <= BGLA_BODY_VFX_CROSS_SCALE_LIMITS.maximumMacroRetentionDrift,
        `E52 ${baseline.name} texture response drifted at ${current.scale}x (${JSON.stringify({
          reference: baseline, current: sample,
        })})`);
      }
    }
  }
  return { calibration: 'accepted-e52-1x-4x',
    targetEnvelopes: BGLA_BODY_VFX_TARGET_ENVELOPES,
    textureLimits: BGLA_BODY_VFX_TEXTURE_LIMITS,
    controlPeakCaps: BGLA_BODY_VFX_CONTROL_PEAK,
    crossScaleLimits: BGLA_BODY_VFX_CROSS_SCALE_LIMITS,
    scales, trueEightXExcluded: true,
    trueEightX: await auditEightXBglaBodyVfxExclusion(cdp, dpr) };
}

async function navigateBglaBodyVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    bglaBodyVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '1', sootyPowderBodyVfx: '0', thermiteBodyVfx: '0',
    snowpackBodyVfx: '0', quartzMesostructureVfx: '0', c4BodyVfx: '0',
    bglaBodyVfx: enabled ? '1' : '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0',
    gasLightVfx: '0', liquidSolidMeniscusVfx: '0', metalWaterContactVfx: '0',
    gasCoreDepthVfx: '0', nobleGasBillowVfx: '0', nobleGasPrismVfx: '0',
    smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', plasmaCoreVfx: '0',
    solidBodyVfx: '0', radioactiveSolidBodyVfx: '0', iszsCrystallineVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0',
    botanicalMesostructureVfx: '0', botanicalPigmentVfx: '0', plantLaminaVfx: '0',
    plantLobeDepthVfx: '0', plantCanopyMassVfx: '0', woodBarkReliefVfx: '0',
    woodTanninVfx: '0', glassBodyVfx: '0', acidBodyVfx: '0', deutBodyVfx: '0',
    oilBodyVfx: '0', oilVolumeFinishVfx: '0', rockRoughnessVfx: '0',
    rockMesostructureVfx: '0', waterBodyVfx: '0', hydrogenBodyVfx: '0',
    carbonDioxideBodyVfx: '0',
  });
  for (const selector of BGLA_BODY_VFX_ISOLATED_SELECTORS) query.set(selector, '0');
  await cdp.send('Page.navigate', { url: AUDIT_BASE_URL + '?' + query });
  const api = '(() => { const p = new URLSearchParams(location.search); const a = window.__ANIFOR_INPUT_AUDIT__;'
    + ' return p.get("bglaBodyVfxAudit") === "1" && p.get("renderScale") === ' + JSON.stringify(String(scale))
    + ' && p.get("bglaBodyVfx") === ' + JSON.stringify(enabled ? '1' : '0')
    + ' && ' + JSON.stringify(BGLA_BODY_VFX_ISOLATED_SELECTORS) + '.every((name) => p.get(name) === "0")'
    + ' && typeof a?.prepareBglaBodyVfxFixture === "function" && typeof a?.bglaBodyVfxFixture === "function"; })()';
  await waitFor(() => evaluate(cdp, api), scale === 4 ? 45_000 : 15_000, 'E52 ' + label + ' page');
  await waitFor(() => evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.backend().backend === ' + JSON.stringify(mode)),
    scale === 4 ? 30_000 : 15_000, 'E52 ' + label + ' backend');
  const fixture = await evaluate(cdp,
    '(() => { const a = window.__ANIFOR_INPUT_AUDIT__; a.prepareBglaBodyVfxFixture(); a.setPowderRenderStyle("smooth"); a.setUnusualPowderStyling(true); return a.bglaBodyVfxFixture(); })()');
  for (let pass = 0; pass < 7; pass++) {
    const before = await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp, `(() => {
      const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
      return current?.dynamicSequence > ${before.dynamicSequence} ? current : false;
    })()`), scale === 4 ? 15_000 : 5_000,
    `E52 ${label} ${scale}x stability pass ${pass + 1}`);
  }
  await sleep(350);
  const pipeline = await evaluate(cdp, `(() => {
    const c = document.querySelector('canvas.semantic-field-canvas');
    const isolated = ${JSON.stringify(BGLA_BODY_VFX_ISOLATED_SELECTORS)};
    return c ? { state: c.dataset.hdrPipeline, powderBodyVfx: c.dataset.powderBodyVfx,
      bglaBodyVfx: c.dataset.bglaBodyVfx,
      isolatedSelectors: Object.fromEntries(isolated.map((name) => [name, c.dataset[name]]))
    } : undefined;
  })()`);
  const controls = bglaBodyVfxControlRegions(fixture);
  const targets = bglaBodyVfxTargetRegions(fixture);
  return { fixture, pipeline, digest: await bglaBodyVfxFixtureDigest(cdp, fixture),
    capture: await waitForStablePageCapture(cdp, 'E52 ' + label + ' ' + scale + 'x framebuffer',
      scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000),
    geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    materialPlane: await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()'),
    walls: await bglaBodyVfxWallDigest(cdp, fixture), velocity: await bglaBodyVfxVelocityDigest(cdp, fixture),
    auxiliary: await bglaBodyVfxAuxiliaryDigest(cdp, fixture), wet: await bglaBodyVfxWetDigest(cdp, fixture),
    state: await bglaBodyVfxStateDigest(cdp, fixture),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, [...targets, ...controls].map(({ name, x, y }) => ({
      name, x: Math.floor(x), y: Math.floor(y),
    }))),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, controls.map(({ name, x, y }) => ({
      name, x: Math.floor(x), y: Math.floor(y),
    }))), };
}

async function bglaBodyVfxFixtureDigest(cdp, fixture) {
  return evaluate(cdp, '(() => { const a = window.__ANIFOR_INPUT_AUDIT__; const f = ' + JSON.stringify(fixture) + ';'
    + ' const exact = (r,m) => r && (() => { for(let y=r.y;y<r.y+r.height;y++) for(let x=r.x;x<r.x+r.width;x++) if(a.cell(x,y)!==m) return false; return true; })();'
    + ' const t=f.target, inside=(r,x,y)=>r&&x>=r.x&&x<r.x+r.width&&y>=r.y&&y<r.y+r.height; let body=true;'
    + ' for(let y=t.body.y;y<t.body.y+t.body.height;y++) for(let x=t.body.x;x<t.body.x+t.body.width;x++) if(a.cell(x,y)!==((inside(t.authoredHole,x,y)||inside(t.openChannel,x,y))?0:44)) body=false;'
    + ' const wet=f.suspensionControl, contacts=Object.values(f.contacts||{}); return { ok: f.version===1 && body'
    + ' && [t.core,t.crown,t.pocket,f.fineTopology.column,f.fineTopology.line,f.movingControl].every(r=>exact(r,44))'
    + ' && a.cell(f.fineTopology.isolated.x,f.fineTopology.isolated.y)===44 && exact(t.authoredHole,0) && exact(t.openChannel,0) && exact(f.guardedBlank,0)'
    + ' && Object.values(f.materialControls||{}).every(r=>exact(r,r.material)) && contacts.every(c=>exact(c.bgla,44)&&exact(c.other,c.otherMaterial))'
    + ' && a.cell(wet.bglaProbe.x,wet.bglaProbe.y)===44 && a.cell(wet.waterProbe.x,wet.waterProbe.y)===2'
    + ' && (()=>{for(let y=f.movingControl.y;y<f.movingControl.y+f.movingControl.height;y++) for(let x=f.movingControl.x;x<f.movingControl.x+f.movingControl.width;x++){const v=a.velocity(x,y);if(v[0]!==f.movingControl.velocityX||v[1]!==f.movingControl.velocityY)return false;}return true;})()'
    + ' && (()=>{const w=t.wallCoexistence;for(let y=w.region.y;y<w.region.y+w.region.height;y++)for(let x=w.region.x;x<w.region.x+w.region.width;x++){const bx=Math.floor((x-w.region.x)/w.blockSize),by=Math.floor((y-w.region.y)/w.blockSize),expected=(bx+by)%2===w.occupiedParity?f.conductiveWall:0;if(a.wall(x,y)!==expected||a.cell(x,y)!==44)return false;}return true;})() }; })()');
}

function assertBglaBodyVfxMaterialPlane(plane, fixture, label) {
  const expected = fixture.expected, controls = Object.values(fixture.materialControls ?? {});
  assert(plane.occupied === expected.occupiedCells
    && plane.materialCounts[44] === expected.bglaCells && plane.materialCounts[2] === expected.waterCells
    && plane.materialCounts[78] === expected.rockCells && plane.materialCounts[23] === expected.metalCells
    && controls.length === 10 && controls.every((entry) => (
      plane.materialCounts[entry.material] === expected.cellsPerMaterialControl
    )), `${label} changed BGLA/material-control cardinalities (${JSON.stringify({
      occupied: plane.occupied, counts: plane.materialCounts, expected,
    })})`);
}

async function bglaBodyVfxWallDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const wall = ${JSON.stringify(fixture.target.wallCoexistence)};
    let occupied = 0, expectedOccupied = 0, mismatches = 0, matterMismatches = 0;
    for (let y = wall.region.y; y < wall.region.y + wall.region.height; y++) for (let x = wall.region.x; x < wall.region.x + wall.region.width; x++) {
      const bx = Math.floor((x - wall.region.x) / wall.blockSize), by = Math.floor((y - wall.region.y) / wall.blockSize);
      const expected = (bx + by) % 2 === wall.occupiedParity ? ${fixture.conductiveWall} : 0;
      occupied += Number(audit.wall(x, y) === ${fixture.conductiveWall}); expectedOccupied += Number(expected === ${fixture.conductiveWall});
      mismatches += Number(audit.wall(x, y) !== expected); matterMismatches += Number(audit.cell(x, y) !== 44);
    }
    return { occupied, expectedOccupied, mismatches, matterMismatches };
  })()`);
}

async function bglaBodyVfxVelocityDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const rect = ${JSON.stringify(fixture.movingControl)};
    let cells = 0, mismatches = 0;
    for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
      const velocity = audit.velocity(x, y); cells++;
      mismatches += Number(velocity[0] !== rect.velocityX || velocity[1] !== rect.velocityY);
    }
    return { cells, expectedCells: rect.width * rect.height, mismatches };
  })()`);
}

async function bglaBodyVfxAuxiliaryDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const range = (rect) => { let min = 255, max = 0;
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        const value = audit.presentationAuxiliary(x, y); min = Math.min(min, value); max = Math.max(max, value);
      } return { min, max }; };
    return { stable: { core: range(fixture.target.core), crown: range(fixture.target.crown), pocket: range(fixture.target.pocket) },
      moving: range(fixture.movingControl) };
  })()`);
}

async function bglaBodyVfxWetDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const wet = ${JSON.stringify(fixture.suspensionControl)};
    let bgla = 0, water = 0, other = 0;
    const points = new Set(wet.bglaPoints.map(({ x, y }) => x + ',' + y));
    let mismatches = 0;
    for (let y = wet.region.y; y < wet.region.y + wet.region.height; y++) for (let x = wet.region.x; x < wet.region.x + wet.region.width; x++) {
      const material = audit.cell(x, y); if (material === 44) bgla++; else if (material === 2) water++; else other++;
      mismatches += Number(material !== (points.has(x + ',' + y) ? 44 : 2));
    }
    return { bgla, water, other, mismatches,
      bglaProbe: audit.cell(wet.bglaProbe.x, wet.bglaProbe.y), waterProbe: audit.cell(wet.waterProbe.x, wet.waterProbe.y) };
  })()`);
}

async function bglaBodyVfxStateDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; let nonZero = 0;
    for (let y = 0; y < audit.height; y++) for (let x = 0; x < audit.width; x++) nonZero += Number(audit.presentationState(x, y) !== 0);
    return { nonZero, expectedNonZero: ${JSON.stringify(fixture.expected.presentationStateCells ?? 0)} };
  })()`);
}

function bglaBodyVfxTargetRegions(fixture) {
  const rect = (name, r) => ({ name, target: true, x: r.x + r.width / 2, y: r.y + r.height / 2,
    radiusX: Math.max(.35, r.width / 2 - .2), radiusY: Math.max(.35, r.height / 2 - .2) });
  return [rect('BGLACore', fixture.target.core), rect('BGLACrown', fixture.target.crown), rect('BGLAPocket', fixture.target.pocket)];
}

function bglaBodyVfxTextureRegions(fixture) {
  return bglaBodyVfxTargetRegions(fixture).map((region) => ({ ...region,
    support: { kind: 'semantic', materials: [fixture.target.material] },
  }));
}

function bglaBodyVfxControlRegions(fixture) {
  const point = (name, p) => p && ({ name, x: Math.floor(p.x) + .5, y: Math.floor(p.y) + .5, radius: 0 });
  const center = (name, r) => point(name, { x: r.x + Math.floor(r.width / 2), y: r.y + Math.floor(r.height / 2) });
  const values = [center('BGLAHole', fixture.target.authoredHole), center('BGLAChannel', fixture.target.openChannel),
    center('ThinColumn', fixture.fineTopology.column), center('ThinLine', fixture.fineTopology.line), point('Isolated', fixture.fineTopology.isolated),
    center('Moving', fixture.movingControl), point('Wall', fixture.target.wallCoexistence.wallProbe), point('WallClear', fixture.target.wallCoexistence.clearProbe),
    point('WetBGLA', fixture.suspensionControl.bglaProbe), point('WetWater', fixture.suspensionControl.waterProbe), center('Blank', fixture.guardedBlank)];
  for (const [name, r] of Object.entries(fixture.materialControls || {})) values.push(center('Material' + name, r));
  for (const [name, c] of Object.entries(fixture.contacts || {})) { values.push(point('BGLA' + name, c.bglaProbe)); values.push(point(name, c.otherProbe)); }
  return values.filter(Boolean);
}

async function writeBglaBodyVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e52-bgla-body-${scale}x-off`),
    on: variantScreenshotPath(source, `e52-bgla-body-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXBglaBodyVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({ scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'eight-bgla-body',
    bglaBodyVfxAudit: '1', renderScale: '8', renderLook: 'realistic', powderBodyVfx: '1', bglaBodyVfx: '1', c4BodyVfx: '0',
    snowpackBodyVfx: '0', quartzMesostructureVfx: '0', volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0', gasMotionVfx: '0' });
  for (const selector of BGLA_BODY_VFX_ISOLATED_SELECTORS) query.set(selector, '0');
  await cdp.send('Page.navigate', { url: AUDIT_BASE_URL + '?' + query });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, 'new URLSearchParams(location.search).get("renderScale") === "8" && Boolean(window.__ANIFOR_INPUT_AUDIT__)'),
    remainingDeadlineMs(deadline, 'true-8x E52 API'), 'true-8x E52 API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E52', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E52');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined, Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E52 geometry')), 'true-8x E52 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
    'true-8x E52 lost exact backing');
  const state = await evaluate(cdp, `(() => {
    const c = document.querySelector('canvas.semantic-field-canvas');
    const isolated = ${JSON.stringify(BGLA_BODY_VFX_ISOLATED_SELECTORS)};
    return c ? { renderer: c.dataset.renderer, look: c.dataset.renderLook,
      selector: c.dataset.bglaBodyVfx, powderBodyVfx: c.dataset.powderBodyVfx,
      hdr: c.dataset.hdrPipeline, reason: c.dataset.hdrPipelineReason,
      bloom: c.dataset.bloomBacking ?? null,
      isolatedSelectors: Object.fromEntries(isolated.map((name) => [name, c.dataset[name]]))
    } : undefined;
  })()`);
  assert(state?.renderer === 'semantic-field-webgl' && state.look === 'realistic'
    && state.selector === 'inactive' && state.powderBodyVfx === 'inactive'
    && state.hdr === 'inactive' && state.reason === 'scale-8' && state.bloom === null
    && Object.values(state.isolatedSelectors).every((selector) => selector === 'inactive'),
    'true-8x E52 selector/resource exclusion failed: ' + JSON.stringify(state));
  // Deliberately do not stage E52's 101,593-cell fixture at true 8x. Observe
  // the blank material plane, then require a completed compact GPU frame.
  const materialPlane = await evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()');
  assert(materialPlane.occupied === 0 && (materialPlane.materialCounts[44] ?? 0) === 0,
    'true-8x E52 unexpectedly uploaded its dense fixture: ' + JSON.stringify(materialPlane));
  const semanticBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E52 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    'true-8x E52 did not complete GPU work: ' + JSON.stringify(timing));
  const semanticAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(semanticBefore, semanticAfter, 'true-8x E52 GPU completion');
  return { geometry, backend, state, materialPlane, fixtureUploaded: false,
    semanticStable: true, timing };
}

// E64 is deliberately calibrated against E52-on rather than the pre-E52
// shader. It must quiet the fit-view cell cadence without flattening E05's
// broad facets or changing any semantic/support byte.
const BGLA_CLUSTER_VFX_TEXTURE_LIMITS = Object.freeze({
  minimumBaselineMicro: 8.0,
  minimumEnabledMicro: 4.5,
  maximumEnabledMicro: 7.8,
  minimumMicroRetention: 0.54,
  maximumMicroRetention: 0.63,
  minimumBaselineChroma: 3.7,
  minimumEnabledChroma: 2.0,
  maximumEnabledChroma: 3.4,
  minimumChromaRetention: 0.51,
  maximumChromaRetention: 0.61,
  minimumEnabledMacro: 7.0,
  maximumEnabledMacro: 30.0,
  minimumMacroRetention: 0.58,
  maximumMacroRetention: 1.02,
  minimumEnabledLumaStdDev: 4.9,
  maximumEnabledLumaStdDev: 9.2,
  minimumEnabledLumaRange: 25.0,
  maximumEnabledLumaRange: 56.0,
  minimumCoverage: 0.86,
});

const BGLA_CLUSTER_VFX_RESPONSE_LIMITS = Object.freeze({
  minimumRgbRms: 3.5,
  maximumRgbRms: 5.8,
  maximumRgbPeak: 22,
  minimumCoverage: 0.65,
  maximumCoverage: 0.82,
});

// Every named topology/material/contact control, including both halves of the
// native wall checker, is byte-exact under the accepted late-body gate.
const BGLA_CLUSTER_VFX_CONTROL_PEAK = Object.freeze({});

const BGLA_CLUSTER_VFX_CROSS_SCALE_LIMITS = Object.freeze({
  maximumRgbRmsDrift: 1.8,
  maximumCoverageDrift: 0.14,
  maximumMicroRetentionDrift: 0.04,
  maximumChromaRetentionDrift: 0.05,
  maximumMacroRetentionDrift: 0.18,
});

/** E64: exact-BGLA fit-view cluster consolidation, subordinate to E52/E05. */
async function auditBglaClusterVfxExperiment(cdp, mode, dpr) {
  if (Number(renderScaleArgument) === 8) {
    return {
      scales: [], trueEightXExcluded: true,
      trueEightX: await auditEightXBglaClusterVfxExclusion(cdp, dpr),
    };
  }
  const normalScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  const scales = [];
  for (const scale of normalScales) {
    assert([1, 2, 4].includes(scale), 'E64 normal matrix requires 1x/2x/4x');
    const frames = {};
    for (const enabled of [false, true, false]) {
      const name = enabled ? 'on' : frames.off ? 'offRepeat' : 'off';
      frames[name] = await navigateBglaClusterVfxState(
        cdp, mode, scale, enabled, name,
      );
      frames[name].references = await capturePowderBodyVfxReferenceStyles(
        cdp, scale, name, 'E64',
      );
    }
    const { off, on, offRepeat } = frames;
    assert(JSON.stringify(off.fixture) === JSON.stringify(on.fixture)
      && JSON.stringify(off.fixture) === JSON.stringify(offRepeat.fixture),
    'E64 fixture metadata changed');
    assert(off.capture.capture.data === offRepeat.capture.capture.data,
      'E64 repeated-off framebuffer changed');
    for (const frame of [off, on, offRepeat]) {
      assertGeometry(frame.geometry, `E64 ${scale}x`, scale);
      assert(frame.geometry.backend.backend === 'webgl'
        && frame.pipeline.state === 'active'
        && frame.pipeline.powderBodyVfx === 'active'
        && frame.pipeline.bglaBodyVfx === 'active'
        && frame.pipeline.bglaClusterVfx === (frame === on ? 'active' : 'inactive')
        && Object.values(frame.pipeline.isolatedSelectors)
          .every((state) => state === 'inactive'),
      `E64 selector/backend state changed: ${JSON.stringify(frame.pipeline)}`);
    }
    assertHdrVfxSemanticEquality(off.semantic, on.semantic, `E64 ${scale}x off/on`);
    assertHdrVfxSemanticEquality(
      off.semantic, offRepeat.semantic, `E64 ${scale}x off/repeat`,
    );
    assertVolumeVfxBackingInvariant(off.backing, on.backing, `E64 ${scale}x off/on`);
    assertVolumeVfxBackingInvariant(
      off.backing, offRepeat.backing, `E64 ${scale}x off/repeat`,
    );
    assertBglaBodyVfxMaterialPlane(off.materialPlane, off.fixture, `E64 ${scale}x`);
    assert(JSON.stringify(off.materialPlane) === JSON.stringify(on.materialPlane)
      && JSON.stringify(off.materialPlane) === JSON.stringify(offRepeat.materialPlane),
    `E64 ${scale}x changed exact material-plane cardinalities`);
    assert(JSON.stringify(off.digest) === JSON.stringify(on.digest)
      && JSON.stringify(off.digest) === JSON.stringify(offRepeat.digest) && off.digest.ok,
    `E64 changed a protected BGLA fixture control: ${JSON.stringify(off.digest)}`);
    for (const name of ['walls', 'velocity', 'auxiliary', 'wet', 'state']) {
      assert(JSON.stringify(off[name]) === JSON.stringify(on[name])
        && JSON.stringify(off[name]) === JSON.stringify(offRepeat[name]),
      `E64 ${scale}x changed ${name} fixture state`);
    }
    assert(off.walls.occupied === off.fixture.expected.wallCells
      && off.walls.mismatches === 0 && off.walls.matterMismatches === 0
      && off.velocity.cells === off.fixture.expected.movingVelocityCells
      && off.velocity.mismatches === 0
      && Object.values(off.auxiliary.stable)
        .every(({ min, max }) => min === 255 && max === 255)
      && off.auxiliary.moving.min < 255 && off.auxiliary.moving.max < 255
      && off.wet.bgla === off.fixture.expected.suspensionBglaCells
      && off.wet.water === off.fixture.expected.suspensionWaterCells
      && off.wet.other === 0 && off.wet.bgla === off.wet.water * 2
      && off.wet.mismatches === 0 && off.wet.bglaProbe === 44
      && off.wet.waterProbe === 2 && off.state.nonZero === off.state.expectedNonZero,
    `E64 ${scale}x lost fixture ownership contracts (${JSON.stringify({
      walls: off.walls, velocity: off.velocity, auxiliary: off.auxiliary,
      wet: off.wet, state: off.state,
    })})`);
    assertVolumeVfxRawAlphaInvariant(off.rawAll, on.rawAll, `E64 ${scale}x off/on`);
    assertVolumeVfxRawAlphaInvariant(
      off.rawAll, offRepeat.rawAll, `E64 ${scale}x off/repeat`,
    );
    assert(JSON.stringify(off.rawControls) === JSON.stringify(on.rawControls)
      && JSON.stringify(off.rawControls) === JSON.stringify(offRepeat.rawControls),
    `E64 ${scale}x changed a raw topology/material/contact control`);

    const targets = bglaBodyVfxTargetRegions(off.fixture);
    const controls = bglaBodyVfxControlRegions(off.fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: off.capture.capture.data,
      refracted: on.capture.capture.data,
      repeatedStraight: offRepeat.capture.capture.data,
    }, [...targets, ...controls], off.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E64 off/on/off was not deterministic: ${JSON.stringify(responses)}`);
    assert(targetResponses.every((sample) => (
      sample.rgbRms >= BGLA_CLUSTER_VFX_RESPONSE_LIMITS.minimumRgbRms
      && sample.rgbRms <= BGLA_CLUSTER_VFX_RESPONSE_LIMITS.maximumRgbRms
      && sample.rgbPeak <= BGLA_CLUSTER_VFX_RESPONSE_LIMITS.maximumRgbPeak
      && sample.coverage >= BGLA_CLUSTER_VFX_RESPONSE_LIMITS.minimumCoverage
      && sample.coverage <= BGLA_CLUSTER_VFX_RESPONSE_LIMITS.maximumCoverage
    )), `E64 lost a real bounded BGLA body response: ${JSON.stringify({
      limits: BGLA_CLUSTER_VFX_RESPONSE_LIMITS, targetResponses,
    })}`);
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (BGLA_CLUSTER_VFX_CONTROL_PEAK[sample.name] ?? 0)),
    `E64 leaked into a protected BGLA control: ${JSON.stringify(controlResponses)}`);

    const texture = {};
    for (const [name, frame] of Object.entries(frames)) {
      texture[name] = await samplePageRegions(
        cdp, frame.capture.capture.data, bglaBodyVfxTextureRegions(off.fixture),
        undefined, undefined, frame.capture.canvasRect,
      );
    }
    const textureResponse = texture.off.map((baseline, index) => {
      const current = texture.on[index], repeated = texture.offRepeat[index];
      assert(current?.name === baseline.name && repeated?.name === baseline.name,
        `E64 ${scale}x reordered BGLA texture regions`);
      return {
        name: baseline.name,
        disabledMicro: baseline.microContrast,
        enabledMicro: current.microContrast,
        microRetention: round(
          current.microContrast / Math.max(0.001, baseline.microContrast), 4,
        ),
        disabledChroma: baseline.chromaticContrast,
        enabledChroma: current.chromaticContrast,
        chromaRetention: round(
          current.chromaticContrast / Math.max(0.001, baseline.chromaticContrast), 4,
        ),
        disabledMacro: baseline.macroLumaRange,
        enabledMacro: current.macroLumaRange,
        macroRetention: round(
          current.macroLumaRange / Math.max(0.001, baseline.macroLumaRange), 4,
        ),
        enabledLumaStdDev: current.lumaStdDev,
        enabledLumaRange: current.lumaRange,
        supportRecall: current.supportRecall,
        coverage: current.coverage,
        clippedFraction: current.clippedFraction,
        repeatExact: JSON.stringify(baseline) === JSON.stringify(repeated),
      };
    });
    const limits = BGLA_CLUSTER_VFX_TEXTURE_LIMITS;
    assert(textureResponse.every((sample) => (
      sample.disabledMicro >= limits.minimumBaselineMicro
      && sample.enabledMicro >= limits.minimumEnabledMicro
      && sample.enabledMicro <= limits.maximumEnabledMicro
      && sample.microRetention >= limits.minimumMicroRetention
      && sample.microRetention <= limits.maximumMicroRetention
      && sample.disabledChroma >= limits.minimumBaselineChroma
      && sample.enabledChroma >= limits.minimumEnabledChroma
      && sample.enabledChroma <= limits.maximumEnabledChroma
      && sample.chromaRetention >= limits.minimumChromaRetention
      && sample.chromaRetention <= limits.maximumChromaRetention
      && sample.enabledMacro >= limits.minimumEnabledMacro
      && sample.enabledMacro <= limits.maximumEnabledMacro
      && sample.macroRetention >= limits.minimumMacroRetention
      && sample.macroRetention <= limits.maximumMacroRetention
      && sample.enabledLumaStdDev >= limits.minimumEnabledLumaStdDev
      && sample.enabledLumaStdDev <= limits.maximumEnabledLumaStdDev
      && sample.enabledLumaRange >= limits.minimumEnabledLumaRange
      && sample.enabledLumaRange <= limits.maximumEnabledLumaRange
      && sample.supportRecall === 1 && sample.coverage >= limits.minimumCoverage
      && sample.clippedFraction === 0 && sample.repeatExact
    )), `E64 lost bounded crystalline granulation or broad relief: ${JSON.stringify({
      limits, textureResponse,
    })}`);

    const references = {};
    for (const style of ['grains', 'local']) {
      const referenceResponses = await sampleBackdropRefractionRegions(cdp, {
        straight: off.references[style].capture.data,
        refracted: on.references[style].capture.data,
        repeatedStraight: offRepeat.references[style].capture.data,
      }, targets, off.references[style].canvasRect);
      assert(referenceResponses.every((sample) => (
        sample.rgbPeak === 0 && sample.repeatRgbPeak === 0
      )), `E64 escaped the exact ${style} reference mode: ${JSON.stringify(
        referenceResponses,
      )}`);
      references[style] = referenceResponses;
    }
    const screenshots = screenshotRequest
      ? await writeBglaClusterVfxScreenshots(screenshotRequest, scale, off, on)
      : undefined;
    scales.push({
      scale, geometry: off.geometry, semantic: off.semantic,
      materialPlane: off.materialPlane, walls: off.walls, velocity: off.velocity,
      auxiliary: off.auxiliary, wet: off.wet, state: off.state,
      rawControls: off.rawControls, targets: targetResponses,
      controls: controlResponses, textureResponse, digest: off.digest,
      references, screenshots, exactRepeatedOff: true,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const current of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(
        reference.geometry.canvas, current.geometry.canvas,
        `E64 ${reference.scale}x/${current.scale}x CSS geometry`,
      );
      assert(JSON.stringify(reference.semantic) === JSON.stringify(current.semantic)
        && JSON.stringify(reference.materialPlane) === JSON.stringify(current.materialPlane)
        && JSON.stringify(reference.walls) === JSON.stringify(current.walls)
        && JSON.stringify(reference.velocity) === JSON.stringify(current.velocity)
        && JSON.stringify(reference.auxiliary) === JSON.stringify(current.auxiliary)
        && JSON.stringify(reference.wet) === JSON.stringify(current.wet)
        && JSON.stringify(reference.state) === JSON.stringify(current.state),
      `E64 ${current.scale}x changed exact fixture state across scales`);
      for (const baseline of reference.targets) {
        const sample = current.targets.find(({ name }) => name === baseline.name);
        assert(sample
          && Math.abs(sample.rgbRms - baseline.rgbRms)
            <= BGLA_CLUSTER_VFX_CROSS_SCALE_LIMITS.maximumRgbRmsDrift
          && Math.abs(sample.coverage - baseline.coverage)
            <= BGLA_CLUSTER_VFX_CROSS_SCALE_LIMITS.maximumCoverageDrift,
        `E64 ${baseline.name} response drifted at ${current.scale}x (${JSON.stringify({
          reference: baseline, current: sample,
        })})`);
      }
      for (const baseline of reference.textureResponse) {
        const sample = current.textureResponse.find(({ name }) => name === baseline.name);
        assert(sample
          && Math.abs(sample.microRetention - baseline.microRetention)
            <= BGLA_CLUSTER_VFX_CROSS_SCALE_LIMITS.maximumMicroRetentionDrift
          && Math.abs(sample.chromaRetention - baseline.chromaRetention)
            <= BGLA_CLUSTER_VFX_CROSS_SCALE_LIMITS.maximumChromaRetentionDrift
          && Math.abs(sample.macroRetention - baseline.macroRetention)
            <= BGLA_CLUSTER_VFX_CROSS_SCALE_LIMITS.maximumMacroRetentionDrift,
        `E64 ${baseline.name} texture response drifted at ${current.scale}x (${JSON.stringify({
          reference: baseline, current: sample,
        })})`);
      }
    }
  }
  return {
    calibration: 'accepted-e64-1x-4x',
    responseLimits: BGLA_CLUSTER_VFX_RESPONSE_LIMITS,
    textureLimits: BGLA_CLUSTER_VFX_TEXTURE_LIMITS,
    controlPeakCaps: BGLA_CLUSTER_VFX_CONTROL_PEAK,
    crossScaleLimits: BGLA_CLUSTER_VFX_CROSS_SCALE_LIMITS,
    scales, trueEightXExcluded: true,
    trueEightX: await auditEightXBglaClusterVfxExclusion(cdp, dpr),
  };
}

async function navigateBglaClusterVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    bglaClusterVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '1', bglaBodyVfx: '1',
    bglaClusterVfx: enabled ? '1' : '0',
  });
  for (const selector of BGLA_CLUSTER_VFX_ISOLATED_SELECTORS) query.set(selector, '0');
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const api = `(() => {
    const p = new URLSearchParams(location.search);
    const a = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = ${JSON.stringify(BGLA_CLUSTER_VFX_ISOLATED_SELECTORS)};
    return p.get('bglaClusterVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('bglaBodyVfx') === '1'
      && p.get('bglaClusterVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof a?.prepareBglaBodyVfxFixture === 'function'
      && typeof a?.bglaBodyVfxFixture === 'function';
  })()`;
  await waitFor(
    () => evaluate(cdp, api), scale === 4 ? 45_000 : 15_000,
    `E64 ${label} page`,
  );
  await waitFor(
    () => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
    scale === 4 ? 30_000 : 15_000, `E64 ${label} backend`,
  );
  const fixture = await evaluate(cdp, `(() => {
    const a = window.__ANIFOR_INPUT_AUDIT__;
    a.prepareBglaBodyVfxFixture();
    a.setPowderRenderStyle('smooth');
    a.setUnusualPowderStyling(true);
    return a.bglaBodyVfxFixture();
  })()`);
  for (let pass = 0; pass < 7; pass++) {
    const before = await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp, `(() => {
      const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
      return current?.dynamicSequence > ${before.dynamicSequence} ? current : false;
    })()`), scale === 4 ? 15_000 : 5_000,
    `E64 ${label} ${scale}x stability pass ${pass + 1}`);
  }
  await sleep(350);
  const pipeline = await evaluate(cdp, `(() => {
    const c = document.querySelector('canvas.semantic-field-canvas');
    const isolated = ${JSON.stringify(BGLA_CLUSTER_VFX_ISOLATED_SELECTORS)};
    return c ? {
      state: c.dataset.hdrPipeline,
      powderBodyVfx: c.dataset.powderBodyVfx,
      bglaBodyVfx: c.dataset.bglaBodyVfx,
      bglaClusterVfx: c.dataset.bglaClusterVfx,
      isolatedSelectors: Object.fromEntries(
        isolated.map((name) => [name, c.dataset[name]]),
      ),
    } : undefined;
  })()`);
  const controls = bglaBodyVfxControlRegions(fixture);
  const targets = bglaBodyVfxTargetRegions(fixture);
  return {
    fixture, pipeline,
    digest: await bglaBodyVfxFixtureDigest(cdp, fixture),
    capture: await waitForStablePageCapture(
      cdp, `E64 ${label} ${scale}x framebuffer`,
      scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000,
    ),
    geometry: await metrics(cdp),
    semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    materialPlane: await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()'),
    walls: await bglaBodyVfxWallDigest(cdp, fixture),
    velocity: await bglaBodyVfxVelocityDigest(cdp, fixture),
    auxiliary: await bglaBodyVfxAuxiliaryDigest(cdp, fixture),
    wet: await bglaBodyVfxWetDigest(cdp, fixture),
    state: await bglaBodyVfxStateDigest(cdp, fixture),
    rawAll: await sampleVolumeVfxRawWorldPixels(
      cdp, [...targets, ...controls].map(({ name, x, y }) => ({
        name, x: Math.floor(x), y: Math.floor(y),
      })),
    ),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, controls.map(({ name, x, y }) => ({
        name, x: Math.floor(x), y: Math.floor(y),
      })),
    ),
  };
}

async function writeBglaClusterVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e64-bgla-cluster-${scale}x-off`),
    on: variantScreenshotPath(source, `e64-bgla-cluster-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXBglaClusterVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1',
    auditStage: 'eight-bgla-cluster', bglaClusterVfxAudit: '1',
    renderScale: '8', renderLook: 'realistic', powderBodyVfx: '1',
    bglaBodyVfx: '1', bglaClusterVfx: '1',
  });
  for (const selector of BGLA_CLUSTER_VFX_ISOLATED_SELECTORS) query.set(selector, '0');
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp,
    `new URLSearchParams(location.search).get('renderScale') === '8'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__)`),
  remainingDeadlineMs(deadline, 'true-8x E64 API'), 'true-8x E64 API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E64', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E64');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E64 geometry')),
    'true-8x E64 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8
    && geometry.outputScale === '8', 'true-8x E64 lost exact backing');
  const state = await evaluate(cdp, `(() => {
    const c = document.querySelector('canvas.semantic-field-canvas');
    const isolated = ${JSON.stringify(BGLA_CLUSTER_VFX_ISOLATED_SELECTORS)};
    return c ? {
      renderer: c.dataset.renderer,
      look: c.dataset.renderLook,
      bglaBodyVfx: c.dataset.bglaBodyVfx,
      bglaClusterVfx: c.dataset.bglaClusterVfx,
      powderBodyVfx: c.dataset.powderBodyVfx,
      hdr: c.dataset.hdrPipeline,
      reason: c.dataset.hdrPipelineReason,
      bloom: c.dataset.bloomBacking ?? null,
      isolatedSelectors: Object.fromEntries(
        isolated.map((name) => [name, c.dataset[name]]),
      ),
    } : undefined;
  })()`);
  assert(state?.renderer === 'semantic-field-webgl' && state.look === 'realistic'
    && state.bglaBodyVfx === 'inactive' && state.bglaClusterVfx === 'inactive'
    && state.powderBodyVfx === 'inactive' && state.hdr === 'inactive'
    && state.reason === 'scale-8' && state.bloom === null
    && Object.values(state.isolatedSelectors).every((selector) => selector === 'inactive'),
  `true-8x E64 selector/resource exclusion failed: ${JSON.stringify(state)}`);
  const materialPlane = await evaluate(cdp,
    'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()');
  assert(materialPlane.occupied === 0 && (materialPlane.materialCounts[44] ?? 0) === 0,
    `true-8x E64 unexpectedly uploaded its dense fixture: ${JSON.stringify(
      materialPlane,
    )}`);
  const semanticBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E64 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E64 did not complete GPU work: ${JSON.stringify(timing)}`);
  const semanticAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(
    semanticBefore, semanticAfter, 'true-8x E64 GPU completion',
  );
  return {
    geometry, backend, state, materialPlane, fixtureUploaded: false,
    semanticStable: true, timing,
  };
}

/** E50: exact C4 granular body with no native presentation-state contract. */
async function auditC4BodyVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      const variant = await navigateC4BodyVfxState(cdp, mode, scale, enabled, key);
      variant.references = await capturePowderBodyVfxReferenceStyles(cdp, scale, key, 'E50');
      captures[key] = variant;
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E50 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E50 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E50 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.powderBodyVfx === 'active'
        && variant.hdrPipeline.c4BodyVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E50 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E50 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E50 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E50 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E50 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E50 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E50 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E50 ${scale}x disabled/repeated`);
    assertC4BodyVfxMaterialPlane(disabled.materialPlane, fixture, `E50 ${scale}x`);
    assert(JSON.stringify(disabled.materialPlane) === JSON.stringify(enabled.materialPlane)
      && JSON.stringify(disabled.materialPlane) === JSON.stringify(disabledRepeat.materialPlane),
    `E50 ${scale}x changed exact material-plane topology`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied === 2_048 && disabled.walls.expectedOccupied === 2_048
      && disabled.walls.mismatches === 0 && disabled.walls.matterMismatches === 0,
    `E50 ${scale}x changed 2,048 native-wall cells (${JSON.stringify(disabled.walls)})`);
    assert(JSON.stringify(disabled.velocity) === JSON.stringify(enabled.velocity)
      && JSON.stringify(disabled.velocity) === JSON.stringify(disabledRepeat.velocity)
      && disabled.velocity.cells === 4_480 && disabled.velocity.expectedCells === 4_480
      && disabled.velocity.mismatches === 0,
    `E50 ${scale}x changed 4,480 authored velocity cells (${JSON.stringify(disabled.velocity)})`);
    assert(JSON.stringify(disabled.auxiliary) === JSON.stringify(enabled.auxiliary)
      && JSON.stringify(disabled.auxiliary) === JSON.stringify(disabledRepeat.auxiliary)
      && Object.values(disabled.auxiliary.stable).every(({ min, max }) => (
        min === 255 && max === 255
      )) && disabled.auxiliary.moving.min < 255 && disabled.auxiliary.moving.max < 255,
    `E50 ${scale}x lost stable-body or moving-control auxiliary state (${JSON.stringify(
      disabled.auxiliary,
    )})`);
    assert(JSON.stringify(disabled.wet) === JSON.stringify(enabled.wet)
      && JSON.stringify(disabled.wet) === JSON.stringify(disabledRepeat.wet)
      && disabled.wet.c4 === fixture.expected.suspensionC4Cells
      && disabled.wet.water === fixture.expected.suspensionWaterCells
      && disabled.wet.c4 === disabled.wet.water * 2 && disabled.wet.other === 0
      && disabled.wet.c4Probe.cell === 31 && disabled.wet.waterProbe.cell === 2
      && disabled.wet.c4Probe.rgba[3] > 0 && disabled.wet.waterProbe.rgba[3] > 0
      && disabled.wet.c4Probe.liquidAlpha > 0 && disabled.wet.waterProbe.liquidAlpha > 0,
    `E50 ${scale}x lost the exact 2:1 C4/Water wet control (${JSON.stringify(disabled.wet)})`);
    assert(JSON.stringify(disabled.state) === JSON.stringify(enabled.state)
      && JSON.stringify(disabled.state) === JSON.stringify(disabledRepeat.state)
      && disabled.state.nonZero === 0 && disabled.state.expectedNonZero === 0,
    `E50 ${scale}x introduced native presentation state (${JSON.stringify(disabled.state)})`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E50 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E50 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E50 ${scale}x changed an exact raw topology/material/contact control (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls,
    })})`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E50 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = c4BodyVfxTargetRegions(fixture);
    const controls = c4BodyVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length).map((sample) => ({
      ...sample,
      spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2
        - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2)), 3),
    }));
    const controlResponses = responses.slice(targets.length);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E50 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    assert(targetResponses.every((sample) => [
      sample.rgbRms, sample.chromaRms, sample.rgbPeak, sample.coverage,
      sample.signedMean, sample.spatialRgbRms,
    ].every(Number.isFinite)
      && sample.rgbRms >= C4_BODY_VFX_RESPONSE_LIMITS.minimumRgbRms
      && sample.rgbRms <= C4_BODY_VFX_RESPONSE_LIMITS.maximumRgbRms
      && sample.rgbPeak <= C4_BODY_VFX_RESPONSE_LIMITS.maximumRgbPeak
      && sample.coverage >= C4_BODY_VFX_RESPONSE_LIMITS.minimumCoverage),
    `E50 ${scale}x C4 response was absent or unbounded (${JSON.stringify(targetResponses)})`);
    assert(targetResponses.every((sample) => {
      const envelope = C4_BODY_VFX_TARGET_ENVELOPES[sample.name];
      return envelope
        && sample.rgbRms >= envelope.rgbRms[0] && sample.rgbRms <= envelope.rgbRms[1]
        && sample.chromaRms >= envelope.chromaRms[0]
        && sample.chromaRms <= envelope.chromaRms[1]
        && sample.rgbPeak >= envelope.rgbPeak[0] && sample.rgbPeak <= envelope.rgbPeak[1]
        && sample.coverage >= envelope.coverage[0] && sample.coverage <= envelope.coverage[1]
        && sample.signedMean >= envelope.signedMean[0]
        && sample.signedMean <= envelope.signedMean[1]
        && sample.spatialRgbRms >= envelope.spatialRgbRms[0]
        && sample.spatialRgbRms <= envelope.spatialRgbRms[1];
    }),
    `E50 ${scale}x escaped the accepted C4 target envelope (${JSON.stringify({
      envelopes: C4_BODY_VFX_TARGET_ENVELOPES, targetResponses,
    })})`);
    const byName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(byName.C4Crown.signedMean > byName.C4Pocket.signedMean + 1.25
      && byName.C4WholeBody.positiveMean >= 1.5
      && byName.C4WholeBody.negativeMean >= 1.5
      && byName.C4WholeBody.responseSignature !== byName.C4Core.responseSignature
      && byName.C4Core.responseSignature !== byName.C4Crown.responseSignature
      && byName.C4Core.responseSignature !== byName.C4Pocket.responseSignature,
    `E50 ${scale}x did not retain relational crown/pocket/core separation (${JSON.stringify(byName)})`);
    assert(controlResponses.length === controls.length
      && controlResponses.every((sample) => sample.rgbPeak
        <= (C4_BODY_VFX_CONTROL_PEAK[sample.name] ?? 0)),
    `E50 ${scale}x escaped an exact topology/material/contact control (${JSON.stringify(controlResponses)})`);

    const textureRegions = c4BodyVfxTextureRegions(fixture);
    const texture = {};
    for (const [name, variant] of Object.entries(captures)) {
      texture[name] = await samplePageRegions(
        cdp, variant.capture.capture.data, textureRegions,
        undefined, undefined, variant.capture.canvasRect,
      );
    }
    const textureResponse = texture.disabled.map((baseline, index) => {
      const current = texture.enabled[index];
      const repeated = texture.disabledRepeat[index];
      assert(current?.name === baseline.name && repeated?.name === baseline.name,
        `E50 ${scale}x reordered C4 texture regions`);
      return {
        name: baseline.name,
        disabledMicro: baseline.microContrast,
        enabledMicro: current.microContrast,
        microRetention: round(current.microContrast / Math.max(0.001, baseline.microContrast), 4),
        disabledMacro: baseline.macroLumaRange,
        enabledMacro: current.macroLumaRange,
        macroRetention: round(current.macroLumaRange / Math.max(0.001, baseline.macroLumaRange), 4),
        enabledLumaStdDev: current.lumaStdDev,
        supportRecall: current.supportRecall,
        clippedFraction: current.clippedFraction,
        repeatExact: JSON.stringify(baseline) === JSON.stringify(repeated),
      };
    });
    assert(textureResponse.every((sample) => sample.disabledMicro
      >= C4_BODY_VFX_TEXTURE_LIMITS.minimumBaselineMicro
      && sample.enabledMicro >= C4_BODY_VFX_TEXTURE_LIMITS.minimumEnabledMicro
      && sample.enabledMicro <= C4_BODY_VFX_TEXTURE_LIMITS.maximumEnabledMicro
      && sample.microRetention >= C4_BODY_VFX_TEXTURE_LIMITS.minimumMicroRetention
      && sample.microRetention <= C4_BODY_VFX_TEXTURE_LIMITS.maximumMicroRetention
      && sample.enabledMacro >= C4_BODY_VFX_TEXTURE_LIMITS.minimumEnabledMacro
      && sample.enabledMacro <= C4_BODY_VFX_TEXTURE_LIMITS.maximumEnabledMacro
      && sample.macroRetention >= C4_BODY_VFX_TEXTURE_LIMITS.minimumMacroRetention
      && sample.macroRetention <= C4_BODY_VFX_TEXTURE_LIMITS.maximumMacroRetention
      && sample.enabledLumaStdDev >= C4_BODY_VFX_TEXTURE_LIMITS.minimumEnabledLumaStdDev
      && sample.enabledLumaStdDev <= C4_BODY_VFX_TEXTURE_LIMITS.maximumEnabledLumaStdDev
      && sample.supportRecall === 1
      && sample.clippedFraction <= C4_BODY_VFX_TEXTURE_LIMITS.maximumClippedFraction
      && sample.repeatExact),
    `E50 ${scale}x did not calm C4 grain while retaining pressed-body relief (${JSON.stringify({
      limits: C4_BODY_VFX_TEXTURE_LIMITS, textureResponse,
    })})`);

    const references = {};
    for (const style of ['grains', 'local']) {
      const samples = await sampleBackdropRefractionRegions(cdp, {
        straight: disabled.references[style].capture.data,
        refracted: enabled.references[style].capture.data,
        repeatedStraight: disabledRepeat.references[style].capture.data,
      }, c4BodyVfxTargetRegions(fixture), disabled.references[style].canvasRect);
      assert(samples.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
        `E50 ${scale}x escaped the exact ${style} reference mode (${JSON.stringify(samples)})`);
      references[style] = samples;
    }
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeC4BodyVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      materialPlane: disabled.materialPlane, walls: disabled.walls, velocity: disabled.velocity,
      auxiliary: disabled.auxiliary, wet: disabled.wet, state: disabled.state,
      rawControls: disabled.rawControls, targets: targetResponses,
      controls: controlResponses, textureResponse,
      references, exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E50 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.materialPlane) === JSON.stringify(sample.materialPlane)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls)
        && JSON.stringify(reference.velocity) === JSON.stringify(sample.velocity)
        && JSON.stringify(reference.auxiliary) === JSON.stringify(sample.auxiliary)
        && JSON.stringify(reference.wet) === JSON.stringify(sample.wet)
        && JSON.stringify(reference.state) === JSON.stringify(sample.state),
      `E50 ${sample.scale}x changed exact fixture state across output scales`);
      for (const baseline of reference.textureResponse) {
        const current = sample.textureResponse.find(({ name }) => name === baseline.name);
        assert(current && Math.abs(current.microRetention - baseline.microRetention)
          <= C4_BODY_VFX_CROSS_SCALE_LIMITS.maximumMicroRetentionDrift
          && Math.abs(current.macroRetention - baseline.macroRetention)
          <= C4_BODY_VFX_CROSS_SCALE_LIMITS.maximumMacroRetentionDrift,
        `E50 ${baseline.name} texture response drifted at ${sample.scale}x (${JSON.stringify({
          reference: baseline, current,
        })})`);
      }
    }
  }
  return {
    calibration: 'accepted-e50-1x-4x',
    textureLimits: C4_BODY_VFX_TEXTURE_LIMITS,
    responseLimits: C4_BODY_VFX_RESPONSE_LIMITS,
    targetEnvelopes: C4_BODY_VFX_TARGET_ENVELOPES,
    controlPeakCaps: C4_BODY_VFX_CONTROL_PEAK,
    crossScaleLimits: C4_BODY_VFX_CROSS_SCALE_LIMITS,
    scales, trueEightXExcluded: true,
    trueEightX: await auditEightXC4BodyVfxExclusion(cdp, dpr),
  };
}

function assertC4BodyVfxMaterialPlane(plane, fixture, label) {
  const controls = Object.values(fixture.materialControls ?? {});
  assert(plane.occupied === 98_713 && plane.materialCounts[31] === 62_841
    && plane.materialCounts[2] === 3_872 && plane.materialCounts[23] === 1_280
    && controls.length === 10 && controls.every((entry) => (
      plane.materialCounts[entry.material] === 3_072
    )) && fixture.expected?.occupiedCells === 98_713
    && fixture.expected?.c4Cells === 62_841 && fixture.expected?.waterCells === 3_872
    && fixture.expected?.metalCells === 1_280 && fixture.expected?.cellsPerMaterialControl === 3_072
    && fixture.expected?.wallCells === 2_048 && fixture.expected?.movingVelocityCells === 4_480
    && fixture.expected?.suspensionC4Cells === fixture.expected?.suspensionWaterCells * 2,
  `${label} changed exact C4/Water/Metal/material-control cardinalities (${JSON.stringify({
    occupied: plane.occupied, c4: plane.materialCounts[31], water: plane.materialCounts[2],
    metal: plane.materialCounts[23], controls: controls.map(({ material }) => plane.materialCounts[material]),
    expected: fixture.expected,
  })})`);
}

async function navigateC4BodyVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    c4BodyVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '1', sootyPowderBodyVfx: '0', thermiteBodyVfx: '0',
    snowpackBodyVfx: '0', quartzMesostructureVfx: '0', c4BodyVfx: enabled ? '1' : '0',
    powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', metalWaterContactVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    radioactiveSolidBodyVfx: '0', iszsCrystallineVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', botanicalMesostructureVfx: '0',
    botanicalPigmentVfx: '0', plantLaminaVfx: '0', plantLobeDepthVfx: '0',
    plantCanopyMassVfx: '0', woodBarkReliefVfx: '0', woodTanninVfx: '0', glassBodyVfx: '0',
    acidBodyVfx: '0', deutBodyVfx: '0', oilBodyVfx: '0', oilVolumeFinishVfx: '0',
    rockRoughnessVfx: '0', rockMesostructureVfx: '0', waterBodyVfx: '0',
    hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = ${JSON.stringify(C4_BODY_VFX_ISOLATED_SELECTORS)};
    return p.get('c4BodyVfxAudit') === '1' && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('powderBodyVfx') === '1'
      && p.get('c4BodyVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareC4BodyVfxFixture === 'function'
      && typeof audit?.c4BodyVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E50 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E50 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareC4BodyVfxFixture(); audit.setPowderRenderStyle('smooth');
    return audit.c4BodyVfxFixture();
  })()`);
  // Seven independently presented refreshes bring the paused C4 body to the
  // established stability byte while the authored moving control stays loose.
  for (let pass = 0; pass < 7; pass++) {
    const before = await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp, `(() => {
      const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
      return current?.dynamicSequence > ${before.dynamicSequence} ? current : false;
    })()`), scale === 4 ? 15_000 : 5_000,
    `E50 ${label} ${scale}x stability pass ${pass + 1}`);
  }
  await waitFor(() => c4BodyVfxFixtureReady(cdp, fixture), 20_000,
    `E50 ${label} ${scale}x fixture/stability hydration`);
  await sleep(350);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    const isolated = ${JSON.stringify(C4_BODY_VFX_ISOLATED_SELECTORS)};
    return canvas ? { look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      powderBodyVfx: canvas.dataset.powderBodyVfx, c4BodyVfx: canvas.dataset.c4BodyVfx,
      isolatedSelectors: Object.fromEntries(isolated.map((name) => [name, canvas.dataset[name]])),
    } : undefined;
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.powderBodyVfx === 'active'
    && hdrPipeline.c4BodyVfx === (enabled ? 'active' : 'inactive')
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive'),
  `E50 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const target = fixture.target;
  return {
    fixture, hdrPipeline,
    capture: await waitForStablePageCapture(cdp, `E50 ${label} ${scale}x framebuffer`,
      scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000),
    geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    materialPlane: await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()'),
    walls: await c4BodyVfxWallDigest(cdp, fixture),
    velocity: await c4BodyVfxVelocityDigest(cdp, fixture),
    auxiliary: await c4BodyVfxAuxiliaryDigest(cdp, fixture),
    wet: await c4BodyVfxWetDigest(cdp, fixture),
    state: await c4BodyVfxStateDigest(cdp, fixture),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, [
      ...c4BodyVfxTargetRegions(fixture).map(({ name, x, y }) => ({ name, x: Math.floor(x), y: Math.floor(y) })),
      ...c4BodyVfxControlRegions(fixture).map(({ name, x, y }) => ({ name, x: Math.floor(x), y: Math.floor(y) })),
      { name: 'TargetMaterial', x: target.body.x, y: target.body.y },
    ]),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp,
      c4BodyVfxControlRegions(fixture).map(({ name, x, y }) => ({
        name, x: Math.floor(x), y: Math.floor(y),
      }))),
  };
}

async function c4BodyVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    if (fixture?.version !== 1 || fixture?.world?.width !== audit?.width
      || fixture?.world?.height !== audit?.height || fixture?.target?.material !== 31) return false;
    const exact = (rect, material) => {
      if (!rect) return false;
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (audit.cell(x, y) !== material) return false;
      }
      return true;
    };
    const t = fixture.target;
    const inside = (rect, x, y) => rect && x >= rect.x && x < rect.x + rect.width && y >= rect.y && y < rect.y + rect.height;
    for (let y = t.body.y; y < t.body.y + t.body.height; y++) for (let x = t.body.x; x < t.body.x + t.body.width; x++) {
      const empty = inside(t.authoredHole, x, y) || inside(t.openChannel, x, y);
      if (audit.cell(x, y) !== (empty ? 0 : 31)) return false;
    }
    if (![t.core, t.crown, t.pocket].every((rect) => exact(rect, 31))) return false;
    if (!exact(fixture.fineTopology?.column, 31) || !exact(fixture.fineTopology?.line, 31)
      || audit.cell(fixture.fineTopology?.isolated?.x, fixture.fineTopology?.isolated?.y) !== 31
      || !exact(fixture.movingControl, 31) || !exact(fixture.guardedBlank, 0)) return false;
    const moving = fixture.movingControl;
    for (let y = moving.y; y < moving.y + moving.height; y++) for (let x = moving.x; x < moving.x + moving.width; x++) {
      const velocity = audit.velocity(x, y);
      if (velocity[0] !== moving.velocityX || velocity[1] !== moving.velocityY) return false;
    }
    const controls = Object.values(fixture.materialControls ?? {});
    const contacts = Object.values(fixture.contacts ?? {});
    const contactExact = (entry) => exact(entry.c4 ?? entry.target ?? entry.owner, 31)
      && exact(entry.other ?? entry.neighbour, entry.otherMaterial ?? entry.neighbourMaterial);
    const digest = audit.materialPlaneDigest();
    const suspension = fixture.suspensionControl;
    const c4Points = new Set((suspension?.c4Points ?? []).map(({ x, y }) => x + ',' + y));
    const suspensionExact = suspension?.region && c4Points.size === fixture.expected?.suspensionC4Cells
      && suspension.region.width * suspension.region.height
        === fixture.expected?.suspensionC4Cells + fixture.expected?.suspensionWaterCells
      && [...c4Points].every((key) => {
        const [x, y] = key.split(',').map(Number); return audit.cell(x, y) === 31;
      })
      && (() => {
        for (let y = suspension.region.y; y < suspension.region.y + suspension.region.height; y++) {
          for (let x = suspension.region.x; x < suspension.region.x + suspension.region.width; x++) {
            if (audit.cell(x, y) !== (c4Points.has(x + ',' + y) ? 31 : 2)) return false;
          }
        }
        return true;
      })();
    return controls.length === 10 && controls.every((entry) => exact(entry, entry.material))
      && contacts.every(contactExact) && digest.occupied === 98_713
      && digest.materialCounts[31] === 62_841 && digest.materialCounts[2] === 3_872
      && digest.materialCounts[23] === 1_280 && suspensionExact;
  })()`);
}

async function c4BodyVfxWallDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const wall = ${JSON.stringify(fixture.target.wallCoexistence)};
    let occupied = 0, expectedOccupied = 0, mismatches = 0, matterMismatches = 0;
    for (let y = wall.region.y; y < wall.region.y + wall.region.height; y++) for (let x = wall.region.x; x < wall.region.x + wall.region.width; x++) {
      const bx = Math.floor((x - wall.region.x) / wall.blockSize), by = Math.floor((y - wall.region.y) / wall.blockSize);
      const expected = (bx + by) % 2 === wall.occupiedParity ? ${JSON.stringify(fixture.conductiveWall)} : 0;
      occupied += Number(audit.wall(x, y) === ${JSON.stringify(fixture.conductiveWall)});
      expectedOccupied += Number(expected === ${JSON.stringify(fixture.conductiveWall)});
      mismatches += Number(audit.wall(x, y) !== expected); matterMismatches += Number(audit.cell(x, y) !== 31);
    }
    return { occupied, expectedOccupied, mismatches, matterMismatches };
  })()`);
}

async function c4BodyVfxVelocityDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const rect = ${JSON.stringify(fixture.movingControl)};
    let cells = 0, mismatches = 0;
    for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
      const velocity = audit.velocity(x, y); cells++;
      mismatches += Number(velocity[0] !== rect.velocityX || velocity[1] !== rect.velocityY);
    }
    return { cells, expectedCells: rect.width * rect.height, mismatches };
  })()`);
}

async function c4BodyVfxAuxiliaryDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const range = (rect) => {
      let min = 255; let max = 0;
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          const value = audit.presentationAuxiliary(x, y);
          min = Math.min(min, value); max = Math.max(max, value);
        }
      }
      return { min, max };
    };
    return {
      stable: { core: range(fixture.target.core), crown: range(fixture.target.crown),
        pocket: range(fixture.target.pocket) },
      moving: range(fixture.movingControl),
    };
  })()`);
}

async function c4BodyVfxWetDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const wet = ${JSON.stringify(fixture.suspensionControl)};
    if (!wet?.region) return { c4: -1, water: -1, other: -1 };
    let c4 = 0, water = 0, other = 0;
    for (let y = wet.region.y; y < wet.region.y + wet.region.height; y++) {
      for (let x = wet.region.x; x < wet.region.x + wet.region.width; x++) {
        const material = audit.cell(x, y);
        if (material === 31) c4++; else if (material === 2) water++; else other++;
      }
    }
    const probe = (point) => ({ cell: audit.cell(point.x, point.y),
      rgba: audit.suspensionAt(point.x, point.y), liquidAlpha: audit.liquidFieldAlpha(point.x, point.y) });
    return { c4, water, other, c4Probe: probe(wet.c4Probe), waterProbe: probe(wet.waterProbe) };
  })()`);
}

async function c4BodyVfxStateDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    let nonZero = 0;
    for (let y = 0; y < audit.height; y++) for (let x = 0; x < audit.width; x++) {
      nonZero += Number(audit.presentationState(x, y) !== 0);
    }
    return { nonZero, expectedNonZero: ${JSON.stringify(fixture.expected.presentationStateCells)} };
  })()`);
}

function c4BodyVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({ name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2), radiusY: Math.max(0.35, candidate.height / 2 - 0.2) });
  return [rect('C4WholeBody', fixture.target.body), rect('C4Crown', fixture.target.crown),
    rect('C4Pocket', fixture.target.pocket), rect('C4Core', fixture.target.core)];
}

function c4BodyVfxTextureRegions(fixture) {
  return c4BodyVfxTargetRegions(fixture)
    .filter(({ name }) => name !== 'C4WholeBody')
    .map((region) => ({ ...region,
      support: { kind: 'semantic', materials: [fixture.target.material] },
    }));
}

function c4BodyVfxControlRegions(fixture) {
  const point = (name, candidate) => candidate && ({ name, x: Math.floor(candidate.x) + 0.5,
    y: Math.floor(candidate.y) + 0.5, radius: 0 });
  const center = (name, rect) => point(name, { x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2) });
  const controls = [center('C4Hole', fixture.target.authoredHole), center('C4OpenChannel', fixture.target.openChannel),
    center('FineColumn', fixture.fineTopology.column), center('FineLine', fixture.fineTopology.line),
    point('Isolated', fixture.fineTopology.isolated), center('Moving', fixture.movingControl),
    point('NativeWallOccupied', fixture.target.wallCoexistence.wallProbe), point('NativeWallClear', fixture.target.wallCoexistence.clearProbe),
    center('GuardedBlank', fixture.guardedBlank)];
  for (const [name, rect] of Object.entries(fixture.materialControls ?? {})) controls.push(center(`Material${name[0].toUpperCase()}${name.slice(1)}`, rect));
  for (const [name, contact] of Object.entries(fixture.contacts ?? {})) {
    controls.push(point(`C4${name[0].toUpperCase()}${name.slice(1)}`, contact.c4Probe ?? contact.targetProbe ?? contact.ownerProbe));
    controls.push(point(`${name[0].toUpperCase()}${name.slice(1)}`, contact.otherProbe ?? contact.neighbourProbe));
  }
  const wet = fixture.suspensionControl;
  if (wet?.c4Probe) controls.push(point('WetC4', wet.c4Probe));
  if (wet?.waterProbe) controls.push(point('WetWater', wet.waterProbe));
  return controls.filter(Boolean);
}

async function writeC4BodyVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e50-c4-body-${scale}x-off`),
    on: variantScreenshotPath(source, `e50-c4-body-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXC4BodyVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({ scene: 'render-lab', inputAudit: '1', blankAudit: '1',
    auditStage: 'eight-c4-body', c4BodyVfxAudit: '1', renderScale: '8', renderLook: 'realistic',
    powderBodyVfx: '1', c4BodyVfx: '1', snowpackBodyVfx: '0', quartzMesostructureVfx: '0',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0', gasMotionVfx: '0' });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => { const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8' && p.get('auditStage') === 'eight-c4-body'
      && p.get('c4BodyVfx') === '1' && p.get('snowpackBodyVfx') === '0'
      && p.get('quartzMesostructureVfx') === '0'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__); })()`),
  remainingDeadlineMs(deadline, 'true-8x E50 input audit API'), 'true-8x E50 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E50', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E50');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E50 geometry')), 'true-8x E50 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8
    && geometry.outputScale === '8', `true-8x E50 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => { const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? { renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      snowpackBodyVfx: canvas.dataset.snowpackBodyVfx,
      quartzMesostructureVfx: canvas.dataset.quartzMesostructureVfx,
      c4BodyVfx: canvas.dataset.c4BodyVfx } : undefined; })()`);
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && isolation.powderBodyVfx === 'inactive' && isolation.snowpackBodyVfx === 'inactive'
    && isolation.quartzMesostructureVfx === 'inactive' && isolation.c4BodyVfx === 'inactive',
  `true-8x E50 selector/resource isolation failed (${JSON.stringify(isolation)})`);
  // Deliberately do not prepare/upload E50's dense fixture at true 8x.
  const stateBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E50 GPU completion');
  const timing = await auditWebGLPresentationTiming(cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1);
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E50 did not complete GPU work (${JSON.stringify(timing)})`);
  const stateAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(stateBefore, stateAfter, 'true-8x E50 GPU completion');
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8' && geometry.backend.backend === 'webgl',
    selectorExcluded: true, resourcesIdentical: isolation.bloomBacking === null,
    semanticStable: true, isolation, timing };
}

// E49's accepted 1x/2x/4x SwiftShader matrix freezes a cohesive Quartz body:
// common cell-frequency grain falls to roughly 43--44%, while broad plate
// relief, native tmp2 contrast, exact support, and material/contact isolation
// remain intact. Keep enough headroom for compositor rounding without letting
// the branch collapse back to the bootstrap's merely non-inert proof.
const QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS = Object.freeze({
  minimumBaselineMicro: 12.0,
  minimumEnabledMicro: 5.5,
  maximumEnabledMicro: 10.0,
  minimumMicroRetention: 0.41,
  maximumMicroRetention: 0.47,
  minimumEnabledMacro: 10.0,
  maximumEnabledMacro: 34.0,
  minimumMacroRetention: 0.55,
  maximumMacroRetention: 1.30,
  minimumEnabledLumaStdDev: 6.2,
  maximumEnabledLumaStdDev: 11.0,
  maximumClippedFraction: 0,
});
const QUARTZ_MESOSTRUCTURE_VFX_RESPONSE_LIMITS = Object.freeze({
  minimumRgbRms: 9.0,
  maximumRgbRms: 15.0,
  maximumRgbPeak: 75,
  minimumCoverage: 0.70,
});
const QUARTZ_MESOSTRUCTURE_VFX_TARGET_ENVELOPES = Object.freeze({
  PQRTWholeBody: Object.freeze({
    rgbRms: [9.2, 13.5], chromaRms: [3.8, 6.7], rgbPeak: [40, 74],
    coverage: [0.70, 0.82], signedMean: [1.7, 3.3], spatialRgbRms: [8.8, 13.0],
  }),
  PQRTCrown: Object.freeze({
    rgbRms: [9.4, 14.4], chromaRms: [4.0, 7.3], rgbPeak: [34, 58],
    coverage: [0.84, 0.93], signedMean: [1.7, 5.6], spatialRgbRms: [9.0, 13.8],
  }),
  PQRTPocket: Object.freeze({
    rgbRms: [9.2, 13.3], chromaRms: [4.2, 7.3], rgbPeak: [28, 56],
    coverage: [0.85, 0.93], signedMean: [-0.9, 2.5], spatialRgbRms: [9.1, 13.3],
  }),
  PQRTCore: Object.freeze({
    rgbRms: [9.8, 14.4], chromaRms: [4.1, 7.2], rgbPeak: [37, 58],
    coverage: [0.85, 0.92], signedMean: [-0.35, 2.3], spatialRgbRms: [9.4, 14.4],
  }),
});
const QUARTZ_MESOSTRUCTURE_STATE_LIMITS = Object.freeze({
  maximumPeak: 40,
  minimumSignedMagnitude: 20,
  minimumSpanRetention: 0.97,
  maximumSpanRetention: 1.04,
});

// Raw RGBA remains exact for every control. These allowances name only the
// page-compositor/HDR footprint adjoining an eligible exact-PQRT body.
const QUARTZ_MESOSTRUCTURE_VFX_CONTROL_PEAK = Object.freeze({
  PQRTHole: 0,
  PQRTOpenChannel: 0,
  FineColumn: 0,
  FineLine: 0,
  Isolated: 0,
  Moving: 0,
  NativeWallOccupied: 0,
  NativeWallClear: 1,
  SuspendedQuartz: 0,
  SuspensionWater: 0,
  QuartzMetal: 0,
  Metal: 0,
  QuartzWater: 0,
  Water: 0,
  GuardedBlank: 0,
});

/** E49: exact native PQRT plate mesostructure over E05's settled Smooth proof. */
async function auditQuartzMesostructureVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      const variant = await navigateQuartzMesostructureVfxState(
        cdp, mode, scale, enabled, key,
      );
      variant.references = await capturePowderBodyVfxReferenceStyles(
        cdp, scale, key, 'E49',
      );
      captures[key] = variant;
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E49 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E49 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E49 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.powderBodyVfx === 'active'
        && variant.hdrPipeline.snowpackBodyVfx === 'inactive'
        && variant.hdrPipeline.quartzMesostructureVfx
          === (label === 'enabled' ? 'active' : 'inactive')
        && Object.values(variant.hdrPipeline.isolatedSelectors)
          .every((state) => state === 'inactive'),
      `E49 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(
        variant.hdrPipeline,
      )})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E49 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E49 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing)
        === JSON.stringify(disabledRepeat.geometry.backing),
    `E49 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic,
      `E49 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E49 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.materialPlane) === JSON.stringify(enabled.materialPlane)
      && JSON.stringify(disabled.materialPlane) === JSON.stringify(disabledRepeat.materialPlane)
      && disabled.materialPlane.occupied === fixture.expected.occupiedCells
      && disabled.materialPlane.materialCounts[fixture.target.material]
        === fixture.expected.quartzCells
      && disabled.materialPlane.materialCounts[2] === fixture.expected.waterCells
      && disabled.materialPlane.materialCounts[23] === fixture.expected.metalCells
      && Object.values(fixture.materialControls).every((entry) => (
        disabled.materialPlane.materialCounts[entry.material]
          === fixture.expected.cellsPerMaterialControl
      )),
    `E49 ${scale}x changed exact material-plane cardinalities (${JSON.stringify({
      materialPlane: disabled.materialPlane, expected: fixture.expected,
    })})`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E49 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E49 ${scale}x disabled/repeated`);
    for (const key of ['walls', 'velocity', 'auxiliary', 'suspension', 'state']) {
      assert(JSON.stringify(disabled[key]) === JSON.stringify(enabled[key])
        && JSON.stringify(disabled[key]) === JSON.stringify(disabledRepeat[key]),
      `E49 ${scale}x changed exact ${key} data (${JSON.stringify({
        disabled: disabled[key], enabled: enabled[key], repeated: disabledRepeat[key],
      })})`);
    }
    assert(disabled.walls.occupied === fixture.expected.wallCells
      && disabled.walls.expectedOccupied === fixture.expected.wallCells
      && disabled.walls.mismatches === 0 && disabled.walls.matterMismatches === 0
      && disabled.walls.stateMismatches === 0,
    `E49 ${scale}x lost native-wall coexistence (${JSON.stringify(disabled.walls)})`);
    assert(disabled.velocity.cells === fixture.expected.movingVelocityCells
      && disabled.velocity.expectedCells === fixture.expected.movingVelocityCells
      && disabled.velocity.mismatches === 0,
    `E49 ${scale}x lost authored PQRT motion (${JSON.stringify(disabled.velocity)})`);
    assert(Object.values(disabled.auxiliary.stable).every((range) => (
      range.min === 255 && range.max === 255
    )) && disabled.auxiliary.moving.min < 255 && disabled.auxiliary.moving.max < 255,
    `E49 ${scale}x lost settled-body or moving-region stability (${JSON.stringify(
      disabled.auxiliary,
    )})`);
    assert(disabled.state.invalidQuartzReservedBits === 0
      && disabled.state.quartzCounts.dark === fixture.expected.stateCounts.dark
      && disabled.state.quartzCounts.neutral === fixture.expected.stateCounts.neutral
      && disabled.state.quartzCounts.bright === fixture.expected.stateCounts.bright
      && disabled.state.qrtzControl.observed === fixture.expected.qrtzState,
    `E49 ${scale}x lost exact PQRT/QRTZ native state (${JSON.stringify(disabled.state)})`);
    const suspendedQuartz = disabled.suspension.find(({ name }) => name === 'SuspendedQuartz');
    const suspensionWater = disabled.suspension.find(({ name }) => name === 'SuspensionWater');
    assert(suspendedQuartz?.cell === fixture.target.material && suspendedQuartz.rgba[3] > 0
      && suspendedQuartz.liquidAlpha > 0 && suspensionWater?.cell === 2
      && suspensionWater.rgba[3] > 0 && suspensionWater.liquidAlpha > 0,
    `E49 ${scale}x did not establish genuine PQRT/Water suspension support (${JSON.stringify(
      disabled.suspension,
    )})`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E49 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E49 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E49 ${scale}x changed an exact raw topology/material/contact control (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls,
    })})`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E49 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = quartzMesostructureVfxTargetRegions(fixture);
    const controls = quartzMesostructureVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length).map((sample) => ({
      ...sample,
      spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2
        - (Math.hypot(...sample.responseRgb) / Math.sqrt(3)) ** 2)), 3),
    }));
    const controlResponses = responses.slice(targets.length);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E49 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    assert(targetResponses.every((sample) => [
      sample.rgbRms, sample.chromaRms, sample.rgbPeak, sample.coverage,
      sample.signedMean, sample.spatialRgbRms,
    ].every(Number.isFinite)
      && sample.rgbRms >= QUARTZ_MESOSTRUCTURE_VFX_RESPONSE_LIMITS.minimumRgbRms
      && sample.rgbRms <= QUARTZ_MESOSTRUCTURE_VFX_RESPONSE_LIMITS.maximumRgbRms
      && sample.rgbPeak <= QUARTZ_MESOSTRUCTURE_VFX_RESPONSE_LIMITS.maximumRgbPeak
      && sample.coverage >= QUARTZ_MESOSTRUCTURE_VFX_RESPONSE_LIMITS.minimumCoverage),
    `E49 ${scale}x PQRT response was absent or unbounded (${JSON.stringify(
      targetResponses,
    )})`);
    assert(targetResponses.every((sample) => {
      const envelope = QUARTZ_MESOSTRUCTURE_VFX_TARGET_ENVELOPES[sample.name];
      return envelope
        && sample.rgbRms >= envelope.rgbRms[0] && sample.rgbRms <= envelope.rgbRms[1]
        && sample.chromaRms >= envelope.chromaRms[0]
        && sample.chromaRms <= envelope.chromaRms[1]
        && sample.rgbPeak >= envelope.rgbPeak[0] && sample.rgbPeak <= envelope.rgbPeak[1]
        && sample.coverage >= envelope.coverage[0] && sample.coverage <= envelope.coverage[1]
        && sample.signedMean >= envelope.signedMean[0]
        && sample.signedMean <= envelope.signedMean[1]
        && sample.spatialRgbRms >= envelope.spatialRgbRms[0]
        && sample.spatialRgbRms <= envelope.spatialRgbRms[1];
    }),
    `E49 ${scale}x escaped the accepted Quartz target envelope (${JSON.stringify({
      envelopes: QUARTZ_MESOSTRUCTURE_VFX_TARGET_ENVELOPES, targetResponses,
    })})`);
    const targetByName = Object.fromEntries(
      targetResponses.map((sample) => [sample.name, sample]),
    );
    assert(targetByName.PQRTCrown?.signedMean
        > targetByName.PQRTPocket?.signedMean + 0.10
      && targetByName.PQRTWholeBody?.positiveMean >= 0.01
      && targetByName.PQRTWholeBody?.negativeMean >= 0.01
      && targetByName.PQRTCore?.responseSignature
        !== targetByName.PQRTCrown?.responseSignature
      && targetByName.PQRTCore?.responseSignature
        !== targetByName.PQRTPocket?.responseSignature,
    `E49 ${scale}x lost broad crystal-plate crown/pocket relief (${JSON.stringify(
      targetByName,
    )})`);
    assert(controlResponses.length === controls.length
      && controlResponses.every((sample) => sample.rgbPeak
        <= (QUARTZ_MESOSTRUCTURE_VFX_CONTROL_PEAK[sample.name] ?? 0)),
    `E49 ${scale}x escaped a named topology/material/contact control (${JSON.stringify(
      controlResponses,
    )})`);

    const textureRegions = quartzMesostructureVfxTextureRegions(fixture);
    const texture = {};
    for (const [name, variant] of Object.entries(captures)) {
      texture[name] = await samplePageRegions(
        cdp, variant.capture.capture.data, textureRegions,
        undefined, undefined, variant.capture.canvasRect,
      );
    }
    const textureResponse = texture.disabled.map((baseline, index) => {
      const current = texture.enabled[index];
      const repeated = texture.disabledRepeat[index];
      assert(current?.name === baseline.name && repeated?.name === baseline.name,
        `E49 ${scale}x reordered Quartz texture regions`);
      return {
        name: baseline.name,
        disabledMicro: baseline.microContrast,
        enabledMicro: current.microContrast,
        microRetention: round(current.microContrast / Math.max(0.001, baseline.microContrast), 4),
        disabledMacro: baseline.macroLumaRange,
        enabledMacro: current.macroLumaRange,
        macroRetention: round(current.macroLumaRange / Math.max(0.001, baseline.macroLumaRange), 4),
        enabledLumaStdDev: current.lumaStdDev,
        supportRecall: current.supportRecall,
        clippedFraction: current.clippedFraction,
        repeatExact: JSON.stringify(baseline) === JSON.stringify(repeated),
      };
    });
    assert(textureResponse.every((sample) => sample.disabledMicro
      >= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.minimumBaselineMicro
      && sample.enabledMicro >= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.minimumEnabledMicro
      && sample.enabledMicro <= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.maximumEnabledMicro
      && sample.microRetention
        >= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.minimumMicroRetention
      && sample.microRetention
        <= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.maximumMicroRetention
      && sample.enabledMacro >= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.minimumEnabledMacro
      && sample.enabledMacro <= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.maximumEnabledMacro
      && sample.macroRetention
        >= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.minimumMacroRetention
      && sample.macroRetention
        <= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.maximumMacroRetention
      && sample.enabledLumaStdDev
        >= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.minimumEnabledLumaStdDev
      && sample.enabledLumaStdDev
        <= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.maximumEnabledLumaStdDev
      && sample.supportRecall === 1
      && sample.clippedFraction
        <= QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS.maximumClippedFraction
      && sample.repeatExact),
    `E49 ${scale}x did not calm PQRT cell grain while retaining plate relief (${JSON.stringify({
      limits: QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS, textureResponse,
    })})`);

    const stateResponses = {};
    for (const label of ['disabled', 'enabled']) {
      const matrix = captures[label].stateMatrix;
      assert(matrix, `E49 ${scale}x ${label} native-state matrix is missing`);
      stateResponses[label] = await sampleBackdropRefractionRegions(cdp, {
        straight: matrix.disabled.capture.data,
        refracted: matrix.enabled.capture.data,
        repeatedStraight: matrix.disabledRepeat.capture.data,
      }, quartzMesostructureNativeStateRegions(fixture), matrix.disabled.canvasRect);
      assertQuartzMesostructureNativeStateResponses(
        stateResponses[label], `E49 ${scale}x ${label}`,
      );
    }
    const disabledStateByName = Object.fromEntries(
      stateResponses.disabled.map((sample) => [sample.name, sample]),
    );
    const enabledStateByName = Object.fromEntries(
      stateResponses.enabled.map((sample) => [sample.name, sample]),
    );
    const disabledSpan = disabledStateByName['PQRTState-bright'].signedMean
      - disabledStateByName['PQRTState-dark'].signedMean;
    const enabledSpan = enabledStateByName['PQRTState-bright'].signedMean
      - enabledStateByName['PQRTState-dark'].signedMean;
    const stateSpanRetention = enabledSpan / Math.max(0.001, disabledSpan);
    assert(stateSpanRetention >= QUARTZ_MESOSTRUCTURE_STATE_LIMITS.minimumSpanRetention
      && stateSpanRetention <= QUARTZ_MESOSTRUCTURE_STATE_LIMITS.maximumSpanRetention
      && Math.abs(enabledStateByName['QRTZState-bright'].signedMean
        - disabledStateByName['QRTZState-bright'].signedMean) <= 0.50,
    `E49 ${scale}x obscured native PQRT/QRTZ state separation (${JSON.stringify({
      disabledSpan, enabledSpan, stateSpanRetention,
      disabled: stateResponses.disabled, enabled: stateResponses.enabled,
    })})`);

    const references = {};
    const referenceRegions = quartzMesostructureVfxReferenceRegions(fixture);
    for (const style of ['grains', 'local']) {
      const samples = await sampleBackdropRefractionRegions(cdp, {
        straight: disabled.references[style].capture.data,
        refracted: enabled.references[style].capture.data,
        repeatedStraight: disabledRepeat.references[style].capture.data,
      }, referenceRegions, disabled.references[style].canvasRect);
      assert(samples.every((sample) => sample.rgbPeak === 0 && sample.repeatRgbPeak === 0),
        `E49 ${scale}x escaped the exact ${style} reference mode (${JSON.stringify(samples)})`);
      references[style] = samples;
    }

    // The E49 fixture proves body/state composition for native 0/5/10 PQRT and
    // bright QRTZ at every normal output scale. Do not stage the independent
    // five-state atlas here: preparing it restarts E05 boundary evolution, so a
    // generic identical-frame wait would measure legitimate powder settling
    // rather than native-state composition. The dedicated normal PQRT gate
    // retains 0/2/5/8/10 coverage, and E49's true-8x tail below exercises the
    // full compact five-state atlas after E49 has been selector-excluded.
    const nativeStateComposition = {
      pqrtStates: [0, fixture.target.neutralSpeckle, 10],
      qrtzState: fixture.expected.qrtzState,
      exactNeutralNoOp: true,
      exactRepeatedOff: true,
    };
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeQuartzMesostructureVfxScreenshots(
        screenshotRequest, scale, disabled, enabled,
      ) : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      materialPlane: disabled.materialPlane, walls: disabled.walls,
      velocity: disabled.velocity, auxiliary: disabled.auxiliary,
      suspension: disabled.suspension, state: disabled.state,
      rawControls: disabled.rawControls, targetResponses, controlResponses,
      textureResponse, stateResponses, stateSpanRetention, references,
      nativeStateComposition, exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E49 ${reference.scale}x/${sample.scale}x CSS geometry`);
      for (const key of ['semantic', 'materialPlane', 'walls', 'velocity', 'auxiliary',
        'suspension', 'state']) {
        assert(JSON.stringify(reference[key]) === JSON.stringify(sample[key]),
          `E49 ${sample.scale}x changed exact ${key} data across output scales`);
      }
      for (const baseline of reference.textureResponse) {
        const current = sample.textureResponse.find(({ name }) => name === baseline.name);
        assert(current && Math.abs(current.microRetention - baseline.microRetention) <= 0.03
          && Math.abs(current.macroRetention - baseline.macroRetention) <= 0.62,
        `E49 ${baseline.name} texture response drifted at ${sample.scale}x (${JSON.stringify({
          reference: baseline, current,
        })})`);
      }
      assert(Math.abs(sample.stateSpanRetention - reference.stateSpanRetention) <= 0.03,
        `E49 ${sample.scale}x native-state retention drifted (${JSON.stringify({
          reference: reference.stateSpanRetention, current: sample.stateSpanRetention,
        })})`);
    }
  }
  return {
    calibration: 'accepted-e49-1x-4x',
    textureLimits: QUARTZ_MESOSTRUCTURE_VFX_TEXTURE_LIMITS,
    responseLimits: QUARTZ_MESOSTRUCTURE_VFX_RESPONSE_LIMITS,
    targetEnvelopes: QUARTZ_MESOSTRUCTURE_VFX_TARGET_ENVELOPES,
    stateLimits: QUARTZ_MESOSTRUCTURE_STATE_LIMITS,
    controlPeakCaps: QUARTZ_MESOSTRUCTURE_VFX_CONTROL_PEAK,
    scales, trueEightXExcluded: true,
    trueEightX: await auditEightXQuartzMesostructureVfxExclusion(cdp, dpr),
  };
}

async function navigateQuartzMesostructureVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    quartzMesostructureVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '1', sootyPowderBodyVfx: '0',
    thermiteBodyVfx: '0', snowpackBodyVfx: '0',
    quartzMesostructureVfx: enabled ? '1' : '0', c4BodyVfx: '0', bglaBodyVfx: '0',
    powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', metalWaterContactVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    radioactiveSolidBodyVfx: '0', iszsCrystallineVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', botanicalMesostructureVfx: '0',
    botanicalPigmentVfx: '0', plantLaminaVfx: '0', plantLobeDepthVfx: '0',
    plantCanopyMassVfx: '0', woodBarkReliefVfx: '0', woodTanninVfx: '0',
    glassBodyVfx: '0', acidBodyVfx: '0', deutBodyVfx: '0', oilBodyVfx: '0',
    oilVolumeFinishVfx: '0', rockRoughnessVfx: '0', rockMesostructureVfx: '0',
    waterBodyVfx: '0', hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = ${JSON.stringify(QUARTZ_MESOSTRUCTURE_VFX_ISOLATED_SELECTORS)};
    return p.get('quartzMesostructureVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('powderBodyVfx') === '1'
      && p.get('quartzMesostructureVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareQuartzMesostructureVfxFixture === 'function'
      && typeof audit?.quartzMesostructureVfxFixture === 'function'
      && typeof audit?.setQuartzCrystalStateStyling === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E49 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E49 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareQuartzMesostructureVfxFixture();
    audit.setPowderRenderStyle('smooth');
    audit.setQuartzCrystalStateStyling(true);
    return audit.quartzMesostructureVfxFixture();
  })()`);
  for (let pass = 0; pass < 7; pass++) {
    const before = await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp, `(() => {
      const current = window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit();
      return current?.dynamicSequence > ${before.dynamicSequence} ? current : false;
    })()`), scale === 4 ? 15_000 : 5_000,
    `E49 ${label} ${scale}x stability pass ${pass + 1}`);
  }
  await waitFor(() => quartzMesostructureVfxFixtureReady(cdp, fixture), 20_000,
    `E49 ${label} ${scale}x fixture/stability hydration`);
  await sleep(350);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const isolated = ${JSON.stringify(QUARTZ_MESOSTRUCTURE_VFX_ISOLATED_SELECTORS)};
    return {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      snowpackBodyVfx: canvas.dataset.snowpackBodyVfx,
      quartzMesostructureVfx: canvas.dataset.quartzMesostructureVfx,
      isolatedSelectors: Object.fromEntries(isolated.map((name) => [name, canvas.dataset[name]])),
    };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.powderBodyVfx === 'active'
    && hdrPipeline.snowpackBodyVfx === 'inactive'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
    && hdrPipeline.quartzMesostructureVfx === (enabled ? 'active' : 'inactive'),
  `E49 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E49 ${label} ${scale}x framebuffer`,
    scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000,
  );
  let stateMatrix;
  if (label !== 'disabledRepeat') {
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.setQuartzCrystalStateStyling(false); true');
    const stateDisabled = await captureSettledPage(
      cdp, `E49 ${label} ${scale}x native-state disabled framebuffer`, 450,
    );
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.setQuartzCrystalStateStyling(true); true');
    const stateEnabled = await captureSettledPage(
      cdp, `E49 ${label} ${scale}x native-state enabled framebuffer`, 450,
    );
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.setQuartzCrystalStateStyling(false); true');
    const stateDisabledRepeat = await captureSettledPage(
      cdp, `E49 ${label} ${scale}x repeated native-state disabled framebuffer`, 450,
    );
    await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.setQuartzCrystalStateStyling(true); true');
    await waitForNextWebGLPresentation(
      cdp, `E49 ${label} ${scale}x native-state restore`,
      scale === 4 ? 20_000 : 10_000, scale === 4 ? 20_000 : 10_000,
    );
    stateMatrix = {
      disabled: stateDisabled, enabled: stateEnabled,
      disabledRepeat: stateDisabledRepeat,
    };
  }
  return {
    fixture, capture, stateMatrix, hdrPipeline,
    geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    materialPlane: await evaluate(cdp,
      'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()'),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    walls: await quartzMesostructureVfxWallDigest(cdp, fixture),
    velocity: await quartzMesostructureVfxVelocityDigest(cdp, fixture),
    auxiliary: await quartzMesostructureVfxAuxiliaryDigest(cdp, fixture),
    suspension: await quartzMesostructureVfxSuspensionDigest(cdp, fixture),
    state: await quartzMesostructureVfxStateDigest(cdp, fixture),
    rawAll: await sampleVolumeVfxRawWorldPixels(
      cdp, quartzMesostructureVfxAllRawPoints(fixture),
    ),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, quartzMesostructureVfxRawControlPoints(fixture),
    ),
  };
}

const QUARTZ_MESOSTRUCTURE_VFX_ISOLATED_SELECTORS = Object.freeze([
  ...SNOWPACK_BODY_VFX_ISOLATED_SELECTORS.filter(
    (name) => name !== 'quartzMesostructureVfx',
  ),
  'snowpackBodyVfx',
]);

async function quartzMesostructureVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = ${JSON.stringify(fixture)};
    if (fixture?.version !== 1 || fixture.world?.width !== audit.width
      || fixture.world?.height !== audit.height || fixture.target?.material !== 29
      || typeof audit?.presentationState !== 'function') return false;
    const inside = (rect, x, y) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const expectedTargetState = (x, y) => {
      for (const region of Object.values(fixture.target.stateRegions)) {
        if (inside(region, x, y)) return region.speckle;
      }
      return fixture.target.neutralSpeckle;
    };
    const exactRect = (rect, material, state) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material
            || (state !== undefined && audit.presentationState(x, y) !== state)) return false;
        }
      }
      return true;
    };
    const exactAuxiliary = (rect, predicate) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (!predicate(audit.presentationAuxiliary(x, y))) return false;
        }
      }
      return true;
    };
    const target = fixture.target;
    for (let y = target.body.y; y < target.body.y + target.body.height; y++) {
      for (let x = target.body.x; x < target.body.x + target.body.width; x++) {
        const empty = inside(target.authoredHole, x, y) || inside(target.openChannel, x, y);
        if (audit.cell(x, y) !== (empty ? 0 : target.material)
          || audit.presentationState(x, y) !== (empty ? 0 : expectedTargetState(x, y))) {
          return false;
        }
      }
    }
    if (![target.core, target.crown, target.pocket,
      ...Object.values(target.stateRegions)].every((rect) => (
      exactRect(rect, target.material, rect.speckle ?? target.neutralSpeckle)
        && exactAuxiliary(rect, (value) => value === 255)
    ))) return false;
    const wall = target.wallCoexistence;
    for (let y = wall.region.y; y < wall.region.y + wall.region.height; y++) {
      for (let x = wall.region.x; x < wall.region.x + wall.region.width; x++) {
        const blockX = Math.floor((x - wall.region.x) / wall.blockSize);
        const blockY = Math.floor((y - wall.region.y) / wall.blockSize);
        const expectedWall = (blockX + blockY) % 2 === wall.occupiedParity
          ? fixture.conductiveWall : 0;
        if (audit.cell(x, y) !== target.material
          || audit.presentationState(x, y) !== target.neutralSpeckle
          || audit.wall(x, y) !== expectedWall) return false;
      }
    }
    if (!exactRect(fixture.fineTopology.column, target.material, target.neutralSpeckle)
      || !exactRect(fixture.fineTopology.line, target.material, target.neutralSpeckle)
      || audit.cell(fixture.fineTopology.isolated.x, fixture.fineTopology.isolated.y)
        !== target.material
      || audit.presentationState(
        fixture.fineTopology.isolated.x, fixture.fineTopology.isolated.y,
      ) !== target.neutralSpeckle) return false;
    const moving = fixture.movingControl;
    if (!exactRect(moving, target.material, target.neutralSpeckle)
      || !exactAuxiliary(moving, (value) => value < 255)) return false;
    for (let y = moving.y; y < moving.y + moving.height; y++) {
      for (let x = moving.x; x < moving.x + moving.width; x++) {
        const velocity = audit.velocity(x, y);
        if (velocity[0] !== moving.velocityX || velocity[1] !== moving.velocityY) return false;
      }
    }
    const suspension = fixture.suspensionControl;
    if (suspension.quartzPoints.length !== fixture.expected.suspensionQuartzCells
      || suspension.region.width * suspension.region.height
        - suspension.quartzPoints.length !== fixture.expected.suspensionWaterCells) return false;
    const quartz = new Set(suspension.quartzPoints.map((point) => point.x + ',' + point.y));
    for (let y = suspension.region.y; y < suspension.region.y + suspension.region.height; y++) {
      for (let x = suspension.region.x; x < suspension.region.x + suspension.region.width; x++) {
        const suspendedQuartz = quartz.has(x + ',' + y);
        if (audit.cell(x, y) !== (suspendedQuartz ? target.material : 2)
          || audit.presentationState(x, y)
            !== (suspendedQuartz ? target.neutralSpeckle : 0)) return false;
      }
    }
    const boundary = (entry) => exactRect(
      entry.quartz, target.material, target.neutralSpeckle,
    ) && exactRect(entry.other, entry.otherMaterial, 0);
    const digest = audit.materialPlaneDigest();
    return Object.values(fixture.materialControls).every((entry) => (
      exactRect(entry, entry.material, entry.speckle)
    )) && Object.values(fixture.contacts).every(boundary)
      && audit.cell(suspension.quartzProbe.x, suspension.quartzProbe.y) === target.material
      && audit.presentationState(suspension.quartzProbe.x, suspension.quartzProbe.y)
        === target.neutralSpeckle
      && audit.cell(suspension.waterProbe.x, suspension.waterProbe.y) === 2
      && audit.presentationState(suspension.waterProbe.x, suspension.waterProbe.y) === 0
      && exactRect(fixture.guardedBlank, 0, 0)
      && digest.occupied === fixture.expected.occupiedCells
      && digest.materialCounts[target.material] === fixture.expected.quartzCells
      && digest.materialCounts[2] === fixture.expected.waterCells
      && digest.materialCounts[23] === fixture.expected.metalCells
      && Object.values(fixture.materialControls).every((entry) => (
        digest.materialCounts[entry.material] === fixture.expected.cellsPerMaterialControl
      ))
      && JSON.stringify(fixture.powderStyleMatrix) === JSON.stringify([
        { style: 'smooth', expectation: 'target' },
        { style: 'local', expectation: 'exact-no-op' },
        { style: 'grains', expectation: 'exact-no-op' },
      ]);
  })()`);
}

async function quartzMesostructureVfxWallDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const pattern = fixture.target.wallCoexistence;
    let occupied = 0; let expectedOccupied = 0; let mismatches = 0;
    let matterMismatches = 0; let stateMismatches = 0;
    for (let y = pattern.region.y; y < pattern.region.y + pattern.region.height; y++) {
      for (let x = pattern.region.x; x < pattern.region.x + pattern.region.width; x++) {
        const blockX = Math.floor((x - pattern.region.x) / pattern.blockSize);
        const blockY = Math.floor((y - pattern.region.y) / pattern.blockSize);
        const expected = (blockX + blockY) % 2 === pattern.occupiedParity
          ? fixture.conductiveWall : 0;
        occupied += Number(audit.wall(x, y) === fixture.conductiveWall);
        expectedOccupied += Number(expected === fixture.conductiveWall);
        mismatches += Number(audit.wall(x, y) !== expected);
        matterMismatches += Number(audit.cell(x, y) !== fixture.target.material);
        stateMismatches += Number(
          audit.presentationState(x, y) !== fixture.target.neutralSpeckle,
        );
      }
    }
    return { occupied, expectedOccupied, mismatches, matterMismatches, stateMismatches,
      wallProbe: audit.wall(pattern.wallProbe.x, pattern.wallProbe.y),
      clearProbe: audit.wall(pattern.clearProbe.x, pattern.clearProbe.y) };
  })()`);
}

async function quartzMesostructureVfxVelocityDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const rect = ${JSON.stringify(fixture.movingControl)};
    let cells = 0; let mismatches = 0; let minimumX = 127; let maximumX = -128;
    let minimumY = 127; let maximumY = -128;
    for (let y = rect.y; y < rect.y + rect.height; y++) {
      for (let x = rect.x; x < rect.x + rect.width; x++) {
        const velocity = audit.velocity(x, y); cells++;
        minimumX = Math.min(minimumX, velocity[0]); maximumX = Math.max(maximumX, velocity[0]);
        minimumY = Math.min(minimumY, velocity[1]); maximumY = Math.max(maximumY, velocity[1]);
        mismatches += Number(velocity[0] !== rect.velocityX || velocity[1] !== rect.velocityY);
      }
    }
    return { cells, expectedCells: rect.width * rect.height, mismatches,
      range: [minimumX, maximumX, minimumY, maximumY] };
  })()`);
}

async function quartzMesostructureVfxAuxiliaryDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const range = (rect) => {
      let min = 255; let max = 0;
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          const value = audit.presentationAuxiliary(x, y);
          min = Math.min(min, value); max = Math.max(max, value);
        }
      }
      return { min, max };
    };
    return {
      stable: {
        core: range(fixture.target.core), crown: range(fixture.target.crown),
        pocket: range(fixture.target.pocket),
        dark: range(fixture.target.stateRegions.dark),
        neutral: range(fixture.target.stateRegions.neutral),
        bright: range(fixture.target.stateRegions.bright),
      },
      moving: range(fixture.movingControl),
    };
  })()`);
}

async function quartzMesostructureVfxSuspensionDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    const counts = { quartz: 0, water: 0, other: 0 };
    for (let y = fixture.suspensionControl.region.y;
      y < fixture.suspensionControl.region.y + fixture.suspensionControl.region.height; y++) {
      for (let x = fixture.suspensionControl.region.x;
        x < fixture.suspensionControl.region.x + fixture.suspensionControl.region.width; x++) {
        const material = audit.cell(x, y);
        if (material === fixture.target.material) counts.quartz++;
        else if (material === 2) counts.water++;
        else counts.other++;
      }
    }
    return [
      { name: 'SuspendedQuartz', material: fixture.target.material,
        point: fixture.suspensionControl.quartzProbe, observedCells: counts.quartz },
      { name: 'SuspensionWater', material: 2,
        point: fixture.suspensionControl.waterProbe, observedCells: counts.water },
    ].map((entry) => ({ name: entry.name, material: entry.material,
      observedCells: entry.observedCells, otherCells: counts.other,
      cell: audit.cell(entry.point.x, entry.point.y),
      state: audit.presentationState(entry.point.x, entry.point.y),
      rgba: audit.suspensionAt(entry.point.x, entry.point.y),
      liquidAlpha: audit.liquidFieldAlpha(entry.point.x, entry.point.y) }));
  })()`);
}

async function quartzMesostructureVfxStateDigest(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const fixture = ${JSON.stringify(fixture)};
    let semantic = 2166136261; let rendered = 2166136261; let auxiliary = 2166136261;
    let walls = 2166136261; let state = 2166136261; let velocity = 2166136261;
    let invalidQuartzReservedBits = 0;
    const quartzCounts = { dark: 0, neutral: 0, bright: 0, other: 0 };
    const mix = (seed, value) => Math.imul(seed ^ (value >>> 0), 16777619) >>> 0;
    for (let y = 0; y < audit.height; y++) {
      for (let x = 0; x < audit.width; x++) {
        const material = audit.cell(x, y);
        const presentationState = audit.presentationState(x, y) >>> 0;
        const stagedVelocity = audit.velocity(x, y);
        semantic = mix(semantic, material);
        rendered = mix(rendered, audit.renderedCell(x, y));
        walls = mix(walls, audit.wall(x, y));
        state = mix(state, presentationState);
        velocity = mix(velocity,
          (stagedVelocity[0] & 255) | ((stagedVelocity[1] & 255) << 8));
        if (material === fixture.target.material || material === 76) {
          auxiliary = mix(auxiliary, audit.presentationAuxiliary(x, y));
          invalidQuartzReservedBits += Number((presentationState & 0xfff0) !== 0);
        }
        if (material === fixture.target.material) {
          if (presentationState === 0) quartzCounts.dark++;
          else if (presentationState === fixture.target.neutralSpeckle) quartzCounts.neutral++;
          else if (presentationState === 10) quartzCounts.bright++;
          else quartzCounts.other++;
        }
      }
    }
    const centre = (rect) => ({
      x: rect.x + Math.floor(rect.width / 2),
      y: rect.y + Math.floor(rect.height / 2),
    });
    const qrtzProbe = centre(fixture.materialControls.qrtz);
    return {
      semantic, rendered, auxiliary, walls, state, velocity,
      invalidQuartzReservedBits, quartzCounts,
      targetStates: Object.entries(fixture.target.stateRegions).map(([name, rect]) => {
        const probe = centre(rect);
        return { name, expected: rect.speckle,
          observed: audit.presentationState(probe.x, probe.y) };
      }),
      qrtzControl: { expected: fixture.expected.qrtzState,
        observed: audit.presentationState(qrtzProbe.x, qrtzProbe.y) },
    };
  })()`);
}

function quartzMesostructureVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  return [
    rect('PQRTWholeBody', fixture.target.body),
    rect('PQRTCrown', fixture.target.crown),
    rect('PQRTPocket', fixture.target.pocket),
    rect('PQRTCore', fixture.target.core),
  ];
}

function quartzMesostructureVfxTextureRegions(fixture) {
  return quartzMesostructureVfxTargetRegions(fixture)
    .filter(({ name }) => name !== 'PQRTWholeBody')
    .map((region) => ({ ...region,
      support: { kind: 'semantic', materials: [fixture.target.material] } }));
}

function quartzMesostructureVfxReferenceRegions(fixture) {
  return quartzMesostructureVfxTargetRegions(fixture)
    .map(({ target: _target, ...region }) => region);
}

function quartzMesostructureVfxControlRegions(fixture) {
  const point = (name, candidate) => ({
    name, x: Math.floor(candidate.x) + 0.5, y: Math.floor(candidate.y) + 0.5, radius: 0,
  });
  const center = (name, rect) => point(name, {
    x: rect.x + Math.floor(rect.width / 2),
    y: rect.y + Math.floor(rect.height / 2),
  });
  const controls = [
    center('PQRTHole', fixture.target.authoredHole),
    center('PQRTOpenChannel', fixture.target.openChannel),
    center('FineColumn', fixture.fineTopology.column),
    center('FineLine', fixture.fineTopology.line),
    point('Isolated', fixture.fineTopology.isolated),
    center('Moving', fixture.movingControl),
    point('NativeWallOccupied', fixture.target.wallCoexistence.wallProbe),
    point('NativeWallClear', fixture.target.wallCoexistence.clearProbe),
  ];
  for (const [name, rect] of Object.entries(fixture.materialControls)) {
    controls.push(center(`Material${name[0].toUpperCase()}${name.slice(1)}`, rect));
  }
  controls.push(
    point('SuspendedQuartz', fixture.suspensionControl.quartzProbe),
    point('SuspensionWater', fixture.suspensionControl.waterProbe),
    point('QuartzMetal', fixture.contacts.metal.quartzProbe),
    point('Metal', fixture.contacts.metal.otherProbe),
    point('QuartzWater', fixture.contacts.water.quartzProbe),
    point('Water', fixture.contacts.water.otherProbe),
    center('GuardedBlank', fixture.guardedBlank),
  );
  return controls;
}

function quartzMesostructureVfxAllRawPoints(fixture) {
  return [
    ...quartzMesostructureVfxTargetRegions(fixture).map(({ name, x, y }) => ({
      name, x: Math.floor(x), y: Math.floor(y),
    })),
    ...quartzMesostructureVfxRawControlPoints(fixture),
  ];
}

function quartzMesostructureVfxRawControlPoints(fixture) {
  return quartzMesostructureVfxControlRegions(fixture).map(({ name, x, y }) => ({
    name, x: Math.floor(x), y: Math.floor(y),
  }));
}

function quartzMesostructureNativeStateRegions(fixture) {
  const rect = (name, candidate, inset = 3) => ({
    name,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - inset),
    radiusY: Math.max(0.35, candidate.height / 2 - inset),
  });
  return [
    rect('PQRTState-dark', fixture.target.stateRegions.dark),
    rect('PQRTState-neutral', fixture.target.stateRegions.neutral),
    rect('PQRTState-bright', fixture.target.stateRegions.bright),
    rect('QRTZState-bright', fixture.materialControls.qrtz, 6),
  ];
}

function assertQuartzMesostructureNativeStateResponses(samples, label) {
  const byName = Object.fromEntries(samples.map((sample) => [sample.name, sample]));
  const dark = byName['PQRTState-dark'];
  const neutral = byName['PQRTState-neutral'];
  const bright = byName['PQRTState-bright'];
  const qrtz = byName['QRTZState-bright'];
  assert(samples.length === 4 && neutral && neutral.rgbPeak <= 1
    && neutral.repeatRgbPeak <= 1,
  `${label}: neutral native Quartz state was not an exact no-op (${JSON.stringify(samples)})`);
  assert(dark && bright && qrtz
    && dark.signedMean < -QUARTZ_MESOSTRUCTURE_STATE_LIMITS.minimumSignedMagnitude
    && bright.signedMean > QUARTZ_MESOSTRUCTURE_STATE_LIMITS.minimumSignedMagnitude
    && qrtz.signedMean > QUARTZ_MESOSTRUCTURE_STATE_LIMITS.minimumSignedMagnitude
    && [dark, bright, qrtz].every(({ rgbPeak, repeatRgbPeak }) => (
      rgbPeak > 0 && rgbPeak <= QUARTZ_MESOSTRUCTURE_STATE_LIMITS.maximumPeak
        && repeatRgbPeak <= 1
    )),
  `${label}: native PQRT/QRTZ signed state response was absent, unbounded, or unstable (${JSON.stringify(
    samples,
  )})`);
}

async function writeQuartzMesostructureVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e49-quartz-mesostructure-${scale}x-off`),
    on: variantScreenshotPath(source, `e49-quartz-mesostructure-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXQuartzMesostructureVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-quartz-mesostructure', quartzMesostructureVfxAudit: '1',
    renderLook: 'realistic', volumeVfx: '0', liquidBodyVfx: '0',
    liquidSurfaceVfx: '0', gasBodyVfx: '0', gasMotionVfx: '0',
    powderBodyVfx: '1', sootyPowderBodyVfx: '0', thermiteBodyVfx: '0',
    snowpackBodyVfx: '0', quartzMesostructureVfx: '1', c4BodyVfx: '0', bglaBodyVfx: '0',
    powderLightVfx: '0',
    powderSolidContactVfx: '0', translucentEdgeVfx: '0', organicSubsurfaceVfx: '0',
    wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0',
    metalWaterContactVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0',
    nobleGasPrismVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0', radioactiveSolidBodyVfx: '0',
    iszsCrystallineVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0',
    botanicalBodyVfx: '0', botanicalMesostructureVfx: '0', botanicalPigmentVfx: '0',
    plantLaminaVfx: '0', plantLobeDepthVfx: '0', plantCanopyMassVfx: '0',
    woodBarkReliefVfx: '0', woodTanninVfx: '0', glassBodyVfx: '0',
    acidBodyVfx: '0', deutBodyVfx: '0', oilBodyVfx: '0', oilVolumeFinishVfx: '0',
    rockRoughnessVfx: '0', rockMesostructureVfx: '0', waterBodyVfx: '0',
    hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return p.get('renderScale') === '8'
      && p.get('auditStage') === 'eight-quartz-mesostructure'
      && p.get('powderBodyVfx') === '1' && p.get('quartzMesostructureVfx') === '1'
      && p.get('snowpackBodyVfx') === '0'
      && p.get('c4BodyVfx') === '0'
      && typeof audit?.preparePqrtStateGraphicsFixture === 'function'
      && typeof audit?.pqrtStateGraphicsAtlas === 'function'
      && typeof audit?.setQuartzCrystalStateStyling === 'function';
  })()`), remainingDeadlineMs(deadline, 'true-8x E49 input audit API'),
  'true-8x E49 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E49', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E49');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E49 geometry')),
    'true-8x E49 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E49 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const readIsolation = (budgetDeadline = deadline) => evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    const isolated = ${JSON.stringify(QUARTZ_MESOSTRUCTURE_VFX_ISOLATED_SELECTORS)};
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      snowpackBodyVfx: canvas.dataset.snowpackBodyVfx,
      quartzMesostructureVfx: canvas.dataset.quartzMesostructureVfx,
      isolatedSelectors: Object.fromEntries(isolated.map((name) => [name, canvas.dataset[name]])),
    } : undefined;
  })()`, Math.min(
    1_000, remainingDeadlineMs(budgetDeadline, 'true-8x E49 isolation'),
  ));
  const isolation = await readIsolation();
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.powderBodyVfx === 'inactive'
    && isolation.snowpackBodyVfx === 'inactive'
    && isolation.quartzMesostructureVfx === 'inactive'
    && Object.values(isolation.isolatedSelectors).every((state) => state === 'inactive'),
  `true-8x E49 selector/resource isolation failed (${JSON.stringify(isolation)})`);

  // Promotion owns one total 30-second deadline. Prove that first compact
  // frame before staging the independent, multi-frame PQRT state atlas below;
  // charging all later state toggles to the startup deadline would turn valid
  // sequential 8x frames into a false promotion timeout.
  const promotionStateBefore = await hdrVfxSemanticDigest(cdp);
  const promotionTimingBudget = remainingDeadlineMs(
    deadline, 'true-8x E49 promotion GPU completion',
  );
  const promotionTiming = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, promotionTimingBudget), promotionTimingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(promotionTiming.source),
    `true-8x E49 promotion did not complete GPU work (${JSON.stringify(promotionTiming)})`);
  const promotionStateAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(
    promotionStateBefore, promotionStateAfter, 'true-8x E49 promotion GPU completion',
  );

  // E49 owns no compact path. The established compact PQRT/QRTZ state atlas
  // must nevertheless remain fully active while the requested E49 selector is fenced off.
  const pqrtStateGraphics = await auditEightXPqrtStateGraphics(cdp, geometry.canvas);
  assert(pqrtStateGraphics?.exactRepeatedOff
    && pqrtStateGraphics.cards.map(({ stateKey }) => stateKey).join(',')
      === 'dark,low,neutral,high,bright',
  `true-8x E49 lost compact PQRT state graphics (${JSON.stringify(pqrtStateGraphics)})`);
  const isolationAfterState = await readIsolation(
    Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS,
  );
  assert(isolationAfterState.quartzMesostructureVfx === 'inactive'
    && isolationAfterState.state === 'inactive'
    && isolationAfterState.reason === 'scale-8'
    && isolationAfterState.bloomBacking === null
    && Object.values(isolationAfterState.isolatedSelectors).every((state) => state === 'inactive'),
  `true-8x E49 selector/resource state changed after compact PQRT proof (${JSON.stringify(
    isolationAfterState,
  )})`);
  const stateBefore = await snapshotEightXPqrtState(cdp);
  assertEightXPqrtTopology(stateBefore, 'true-8x E49 pre-fence PQRT fixture');
  // The atlas deliberately submits several later frames. Its final queued
  // presentation receives its own one-frame fence deadline after the already
  // proven startup promotion, matching the presenter's post-promotion contract.
  const stateDeadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  const timingBudget = remainingDeadlineMs(stateDeadline, 'true-8x E49 state GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E49 did not complete GPU work (${JSON.stringify(timing)})`);
  const stateAfter = await snapshotEightXPqrtState(cdp);
  assertEightXPqrtTopology(stateAfter, 'true-8x E49 post-fence PQRT fixture');
  assert(JSON.stringify(stateBefore) === JSON.stringify(stateAfter),
    'true-8x E49 GPU completion changed compact PQRT semantic/state topology');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8'
      && geometry.backend.backend === 'webgl',
    selectorExcluded: true, resourcesIdentical: isolation.bloomBacking === null,
    isolation, isolationAfterState, pqrtStateGraphics,
    semanticStable: true, promotionFence: 'signaled', promotionTiming,
    stateFence: 'signaled', timing,
  };
}

// E25's accepted SwiftShader matrix freezes the body response without making
// the bounds sensitive to sub-byte browser composition. Exact raw controls
// remain byte-identical; only named neighbours of an eligible Noble Gas body
// may carry a small HDR-filter footprint in the composed page screenshot.
const NOBLE_GAS_BILLOW_VFX_LOCAL_CONTROL_PEAK = Object.freeze({
  NOBLAuthoredVoid: 1,
  NOBLOpenChannel: 1,
  GasSeamNoble: 1,
});
const NOBLE_GAS_BILLOW_VFX_ACCEPTANCE = Object.freeze({
  NOBLDeepCore: Object.freeze({
    rgbRms: [2.30, 2.60], chromaRms: [0.55, 0.80], rgbPeak: [4, 4],
    coverage: [0.82, 0.92], signedMean: [2.35, 2.75],
  }),
  NOBLCrown: Object.freeze({
    rgbRms: [2.85, 3.15], chromaRms: [0.65, 0.90], rgbPeak: [4, 4],
    coverage: [0.98, 1.00], signedMean: [3.10, 3.45],
  }),
  NOBLPocket: Object.freeze({
    rgbRms: [0.70, 0.95], chromaRms: [0.35, 0.55], rgbPeak: [1, 1],
    coverage: [0.00, 0.00], signedMean: [-0.90, -0.60],
  }),
});

/** E25: exact style-7 billow recomposition over E04's connected gas body. */
async function auditNobleGasBillowVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateNobleGasBillowVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E25 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E25 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E25 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.nobleGasBillowVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E25 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E25 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E25 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E25 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E25 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E25 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E25 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E25 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E25 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E25 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E25 ${scale}x changed an exact raw control (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls,
      disabledRepeat: disabledRepeat.rawControls,
    })})`);
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E25 ${scale}x changed E04 atmosphere ownership/density (${JSON.stringify(disabled.field)})`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E25 ${scale}x changed native-wall topology (${JSON.stringify(disabled.walls)})`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E25 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = nobleGasBillowVfxTargetRegions(fixture);
    const controls = nobleGasBillowVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const targetByName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(targetResponses.length === 3 && targetResponses.every((sample) => {
      const bounds = NOBLE_GAS_BILLOW_VFX_ACCEPTANCE[sample.name];
      return bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1]
        && sample.meanBiasRatio >= 0.85 && sample.repeatRgbPeak === 0
        && Math.abs(sample.responseRgb[1]) >= Math.abs(sample.responseRgb[0]) + 0.15;
    }), `E25 ${scale}x escaped its frozen Noble Gas body response (${JSON.stringify(targetResponses)})`);
    assert(targetByName.NOBLDeepCore?.signedMean > 0
      && targetByName.NOBLCrown?.signedMean > 0
      && targetByName.NOBLPocket?.signedMean < 0,
    `E25 ${scale}x lost its crown/pocket polarity (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (NOBLE_GAS_BILLOW_VFX_LOCAL_CONTROL_PEAK[sample.name] ?? 0)),
    `E25 ${scale}x escaped an exact sibling/topology/contact/wall control (${JSON.stringify(controlResponses)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E25 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeNobleGasBillowVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      field: disabled.field, walls: disabled.walls, rawControls: disabled.rawControls,
      targetResponses, controlResponses, exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E25 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(sample.field)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls),
      `E25 ${sample.scale}x changed the exact fixture/field contract across output scales`);
    }
    const spread = (values) => Math.max(...values) - Math.min(...values);
    for (const name of ['NOBLDeepCore', 'NOBLCrown', 'NOBLPocket']) {
      const samples = scales.map((entry) => (
        entry.targetResponses.find((sample) => sample.name === name)
      ));
      assert(samples.every(Boolean)
        && spread(samples.map((sample) => sample.rgbRms)) <= 1.0
        && spread(samples.map((sample) => sample.chromaRms)) <= 0.6
        && spread(samples.map((sample) => sample.signedMean)) <= 1.0
        && spread(samples.map((sample) => sample.coverage)) <= 0.15
        && spread(samples.map((sample) => sample.rgbPeak)) <= 4,
      `E25 ${name} visual response drifted across output scales (${JSON.stringify(samples)})`);
    }
  }
  const trueEightX = await auditEightXNobleGasBillowVfxExclusion(cdp, dpr);
  return {
    calibration: 'accepted-matrix', scales, trueEightXExcluded: true, trueEightX,
  };
}

async function navigateNobleGasBillowVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    nobleGasBillowVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0',
    gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: enabled ? '1' : '0', nobleGasPrismVfx: '0', nobleGasCoreReliefVfx: '0', smokeBillowDepthVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0',
    glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = [
      'volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasMotionVfx',
      'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx',
      'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx',
      'gasLightVfx', 'liquidSolidMeniscusVfx', 'gasCoreDepthVfx', 'nobleGasCoreReliefVfx', 'smokeBillowDepthVfx',
      'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
      'botanicalBodyVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
      'waterBodyVfx',
    ];
    return p.get('nobleGasBillowVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('gasBodyVfx') === '1'
      && p.get('nobleGasBillowVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && p.get('nobleGasPrismVfx') === '0'
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareNobleGasBillowVfxFixture === 'function'
      && typeof audit?.nobleGasBillowVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E25 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E25 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareNobleGasBillowVfxFixture();
    return audit.nobleGasBillowVfxFixture();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E25 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => nobleGasBillowVfxFixtureReady(cdp, fixture),
    20_000, `E25 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const isolatedSelectors = {
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx,
      gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx,
      wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx,
      solidBodyVfx: canvas.dataset.solidBodyVfx,
      platinumBodyVfx: canvas.dataset.platinumBodyVfx,
      ceramicGlazeVfx: canvas.dataset.ceramicGlazeVfx,
      botanicalBodyVfx: canvas.dataset.botanicalBodyVfx,
      glassBodyVfx: canvas.dataset.glassBodyVfx,
      oilBodyVfx: canvas.dataset.oilBodyVfx,
      rockRoughnessVfx: canvas.dataset.rockRoughnessVfx,
      waterBodyVfx: canvas.dataset.waterBodyVfx,
    };
    return {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      nobleGasPrismVfx: canvas.dataset.nobleGasPrismVfx,
      nobleGasCoreReliefVfx: canvas.dataset.nobleGasCoreReliefVfx,
      isolatedSelectors,
    };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.gasBodyVfx === 'active'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
    && hdrPipeline.nobleGasBillowVfx === (enabled ? 'active' : 'inactive')
    && hdrPipeline.nobleGasPrismVfx === 'inactive'
    && hdrPipeline.nobleGasCoreReliefVfx === 'inactive',
  `E25 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E25 ${label} ${scale}x framebuffer`,
    scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await nobleGasBillowVfxFieldDigest(cdp, fixture),
    walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, nobleGasBillowVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, nobleGasBillowVfxRawControlPoints(fixture),
    ),
    hdrPipeline,
  };
}

async function nobleGasBillowVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = ${JSON.stringify(fixture)};
    if (fixture.version !== 1 || fixture.world.width !== audit.width
      || fixture.world.height !== audit.height
      || typeof audit?.gasIdentityStyle !== 'function'
      || typeof audit?.atmosphereFieldAlpha !== 'function') return false;
    const inside = (rect, x, y) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const centre = (rect) => ({
      x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2),
    });
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    const target = fixture.target;
    const radiusX = target.body.width * 0.5;
    const radiusY = target.body.height * 0.5;
    const centreX = target.body.x + radiusX;
    const centreY = target.body.y + radiusY;
    for (let y = target.body.y; y < target.body.y + target.body.height; y++) {
      for (let x = target.body.x; x < target.body.x + target.body.width; x++) {
        const normalizedX = Math.abs((x + 0.5 - centreX) / radiusX);
        const normalizedY = Math.abs((y + 0.5 - centreY) / radiusY);
        const empty = normalizedX ** 4 + normalizedY ** 4 > 1
          || inside(target.authoredVoid, x, y) || inside(target.openChannel, x, y);
        if (audit.cell(x, y) !== (empty ? 0 : target.material)) return false;
      }
    }
    if (!exactRect(target.deepCore, target.material)
      || !exactRect(target.authoredVoid, 0) || !exactRect(target.openChannel, 0)
      || !target.billowProbes.every((probe) => exactRect(probe.region, target.material))) return false;
    const deepPoint = centre(target.deepCore);
    if (audit.gasIdentityStyle(deepPoint.x, deepPoint.y) !== 7
      || audit.atmosphereFieldAlpha(deepPoint.x, deepPoint.y) !== 255) return false;
    for (const probe of target.billowProbes) {
      const alpha = audit.atmosphereFieldAlpha(probe.centre.x, probe.centre.y);
      if (audit.gasIdentityStyle(probe.centre.x, probe.centre.y) !== 7
        || alpha !== 255) return false;
    }
    const expectedStyles = [1, 4, 5, 10, 12];
    if (!fixture.protectedGases.every((control, index) => exactRect(control.body, control.material)
      && audit.gasIdentityStyle(control.probe.x, control.probe.y) === expectedStyles[index])) return false;
    if (!fixture.sparse.carriers.every((point) => audit.cell(point.x, point.y) === fixture.sparse.material)
      || audit.cell(fixture.sparse.midpoint.x, fixture.sparse.midpoint.y) !== 0
      || audit.cell(fixture.sparse.gap.x, fixture.sparse.gap.y) !== 0
      || audit.cell(fixture.sparse.isolated.x, fixture.sparse.isolated.y) !== fixture.sparse.material) return false;
    return target.billowProbes[0].billow > 0 && target.billowProbes[1].billow < 0
      && exactRect(fixture.gasSeam.gas, target.material)
      && exactRect(fixture.gasSeam.foreignGas, fixture.gasSeam.foreignMaterial)
      && audit.gasIdentityStyle(fixture.gasSeam.gasProbe.x, fixture.gasSeam.gasProbe.y) === 7
      && audit.gasIdentityStyle(fixture.gasSeam.foreignProbe.x, fixture.gasSeam.foreignProbe.y) === 10
      && exactRect(fixture.waterContact.gas, target.material)
      && exactRect(fixture.waterContact.water, 2)
      && exactRect(fixture.metalContact.gas, target.material)
      && exactRect(fixture.metalContact.metal, 23)
      && exactRect(fixture.nativeWall.gas, target.material)
      && audit.wall(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.conductiveWall
      && audit.gasIdentityStyle(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) !== 7
      && exactRect(fixture.guardedBlank, 0)
      && audit.gasIdentityStyle(centre(fixture.guardedBlank).x, centre(fixture.guardedBlank).y) !== 7;
  })()`);
}

function nobleGasBillowVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  return [
    rect('NOBLDeepCore', fixture.target.deepCore),
    ...fixture.target.billowProbes.map((probe) => (
      rect(`NOBL${probe.code === 'CROWN' ? 'Crown' : 'Pocket'}`, probe.region)
    )),
  ];
}

function nobleGasBillowVfxControlRegions(fixture) {
  const point = (name, candidate) => ({
    name, x: Math.floor(candidate.x) + 0.5, y: Math.floor(candidate.y) + 0.5, radius: 0,
  });
  const rect = (name, candidate, inset = 0) => ({
    name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - inset - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - inset - 0.2),
  });
  return [
    rect('NOBLAuthoredVoid', fixture.target.authoredVoid, 4),
    rect('NOBLOpenChannel', fixture.target.openChannel, 4),
    ...fixture.protectedGases.map((control) => point(`Protected${control.code}`, control.probe)),
    ...fixture.sparse.carriers.map((carrier, index) => (
      point(`SparseCarrier${index + 1}`, carrier)
    )),
    point('SparseMidpoint', fixture.sparse.midpoint),
    point('SparseGap', fixture.sparse.gap),
    point('SparseIsolated', fixture.sparse.isolated),
    point('GasSeamNoble', fixture.gasSeam.gasProbe),
    point('GasSeamFOG', fixture.gasSeam.foreignProbe),
    point('WaterContactNoble', fixture.waterContact.gasProbe),
    point('WaterContactWater', fixture.waterContact.waterProbe),
    point('MetalContactNoble', fixture.metalContact.gasProbe),
    point('MetalContactMetal', fixture.metalContact.metalProbe),
    point('NativeWall', fixture.nativeWall.wallAnchor),
    rect('GuardedBlank', fixture.guardedBlank, 4),
  ];
}

function nobleGasBillowVfxAllRawPoints(fixture) {
  return [
    ...nobleGasBillowVfxTargetRegions(fixture).map((region) => ({
      name: region.name, x: Math.floor(region.x), y: Math.floor(region.y),
    })),
    ...nobleGasBillowVfxRawControlPoints(fixture),
    { name: 'GasSeamNoble', ...fixture.gasSeam.gasProbe },
  ];
}

function nobleGasBillowVfxRawControlPoints(fixture) {
  return nobleGasBillowVfxControlRegions(fixture)
    // E25 may grade the exact Noble-side categorical seam owner. It remains
    // covered by raw alpha/support and the bounded composed seam response;
    // only the foreign FOG owner is an exact seam-RGB control.
    .filter((region) => region.name !== 'GasSeamNoble')
    .map((region) => ({
      name: region.name, x: Math.floor(region.x), y: Math.floor(region.y),
    }));
}

async function nobleGasBillowVfxFieldDigest(cdp, fixture) {
  const points = [
    { name: 'NOBLDeepCore', ...fixture.target.deepCore, centre: true },
    ...fixture.target.billowProbes.map((probe) => ({
      name: `NOBL${probe.code}`, ...probe.centre,
    })),
    ...fixture.protectedGases.map((control) => ({ name: control.code, ...control.probe })),
    { name: 'AuthoredVoid', ...fixture.target.authoredVoid, centre: true },
    { name: 'OpenChannel', ...fixture.target.openChannel, centre: true },
    ...fixture.sparse.carriers.map((point, index) => ({
      name: `SparseCarrier${index + 1}`, ...point,
    })),
    { name: 'SparseMidpoint', ...fixture.sparse.midpoint },
    { name: 'SparseGap', ...fixture.sparse.gap },
    { name: 'SparseIsolated', ...fixture.sparse.isolated },
    { name: 'GasSeamNoble', ...fixture.gasSeam.gasProbe },
    { name: 'GasSeamFOG', ...fixture.gasSeam.foreignProbe },
    { name: 'WaterContactNoble', ...fixture.waterContact.gasProbe },
    { name: 'WaterContactWater', ...fixture.waterContact.waterProbe },
    { name: 'MetalContactNoble', ...fixture.metalContact.gasProbe },
    { name: 'MetalContactMetal', ...fixture.metalContact.metalProbe },
    { name: 'NativeWall', ...fixture.nativeWall.wallAnchor },
    { name: 'GuardedBlank', ...fixture.guardedBlank, centre: true },
  ];
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return ${JSON.stringify(points)}.map((entry) => {
      const x = entry.centre ? entry.x + Math.floor(entry.width / 2) : entry.x;
      const y = entry.centre ? entry.y + Math.floor(entry.height / 2) : entry.y;
      return {
        name: entry.name, material: audit.cell(x, y), style: audit.gasIdentityStyle(x, y),
        alpha: Math.round(audit.atmosphereFieldAlpha(x, y) * 1000) / 1000,
      };
    });
  })()`);
}

async function nobleGasBillowVfxWallDigest(cdp) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    let occupied = 0; let hash = 2166136261;
    for (let y = 0; y < audit.height; y++) for (let x = 0; x < audit.width; x++) {
      const wall = audit.wall(x, y); occupied += Number(wall !== 0);
      hash = Math.imul(hash ^ wall ^ ((x + y * audit.width) & 255), 16777619) >>> 0;
    }
    return { occupied, hash };
  })()`);
}

async function writeNobleGasBillowVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e25-noble-gas-billow-${scale}x-off`),
    on: variantScreenshotPath(source, `e25-noble-gas-billow-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXNobleGasBillowVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-noble-gas-billow', nobleGasBillowVfxAudit: '1',
    renderLook: 'realistic', volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0',
    gasBodyVfx: '1', gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0',
    powderSolidContactVfx: '0', translucentEdgeVfx: '0', organicSubsurfaceVfx: '0',
    wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0',
    gasCoreDepthVfx: '0', nobleGasBillowVfx: '1', nobleGasPrismVfx: '0', nobleGasCoreReliefVfx: '0', smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0',
    oilBodyVfx: '0', rockRoughnessVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8'
      && p.get('auditStage') === 'eight-noble-gas-billow'
      && p.get('gasBodyVfx') === '1' && p.get('gasCoreDepthVfx') === '0'
      && p.get('nobleGasBillowVfx') === '1' && p.get('nobleGasPrismVfx') === '0'
      && p.get('nobleGasCoreReliefVfx') === '0'
      && p.get('smokeBillowDepthVfx') === '0'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E25 input audit API'),
  'true-8x E25 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E25', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E25');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E25 geometry')),
    'true-8x E25 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E25 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx,
      nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      nobleGasPrismVfx: canvas.dataset.nobleGasPrismVfx,
      nobleGasCoreReliefVfx: canvas.dataset.nobleGasCoreReliefVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
    } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E25 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.gasBodyVfx === 'inactive'
    && isolation.gasCoreDepthVfx === 'inactive'
    && isolation.nobleGasBillowVfx === 'inactive' && isolation.nobleGasPrismVfx === 'inactive'
    && isolation.nobleGasCoreReliefVfx === 'inactive'
    && isolation.smokeBillowDepthVfx === 'inactive',
  `true-8x E25 isolation failed (${JSON.stringify(isolation)})`);
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, 12_000, EIGHT_X_PRESENTATION_DEADLINE_MS, 1,
  );
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence'
    || timing.source === 'gpu-finish',
  `true-8x E25 did not complete GPU work (${JSON.stringify(timing)})`);
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8'
      && geometry.backend.backend === 'webgl',
    isolation, timing,
  };
}

// E42's accepted SwiftShader matrix freezes the 1x/2x/4x transmission response.
// Highlights carry a blue-white key while pockets preferentially absorb red;
// exact raw controls remain byte-identical and only the immediate FOG-side
// compositor may retain a two-byte low-resolution HDR shoulder.
const HYDROGEN_BODY_VFX_LOCAL_CONTROL_PEAK = Object.freeze({
  H2AuthoredVoid: 2,
  H2OpenChannel: 2,
  // The exact foreign FOG owner remains raw-RGB identical; up to two composed
  // bytes are the bounded HDR-filter shoulder from the adjacent eligible H2 side.
  GasSeamFOG: 2,
  // The connected H2 side remains an eligible atmosphere-owned body right up
  // to an unlike-gas seam; freeze that response separately from the foreign
  // owner rather than silently treating it as an exact contact no-op.
  GasSeamH2: 4,
});
const HYDROGEN_BODY_VFX_ACCEPTANCE = Object.freeze({
  H2DeepCore: Object.freeze({
    rgbRms: [4.75, 5.30], chromaRms: [0.85, 1.20], rgbPeak: [8, 10],
    coverage: [0.84, 0.92], signedMean: [4.10, 4.65],
    meanBiasRatio: [0.88, 0.95], responseMicroContrast: [0.15, 0.40],
  }),
  H2Crown: Object.freeze({
    rgbRms: [5.75, 6.35], chromaRms: [1.00, 1.40], rgbPeak: [8, 10],
    coverage: [0.98, 1.00], signedMean: [5.40, 6.00],
    meanBiasRatio: [0.97, 1.00], responseMicroContrast: [0.15, 0.40],
  }),
  H2Pocket: Object.freeze({
    rgbRms: [1.80, 2.30], chromaRms: [0.80, 1.20], rgbPeak: [3, 5],
    coverage: [0.55, 0.70], signedMean: [-2.10, -1.60],
    meanBiasRatio: [0.90, 0.98], responseMicroContrast: [0.10, 0.35],
  }),
});

/** E42: exact style-5 Hydrogen transmission folds over E04's connected body. */
async function auditHydrogenBodyVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateHydrogenBodyVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E42 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E42 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E42 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.hydrogenBodyVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E42 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E42 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E42 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E42 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E42 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E42 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E42 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E42 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E42 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E42 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E42 ${scale}x changed an exact raw sibling/topology/contact/wall control (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls,
      disabledRepeat: disabledRepeat.rawControls,
    })})`);
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E42 ${scale}x changed E04 atmosphere ownership/density (${JSON.stringify(disabled.field)})`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E42 ${scale}x changed native-wall topology (${JSON.stringify(disabled.walls)})`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E42 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = hydrogenBodyVfxTargetRegions(fixture);
    const controls = hydrogenBodyVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const targetByName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(targetResponses.length === 3 && targetResponses.every((sample) => {
      const bounds = HYDROGEN_BODY_VFX_ACCEPTANCE[sample.name];
      return bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1]
        && sample.meanBiasRatio >= bounds.meanBiasRatio[0]
        && sample.meanBiasRatio <= bounds.meanBiasRatio[1]
        && sample.responseMicroContrast >= bounds.responseMicroContrast[0]
        && sample.responseMicroContrast <= bounds.responseMicroContrast[1]
        && sample.repeatRgbPeak === 0;
    }), `E42 ${scale}x escaped its accepted Hydrogen response (${JSON.stringify(targetResponses)})`);
    assert(targetByName.H2Crown?.signedMean > 0.20
      && targetByName.H2Pocket?.signedMean < -0.20
      && targetByName.H2DeepCore?.responseSignature !== targetByName.H2Crown?.responseSignature,
    `E42 ${scale}x lost its transmission crown/pocket or spatial body response (${JSON.stringify(targetResponses)})`);
    assert(targetResponses.every((sample) => (
      sample.responseRgb[2] >= sample.responseRgb[0] + 0.50
    )), `E42 ${scale}x lost its blue-white transmission bias (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (HYDROGEN_BODY_VFX_LOCAL_CONTROL_PEAK[sample.name] ?? 0)),
    `E42 ${scale}x escaped an exact sibling/topology/contact/wall control (${JSON.stringify(controlResponses)})`);
    const gasSeamH2 = controlResponses.find((sample) => sample.name === 'GasSeamH2');
    assert(gasSeamH2?.rgbRms >= 1.50 && gasSeamH2.rgbRms <= 2.60
      && gasSeamH2.rgbPeak >= 2 && gasSeamH2.rgbPeak <= 4
      && gasSeamH2.signedMean >= -2.50 && gasSeamH2.signedMean <= -1.50
      && gasSeamH2.responseRgb[2] >= gasSeamH2.responseRgb[0] + 2,
    `E42 ${scale}x lost its bounded Hydrogen-side gas-seam continuity (${JSON.stringify(gasSeamH2)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E42 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeHydrogenBodyVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      field: disabled.field, walls: disabled.walls, rawControls: disabled.rawControls,
      targetResponses, controlResponses, exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E42 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(sample.field)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls),
      `E42 ${sample.scale}x changed the exact fixture/field contract across output scales`);
    }
    const spread = (values) => Math.max(...values) - Math.min(...values);
    for (const name of ['H2DeepCore', 'H2Crown', 'H2Pocket']) {
      const samples = scales.map((entry) => (
        entry.targetResponses.find((sample) => sample.name === name)
      ));
      assert(samples.every(Boolean)
        && spread(samples.map((sample) => sample.rgbRms)) <= 0.20
        && spread(samples.map((sample) => sample.chromaRms)) <= 0.20
        && spread(samples.map((sample) => sample.signedMean)) <= 0.20
        && spread(samples.map((sample) => sample.coverage)) <= 0.04
        && spread(samples.map((sample) => sample.rgbPeak)) <= 1,
      `E42 ${name} visual response drifted across output scales (${JSON.stringify(samples)})`);
    }
  }
  const trueEightX = await auditEightXHydrogenBodyVfxExclusion(cdp, dpr);
  return { calibration: 'accepted-matrix', scales, trueEightXExcluded: true, trueEightX };
}

async function navigateHydrogenBodyVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    hydrogenBodyVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    hydrogenBodyVfx: enabled ? '1' : '0', gasMotionVfx: '0', powderBodyVfx: '0',
    powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', metalWaterContactVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0',
    glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0',
    rockMesostructureVfx: '0', waterBodyVfx: '0', acidBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = [
      'volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasMotionVfx',
      'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx',
      'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx',
      'gasLightVfx', 'liquidSolidMeniscusVfx', 'metalWaterContactVfx',
      'gasCoreDepthVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx',
      'smokeSoftnessVfx', 'smokeBillowDepthVfx', 'plasmaCoreVfx',
      'solidBodyVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
      'botanicalBodyVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
      'rockMesostructureVfx', 'waterBodyVfx', 'acidBodyVfx',
    ];
    return p.get('hydrogenBodyVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('gasBodyVfx') === '1'
      && p.get('hydrogenBodyVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareHydrogenBodyVfxFixture === 'function'
      && typeof audit?.hydrogenBodyVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E42 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E42 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareHydrogenBodyVfxFixture();
    return audit.hydrogenBodyVfxFixture();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E42 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => hydrogenBodyVfxFixtureReady(cdp, fixture),
    20_000, `E42 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const isolatedSelectors = {
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx,
      gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx,
      wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx,
      metalWaterContactVfx: canvas.dataset.metalWaterContactVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx,
      nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      nobleGasPrismVfx: canvas.dataset.nobleGasPrismVfx,
      smokeSoftnessVfx: canvas.dataset.smokeSoftnessVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx,
      solidBodyVfx: canvas.dataset.solidBodyVfx,
      platinumBodyVfx: canvas.dataset.platinumBodyVfx,
      ceramicGlazeVfx: canvas.dataset.ceramicGlazeVfx,
      botanicalBodyVfx: canvas.dataset.botanicalBodyVfx,
      glassBodyVfx: canvas.dataset.glassBodyVfx,
      oilBodyVfx: canvas.dataset.oilBodyVfx,
      rockRoughnessVfx: canvas.dataset.rockRoughnessVfx,
      rockMesostructureVfx: canvas.dataset.rockMesostructureVfx,
      waterBodyVfx: canvas.dataset.waterBodyVfx,
      acidBodyVfx: canvas.dataset.acidBodyVfx,
    };
    return {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      hydrogenBodyVfx: canvas.dataset.hydrogenBodyVfx,
      isolatedSelectors,
    };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.gasBodyVfx === 'active'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
    && hdrPipeline.hydrogenBodyVfx === (enabled ? 'active' : 'inactive'),
  `E42 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E42 ${label} ${scale}x framebuffer`,
    scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await hydrogenBodyVfxFieldDigest(cdp, fixture),
    walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, hydrogenBodyVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, hydrogenBodyVfxRawControlPoints(fixture),
    ),
    hdrPipeline,
  };
}

async function hydrogenBodyVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = ${JSON.stringify(fixture)};
    if (fixture.version !== 1 || fixture.world.width !== audit.width
      || fixture.world.height !== audit.height
      || fixture.target.material !== 40 || fixture.target.atmosphereStyle !== 5
      || typeof audit?.gasIdentityStyle !== 'function'
      || typeof audit?.atmosphereFieldAlpha !== 'function') return false;
    const inside = (rect, x, y) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const centre = (rect) => ({
      x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2),
    });
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    const target = fixture.target;
    const radiusX = target.body.width * 0.5;
    const radiusY = target.body.height * 0.5;
    const centreX = target.body.x + radiusX;
    const centreY = target.body.y + radiusY;
    for (let y = target.body.y; y < target.body.y + target.body.height; y++) {
      for (let x = target.body.x; x < target.body.x + target.body.width; x++) {
        const normalizedX = Math.abs((x + 0.5 - centreX) / radiusX);
        const normalizedY = Math.abs((y + 0.5 - centreY) / radiusY);
        const empty = normalizedX ** 4 + normalizedY ** 4 > 1
          || inside(target.authoredVoid, x, y) || inside(target.openChannel, x, y);
        if (audit.cell(x, y) !== (empty ? 0 : target.material)) return false;
      }
    }
    if (!exactRect(target.deepCore, target.material)
      || !exactRect(target.authoredVoid, 0) || !exactRect(target.openChannel, 0)
      || !target.billowProbes.every((probe) => exactRect(probe.region, target.material))) return false;
    const targetPoints = [centre(target.deepCore), ...target.billowProbes.map(({ centre }) => centre)];
    if (!targetPoints.every((point) => audit.gasIdentityStyle(point.x, point.y) === 5
      && audit.atmosphereFieldAlpha(point.x, point.y) === 255)) return false;
    if (!fixture.protectedGases.every((control) => exactRect(control.body, control.material)
      && audit.gasIdentityStyle(control.probe.x, control.probe.y) === control.atmosphereStyle)) return false;
    if (!fixture.sparse.carriers.every((point) => audit.cell(point.x, point.y) === fixture.sparse.material)
      || audit.cell(fixture.sparse.midpoint.x, fixture.sparse.midpoint.y) !== 0
      || audit.cell(fixture.sparse.gap.x, fixture.sparse.gap.y) !== 0
      || audit.cell(fixture.sparse.isolated.x, fixture.sparse.isolated.y) !== fixture.sparse.material) return false;
    return target.billowProbes[0].billow > 0 && target.billowProbes[1].billow < 0
      && exactRect(fixture.gasSeam.gas, target.material)
      && exactRect(fixture.gasSeam.foreignGas, fixture.gasSeam.foreignMaterial)
      && audit.gasIdentityStyle(fixture.gasSeam.gasProbe.x, fixture.gasSeam.gasProbe.y) === 5
      && audit.gasIdentityStyle(fixture.gasSeam.foreignProbe.x, fixture.gasSeam.foreignProbe.y) === 10
      && exactRect(fixture.waterContact.gas, target.material)
      && exactRect(fixture.waterContact.water, 2)
      && exactRect(fixture.metalContact.gas, target.material)
      && exactRect(fixture.metalContact.metal, 23)
      && exactRect(fixture.nativeWall.gas, target.material)
      && audit.wall(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.conductiveWall
      && audit.gasIdentityStyle(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) !== 5
      && exactRect(fixture.guardedBlank, 0)
      && audit.gasIdentityStyle(centre(fixture.guardedBlank).x, centre(fixture.guardedBlank).y) !== 5;
  })()`);
}

function hydrogenBodyVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  return [
    rect('H2DeepCore', fixture.target.deepCore),
    ...fixture.target.billowProbes.map((probe) => (
      rect(`H2${probe.code === 'CROWN' ? 'Crown' : 'Pocket'}`, probe.region)
    )),
  ];
}

function hydrogenBodyVfxControlRegions(fixture) {
  const point = (name, candidate) => ({
    name, x: Math.floor(candidate.x) + 0.5, y: Math.floor(candidate.y) + 0.5, radius: 0,
  });
  const rect = (name, candidate, inset = 0) => ({
    name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - inset - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - inset - 0.2),
  });
  return [
    rect('H2AuthoredVoid', fixture.target.authoredVoid, 4),
    rect('H2OpenChannel', fixture.target.openChannel, 4),
    ...fixture.protectedGases.map((control) => point(`Protected${control.code}`, control.probe)),
    ...fixture.sparse.carriers.map((carrier, index) => point(`SparseCarrier${index + 1}`, carrier)),
    point('SparseMidpoint', fixture.sparse.midpoint),
    point('SparseGap', fixture.sparse.gap),
    point('SparseIsolated', fixture.sparse.isolated),
    point('GasSeamH2', fixture.gasSeam.gasProbe),
    point('GasSeamFOG', fixture.gasSeam.foreignProbe),
    point('WaterContactH2', fixture.waterContact.gasProbe),
    point('WaterContactWater', fixture.waterContact.waterProbe),
    point('MetalContactH2', fixture.metalContact.gasProbe),
    point('MetalContactMetal', fixture.metalContact.metalProbe),
    point('NativeWall', fixture.nativeWall.wallAnchor),
    rect('GuardedBlank', fixture.guardedBlank, 4),
  ];
}

function hydrogenBodyVfxAllRawPoints(fixture) {
  return [
    ...hydrogenBodyVfxTargetRegions(fixture).map((region) => ({
      name: region.name, x: Math.floor(region.x), y: Math.floor(region.y),
    })),
    ...hydrogenBodyVfxRawControlPoints(fixture),
    { name: 'GasSeamH2', ...fixture.gasSeam.gasProbe },
    { name: 'WaterContactH2', ...fixture.waterContact.gasProbe },
    { name: 'MetalContactH2', ...fixture.metalContact.gasProbe },
  ];
}

function hydrogenBodyVfxRawControlPoints(fixture) {
  return hydrogenBodyVfxControlRegions(fixture)
    // The exact H2 seam owner is intentionally eligible and is bounded in the
    // composed response matrix; every other raw control remains byte exact.
    .filter((region) => region.name !== 'GasSeamH2')
    .map((region) => ({
      name: region.name, x: Math.floor(region.x), y: Math.floor(region.y),
    }));
}

async function hydrogenBodyVfxFieldDigest(cdp, fixture) {
  const points = [
    { name: 'H2DeepCore', ...fixture.target.deepCore, centre: true },
    ...fixture.target.billowProbes.map((probe) => ({ name: `H2${probe.code}`, ...probe.centre })),
    ...fixture.protectedGases.map((control) => ({ name: control.code, ...control.probe })),
    { name: 'AuthoredVoid', ...fixture.target.authoredVoid, centre: true },
    { name: 'OpenChannel', ...fixture.target.openChannel, centre: true },
    ...fixture.sparse.carriers.map((point, index) => ({ name: `SparseCarrier${index + 1}`, ...point })),
    { name: 'SparseMidpoint', ...fixture.sparse.midpoint },
    { name: 'SparseGap', ...fixture.sparse.gap },
    { name: 'SparseIsolated', ...fixture.sparse.isolated },
    { name: 'GasSeamH2', ...fixture.gasSeam.gasProbe },
    { name: 'GasSeamFOG', ...fixture.gasSeam.foreignProbe },
    { name: 'WaterContactH2', ...fixture.waterContact.gasProbe },
    { name: 'WaterContactWater', ...fixture.waterContact.waterProbe },
    { name: 'MetalContactH2', ...fixture.metalContact.gasProbe },
    { name: 'MetalContactMetal', ...fixture.metalContact.metalProbe },
    { name: 'NativeWall', ...fixture.nativeWall.wallAnchor },
    { name: 'GuardedBlank', ...fixture.guardedBlank, centre: true },
  ];
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return ${JSON.stringify(points)}.map((entry) => {
      const x = entry.centre ? entry.x + Math.floor(entry.width / 2) : entry.x;
      const y = entry.centre ? entry.y + Math.floor(entry.height / 2) : entry.y;
      return {
        name: entry.name, material: audit.cell(x, y), style: audit.gasIdentityStyle(x, y),
        alpha: Math.round(audit.atmosphereFieldAlpha(x, y) * 1000) / 1000,
      };
    });
  })()`);
}

async function writeHydrogenBodyVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e42-hydrogen-body-${scale}x-off`),
    on: variantScreenshotPath(source, `e42-hydrogen-body-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXHydrogenBodyVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-hydrogen-body', hydrogenBodyVfxAudit: '1', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    hydrogenBodyVfx: '1', gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0',
    powderSolidContactVfx: '0', translucentEdgeVfx: '0', organicSubsurfaceVfx: '0',
    wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0',
    metalWaterContactVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0',
    nobleGasPrismVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0',
    oilBodyVfx: '0', rockRoughnessVfx: '0', rockMesostructureVfx: '0',
    waterBodyVfx: '0', acidBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8'
      && p.get('auditStage') === 'eight-hydrogen-body'
      && p.get('gasBodyVfx') === '1' && p.get('hydrogenBodyVfx') === '1'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E42 input audit API'),
  'true-8x E42 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E42', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E42');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E42 geometry')),
    'true-8x E42 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E42 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      hydrogenBodyVfx: canvas.dataset.hydrogenBodyVfx,
    } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E42 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.gasBodyVfx === 'inactive'
    && isolation.hydrogenBodyVfx === 'inactive',
  `true-8x E42 isolation failed (${JSON.stringify(isolation)})`);
  // E42 has no compact-shader implementation. This focused tail therefore
  // proves requested-on selector exclusion on the already-fenced native 8x
  // path; the 1x/2x/4x gate above owns the exact H2 fixture. Uploading that
  // dense fixture here would queue an unrelated extra 15M-fragment frame and
  // turn an exclusion test into a second content-performance gate.
  const stateBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E42 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E42 did not complete GPU work (${JSON.stringify(timing)})`);
  const stateAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(stateBefore, stateAfter, 'true-8x E42 GPU completion');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8'
      && geometry.backend.backend === 'webgl',
    selectorExcluded: true, semanticStable: true, isolation, timing,
  };
}

// E44's accepted SwiftShader matrix freezes the broad connected-body response
// per probe. A uniform tint cannot satisfy the bright deep body and crown plus
// the opposing pocket, while the narrow bounds keep 1x/2x/4x visually aligned.
const CARBON_DIOXIDE_BODY_VFX_LOCAL_CONTROL_PEAK = Object.freeze({
  CO2AuthoredVoid: 1,
  CO2OpenChannel: 1,
  // The exact foreign FOG owner remains raw-RGB identical; the composed sample
  // may include a bounded low-resolution HDR shoulder from eligible CO2.
  GasSeamFOG: 1,
  // The connected CO2 side remains an eligible atmosphere-owned body right up
  // to an unlike-gas seam; freeze that response separately from the foreign
  // owner rather than silently treating it as an exact contact no-op.
  GasSeamCO2: 2,
});
const CARBON_DIOXIDE_BODY_VFX_ACCEPTANCE = Object.freeze({
  CO2DeepCore: Object.freeze({
    rgbRms: [6.20, 6.65], chromaRms: [0.70, 0.98], rgbPeak: [9, 11],
    coverage: [0.88, 0.97], signedMean: [5.55, 6.10],
    meanBiasRatio: [0.89, 0.97], responseMicroContrast: [0.15, 0.40],
  }),
  CO2Crown: Object.freeze({
    rgbRms: [7.55, 8.05], chromaRms: [0.80, 1.12], rgbPeak: [9, 11],
    coverage: [0.97, 1.00], signedMean: [7.30, 7.85],
    meanBiasRatio: [0.96, 1.00], responseMicroContrast: [0.14, 0.35],
  }),
  CO2Pocket: Object.freeze({
    rgbRms: [1.30, 1.75], chromaRms: [0.42, 0.75], rgbPeak: [2, 4],
    coverage: [0.30, 0.52], signedMean: [-1.70, -1.25],
    meanBiasRatio: [0.92, 0.99], responseMicroContrast: [0.06, 0.25],
  }),
});

/** E44: exact style-6 Carbon Dioxide transmission folds over E04's connected body. */
async function auditCarbonDioxideBodyVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateCarbonDioxideBodyVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E44 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E44 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl',
        `E44 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.carbonDioxideBodyVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E44 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E44 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E44 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E44 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E44 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E44 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E44 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E44 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E44 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E44 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E44 ${scale}x changed an exact raw sibling/topology/contact/wall control (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls,
      disabledRepeat: disabledRepeat.rawControls,
    })})`);
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E44 ${scale}x changed E04 atmosphere ownership/density (${JSON.stringify(disabled.field)})`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E44 ${scale}x changed native-wall topology (${JSON.stringify(disabled.walls)})`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E44 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = carbonDioxideBodyVfxTargetRegions(fixture);
    const controls = carbonDioxideBodyVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const targetByName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(targetResponses.length === 3 && targetResponses.every((sample) => {
      const bounds = CARBON_DIOXIDE_BODY_VFX_ACCEPTANCE[sample.name];
      return bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1]
        && sample.meanBiasRatio >= bounds.meanBiasRatio[0]
        && sample.meanBiasRatio <= bounds.meanBiasRatio[1]
        && sample.responseMicroContrast >= bounds.responseMicroContrast[0]
        && sample.responseMicroContrast <= bounds.responseMicroContrast[1]
        && sample.repeatRgbPeak === 0;
    }), `E44 ${scale}x escaped its accepted Carbon Dioxide response (${JSON.stringify(targetResponses)})`);
    assert(targetByName.CO2Crown?.signedMean > 0.20
      && targetByName.CO2Pocket?.signedMean < -0.20
      && targetByName.CO2DeepCore?.responseSignature !== targetByName.CO2Crown?.responseSignature,
    `E44 ${scale}x lost its transmission crown/pocket or spatial body response (${JSON.stringify(targetResponses)})`);
    assert(targetResponses.every((sample) => (
      sample.responseRgb[2] >= sample.responseRgb[0] + 0.50
    )), `E44 ${scale}x lost its blue-white transmission bias (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (CARBON_DIOXIDE_BODY_VFX_LOCAL_CONTROL_PEAK[sample.name] ?? 0)),
    `E44 ${scale}x escaped an exact sibling/topology/contact/wall control (${JSON.stringify(controlResponses)})`);
    const gasSeamCO2 = controlResponses.find((sample) => sample.name === 'GasSeamCO2');
    assert(gasSeamCO2?.rgbRms >= 1.10 && gasSeamCO2.rgbRms <= 2.10
      && gasSeamCO2.rgbPeak === 2
      && gasSeamCO2.signedMean >= -2.15 && gasSeamCO2.signedMean <= -1.00,
    `E44 ${scale}x lost its bounded Carbon Dioxide-side gas-seam continuity (${JSON.stringify(gasSeamCO2)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E44 ${scale}x off -> on -> off was not deterministic (${JSON.stringify(responses)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeCarbonDioxideBodyVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      field: disabled.field, walls: disabled.walls, rawControls: disabled.rawControls,
      targetResponses, controlResponses, exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E44 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(sample.field)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls),
      `E44 ${sample.scale}x changed the exact fixture/field contract across output scales`);
    }
    const spread = (values) => Math.max(...values) - Math.min(...values);
    for (const name of ['CO2DeepCore', 'CO2Crown', 'CO2Pocket']) {
      const samples = scales.map((entry) => (
        entry.targetResponses.find((sample) => sample.name === name)
      ));
      assert(samples.every(Boolean)
        && spread(samples.map((sample) => sample.rgbRms)) <= 0.15
        && spread(samples.map((sample) => sample.chromaRms)) <= 0.15
        && spread(samples.map((sample) => sample.signedMean)) <= 0.15
        && spread(samples.map((sample) => sample.coverage)) <= 0.06
        && spread(samples.map((sample) => sample.rgbPeak)) <= 1,
      `E44 ${name} visual response drifted across output scales (${JSON.stringify(samples)})`);
    }
  }
  const trueEightX = await auditEightXCarbonDioxideBodyVfxExclusion(cdp, dpr);
  return { calibration: 'e44-frozen-1x-4x', scales, trueEightXExcluded: true, trueEightX };
}

async function navigateCarbonDioxideBodyVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    carbonDioxideBodyVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    hydrogenBodyVfx: '0', carbonDioxideBodyVfx: enabled ? '1' : '0', fogCoreDiffuseVfx: '0',
    gasMotionVfx: '0', powderBodyVfx: '0',
    powderLightVfx: '0', powderSolidContactVfx: '0', translucentEdgeVfx: '0',
    organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', metalWaterContactVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '0', nobleGasPrismVfx: '0', smokeSoftnessVfx: '0',
    smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0',
    glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0',
    rockMesostructureVfx: '0', waterBodyVfx: '0', acidBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = [
      'volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'hydrogenBodyVfx', 'gasMotionVfx',
      'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx',
      'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx',
      'gasLightVfx', 'liquidSolidMeniscusVfx', 'metalWaterContactVfx',
      'gasCoreDepthVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx',
      'smokeSoftnessVfx', 'smokeBillowDepthVfx', 'fogCoreDiffuseVfx', 'plasmaCoreVfx',
      'solidBodyVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
      'botanicalBodyVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
      'rockMesostructureVfx', 'waterBodyVfx', 'acidBodyVfx',
    ];
    return p.get('carbonDioxideBodyVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('gasBodyVfx') === '1'
      && p.get('carbonDioxideBodyVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareCarbonDioxideBodyVfxFixture === 'function'
      && typeof audit?.carbonDioxideBodyVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E44 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E44 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareCarbonDioxideBodyVfxFixture();
    return audit.carbonDioxideBodyVfxFixture();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E44 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => carbonDioxideBodyVfxFixtureReady(cdp, fixture),
    20_000, `E44 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const isolatedSelectors = {
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx,
      gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx,
      powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx,
      wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx,
      metalWaterContactVfx: canvas.dataset.metalWaterContactVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx,
      nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      nobleGasPrismVfx: canvas.dataset.nobleGasPrismVfx,
      smokeSoftnessVfx: canvas.dataset.smokeSoftnessVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
      fogCoreDiffuseVfx: canvas.dataset.fogCoreDiffuseVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx,
      solidBodyVfx: canvas.dataset.solidBodyVfx,
      platinumBodyVfx: canvas.dataset.platinumBodyVfx,
      ceramicGlazeVfx: canvas.dataset.ceramicGlazeVfx,
      botanicalBodyVfx: canvas.dataset.botanicalBodyVfx,
      glassBodyVfx: canvas.dataset.glassBodyVfx,
      oilBodyVfx: canvas.dataset.oilBodyVfx,
      rockRoughnessVfx: canvas.dataset.rockRoughnessVfx,
      rockMesostructureVfx: canvas.dataset.rockMesostructureVfx,
      waterBodyVfx: canvas.dataset.waterBodyVfx,
      acidBodyVfx: canvas.dataset.acidBodyVfx,
    };
    return {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      hydrogenBodyVfx: canvas.dataset.hydrogenBodyVfx,
      carbonDioxideBodyVfx: canvas.dataset.carbonDioxideBodyVfx,
      isolatedSelectors,
    };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.gasBodyVfx === 'active'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
    && hdrPipeline.hydrogenBodyVfx === 'inactive'
    && hdrPipeline.carbonDioxideBodyVfx === (enabled ? 'active' : 'inactive')
    && hdrPipeline.fogCoreDiffuseVfx === 'inactive',
  `E44 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E44 ${label} ${scale}x framebuffer`,
    scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await carbonDioxideBodyVfxFieldDigest(cdp, fixture),
    walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, carbonDioxideBodyVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, carbonDioxideBodyVfxRawControlPoints(fixture),
    ),
    hdrPipeline,
  };
}

async function carbonDioxideBodyVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = ${JSON.stringify(fixture)};
    if (fixture.version !== 1 || fixture.world.width !== audit.width
      || fixture.world.height !== audit.height
      || fixture.target.material !== 41 || fixture.target.atmosphereStyle !== 6
      || typeof audit?.gasIdentityStyle !== 'function'
      || typeof audit?.atmosphereFieldAlpha !== 'function') return false;
    const inside = (rect, x, y) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const centre = (rect) => ({
      x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2),
    });
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    const target = fixture.target;
    const radiusX = target.body.width * 0.5;
    const radiusY = target.body.height * 0.5;
    const centreX = target.body.x + radiusX;
    const centreY = target.body.y + radiusY;
    for (let y = target.body.y; y < target.body.y + target.body.height; y++) {
      for (let x = target.body.x; x < target.body.x + target.body.width; x++) {
        const normalizedX = Math.abs((x + 0.5 - centreX) / radiusX);
        const normalizedY = Math.abs((y + 0.5 - centreY) / radiusY);
        const empty = normalizedX ** 4 + normalizedY ** 4 > 1
          || inside(target.authoredVoid, x, y) || inside(target.openChannel, x, y);
        if (audit.cell(x, y) !== (empty ? 0 : target.material)) return false;
      }
    }
    if (!exactRect(target.deepCore, target.material)
      || !exactRect(target.authoredVoid, 0) || !exactRect(target.openChannel, 0)
      || !target.billowProbes.every((probe) => exactRect(probe.region, target.material))) return false;
    const targetPoints = [centre(target.deepCore), ...target.billowProbes.map(({ centre }) => centre)];
    if (!targetPoints.every((point) => audit.gasIdentityStyle(point.x, point.y) === 6
      && audit.atmosphereFieldAlpha(point.x, point.y) === 255)) return false;
    if (!fixture.protectedGases.every((control) => exactRect(control.body, control.material)
      && audit.gasIdentityStyle(control.probe.x, control.probe.y) === control.atmosphereStyle)) return false;
    if (!fixture.sparse.carriers.every((point) => audit.cell(point.x, point.y) === fixture.sparse.material)
      || audit.cell(fixture.sparse.midpoint.x, fixture.sparse.midpoint.y) !== 0
      || audit.cell(fixture.sparse.gap.x, fixture.sparse.gap.y) !== 0
      || audit.cell(fixture.sparse.isolated.x, fixture.sparse.isolated.y) !== fixture.sparse.material) return false;
    return target.billowProbes[0].billow > 0 && target.billowProbes[1].billow < 0
      && exactRect(fixture.gasSeam.gas, target.material)
      && exactRect(fixture.gasSeam.foreignGas, fixture.gasSeam.foreignMaterial)
      && audit.gasIdentityStyle(fixture.gasSeam.gasProbe.x, fixture.gasSeam.gasProbe.y) === 6
      && audit.gasIdentityStyle(fixture.gasSeam.foreignProbe.x, fixture.gasSeam.foreignProbe.y) === 10
      && exactRect(fixture.waterContact.gas, target.material)
      && exactRect(fixture.waterContact.water, 2)
      && exactRect(fixture.metalContact.gas, target.material)
      && exactRect(fixture.metalContact.metal, 23)
      && exactRect(fixture.nativeWall.gas, target.material)
      && audit.wall(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.conductiveWall
      && audit.gasIdentityStyle(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) !== 6
      && exactRect(fixture.guardedBlank, 0)
      && audit.gasIdentityStyle(centre(fixture.guardedBlank).x, centre(fixture.guardedBlank).y) !== 6;
  })()`);
}

function carbonDioxideBodyVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  return [
    rect('CO2DeepCore', fixture.target.deepCore),
    ...fixture.target.billowProbes.map((probe) => (
      rect(`CO2${probe.code === 'CROWN' ? 'Crown' : 'Pocket'}`, probe.region)
    )),
  ];
}

function carbonDioxideBodyVfxControlRegions(fixture) {
  const point = (name, candidate) => ({
    name, x: Math.floor(candidate.x) + 0.5, y: Math.floor(candidate.y) + 0.5, radius: 0,
  });
  const rect = (name, candidate, inset = 0) => ({
    name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - inset - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - inset - 0.2),
  });
  return [
    rect('CO2AuthoredVoid', fixture.target.authoredVoid, 4),
    rect('CO2OpenChannel', fixture.target.openChannel, 4),
    ...fixture.protectedGases.map((control) => point(`Protected${control.code}`, control.probe)),
    ...fixture.sparse.carriers.map((carrier, index) => point(`SparseCarrier${index + 1}`, carrier)),
    point('SparseMidpoint', fixture.sparse.midpoint),
    point('SparseGap', fixture.sparse.gap),
    point('SparseIsolated', fixture.sparse.isolated),
    point('GasSeamCO2', fixture.gasSeam.gasProbe),
    point('GasSeamFOG', fixture.gasSeam.foreignProbe),
    point('WaterContactCO2', fixture.waterContact.gasProbe),
    point('WaterContactWater', fixture.waterContact.waterProbe),
    point('MetalContactCO2', fixture.metalContact.gasProbe),
    point('MetalContactMetal', fixture.metalContact.metalProbe),
    point('NativeWall', fixture.nativeWall.wallAnchor),
    rect('GuardedBlank', fixture.guardedBlank, 4),
  ];
}

function carbonDioxideBodyVfxAllRawPoints(fixture) {
  return [
    ...carbonDioxideBodyVfxTargetRegions(fixture).map((region) => ({
      name: region.name, x: Math.floor(region.x), y: Math.floor(region.y),
    })),
    ...carbonDioxideBodyVfxRawControlPoints(fixture),
    { name: 'GasSeamCO2', ...fixture.gasSeam.gasProbe },
    { name: 'WaterContactCO2', ...fixture.waterContact.gasProbe },
    { name: 'MetalContactCO2', ...fixture.metalContact.gasProbe },
  ];
}

function carbonDioxideBodyVfxRawControlPoints(fixture) {
  return carbonDioxideBodyVfxControlRegions(fixture)
    // The exact CO2 seam owner is intentionally eligible and is bounded in the
    // composed response matrix; every other raw control remains byte exact.
    .filter((region) => region.name !== 'GasSeamCO2')
    .map((region) => ({
      name: region.name, x: Math.floor(region.x), y: Math.floor(region.y),
    }));
}

async function carbonDioxideBodyVfxFieldDigest(cdp, fixture) {
  const points = [
    { name: 'CO2DeepCore', ...fixture.target.deepCore, centre: true },
    ...fixture.target.billowProbes.map((probe) => ({ name: `CO2${probe.code}`, ...probe.centre })),
    ...fixture.protectedGases.map((control) => ({ name: control.code, ...control.probe })),
    { name: 'AuthoredVoid', ...fixture.target.authoredVoid, centre: true },
    { name: 'OpenChannel', ...fixture.target.openChannel, centre: true },
    ...fixture.sparse.carriers.map((point, index) => ({ name: `SparseCarrier${index + 1}`, ...point })),
    { name: 'SparseMidpoint', ...fixture.sparse.midpoint },
    { name: 'SparseGap', ...fixture.sparse.gap },
    { name: 'SparseIsolated', ...fixture.sparse.isolated },
    { name: 'GasSeamCO2', ...fixture.gasSeam.gasProbe },
    { name: 'GasSeamFOG', ...fixture.gasSeam.foreignProbe },
    { name: 'WaterContactCO2', ...fixture.waterContact.gasProbe },
    { name: 'WaterContactWater', ...fixture.waterContact.waterProbe },
    { name: 'MetalContactCO2', ...fixture.metalContact.gasProbe },
    { name: 'MetalContactMetal', ...fixture.metalContact.metalProbe },
    { name: 'NativeWall', ...fixture.nativeWall.wallAnchor },
    { name: 'GuardedBlank', ...fixture.guardedBlank, centre: true },
  ];
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return ${JSON.stringify(points)}.map((entry) => {
      const x = entry.centre ? entry.x + Math.floor(entry.width / 2) : entry.x;
      const y = entry.centre ? entry.y + Math.floor(entry.height / 2) : entry.y;
      return {
        name: entry.name, material: audit.cell(x, y), style: audit.gasIdentityStyle(x, y),
        alpha: Math.round(audit.atmosphereFieldAlpha(x, y) * 1000) / 1000,
      };
    });
  })()`);
}

async function writeCarbonDioxideBodyVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e44-carbon-dioxide-body-${scale}x-off`),
    on: variantScreenshotPath(source, `e44-carbon-dioxide-body-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXCarbonDioxideBodyVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-carbon-dioxide-body', carbonDioxideBodyVfxAudit: '1', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '1', fogCoreDiffuseVfx: '0', gasMotionVfx: '0',
    powderBodyVfx: '0', powderLightVfx: '0',
    powderSolidContactVfx: '0', translucentEdgeVfx: '0', organicSubsurfaceVfx: '0',
    wetSedimentVfx: '0', gasLightVfx: '0', liquidSolidMeniscusVfx: '0',
    metalWaterContactVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0',
    nobleGasPrismVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0',
    oilBodyVfx: '0', rockRoughnessVfx: '0', rockMesostructureVfx: '0',
    waterBodyVfx: '0', acidBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8'
      && p.get('auditStage') === 'eight-carbon-dioxide-body'
      && p.get('gasBodyVfx') === '1' && p.get('carbonDioxideBodyVfx') === '1'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E44 input audit API'),
  'true-8x E44 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E44', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E44');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E44 geometry')),
    'true-8x E44 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E44 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      hydrogenBodyVfx: canvas.dataset.hydrogenBodyVfx,
      carbonDioxideBodyVfx: canvas.dataset.carbonDioxideBodyVfx,
      fogCoreDiffuseVfx: canvas.dataset.fogCoreDiffuseVfx,
    } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E44 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.gasBodyVfx === 'inactive'
    && isolation.hydrogenBodyVfx === 'inactive'
    && isolation.carbonDioxideBodyVfx === 'inactive' && isolation.fogCoreDiffuseVfx === 'inactive',
  `true-8x E44 isolation failed (${JSON.stringify(isolation)})`);
  // E44 has no compact-shader implementation. This focused tail therefore
  // proves requested-on selector and HDR-resource exclusion on the already-fenced native 8x
  // path; the 1x/2x/4x gate above owns the exact CO2 fixture. Uploading that
  // dense fixture here would queue an unrelated extra 15M-fragment frame and
  // turn an exclusion test into a second content-performance gate.
  const stateBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E44 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E44 did not complete GPU work (${JSON.stringify(timing)})`);
  const stateAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(stateBefore, stateAfter, 'true-8x E44 GPU completion');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8'
      && geometry.backend.backend === 'webgl',
    selectorExcluded: true, resourcesIdentical: isolation.bloomBacking === null,
    semanticStable: true, isolation, timing,
  };
}

// E73 is measured only as a strict E44 child. Keep every sibling explicit so
// future ordinary-play defaults cannot silently enter the accepted calibration.
const CARBON_DIOXIDE_CORE_FOLD_VFX_ISOLATED_SELECTORS = Object.freeze([
  'volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx',
  'waterCurvatureVfx', 'fireFlameVfx', 'cflmColdFlameVfx',
  'gasMotionVfx', 'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx',
  'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx',
  'liquidSolidMeniscusVfx', 'metalWaterContactVfx', 'waterMetalTransmissionVfx', 'waterMetalSeparationVfx',
  'gasCoreDepthVfx', 'hydrogenBodyVfx',
  'steamCondensateVfx', 'fogCoreDiffuseVfx', 'nobleGasBillowVfx',
  'nobleGasPrismVfx', 'smokeSoftnessVfx', 'smokeBillowDepthVfx',
  'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx', 'ceramicGlazeVfx',
  'botanicalBodyVfx', 'botanicalMesostructureVfx', 'botanicalPigmentVfx',
  'plantLaminaVfx', 'plantLobeDepthVfx', 'plantCanopyMassVfx',
  'plantCanopyTissueVfx', 'plantCanopyInterlockVfx', 'plantCanopyHierarchyVfx',
  'plantCanopyFoliageVfx', 'plantCanopyLifecycleVfx', 'woodBarkReliefVfx', 'woodTanninVfx',
  'glassBodyVfx', 'oilBodyVfx', 'oilVolumeFinishVfx', 'oilDepthTransmissionVfx',
  'nitroBodyVfx', 'rockRoughnessVfx', 'rockMesostructureVfx',
  'rockWeatheredFacetVfx', 'waterBodyVfx', 'waterVolumeRecessionVfx',
  'acidBodyVfx', 'soapBodyVfx', 'sootyPowderBodyVfx', 'thermiteBodyVfx',
  'snowpackBodyVfx', 'quartzMesostructureVfx', 'c4BodyVfx', 'bglaBodyVfx',
  'bglaClusterVfx', 'deutBodyVfx', 'radioactiveSolidBodyVfx',
  'iszsCrystallineVfx', 'iszsCrystalHierarchyVfx', 'vibrMacroReliefVfx',
]);

// E73's accepted 1x/2x/4x SwiftShader matrix freezes one balanced whole-body
// response plus the opposing crown/pocket anchors. Tight common envelopes are
// possible because the fold is world-anchored and independent of output scale.
const CARBON_DIOXIDE_CORE_FOLD_VFX_ACCEPTANCE = Object.freeze({
  CO2WholeBodyInset: Object.freeze({
    rgbRms: [3.12, 3.22], chromaRms: [0.70, 0.80], rgbPeak: [8, 8],
    coverage: [0.54, 0.57], signedMean: [0.16, 0.24],
    meanBiasRatio: [0.04, 0.10], positiveMean: [1.16, 1.26],
    negativeMean: [0.96, 1.06], bipolarBalance: [0.78, 0.88],
    responseMicroContrast: [0.20, 0.28],
    responseRgb: [[0.27, 0.35], [0.15, 0.24], [-0.08, 0.00]],
  }),
  CO2PositiveFold: Object.freeze({
    rgbRms: [5.17, 5.29], chromaRms: [0.77, 0.87], rgbPeak: [7, 7],
    coverage: [0.99, 1.00], signedMean: [4.92, 5.08],
    meanBiasRatio: [0.98, 1.00], positiveMean: [4.92, 5.08],
    negativeMean: [0, 0], bipolarBalance: [0, 0],
    responseMicroContrast: [0.31, 0.40],
    responseRgb: [[4.25, 4.40], [5.02, 5.20], [5.90, 6.03]],
  }),
  CO2NegativeFold: Object.freeze({
    rgbRms: [5.54, 5.70], chromaRms: [1.44, 1.58], rgbPeak: [8, 8],
    coverage: [0.99, 1.00], signedMean: [-5.14, -5.00],
    meanBiasRatio: [0.99, 1.00], positiveMean: [0, 0],
    negativeMean: [5.00, 5.14], bipolarBalance: [0, 0],
    responseMicroContrast: [0.13, 0.20],
    responseRgb: [[-3.82, -3.66], [-5.32, -5.17], [-7.34, -7.19]],
  }),
});

// Exact foreign owners and sparse topology remain zero. Only the named soft
// style-6 rim gets a bounded RGB allowance; material/alpha/field evidence is
// still exact below.
const CARBON_DIOXIDE_CORE_FOLD_VFX_CONTROL_PEAK = Object.freeze({
  CO2SoftRim: 5,
});
const CARBON_DIOXIDE_CORE_FOLD_VFX_RAW_CONTROL_PEAK = Object.freeze({
  // One 1x/2x centre sample can retain more RGB than the fitted composed
  // footprint even though E73 preserves the authoritative alpha byte.
  CO2SoftRim: 12,
});

/** E73: accepted exact style-6 core fold, strictly subordinate to E04/E44. */
async function auditCarbonDioxideCoreFoldVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateCarbonDioxideCoreFoldVfxState(
        cdp, mode, scale, enabled, key,
      );
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    const rawControlResponses = carbonDioxideCoreFoldRawControlResponses(
      disabled.rawControls, enabled.rawControls,
    );
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E73 ${scale}x E44 fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E73 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl'
        && variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.carbonDioxideBodyVfx === 'active'
        && variant.hdrPipeline.carbonDioxideCoreFoldVfx
          === (label === 'enabled' ? 'active' : 'inactive')
        && Object.values(variant.hdrPipeline.isolatedSelectors)
          .every((state) => state === 'inactive'),
      `E73 ${label} ${scale}x parent/selector isolation failed (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E73 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E73 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E73 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic,
      `E73 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E73 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E73 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E73 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E73 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E73 ${scale}x disabled/repeated`);
    assertCarbonDioxideCoreFoldRawControlsInvariant(
      disabled.rawControls, enabled.rawControls, `E73 ${scale}x disabled/enabled`,
    );
    assertCarbonDioxideCoreFoldRawControlsInvariant(
      disabled.rawControls, disabledRepeat.rawControls, `E73 ${scale}x disabled/repeated`,
    );
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E73 ${scale}x changed style-6 atmosphere ownership/density`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E73 ${scale}x changed native-wall topology`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E73 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = carbonDioxideCoreFoldVfxTargetRegions(fixture);
    const controls = carbonDioxideCoreFoldVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const inRange = (value, range) => value >= range[0] && value <= range[1];
    assert(targetResponses.length === 3 && targetResponses.every((sample) => {
      const bounds = CARBON_DIOXIDE_CORE_FOLD_VFX_ACCEPTANCE[sample.name];
      return bounds
        && inRange(sample.rgbRms, bounds.rgbRms)
        && inRange(sample.chromaRms, bounds.chromaRms)
        && inRange(sample.rgbPeak, bounds.rgbPeak)
        && inRange(sample.coverage, bounds.coverage)
        && inRange(sample.signedMean, bounds.signedMean)
        && inRange(sample.meanBiasRatio, bounds.meanBiasRatio)
        && inRange(sample.positiveMean, bounds.positiveMean)
        && inRange(sample.negativeMean, bounds.negativeMean)
        && inRange(sample.bipolarBalance, bounds.bipolarBalance)
        && inRange(sample.responseMicroContrast, bounds.responseMicroContrast)
        && sample.responseRgb.every((value, channel) => (
          inRange(value, bounds.responseRgb[channel])
        ))
        && sample.repeatRgbPeak === 0;
    }), `E73 ${scale}x escaped its accepted core-fold response (${JSON.stringify(targetResponses)})`);
    const targetByName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(targetByName.CO2PositiveFold?.signedMean > 0
      && targetByName.CO2NegativeFold?.signedMean < 0
      && targetByName.CO2PositiveFold.responseSignature
        !== targetByName.CO2NegativeFold.responseSignature,
    `E73 ${scale}x lost its bipolar fold (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.length === controls.length && controlResponses.every((sample) => (
      sample.rgbPeak <= (CARBON_DIOXIDE_CORE_FOLD_VFX_CONTROL_PEAK[sample.name] ?? 0)
        && sample.repeatRgbPeak === 0
    )), `E73 ${scale}x escaped an E44 sibling/topology/contact/wall control (${JSON.stringify(controlResponses)})`);
    assert(responses.every((sample) => sample.repeatRgbPeak === 0),
      `E73 ${scale}x off -> on -> off was not deterministic`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeCarbonDioxideCoreFoldVfxScreenshots(
        screenshotRequest, scale, disabled, enabled, disabledRepeat,
      ) : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      field: disabled.field, walls: disabled.walls, rawControls: disabled.rawControls,
      rawControlResponses, targetResponses, controlResponses,
      exactRepeatedOff: true, screenshots,
      numericCalibration: 'accepted-e73-focused-and-composed-matrix',
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E73 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(sample.field)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls),
      `E73 ${sample.scale}x changed the exact fixture/field contract across scales`);
    }
    for (const name of Object.keys(CARBON_DIOXIDE_CORE_FOLD_VFX_ACCEPTANCE)) {
      const samples = scales.map((entry) => (
        entry.targetResponses.find((sample) => sample.name === name)
      ));
      const spread = (field) => {
        const values = samples.map((sample) => sample[field]);
        return Math.max(...values) - Math.min(...values);
      };
      const channelSpread = Math.max(...[0, 1, 2].map((channel) => {
        const values = samples.map((sample) => sample.responseRgb[channel]);
        return Math.max(...values) - Math.min(...values);
      }));
      assert(samples.every(Boolean) && spread('rgbRms') <= 0.03
        && spread('chromaRms') <= 0.04 && spread('signedMean') <= 0.05
        && spread('coverage') <= 0.006 && spread('responseMicroContrast') <= 0.03
        && spread('rgbPeak') === 0 && channelSpread <= 0.08,
      `E73 ${name} response diverged across scales (${JSON.stringify(samples)})`);
    }
  }
  return {
    calibration: 'accepted-e73-focused-and-composed-matrix',
    acceptance: CARBON_DIOXIDE_CORE_FOLD_VFX_ACCEPTANCE,
    scales, trueEightXExcluded: true,
    trueEightX: await auditEightXCarbonDioxideCoreFoldVfxExclusion(cdp, dpr),
  };
}

async function navigateCarbonDioxideCoreFoldVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    carbonDioxideBodyVfxAudit: '1', carbonDioxideCoreFoldVfxAudit: '1',
    renderScale: String(scale), renderLook: 'realistic', gasBodyVfx: '1',
    carbonDioxideBodyVfx: '1', carbonDioxideCoreFoldVfx: enabled ? '1' : '0',
    ...Object.fromEntries(CARBON_DIOXIDE_CORE_FOLD_VFX_ISOLATED_SELECTORS.map(
      (name) => [name, '0'],
    )),
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return p.get('carbonDioxideBodyVfxAudit') === '1'
      && p.get('carbonDioxideCoreFoldVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('gasBodyVfx') === '1'
      && p.get('carbonDioxideBodyVfx') === '1'
      && p.get('carbonDioxideCoreFoldVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && ${JSON.stringify(CARBON_DIOXIDE_CORE_FOLD_VFX_ISOLATED_SELECTORS)}
        .every((name) => p.get(name) === '0')
      && typeof audit?.prepareCarbonDioxideBodyVfxFixture === 'function'
      && typeof audit?.carbonDioxideBodyVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E73 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E73 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareCarbonDioxideBodyVfxFixture();
    return audit.carbonDioxideBodyVfxFixture();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E73 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => carbonDioxideBodyVfxFixtureReady(cdp, fixture),
    20_000, `E73 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const names = ${JSON.stringify(CARBON_DIOXIDE_CORE_FOLD_VFX_ISOLATED_SELECTORS)};
    return {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      carbonDioxideBodyVfx: canvas.dataset.carbonDioxideBodyVfx,
      carbonDioxideCoreFoldVfx: canvas.dataset.carbonDioxideCoreFoldVfx,
      isolatedSelectors: Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])),
    };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom
    && hdrPipeline.gasBodyVfx === 'active'
    && hdrPipeline.carbonDioxideBodyVfx === 'active'
    && hdrPipeline.carbonDioxideCoreFoldVfx === (enabled ? 'active' : 'inactive')
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive'),
  `E73 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E73 ${label} ${scale}x framebuffer`,
    scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await carbonDioxideCoreFoldVfxFieldDigest(cdp, fixture),
    walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, carbonDioxideCoreFoldVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(
      cdp, carbonDioxideCoreFoldVfxRawControlPoints(fixture),
    ),
    hdrPipeline,
  };
}

function carbonDioxideCoreFoldVfxTargetRegions(fixture) {
  const rect = (name, candidate, inset = 0) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - inset - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - inset - 0.2),
  });
  return [
    rect('CO2WholeBodyInset', fixture.target.body, 12),
    rect('CO2PositiveFold', { x: 84, y: 35, width: 16, height: 10 }),
    rect('CO2NegativeFold', { x: 102, y: 151, width: 16, height: 10 }),
  ];
}

function carbonDioxideCoreFoldVfxControlRegions(fixture) {
  return [
    ...carbonDioxideBodyVfxControlRegions(fixture),
    { name: 'CO2SoftRim', x: 160.5, y: 20.5, radius: 0 },
  ];
}

function carbonDioxideCoreFoldVfxAllRawPoints(fixture) {
  return [
    ...carbonDioxideCoreFoldVfxTargetRegions(fixture).map(({ name, x, y }) => ({
      name, x: Math.floor(x), y: Math.floor(y),
    })),
    ...carbonDioxideCoreFoldVfxRawControlPoints(fixture),
    { name: 'GasSeamCO2', ...fixture.gasSeam.gasProbe },
  ];
}

function carbonDioxideCoreFoldVfxRawControlPoints(fixture) {
  return carbonDioxideCoreFoldVfxControlRegions(fixture)
    // As in E44, the connected CO2 side is intentionally eligible up to the
    // unlike-gas seam; its composed one-byte rail is frozen separately.
    .filter(({ name }) => name !== 'GasSeamCO2')
    .map(({ name, x, y }) => ({ name, x: Math.floor(x), y: Math.floor(y) }));
}

function assertCarbonDioxideCoreFoldRawControlsInvariant(left, right, label) {
  const responses = carbonDioxideCoreFoldRawControlResponses(left, right);
  const same = left.length === right.length && responses.length === left.length
    && responses.every((response) => response.alphaExact
      && response.rgbPeak <= (
        CARBON_DIOXIDE_CORE_FOLD_VFX_RAW_CONTROL_PEAK[response.name] ?? 0
      ));
  assert(same,
    `${label}: E73 escaped an exact or bounded raw E44 control (${JSON.stringify({
      responses, left, right,
    })})`);
}

function carbonDioxideCoreFoldRawControlResponses(left, right) {
  return left.map((point, index) => {
    const candidate = right[index];
    const identityExact = candidate && point.name === candidate.name
      && point.x === candidate.x && point.y === candidate.y;
    const responseRgb = identityExact ? point.rgba.slice(0, 3).map(
      (value, channel) => candidate.rgba[channel] - value,
    ) : [Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY];
    return {
      name: point.name, x: point.x, y: point.y, identityExact,
      alphaExact: Boolean(identityExact && point.rgba[3] === candidate.rgba[3]),
      responseRgb,
      rgbPeak: Math.max(...responseRgb.map((value) => Math.abs(value))),
    };
  });
}

async function carbonDioxideCoreFoldVfxFieldDigest(cdp, fixture) {
  const inherited = await carbonDioxideBodyVfxFieldDigest(cdp, fixture);
  const points = [
    { name: 'CO2PositiveFold', x: 92, y: 40 },
    { name: 'CO2NegativeFold', x: 110, y: 156 },
    { name: 'CO2SoftRim', x: 160, y: 20 },
  ];
  const probes = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return ${JSON.stringify(points)}.map((point) => ({
      ...point, material: audit.cell(point.x, point.y),
      style: audit.gasIdentityStyle(point.x, point.y),
      alpha: Math.round(audit.atmosphereFieldAlpha(point.x, point.y) * 1000) / 1000,
    }));
  })()`);
  assert(probes.slice(0, 2).every((probe) => (
    probe.material === 41 && probe.style === 6 && probe.alpha === 255
  )), `E73 target probes lost exact dense style-6 ownership (${JSON.stringify(probes)})`);
  return { inherited, probes };
}

async function writeCarbonDioxideCoreFoldVfxScreenshots(
  source, scale, disabled, enabled, disabledRepeat,
) {
  const paths = {
    off: variantScreenshotPath(source, `e73-carbon-dioxide-core-fold-${scale}x-off`),
    on: variantScreenshotPath(source, `e73-carbon-dioxide-core-fold-${scale}x-on`),
    repeatedOff: variantScreenshotPath(
      source, `e73-carbon-dioxide-core-fold-${scale}x-repeated-off`,
    ),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  await writeFile(
    paths.repeatedOff, Buffer.from(disabledRepeat.capture.capture.data, 'base64'),
  );
  return paths;
}

async function auditEightXCarbonDioxideCoreFoldVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-carbon-dioxide-core-fold', carbonDioxideBodyVfxAudit: '1',
    carbonDioxideCoreFoldVfxAudit: '1', renderLook: 'realistic', gasBodyVfx: '1',
    carbonDioxideBodyVfx: '1', carbonDioxideCoreFoldVfx: '1',
    ...Object.fromEntries(CARBON_DIOXIDE_CORE_FOLD_VFX_ISOLATED_SELECTORS.map(
      (name) => [name, '0'],
    )),
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8'
      && p.get('auditStage') === 'eight-carbon-dioxide-core-fold'
      && p.get('gasBodyVfx') === '1' && p.get('carbonDioxideBodyVfx') === '1'
      && p.get('carbonDioxideCoreFoldVfx') === '1'
      && ${JSON.stringify(CARBON_DIOXIDE_CORE_FOLD_VFX_ISOLATED_SELECTORS)}
        .every((name) => p.get(name) === '0')
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E73 input audit API'),
  'true-8x E73 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E73', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E73');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E73 geometry')),
    'true-8x E73 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E73 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      carbonDioxideBodyVfx: canvas.dataset.carbonDioxideBodyVfx,
      carbonDioxideCoreFoldVfx: canvas.dataset.carbonDioxideCoreFoldVfx,
    } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E73 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.gasBodyVfx === 'inactive'
    && isolation.carbonDioxideBodyVfx === 'inactive'
    && isolation.carbonDioxideCoreFoldVfx === 'inactive',
  `true-8x E73 selector/resource isolation failed (${JSON.stringify(isolation)})`);
  const materialPlane = await evaluate(
    cdp, 'window.__ANIFOR_INPUT_AUDIT__.materialPlaneDigest()',
  );
  assert(materialPlane.occupied === 0,
    `true-8x E73 unexpectedly uploaded its dense fixture (${JSON.stringify(materialPlane)})`);
  const semanticBefore = await hdrVfxSemanticDigest(cdp);
  assert(semanticBefore.occupied === 0,
    `true-8x E73 material plane was not blank (${JSON.stringify(semanticBefore)})`);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E73 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(timing.source === 'gpu-fence',
    `true-8x E73 did not signal its GPU fence (${JSON.stringify(timing)})`);
  const semanticAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(semanticBefore, semanticAfter, 'true-8x E73 GPU completion');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8'
      && geometry.backend.backend === 'webgl',
    selectorExcluded: true, fixtureUploaded: false, semanticStable: true,
    materialPlane, isolation, timing,
  };
}

