/** E70: exact style-2 Steam gains a pearly crown and cool condensate pocket. */
async function auditSteamCondensateVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateSteamCondensateVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E70 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E70 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl'
        && variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.steamCondensateVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E70 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E70 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E70 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E70 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E70 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E70 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E70 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E70 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E70 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E70 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E70 ${scale}x changed an exact raw sibling/topology/contact/wall control (${JSON.stringify({
      disabled: disabled.rawControls, enabled: enabled.rawControls,
    })})`);
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E70 ${scale}x changed atmosphere ownership/density (${JSON.stringify(disabled.field)})`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E70 ${scale}x changed native-wall topology (${JSON.stringify(disabled.walls)})`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E70 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = steamCondensateVfxTargetRegions(fixture);
    const controls = steamCondensateVfxControlRegions(fixture);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const targetByName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(targetResponses.length === 4 && targetResponses.every((sample) => {
      const bounds = STEAM_CONDENSATE_VFX_ACCEPTANCE[sample.name];
      return bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1]
        && sample.meanBiasRatio >= bounds.meanBiasRatio[0]
        && sample.meanBiasRatio <= bounds.meanBiasRatio[1]
        && sample.responseMicroContrast >= bounds.responseMicroContrast[0]
        && sample.responseMicroContrast <= bounds.responseMicroContrast[1]
        && sample.repeatRgbPeak === 0;
    }), `E70 ${scale}x escaped its accepted Steam response (${JSON.stringify(targetResponses)})`);
    assert(targetByName.SteamCrown?.signedMean > 0.20
      && targetByName.SteamPocket?.signedMean < -0.20
      && new Set(targetResponses.map((sample) => sample.responseSignature)).size >= 3,
    `E70 ${scale}x lost its crown/pocket polarity or spatial variation (${JSON.stringify(targetResponses)})`);
    assert(targetByName.SteamCrown.responseRgb[0] >= targetByName.SteamCrown.responseRgb[2] + 1.50
      && targetByName.SteamPocket.responseRgb[0] <= targetByName.SteamPocket.responseRgb[2] - 1.50
      && targetByName.SteamBroad.responseRgb[2] >= targetByName.SteamBroad.responseRgb[0] + 0.50,
    `E70 ${scale}x lost its warm pearl/cool pocket hierarchy (${JSON.stringify(targetResponses)})`);
    // The effect is exact-style guarded. A small composed HDR footprint may
    // reach a neighbouring edge, but no protected control may become a body.
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (STEAM_CONDENSATE_VFX_LOCAL_CONTROL_PEAK[sample.name] ?? 0)
      && sample.repeatRgbPeak === 0),
      `E70 ${scale}x escaped a protected control (${JSON.stringify(controlResponses)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeSteamCondensateVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic,
      backing: disabled.geometry.backing, alphaSupport: disabled.backing,
      field: disabled.field, walls: disabled.walls, rawControls: disabled.rawControls,
      targetResponses, controlResponses, exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E70 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(sample.field)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls),
      `E70 ${sample.scale}x changed the exact fixture/field contract across output scales`);
    }
    const spread = (values) => Math.max(...values) - Math.min(...values);
    for (const name of ['SteamBroad', 'SteamCore', 'SteamCrown', 'SteamPocket']) {
      const samples = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
      assert(samples.every(Boolean)
        && spread(samples.map((sample) => sample.rgbRms)) <= 0.25
        && spread(samples.map((sample) => sample.chromaRms)) <= 0.25
        && spread(samples.map((sample) => sample.signedMean)) <= 0.25
        && spread(samples.map((sample) => sample.coverage)) <= 0.08
        && spread(samples.map((sample) => sample.rgbPeak)) <= 2,
      `E70 ${name} visual response drifted across output scales (${JSON.stringify(samples)})`);
    }
  }
  const trueEightX = await auditEightXSteamCondensateVfxExclusion(cdp, dpr);
  return { calibration: 'e70-steam-condensate-1x-4x', scales, trueEightXExcluded: true, trueEightX };
}

async function navigateSteamCondensateVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    steamCondensateVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    ...Object.fromEntries(STEAM_CONDENSATE_VFX_ISOLATED_SELECTORS.map((name) => [name, '0'])),
    gasBodyVfx: '1', steamCondensateVfx: enabled ? '1' : '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return p.get('steamCondensateVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('gasBodyVfx') === '1'
      && p.get('steamCondensateVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && ${JSON.stringify(STEAM_CONDENSATE_VFX_ISOLATED_SELECTORS)}.every((name) => p.get(name) === '0')
      && typeof audit?.prepareSteamCondensateVfxFixture === 'function'
      && typeof audit?.steamCondensateVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E70 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E70 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareSteamCondensateVfxFixture();
    return audit.steamCondensateVfxFixture();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E70 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => steamCondensateVfxFixtureReady(cdp, fixture),
    20_000, `E70 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    if (!canvas) return undefined;
    const names = ${JSON.stringify(STEAM_CONDENSATE_VFX_ISOLATED_SELECTORS)};
    return {
      look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      steamCondensateVfx: canvas.dataset.steamCondensateVfx,
      isolatedSelectors: Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])),
    };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.gasBodyVfx === 'active'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
    && hdrPipeline.steamCondensateVfx === (enabled ? 'active' : 'inactive'),
  `E70 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E70 ${label} ${scale}x framebuffer`,
    scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await steamCondensateVfxFieldDigest(cdp, fixture),
    walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, steamCondensateVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, steamCondensateVfxRawControlPoints(fixture)),
    hdrPipeline,
  };
}

async function steamCondensateVfxFixtureReady(cdp, fixture) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const fixture = ${JSON.stringify(fixture)};
    if (fixture.version !== 1 || fixture.world.width !== audit.width
      || fixture.world.height !== audit.height || fixture.target.material !== 15
      || fixture.target.atmosphereStyle !== 2
      || fixture.protectedGases.length !== 16
      || typeof audit?.gasIdentityStyle !== 'function'
      || typeof audit?.atmosphereFieldAlpha !== 'function') return false;
    const inside = (rect, x, y) => x >= rect.x && x < rect.x + rect.width
      && y >= rect.y && y < rect.y + rect.height;
    const centre = (rect) => ({
      x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2),
    });
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) {
        for (let x = rect.x; x < rect.x + rect.width; x++) {
          if (audit.cell(x, y) !== material) return false;
        }
      }
      return true;
    };
    const target = fixture.target;
    const radiusX = target.body.width * 0.5;
    const radiusY = target.body.height * 0.5;
    const centreX = target.body.x + radiusX;
    const centreY = target.body.y + radiusY;
    for (let y = target.body.y; y < target.body.y + target.body.height; y++) {
      for (let x = target.body.x; x < target.body.x + target.body.width; x++) {
        const normalizedX = Math.abs((x + 0.5 - centreX) / radiusX);
        const normalizedY = Math.abs((y + 0.5 - centreY) / radiusY);
        const empty = normalizedX ** 4 + normalizedY ** 4 > 1
          || inside(target.authoredVoid, x, y) || inside(target.openChannel, x, y);
        if (audit.cell(x, y) !== (empty ? 0 : target.material)) return false;
      }
    }
    const targetRegions = [target.broad, target.core, target.crown, target.pocket, ...target.shoulders];
    if (!targetRegions.every((rect) => exactRect(rect, target.material))
      || !exactRect(target.authoredVoid, 0) || !exactRect(target.openChannel, 0)) return false;
    if (!targetRegions.map(centre).every((point) => audit.gasIdentityStyle(point.x, point.y) === 2
      && audit.atmosphereFieldAlpha(point.x, point.y) === 255)) return false;
    if (!fixture.protectedGases.every((control) => exactRect(control.body, control.material)
      && audit.gasIdentityStyle(control.probe.x, control.probe.y) === control.atmosphereStyle)) return false;
    const sparse = fixture.sparseWisps;
    if (!sparse.carriers.every((point) => audit.cell(point.x, point.y) === sparse.material)
      || audit.cell(sparse.midpoint.x, sparse.midpoint.y) !== 0
      || audit.cell(sparse.gap.x, sparse.gap.y) !== 0
      || !exactRect(sparse.thin, sparse.material)
      || audit.cell(sparse.isolated.x, sparse.isolated.y) !== sparse.material) return false;
    return exactRect(fixture.gasSeam.steam, target.material)
      && exactRect(fixture.gasSeam.foreignGas, fixture.gasSeam.foreignMaterial)
      && audit.gasIdentityStyle(fixture.gasSeam.steamProbe.x, fixture.gasSeam.steamProbe.y) === 2
      && audit.gasIdentityStyle(fixture.gasSeam.foreignProbe.x, fixture.gasSeam.foreignProbe.y) === 10
      && exactRect(fixture.waterContact.steam, target.material)
      && exactRect(fixture.waterContact.water, 2)
      && exactRect(fixture.metalContact.steam, target.material)
      && exactRect(fixture.metalContact.metal, 23)
      && exactRect(fixture.nativeWall.steam, target.material)
      && audit.wall(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) === fixture.conductiveWall
      && audit.gasIdentityStyle(fixture.nativeWall.wallAnchor.x, fixture.nativeWall.wallAnchor.y) !== 2
      && exactRect(fixture.guardedBlank, 0)
      && audit.gasIdentityStyle(centre(fixture.guardedBlank).x, centre(fixture.guardedBlank).y) !== 2;
  })()`);
}

function steamCondensateVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true, x: candidate.x + candidate.width / 2,
    y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  return [
    rect('SteamBroad', fixture.target.broad), rect('SteamCore', fixture.target.core),
    rect('SteamCrown', fixture.target.crown), rect('SteamPocket', fixture.target.pocket),
  ];
}

function steamCondensateVfxControlRegions(fixture) {
  const point = (name, candidate) => ({
    name, x: Math.floor(candidate.x) + 0.5, y: Math.floor(candidate.y) + 0.5, radius: 0,
  });
  const rect = (name, candidate, inset = 0) => ({
    name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - inset - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - inset - 0.2),
  });
  return [
    rect('SteamAuthoredVoid', fixture.target.authoredVoid, 4),
    rect('SteamOpenChannel', fixture.target.openChannel, 4),
    ...fixture.protectedGases.map((control) => point(`Protected${control.code}`, control.probe)),
    ...fixture.sparseWisps.carriers.map((carrier, index) => point(`SparseCarrier${index + 1}`, carrier)),
    point('SparseMidpoint', fixture.sparseWisps.midpoint),
    point('SparseGap', fixture.sparseWisps.gap),
    point('SparseThin', {
      x: fixture.sparseWisps.thin.x,
      y: fixture.sparseWisps.thin.y + Math.floor(fixture.sparseWisps.thin.height / 2),
    }),
    point('SparseIsolated', fixture.sparseWisps.isolated),
    point('GasSeamSteam', fixture.gasSeam.steamProbe),
    point('GasSeamFOG', fixture.gasSeam.foreignProbe),
    point('WaterContactSteam', fixture.waterContact.steamProbe),
    point('WaterContactWater', fixture.waterContact.waterProbe),
    point('MetalContactSteam', fixture.metalContact.steamProbe),
    point('MetalContactMetal', fixture.metalContact.metalProbe),
    point('NativeWall', fixture.nativeWall.wallAnchor),
    rect('GuardedBlank', fixture.guardedBlank, 4),
  ];
}

function steamCondensateVfxAllRawPoints(fixture) {
  return [
    ...steamCondensateVfxTargetRegions(fixture).map((region) => ({
      name: region.name, x: Math.floor(region.x), y: Math.floor(region.y),
    })),
    ...steamCondensateVfxRawControlPoints(fixture),
    { name: 'SteamAuthoredVoid', x: fixture.target.authoredVoid.x + 8,
      y: fixture.target.authoredVoid.y + 8 },
    { name: 'SteamOpenChannel', x: fixture.target.openChannel.x + 8,
      y: fixture.target.openChannel.y + 12 },
    { name: 'GasSeamSteam', ...fixture.gasSeam.steamProbe },
    { name: 'WaterContactSteam', ...fixture.waterContact.steamProbe },
    { name: 'MetalContactSteam', ...fixture.metalContact.steamProbe },
  ];
}

function steamCondensateVfxRawControlPoints(fixture) {
  return steamCondensateVfxControlRegions(fixture)
    .filter((region) => !['SteamAuthoredVoid', 'SteamOpenChannel', 'GasSeamSteam',
      'WaterContactSteam', 'MetalContactSteam', 'SparseThin'].includes(region.name))
    .map((region) => ({ name: region.name, x: Math.floor(region.x), y: Math.floor(region.y) }));
}

async function steamCondensateVfxFieldDigest(cdp, fixture) {
  const points = [
    { name: 'SteamBroad', ...fixture.target.broad, centre: true },
    { name: 'SteamCore', ...fixture.target.core, centre: true },
    { name: 'SteamCrown', ...fixture.target.crown, centre: true },
    { name: 'SteamPocket', ...fixture.target.pocket, centre: true },
    ...fixture.protectedGases.map((control) => ({ name: control.code, ...control.probe })),
    { name: 'AuthoredVoid', ...fixture.target.authoredVoid, centre: true },
    { name: 'OpenChannel', ...fixture.target.openChannel, centre: true },
    ...fixture.sparseWisps.carriers.map((point, index) => ({ name: `SparseCarrier${index + 1}`, ...point })),
    { name: 'SparseMidpoint', ...fixture.sparseWisps.midpoint },
    { name: 'SparseGap', ...fixture.sparseWisps.gap },
    { name: 'SparseThin', x: fixture.sparseWisps.thin.x,
      y: fixture.sparseWisps.thin.y + Math.floor(fixture.sparseWisps.thin.height / 2) },
    { name: 'SparseIsolated', ...fixture.sparseWisps.isolated },
    { name: 'GasSeamSteam', ...fixture.gasSeam.steamProbe },
    { name: 'GasSeamFOG', ...fixture.gasSeam.foreignProbe },
    { name: 'WaterContactSteam', ...fixture.waterContact.steamProbe },
    { name: 'WaterContactWater', ...fixture.waterContact.waterProbe },
    { name: 'MetalContactSteam', ...fixture.metalContact.steamProbe },
    { name: 'MetalContactMetal', ...fixture.metalContact.metalProbe },
    { name: 'NativeWall', ...fixture.nativeWall.wallAnchor },
    { name: 'GuardedBlank', ...fixture.guardedBlank, centre: true },
  ];
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    return ${JSON.stringify(points)}.map((entry) => {
      const x = entry.centre ? entry.x + Math.floor(entry.width / 2) : entry.x;
      const y = entry.centre ? entry.y + Math.floor(entry.height / 2) : entry.y;
      return {
        name: entry.name, material: audit.cell(x, y), style: audit.gasIdentityStyle(x, y),
        alpha: Math.round(audit.atmosphereFieldAlpha(x, y) * 1000) / 1000,
      };
    });
  })()`);
}

async function writeSteamCondensateVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e70-steam-condensate-${scale}x-off`),
    on: variantScreenshotPath(source, `e70-steam-condensate-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXSteamCondensateVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-steam-condensate', steamCondensateVfxAudit: '1', renderLook: 'realistic',
    ...Object.fromEntries(STEAM_CONDENSATE_VFX_ISOLATED_SELECTORS.map((name) => [name, '0'])),
    gasBodyVfx: '1', steamCondensateVfx: '1',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8' && p.get('auditStage') === 'eight-steam-condensate'
      && p.get('gasBodyVfx') === '1' && p.get('steamCondensateVfx') === '1'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E70 input audit API'),
  'true-8x E70 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E70', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E70');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E70 geometry')),
    'true-8x E70 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E70 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? {
      renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null,
      gasBodyVfx: canvas.dataset.gasBodyVfx,
      steamCondensateVfx: canvas.dataset.steamCondensateVfx,
    } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E70 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8'
    && isolation.bloomBacking === null && isolation.gasBodyVfx === 'inactive'
    && isolation.steamCondensateVfx === 'inactive',
  `true-8x E70 isolation failed (${JSON.stringify(isolation)})`);
  const stateBefore = await hdrVfxSemanticDigest(cdp);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E70 GPU completion');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E70 did not complete GPU work (${JSON.stringify(timing)})`);
  const stateAfter = await hdrVfxSemanticDigest(cdp);
  assertHdrVfxSemanticEquality(stateBefore, stateAfter, 'true-8x E70 GPU completion');
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8' && geometry.backend.backend === 'webgl',
    selectorExcluded: true, resourcesIdentical: isolation.bloomBacking === null,
    semanticStable: true, isolation, timing,
  };
}

// E57 freezes a broad, low-microcontrast response. Separate core/crown/pocket
// envelopes make a whole-body tint or stamped high-frequency noise insufficient.
const FOG_CORE_DIFFUSE_VFX_ACCEPTANCE = Object.freeze({
  FOGBroadBody: Object.freeze({
    rgbRms: [1.95, 2.20], chromaRms: [0.25, 0.45], rgbPeak: [5, 7],
    coverage: [0.70, 0.80], signedMean: [-1.60, -1.30],
    meanBiasRatio: [0.68, 0.76], responseMicroContrast: [0.12, 0.26],
  }),
  FOGDeepCore: Object.freeze({
    rgbRms: [3.80, 4.05], chromaRms: [0.32, 0.52], rgbPeak: [5, 7],
    coverage: [0.78, 0.87], signedMean: [3.38, 3.62],
    meanBiasRatio: [0.87, 0.92], responseMicroContrast: [0.15, 0.29],
  }),
  FOGCrown: Object.freeze({
    rgbRms: [4.90, 5.15], chromaRms: [0.35, 0.56], rgbPeak: [5, 7],
    coverage: [0.98, 1.00], signedMean: [4.85, 5.10],
    meanBiasRatio: [0.98, 1.00], responseMicroContrast: [0.12, 0.25],
  }),
  FOGPocket: Object.freeze({
    rgbRms: [2.65, 2.90], chromaRms: [0.24, 0.45], rgbPeak: [3, 5],
    coverage: [0.98, 1.00], signedMean: [-2.85, -2.60],
    meanBiasRatio: [0.97, 1.00], responseMicroContrast: [0.08, 0.22],
  }),
});
const FOG_CORE_DIFFUSE_VFX_LOCAL_CONTROL_PEAK = Object.freeze({
  // The eligible FOG shoulder keeps E57's connected-core treatment, but the
  // exact species seam must remain a bounded local response rather than
  // spreading that treatment across the interface.
  GasSeamFOG: 7,
  // The exact foreign CO2 pixel remains raw-RGB identical. The composed point
  // shares the compact HDR footprint of the eligible FOG side of the seam.
  GasSeamCO2: 2,
});

/** E57: exact style-10 FOG diffuse core over E04's connected atmosphere body. */
async function auditFogCoreDiffuseVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateFogCoreDiffuseVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const atlas = disabled.atlas;
    assert(JSON.stringify(atlas) === JSON.stringify(enabled.atlas)
      && JSON.stringify(atlas) === JSON.stringify(disabledRepeat.atlas),
    `E57 ${scale}x atlas metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E57 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl'
        && variant.hdrPipeline?.state === 'active'
        && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.fogCoreDiffuseVfx === (label === 'enabled' ? 'active' : 'inactive'),
      `E57 ${label} ${scale}x selector/HDR state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E57 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E57 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E57 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E57 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic, `E57 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing, `E57 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing, `E57 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll, `E57 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll, `E57 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E57 ${scale}x changed an exact raw sibling/topology/contact/wall control`);
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E57 ${scale}x changed exact semantic/style/atmosphere-alpha ownership`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E57 ${scale}x changed native-wall topology`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E57 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = fogCoreDiffuseVfxTargetRegions(atlas);
    const controls = fogCoreDiffuseVfxControlRegions(atlas);
    const responses = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    // Preserve requested visual evidence before the provisional response gate.
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeFogCoreDiffuseVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    const targetByName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(targetResponses.length === 4 && targetResponses.every((sample) => {
      const bounds = FOG_CORE_DIFFUSE_VFX_ACCEPTANCE[sample.name];
      return bounds
        && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1]
        && sample.meanBiasRatio >= bounds.meanBiasRatio[0]
        && sample.meanBiasRatio <= bounds.meanBiasRatio[1]
        && sample.responseMicroContrast >= bounds.responseMicroContrast[0]
        && sample.responseMicroContrast <= bounds.responseMicroContrast[1]
        && sample.repeatRgbPeak === 0;
    }), `E57 ${scale}x escaped its accepted FOG core response (${JSON.stringify(targetResponses)})`);
    assert(targetByName.FOGBroadBody?.positiveMean >= 0.15
      && targetByName.FOGBroadBody?.negativeMean >= 1.50
      && targetByName.FOGDeepCore?.signedMean > 3.0
      && targetByName.FOGCrown?.signedMean > 4.5
      && targetByName.FOGPocket?.signedMean < -2.4
      && new Set(targetResponses.map(({ responseSignature }) => responseSignature)).size === 4,
    `E57 ${scale}x lost broad bipolar volume hierarchy (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (FOG_CORE_DIFFUSE_VFX_LOCAL_CONTROL_PEAK[sample.name] ?? 0)
      && sample.repeatRgbPeak === 0),
      `E57 ${scale}x escaped an exact sibling/topology/contact/wall control (${JSON.stringify(controlResponses)})`);
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic, backing: disabled.geometry.backing,
      alphaSupport: disabled.backing, field: disabled.field, walls: disabled.walls,
      rawControls: disabled.rawControls, targetResponses, controlResponses, exactRepeatedOff: true,
      screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    for (const sample of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, sample.geometry.canvas,
        `E57 ${reference.scale}x/${sample.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(sample.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(sample.field)
        && JSON.stringify(reference.walls) === JSON.stringify(sample.walls),
      `E57 ${sample.scale}x changed the exact fixture/field contract across output scales`);
    }
    const spread = (values) => Math.max(...values) - Math.min(...values);
    for (const name of Object.keys(FOG_CORE_DIFFUSE_VFX_ACCEPTANCE)) {
      const samples = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
      assert(samples.every(Boolean)
        && spread(samples.map((sample) => sample.rgbRms)) <= 0.03
        && spread(samples.map((sample) => sample.chromaRms)) <= 0.04
        && spread(samples.map((sample) => sample.signedMean)) <= 0.04
        && spread(samples.map((sample) => sample.coverage)) <= 0.02
        && spread(samples.map((sample) => sample.responseMicroContrast)) <= 0.04
        && spread(samples.map((sample) => sample.rgbPeak)) <= 1,
      `E57 ${name} visual response drifted across output scales (${JSON.stringify(samples)})`);
    }
  }
  const trueEightX = await auditEightXFogCoreDiffuseVfxExclusion(cdp, dpr);
  return {
    calibration: 'e57-frozen-1x-4x', acceptance: FOG_CORE_DIFFUSE_VFX_ACCEPTANCE,
    scales, trueEightXExcluded: true, trueEightX,
  };
}

async function navigateFogCoreDiffuseVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    fogCoreDiffuseVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '0', fogCoreDiffuseVfx: enabled ? '1' : '0',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0', gasLightVfx: '0',
    liquidSolidMeniscusVfx: '0', metalWaterContactVfx: '0', waterMetalTransmissionVfx: '0',
    waterMetalSeparationVfx: '0',
    gasCoreDepthVfx: '0', nobleGasBillowVfx: '0', nobleGasPrismVfx: '0',
    smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0', glassBodyVfx: '0',
    oilBodyVfx: '0', rockRoughnessVfx: '0', rockMesostructureVfx: '0', waterBodyVfx: '0', acidBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'hydrogenBodyVfx',
      'carbonDioxideBodyVfx', 'gasMotionVfx', 'powderBodyVfx', 'powderLightVfx',
      'powderSolidContactVfx', 'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx',
      'gasLightVfx', 'liquidSolidMeniscusVfx', 'metalWaterContactVfx', 'waterMetalTransmissionVfx',
      'waterMetalSeparationVfx',
      'gasCoreDepthVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
      'smokeBillowDepthVfx', 'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx',
      'ceramicGlazeVfx', 'botanicalBodyVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
      'rockMesostructureVfx', 'waterBodyVfx', 'acidBodyVfx'];
    return p.get('fogCoreDiffuseVfxAudit') === '1' && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('gasBodyVfx') === '1'
      && p.get('fogCoreDiffuseVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareFogCoreDiffuseVfxFixture === 'function'
      && typeof audit?.fogCoreDiffuseVfxAtlas === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E57 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E57 ${label} ${scale}x backend`);
  const atlas = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareFogCoreDiffuseVfxFixture();
    return audit.fogCoreDiffuseVfxAtlas();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E57 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => fogCoreDiffuseVfxAtlasReady(cdp, atlas), 20_000,
    `E57 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await fogCoreDiffuseVfxPipelineState(cdp);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.gasBodyVfx === 'active'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive')
    && hdrPipeline.fogCoreDiffuseVfx === (enabled ? 'active' : 'inactive'),
  `E57 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(cdp, `E57 ${label} ${scale}x framebuffer`,
    scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1);
  return {
    atlas, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await fogCoreDiffuseVfxFieldDigest(cdp, atlas), walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, fogCoreDiffuseVfxAllRawPoints(atlas)),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, fogCoreDiffuseVfxRawControlPoints(atlas)),
    hdrPipeline,
  };
}

async function fogCoreDiffuseVfxAtlasReady(cdp, atlas) {
  return evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__; const atlas = ${JSON.stringify(atlas)};
    if (atlas.version !== 1 || atlas.world.width !== audit.width || atlas.world.height !== audit.height
      || atlas.target.code !== 'FOG' || atlas.target.atmosphereStyle !== 10
      || typeof audit?.gasIdentityStyle !== 'function' || typeof audit?.atmosphereFieldAlpha !== 'function') return false;
    const centre = (rect) => ({ x: rect.x + Math.floor(rect.width / 2), y: rect.y + Math.floor(rect.height / 2) });
    const exactRect = (rect, material) => {
      for (let y = rect.y; y < rect.y + rect.height; y++) for (let x = rect.x; x < rect.x + rect.width; x++) {
        if (audit.cell(x, y) !== material) return false;
      } return true;
    };
    const target = atlas.target;
    if (!exactRect(target.deepCore, target.material) || !exactRect(target.authoredVoid, 0)
      || !exactRect(target.openChannel, 0) || !target.billowProbes.every((probe) => exactRect(probe.region, target.material))) return false;
    const targetPoints = [centre(target.deepCore), ...target.billowProbes.map(({ centre }) => centre)];
    if (!targetPoints.every((point) => audit.gasIdentityStyle(point.x, point.y) === 10
      && audit.atmosphereFieldAlpha(point.x, point.y) === 255)) return false;
    return atlas.protectedGases.every((control) => exactRect(control.body, control.material)
      && audit.gasIdentityStyle(control.probe.x, control.probe.y) === control.atmosphereStyle)
      && atlas.sparse.carriers.every((point) => audit.cell(point.x, point.y) === atlas.sparse.material)
      && audit.cell(atlas.sparse.midpoint.x, atlas.sparse.midpoint.y) === 0
      && audit.cell(atlas.sparse.gap.x, atlas.sparse.gap.y) === 0
      && audit.cell(atlas.sparse.isolated.x, atlas.sparse.isolated.y) === atlas.sparse.material
      && target.billowProbes[0].billow > 0 && target.billowProbes[1].billow < 0
      && exactRect(atlas.gasSeam.gas, target.material)
      && exactRect(atlas.gasSeam.foreignGas, atlas.gasSeam.foreignMaterial)
      && audit.gasIdentityStyle(atlas.gasSeam.gasProbe.x, atlas.gasSeam.gasProbe.y) === 10
      && audit.gasIdentityStyle(atlas.gasSeam.foreignProbe.x, atlas.gasSeam.foreignProbe.y) === 6
      && exactRect(atlas.waterContact.gas, target.material) && exactRect(atlas.waterContact.water, 2)
      && exactRect(atlas.metalContact.gas, target.material) && exactRect(atlas.metalContact.metal, 23)
      && exactRect(atlas.nativeWall.gas, target.material)
      && audit.wall(atlas.nativeWall.wallAnchor.x, atlas.nativeWall.wallAnchor.y) === atlas.conductiveWall
      && exactRect(atlas.guardedBlank, 0);
  })()`);
}

async function fogCoreDiffuseVfxPipelineState(cdp, timeout) {
  return evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas'); if (!canvas) return undefined;
    const names = ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'hydrogenBodyVfx',
      'carbonDioxideBodyVfx', 'gasMotionVfx', 'powderBodyVfx', 'powderLightVfx',
      'powderSolidContactVfx', 'translucentEdgeVfx', 'organicSubsurfaceVfx', 'wetSedimentVfx',
      'gasLightVfx', 'liquidSolidMeniscusVfx', 'metalWaterContactVfx', 'waterMetalTransmissionVfx',
      'waterMetalSeparationVfx',
      'gasCoreDepthVfx', 'nobleGasBillowVfx', 'nobleGasPrismVfx', 'smokeSoftnessVfx',
      'smokeBillowDepthVfx', 'plasmaCoreVfx', 'solidBodyVfx', 'platinumBodyVfx',
      'ceramicGlazeVfx', 'botanicalBodyVfx', 'glassBodyVfx', 'oilBodyVfx', 'rockRoughnessVfx',
      'rockMesostructureVfx', 'waterBodyVfx', 'acidBodyVfx'];
    return { renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking ?? null,
      gasBodyVfx: canvas.dataset.gasBodyVfx, fogCoreDiffuseVfx: canvas.dataset.fogCoreDiffuseVfx,
      isolatedSelectors: Object.fromEntries(names.map((name) => [name, canvas.dataset[name]])) };
  })()`, timeout);
}

function fogCoreDiffuseVfxTargetRegions(atlas) {
  const rect = (name, candidate) => ({ name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2), radiusY: Math.max(0.35, candidate.height / 2 - 0.2) });
  const broadBody = { x: atlas.target.body.x + 24, y: atlas.target.body.y + 96, width: 100, height: 40 };
  return [rect('FOGBroadBody', broadBody), rect('FOGDeepCore', atlas.target.deepCore),
    ...atlas.target.billowProbes.map((probe) => rect(`FOG${probe.code === 'CROWN' ? 'Crown' : 'Pocket'}`, probe.region))];
}

function fogCoreDiffuseVfxControlRegions(atlas) {
  const point = (name, candidate) => ({ name, x: Math.floor(candidate.x) + 0.5, y: Math.floor(candidate.y) + 0.5, radius: 0 });
  const rect = (name, candidate, inset = 0) => ({ name, x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - inset - 0.2), radiusY: Math.max(0.35, candidate.height / 2 - inset - 0.2) });
  return [rect('FOGAuthoredVoid', atlas.target.authoredVoid, 4), rect('FOGOpenChannel', atlas.target.openChannel, 4),
    ...atlas.protectedGases.map((control) => point(`Protected${control.code}`, control.probe)),
    ...atlas.sparse.carriers.map((pointAt, index) => point(`SparseCarrier${index + 1}`, pointAt)),
    point('SparseMidpoint', atlas.sparse.midpoint), point('SparseGap', atlas.sparse.gap), point('SparseIsolated', atlas.sparse.isolated),
    point('GasSeamFOG', atlas.gasSeam.gasProbe), point('GasSeamCO2', atlas.gasSeam.foreignProbe),
    point('WaterContactFOG', atlas.waterContact.gasProbe),
    point('WaterContactWater', atlas.waterContact.waterProbe), point('MetalContactFOG', atlas.metalContact.gasProbe),
    point('MetalContactMetal', atlas.metalContact.metalProbe), point('NativeWall', atlas.nativeWall.wallAnchor),
    rect('GuardedBlank', atlas.guardedBlank, 4)];
}

function fogCoreDiffuseVfxAllRawPoints(atlas) {
  return [...fogCoreDiffuseVfxTargetRegions(atlas).map((region) => ({ name: region.name, x: Math.floor(region.x), y: Math.floor(region.y) })),
    ...fogCoreDiffuseVfxRawControlPoints(atlas),
    { name: 'GasSeamFOG', ...atlas.gasSeam.gasProbe }];
}

function fogCoreDiffuseVfxRawControlPoints(atlas) {
  return fogCoreDiffuseVfxControlRegions(atlas)
    .filter(({ name }) => name !== 'GasSeamFOG')
    .map((region) => ({ name: region.name, x: Math.floor(region.x), y: Math.floor(region.y) }));
}

async function fogCoreDiffuseVfxFieldDigest(cdp, atlas) {
  const points = [
    { name: 'FOGDeepCore', ...atlas.target.deepCore, centre: true },
    ...atlas.target.billowProbes.map((probe) => ({ name: `FOG${probe.code}`, ...probe.centre })),
    ...atlas.protectedGases.map((control) => ({ name: control.code, ...control.probe })),
    { name: 'AuthoredVoid', ...atlas.target.authoredVoid, centre: true }, { name: 'OpenChannel', ...atlas.target.openChannel, centre: true },
    ...atlas.sparse.carriers.map((pointAt, index) => ({ name: `SparseCarrier${index + 1}`, ...pointAt })),
    { name: 'SparseMidpoint', ...atlas.sparse.midpoint }, { name: 'SparseGap', ...atlas.sparse.gap }, { name: 'SparseIsolated', ...atlas.sparse.isolated },
    { name: 'GasSeamFOG', ...atlas.gasSeam.gasProbe }, { name: 'GasSeamCO2', ...atlas.gasSeam.foreignProbe },
    { name: 'WaterContactFOG', ...atlas.waterContact.gasProbe }, { name: 'WaterContactWater', ...atlas.waterContact.waterProbe },
    { name: 'MetalContactFOG', ...atlas.metalContact.gasProbe }, { name: 'MetalContactMetal', ...atlas.metalContact.metalProbe },
    { name: 'NativeWall', ...atlas.nativeWall.wallAnchor }, { name: 'GuardedBlank', ...atlas.guardedBlank, centre: true },
  ];
  return evaluate(cdp, `(() => { const audit = window.__ANIFOR_INPUT_AUDIT__; return ${JSON.stringify(points)}.map((entry) => {
    const x = entry.centre ? entry.x + Math.floor(entry.width / 2) : entry.x;
    const y = entry.centre ? entry.y + Math.floor(entry.height / 2) : entry.y;
    return { name: entry.name, material: audit.cell(x, y), style: audit.gasIdentityStyle(x, y), alpha: Math.round(audit.atmosphereFieldAlpha(x, y) * 1000) / 1000 };
  }); })()`);
}

async function writeFogCoreDiffuseVfxScreenshots(source, scale, disabled, enabled) {
  const paths = { off: variantScreenshotPath(source, `e57-fog-core-diffuse-${scale}x-off`), on: variantScreenshotPath(source, `e57-fog-core-diffuse-${scale}x-on`) };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXFogCoreDiffuseVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({ scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-fog-core-diffuse', fogCoreDiffuseVfxAudit: '1', renderLook: 'realistic',
    gasBodyVfx: '1', fogCoreDiffuseVfx: '1', gasLightVfx: '0', gasCoreDepthVfx: '0', nobleGasBillowVfx: '0',
    nobleGasPrismVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', hydrogenBodyVfx: '0', carbonDioxideBodyVfx: '0' });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => { const p = new URLSearchParams(location.search); return p.get('renderScale') === '8'
    && p.get('auditStage') === 'eight-fog-core-diffuse' && p.get('gasBodyVfx') === '1' && p.get('fogCoreDiffuseVfx') === '1'
    && Boolean(window.__ANIFOR_INPUT_AUDIT__); })()`), remainingDeadlineMs(deadline, 'true-8x E57 input audit API'), 'true-8x E57 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E57', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E57');
  const geometry = await waitForStableCanvas(cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E57 geometry')), 'true-8x E57 geometry');
  assert(geometry.backing.width === WORLD_WIDTH * 8 && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
    `true-8x E57 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await fogCoreDiffuseVfxPipelineState(cdp, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E57 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && isolation.gasBodyVfx === 'inactive' && isolation.fogCoreDiffuseVfx === 'inactive',
  `true-8x E57 E04/E57/HDR exclusion failed (${JSON.stringify(isolation)})`);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E57 GPU completion');
  const timing = await auditWebGLPresentationTiming(cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1);
  assert(['gpu-query', 'gpu-fence', 'gpu-finish'].includes(timing.source),
    `true-8x E57 did not complete GPU work (${JSON.stringify(timing)})`);
  return { backing: `${geometry.backing.width}x${geometry.backing.height}`, promotedWebGLObserved: geometry.outputScale === '8' && geometry.backend.backend === 'webgl', selectorExcluded: true, promotionFence: 'signaled', isolation, timing };
}

// E31's accepted SwiftShader matrix freezes a broad spatial response rather
// than merely requiring nonzero pixels. The positive key and negative pocket
// have separate bounds; a whole-body tint cannot satisfy both. E25's accepted
// bounds remain untouched.
const NOBLE_GAS_PRISM_VFX_ACCEPTANCE = Object.freeze({
  NOBLPrismKey: Object.freeze({
    rgbRms: [6.70, 7.40], chromaRms: [1.35, 1.80], rgbPeak: [8, 10],
    signedMean: [7.30, 8.00], coverage: [0.98, 1.00],
    spatialRgbRms: [0.45, 0.82], responseMicroContrast: [0.15, 0.38],
  }),
  NOBLPrismPocket: Object.freeze({
    rgbRms: [0.70, 1.10], chromaRms: [0.35, 0.65], rgbPeak: [2, 3],
    signedMean: [-0.98, -0.60], coverage: [0.08, 0.18],
    spatialRgbRms: [0.40, 0.68], responseMicroContrast: [0.18, 0.45],
  }),
  broad: Object.freeze({
    rgbRms: [5.30, 5.90], chromaRms: [1.10, 1.50], rgbPeak: [8, 10],
    signedMean: [5.25, 5.90], meanBiasRatio: [0.88, 0.94],
    spatialRgbRms: [2.15, 2.50], spatialShare: [0.38, 0.46],
    responseMicroContrast: [0.18, 0.45],
  }),
  crossScale: Object.freeze({
    rgbRms: 0.08, chromaRms: 0.08, signedMean: 0.15,
    coverage: 0.05, spatialRgbRms: 0.15, responseMicroContrast: 0.15,
    broadRgbRms: 0.08, broadSpatialRgbRms: 0.08,
  }),
});

// Raw controls remain exact. The accepted HDR filter may carry only these
// named, local composed footprints from the eligible Noble side of the scene.
const NOBLE_GAS_PRISM_VFX_LOCAL_CONTROL_PEAK = Object.freeze({
  NOBLAuthoredVoid: 1,
  NOBLOpenChannel: 1,
  GasSeamNoble: 3,
  GasSeamFOG: 1,
});

function nobleGasPrismVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  // Both regions are strictly inside E25's exact fully-dense core. The first
  // mirrors a strong positive E04 billow/wave-C phase; the second mirrors the
  // opposing third-wave phase. This makes a shared whole-body tint insufficient.
  return [
    rect('NOBLPrismKey', { x: 74, y: 88, width: 10, height: 12 }),
    rect('NOBLPrismPocket', { x: 96, y: 82, width: 4, height: 6 }),
  ];
}

function nobleGasPrismVfxBroadRegion(fixture) {
  const candidate = fixture.target.deepCore;
  return {
    name: 'NOBLPrismDeepBody', target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  };
}

function withSpatialRgbRms(samples) {
  return samples.map((sample) => {
    const meanRgbRms = Math.hypot(...sample.responseRgb) / Math.sqrt(3);
    return {
      ...sample,
      spatialRgbRms: round(Math.sqrt(Math.max(0, sample.rgbRms ** 2 - meanRgbRms ** 2)), 3),
    };
  });
}

/** E31: calibrated exact-Noble inner-volume prism response over E04/E25. */
async function auditNobleGasPrismVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateNobleGasPrismVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E31 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E31 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl', `E31 ${label} ${scale}x lost WebGL presentation`);
      assert(variant.hdrPipeline?.state === 'active' && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.nobleGasBillowVfx === 'active'
        && variant.hdrPipeline.nobleGasPrismVfx === (label === 'enabled' ? 'active' : 'inactive')
        && Object.values(variant.hdrPipeline.isolatedSelectors).every((state) => state === 'inactive'),
      `E31 ${label} ${scale}x parent/selector state was wrong (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E31 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E31 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E31 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E31 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E31 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E31 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E31 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E31 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E31 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E31 ${scale}x changed an exact raw control`);
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E31 ${scale}x changed E04 atmosphere ownership/density`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E31 ${scale}x changed native-wall topology`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E31 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = nobleGasPrismVfxTargetRegions(fixture);
    const controls = nobleGasBillowVfxControlRegions(fixture);
    const sampled = await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect);
    const responses = withSpatialRgbRms(sampled);
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const acceptance = NOBLE_GAS_PRISM_VFX_ACCEPTANCE;
    assert(targetResponses.length === 2 && targetResponses.every((sample) => sample
      && acceptance[sample.name]
      && sample.rgbRms >= acceptance[sample.name].rgbRms[0]
      && sample.rgbRms <= acceptance[sample.name].rgbRms[1]
      && sample.chromaRms >= acceptance[sample.name].chromaRms[0]
      && sample.chromaRms <= acceptance[sample.name].chromaRms[1]
      && sample.rgbPeak >= acceptance[sample.name].rgbPeak[0]
      && sample.rgbPeak <= acceptance[sample.name].rgbPeak[1]
      && sample.signedMean >= acceptance[sample.name].signedMean[0]
      && sample.signedMean <= acceptance[sample.name].signedMean[1]
      && sample.coverage >= acceptance[sample.name].coverage[0]
      && sample.coverage <= acceptance[sample.name].coverage[1]
      && sample.spatialRgbRms >= acceptance[sample.name].spatialRgbRms[0]
      && sample.spatialRgbRms <= acceptance[sample.name].spatialRgbRms[1]
      && sample.responseMicroContrast >= acceptance[sample.name].responseMicroContrast[0]
      && sample.responseMicroContrast <= acceptance[sample.name].responseMicroContrast[1]
      && sample.repeatRgbPeak === 0),
    `E31 ${scale}x prism targets were inert, flat, or unbounded (${JSON.stringify(targetResponses)})`);
    const byName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(byName.NOBLPrismKey?.signedMean > 0 && byName.NOBLPrismPocket?.signedMean < 0,
      `E31 ${scale}x lost its deep-body key/pocket polarity (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (NOBLE_GAS_PRISM_VFX_LOCAL_CONTROL_PEAK[sample.name] ?? 0)
      && sample.repeatRgbPeak === 0),
    `E31 ${scale}x escaped an E25 topology/sibling/contact/wall control (${JSON.stringify(controlResponses)})`);

    const [broad] = withSpatialRgbRms(await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [nobleGasPrismVfxBroadRegion(fixture)], disabled.capture.canvasRect));
    const broadBounds = NOBLE_GAS_PRISM_VFX_ACCEPTANCE.broad;
    const broadSpatialShare = broad.spatialRgbRms / Math.max(0.001, broad.rgbRms);
    assert(broad.rgbRms >= broadBounds.rgbRms[0] && broad.rgbRms <= broadBounds.rgbRms[1]
      && broad.chromaRms >= broadBounds.chromaRms[0]
      && broad.chromaRms <= broadBounds.chromaRms[1]
      && broad.rgbPeak >= broadBounds.rgbPeak[0] && broad.rgbPeak <= broadBounds.rgbPeak[1]
      && broad.signedMean >= broadBounds.signedMean[0]
      && broad.signedMean <= broadBounds.signedMean[1]
      && broad.spatialRgbRms >= broadBounds.spatialRgbRms[0]
      && broad.spatialRgbRms <= broadBounds.spatialRgbRms[1]
      && broadSpatialShare >= broadBounds.spatialShare[0]
      && broadSpatialShare <= broadBounds.spatialShare[1]
      && broad.meanBiasRatio >= broadBounds.meanBiasRatio[0]
      && broad.meanBiasRatio <= broadBounds.meanBiasRatio[1]
      && broad.responseMicroContrast >= broadBounds.responseMicroContrast[0]
      && broad.responseMicroContrast <= broadBounds.responseMicroContrast[1]
      && broad.repeatRgbPeak === 0,
    `E31 ${scale}x reduced to a flat, noisy, or unstable deep-body tint (${JSON.stringify(broad)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeNobleGasPrismVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic, backing: disabled.geometry.backing,
      alphaSupport: disabled.backing, field: disabled.field, walls: disabled.walls,
      rawControls: disabled.rawControls, targetResponses, controlResponses, broad,
      exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    const spread = (values) => Math.max(...values) - Math.min(...values);
    for (const entry of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, entry.geometry.canvas,
        `E31 ${reference.scale}x/${entry.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(entry.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(entry.field)
        && JSON.stringify(reference.walls) === JSON.stringify(entry.walls),
      `E31 ${entry.scale}x changed the exact fixture/field contract across output scales`);
    }
    const bounds = NOBLE_GAS_PRISM_VFX_ACCEPTANCE.crossScale;
    for (const name of ['NOBLPrismKey', 'NOBLPrismPocket']) {
      const samples = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
      assert(samples.every(Boolean)
        && spread(samples.map((sample) => sample.rgbRms)) <= bounds.rgbRms
        && spread(samples.map((sample) => sample.chromaRms)) <= bounds.chromaRms
        && spread(samples.map((sample) => sample.signedMean)) <= bounds.signedMean
        && spread(samples.map((sample) => sample.coverage)) <= bounds.coverage
        && spread(samples.map((sample) => sample.spatialRgbRms)) <= bounds.spatialRgbRms
        && spread(samples.map((sample) => sample.responseMicroContrast))
          <= bounds.responseMicroContrast,
      `E31 ${name} response drifted excessively across output scales (${JSON.stringify(samples)})`);
    }
    assert(spread(scales.map((entry) => entry.broad.rgbRms)) <= bounds.broadRgbRms
      && spread(scales.map((entry) => entry.broad.spatialRgbRms)) <= bounds.broadSpatialRgbRms,
    `E31 broad response drifted excessively across output scales (${JSON.stringify(
      scales.map(({ scale, broad }) => ({ scale, broad }))
    )})`);
  }
  const trueEightX = await auditEightXNobleGasPrismVfxExclusion(cdp, dpr);
  return {
    calibration: 'accepted-prismatic-inner-volume',
    acceptance: NOBLE_GAS_PRISM_VFX_ACCEPTANCE,
    scales,
    trueEightXExcluded: true, trueEightX,
  };
}

async function navigateNobleGasPrismVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    nobleGasPrismVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0',
    gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '1', nobleGasPrismVfx: enabled ? '1' : '0', nobleGasCoreReliefVfx: '0',
    smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0',
    ceramicGlazeVfx: '0', botanicalBodyVfx: '0', botanicalMesostructureVfx: '0',
    botanicalPigmentVfx: '0', woodBarkReliefVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0',
    rockRoughnessVfx: '0', rockMesostructureVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasMotionVfx',
      'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx',
      'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx', 'liquidSolidMeniscusVfx',
      'gasCoreDepthVfx', 'nobleGasCoreReliefVfx', 'smokeSoftnessVfx', 'smokeBillowDepthVfx', 'plasmaCoreVfx', 'solidBodyVfx',
      'platinumBodyVfx', 'ceramicGlazeVfx', 'botanicalBodyVfx', 'botanicalMesostructureVfx',
      'botanicalPigmentVfx', 'woodBarkReliefVfx', 'glassBodyVfx', 'oilBodyVfx',
      'rockRoughnessVfx', 'rockMesostructureVfx', 'waterBodyVfx'];
    return p.get('nobleGasPrismVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))}
      && p.get('renderLook') === 'realistic' && p.get('gasBodyVfx') === '1'
      && p.get('nobleGasBillowVfx') === '1'
      && p.get('nobleGasPrismVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareNobleGasBillowVfxFixture === 'function'
      && typeof audit?.nobleGasBillowVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E31 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E31 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareNobleGasBillowVfxFixture(); return audit.nobleGasBillowVfxFixture();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E31 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => nobleGasBillowVfxFixtureReady(cdp, fixture),
    20_000, `E31 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas'); if (!canvas) return undefined;
    const isolatedSelectors = {
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx, gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx, powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx, wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx, smokeSoftnessVfx: canvas.dataset.smokeSoftnessVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx, solidBodyVfx: canvas.dataset.solidBodyVfx,
      platinumBodyVfx: canvas.dataset.platinumBodyVfx, ceramicGlazeVfx: canvas.dataset.ceramicGlazeVfx,
      botanicalBodyVfx: canvas.dataset.botanicalBodyVfx,
      botanicalMesostructureVfx: canvas.dataset.botanicalMesostructureVfx,
      botanicalPigmentVfx: canvas.dataset.botanicalPigmentVfx,
      woodBarkReliefVfx: canvas.dataset.woodBarkReliefVfx, glassBodyVfx: canvas.dataset.glassBodyVfx,
      oilBodyVfx: canvas.dataset.oilBodyVfx, rockRoughnessVfx: canvas.dataset.rockRoughnessVfx,
      rockMesostructureVfx: canvas.dataset.rockMesostructureVfx, waterBodyVfx: canvas.dataset.waterBodyVfx,
    };
    return { look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      gasBodyVfx: canvas.dataset.gasBodyVfx, nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      nobleGasPrismVfx: canvas.dataset.nobleGasPrismVfx,
      nobleGasCoreReliefVfx: canvas.dataset.nobleGasCoreReliefVfx, isolatedSelectors };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.gasBodyVfx === 'active'
    && hdrPipeline.nobleGasBillowVfx === 'active'
    && hdrPipeline.nobleGasPrismVfx === (enabled ? 'active' : 'inactive')
    && hdrPipeline.nobleGasCoreReliefVfx === 'inactive'
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive'),
  `E31 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E31 ${label} ${scale}x framebuffer`, scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await nobleGasBillowVfxFieldDigest(cdp, fixture), walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, nobleGasBillowVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, nobleGasBillowVfxRawControlPoints(fixture)),
    hdrPipeline,
  };
}

async function writeNobleGasPrismVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e31-noble-gas-prism-${scale}x-off`),
    on: variantScreenshotPath(source, `e31-noble-gas-prism-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

async function auditEightXNobleGasPrismVfxExclusion(cdp, dpr) {
  await setDesktopMetrics(cdp, 1280, 720, dpr);
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', renderScale: '8',
    auditStage: 'eight-noble-gas-prism', nobleGasPrismVfxAudit: '1', renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0',
    gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '1', nobleGasPrismVfx: '1', nobleGasCoreReliefVfx: '0', smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0',
    plasmaCoreVfx: '0', solidBodyVfx: '0', platinumBodyVfx: '0', ceramicGlazeVfx: '0',
    botanicalBodyVfx: '0', botanicalMesostructureVfx: '0', botanicalPigmentVfx: '0',
    woodBarkReliefVfx: '0', glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0',
    rockMesostructureVfx: '0', waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  const deadline = Date.now() + EIGHT_X_PRESENTATION_DEADLINE_MS;
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search);
    return p.get('renderScale') === '8' && p.get('auditStage') === 'eight-noble-gas-prism'
      && p.get('gasBodyVfx') === '1' && p.get('nobleGasBillowVfx') === '1'
      && p.get('nobleGasPrismVfx') === '1' && p.get('nobleGasCoreReliefVfx') === '0'
      && p.get('smokeBillowDepthVfx') === '0'
      && Boolean(window.__ANIFOR_INPUT_AUDIT__);
  })()`), remainingDeadlineMs(deadline, 'true-8x E31 input audit API'), 'true-8x E31 input audit API');
  const backend = await waitForEightXTerminalBackend(cdp, 'true-8x E31', deadline);
  assertEightXWebGLBackend(backend, 'true-8x E31');
  const geometry = await waitForStableCanvas(
    cdp, 1280, 720, undefined,
    Math.min(45_000, remainingDeadlineMs(deadline, 'true-8x E31 geometry')), 'true-8x E31 geometry',
  );
  assert(geometry.backing.width === WORLD_WIDTH * 8
    && geometry.backing.height === WORLD_HEIGHT * 8 && geometry.outputScale === '8',
  `true-8x E31 lost exact backing (${JSON.stringify(geometry.backing)})`);
  const isolation = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas');
    return canvas ? { renderer: canvas.dataset.renderer, look: canvas.dataset.renderLook,
      state: canvas.dataset.hdrPipeline, reason: canvas.dataset.hdrPipelineReason,
      bloomBacking: canvas.dataset.bloomBacking ?? null, gasBodyVfx: canvas.dataset.gasBodyVfx,
      nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      nobleGasPrismVfx: canvas.dataset.nobleGasPrismVfx,
      nobleGasCoreReliefVfx: canvas.dataset.nobleGasCoreReliefVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx } : undefined;
  })()`, Math.min(1_000, remainingDeadlineMs(deadline, 'true-8x E31 isolation')));
  assert(isolation?.renderer === 'semantic-field-webgl' && isolation.look === 'realistic'
    && isolation.state === 'inactive' && isolation.reason === 'scale-8' && isolation.bloomBacking === null
    && isolation.gasBodyVfx === 'inactive' && isolation.nobleGasBillowVfx === 'inactive'
    && isolation.nobleGasPrismVfx === 'inactive' && isolation.nobleGasCoreReliefVfx === 'inactive'
    && isolation.smokeBillowDepthVfx === 'inactive',
  `true-8x E31 isolation failed (${JSON.stringify(isolation)})`);
  const timingBudget = remainingDeadlineMs(deadline, 'true-8x E31 timing');
  const timing = await auditWebGLPresentationTiming(
    cdp, 1, Math.min(12_000, timingBudget), timingBudget, 1,
  );
  assert(timing.source === 'gpu-query' || timing.source === 'gpu-fence' || timing.source === 'gpu-finish',
    `true-8x E31 did not complete GPU work (${JSON.stringify(timing)})`);
  return {
    backing: `${geometry.backing.width}x${geometry.backing.height}`,
    promotedWebGLObserved: geometry.outputScale === '8' && geometry.backend.backend === 'webgl',
    isolation, timing,
  };
}

// Frozen from the accepted real 1x/2x/4x SwiftShader matrix. E77 must retain a
// broad cool crown and a deeper violet pocket without collapsing either into a
// flat tint or particle-scale contrast. These rails also preserve the measured
// hue direction, low microcontrast, and scale-stable spatial response.
const NOBLE_GAS_CORE_RELIEF_VFX_ACCEPTANCE = Object.freeze({
  NOBLCoreCrown: Object.freeze({
    rgbRms: [1.90, 2.25], chromaRms: [0.58, 0.82], rgbPeak: [2, 5],
    signedMean: [1.40, 1.80], coverage: [0.43, 0.52], spatialRgbRms: [0.52, 0.72],
    responseMicroContrast: [0.22, 0.42],
    responseRgb: [[1.85, 2.20], [1.20, 1.58], [2.15, 2.58]],
  }),
  NOBLCorePocket: Object.freeze({
    rgbRms: [2.50, 2.90], chromaRms: [0.84, 1.05], rgbPeak: [3, 5],
    signedMean: [-2.20, -1.85], coverage: [0.84, 0.97], spatialRgbRms: [0.30, 0.52],
    responseMicroContrast: [0.18, 0.36],
    responseRgb: [[-3.10, -2.60], [-1.85, -1.45], [-3.50, -2.95]],
  }),
  crossScale: Object.freeze({
    rgbRms: 0.12, chromaRms: 0.06, signedMean: 0.10, coverage: 0.08,
    spatialRgbRms: 0.12, responseMicroContrast: 0.08, responseRgb: 0.18, rgbPeak: 1,
  }),
});

// The foreign FOG shader branch remains exact. A two-byte composed-frame
// allowance covers the accepted HDR filter footprint from its immediately
// adjacent, darkened Noble cell without admitting a species-side response.
const NOBLE_GAS_CORE_RELIEF_VFX_LOCAL_CONTROL_PEAK = Object.freeze({
  NOBLAuthoredVoid: 0,
  NOBLOpenChannel: 0,
  GasSeamNoble: 4,
  GasSeamFOG: 2,
});

function nobleGasCoreReliefVfxTargetRegions(fixture) {
  const rect = (name, candidate) => ({
    name, target: true,
    x: candidate.x + candidate.width / 2, y: candidate.y + candidate.height / 2,
    radiusX: Math.max(0.35, candidate.width / 2 - 0.2),
    radiusY: Math.max(0.35, candidate.height / 2 - 0.2),
  });
  // Both probes are fully dense, exact-style-7 Noble volume with opposing
  // established E31 composite relief. E77 must expand that accepted contrast
  // through optical depth without rebuilding the prism phase. A flat tint or
  // particle-scale accent cannot satisfy both polarities while the
  // sparse/topology controls below remain exact.
  return [
    rect('NOBLCoreCrown', { x: 74, y: 88, width: 10, height: 12 }),
    rect('NOBLCorePocket', { x: 96, y: 82, width: 4, height: 6 }),
  ];
}

/** E77: exact Noble deep-core relief over E04/E25/E31. */
async function auditNobleGasCoreReliefVfxExperiment(cdp, mode, dpr) {
  const scales = [];
  const requestedScales = renderScaleArgument === undefined
    ? VOLUME_VFX_SCALES : [Number(renderScaleArgument)];
  for (const scale of requestedScales) {
    const captures = {};
    for (const enabled of [false, true, false]) {
      const key = enabled ? 'enabled' : captures.disabled ? 'disabledRepeat' : 'disabled';
      captures[key] = await navigateNobleGasCoreReliefVfxState(cdp, mode, scale, enabled, key);
    }
    const { disabled, enabled, disabledRepeat } = captures;
    const fixture = disabled.fixture;
    assert(JSON.stringify(fixture) === JSON.stringify(enabled.fixture)
      && JSON.stringify(fixture) === JSON.stringify(disabledRepeat.fixture),
    `E77 ${scale}x fixture metadata changed`);
    for (const [label, variant] of Object.entries(captures)) {
      assertGeometry(variant.geometry, `E77 ${label} ${scale}x`, scale);
      assert(variant.geometry.backend.backend === 'webgl', `E77 ${label} ${scale}x lost WebGL`);
      assert(variant.hdrPipeline?.state === 'active' && variant.hdrPipeline.gasBodyVfx === 'active'
        && variant.hdrPipeline.nobleGasBillowVfx === 'active'
        && variant.hdrPipeline.nobleGasPrismVfx === 'active'
        && variant.hdrPipeline.nobleGasCoreReliefVfx === (label === 'enabled' ? 'active' : 'inactive')
        && Object.values(variant.hdrPipeline.isolatedSelectors).every((state) => state === 'inactive'),
      `E77 ${label} ${scale}x selector isolation failed (${JSON.stringify(variant.hdrPipeline)})`);
    }
    assertCanvasRectsEqual(disabled.geometry.canvas, enabled.geometry.canvas,
      `E77 ${scale}x disabled/enabled CSS geometry`);
    assertCanvasRectsEqual(disabled.geometry.canvas, disabledRepeat.geometry.canvas,
      `E77 ${scale}x disabled/repeated CSS geometry`);
    assert(JSON.stringify(disabled.geometry.backing) === JSON.stringify(enabled.geometry.backing)
      && JSON.stringify(disabled.geometry.backing) === JSON.stringify(disabledRepeat.geometry.backing),
    `E77 ${scale}x backing geometry changed`);
    assertHdrVfxSemanticEquality(disabled.semantic, enabled.semantic, `E77 ${scale}x disabled/enabled`);
    assertHdrVfxSemanticEquality(disabled.semantic, disabledRepeat.semantic,
      `E77 ${scale}x disabled/repeated`);
    assertVolumeVfxBackingInvariant(disabled.backing, enabled.backing,
      `E77 ${scale}x disabled/enabled`);
    assertVolumeVfxBackingInvariant(disabled.backing, disabledRepeat.backing,
      `E77 ${scale}x disabled/repeated`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, enabled.rawAll,
      `E77 ${scale}x disabled/enabled`);
    assertVolumeVfxRawAlphaInvariant(disabled.rawAll, disabledRepeat.rawAll,
      `E77 ${scale}x disabled/repeated`);
    assert(JSON.stringify(disabled.rawControls) === JSON.stringify(enabled.rawControls)
      && JSON.stringify(disabled.rawControls) === JSON.stringify(disabledRepeat.rawControls),
    `E77 ${scale}x changed an exact raw control`);
    assert(JSON.stringify(disabled.field) === JSON.stringify(enabled.field)
      && JSON.stringify(disabled.field) === JSON.stringify(disabledRepeat.field),
    `E77 ${scale}x changed atmosphere ownership/density`);
    assert(JSON.stringify(disabled.walls) === JSON.stringify(enabled.walls)
      && JSON.stringify(disabled.walls) === JSON.stringify(disabledRepeat.walls)
      && disabled.walls.occupied > 0,
    `E77 ${scale}x changed native-wall topology`);
    assert(disabled.capture.capture.data === disabledRepeat.capture.capture.data,
      `E77 ${scale}x repeated off framebuffer was not byte exact`);

    const targets = nobleGasCoreReliefVfxTargetRegions(fixture);
    const controls = nobleGasBillowVfxControlRegions(fixture);
    const responses = withSpatialRgbRms(await sampleBackdropRefractionRegions(cdp, {
      straight: disabled.capture.capture.data,
      refracted: enabled.capture.capture.data,
      repeatedStraight: disabledRepeat.capture.capture.data,
    }, [...targets, ...controls], disabled.capture.canvasRect));
    const targetResponses = responses.slice(0, targets.length);
    const controlResponses = responses.slice(targets.length);
    const acceptance = NOBLE_GAS_CORE_RELIEF_VFX_ACCEPTANCE;
    assert(targetResponses.length === 2 && targetResponses.every((sample) => {
      const bounds = acceptance[sample.name];
      return bounds && sample.rgbRms >= bounds.rgbRms[0] && sample.rgbRms <= bounds.rgbRms[1]
        && sample.chromaRms >= bounds.chromaRms[0] && sample.chromaRms <= bounds.chromaRms[1]
        && sample.rgbPeak >= bounds.rgbPeak[0] && sample.rgbPeak <= bounds.rgbPeak[1]
        && sample.signedMean >= bounds.signedMean[0] && sample.signedMean <= bounds.signedMean[1]
        && sample.coverage >= bounds.coverage[0] && sample.coverage <= bounds.coverage[1]
        && sample.spatialRgbRms >= bounds.spatialRgbRms[0]
        && sample.spatialRgbRms <= bounds.spatialRgbRms[1]
        && sample.responseMicroContrast >= bounds.responseMicroContrast[0]
        && sample.responseMicroContrast <= bounds.responseMicroContrast[1]
        && sample.responseRgb.every((value, index) => value >= bounds.responseRgb[index][0]
          && value <= bounds.responseRgb[index][1])
        && sample.repeatRgbPeak === 0;
    }), `E77 ${scale}x core targets were inert, flat, or unbounded (${JSON.stringify(targetResponses)})`);
    const byName = Object.fromEntries(targetResponses.map((sample) => [sample.name, sample]));
    assert(byName.NOBLCoreCrown?.signedMean > 0 && byName.NOBLCorePocket?.signedMean < 0,
      `E77 ${scale}x lost opposing deep-core polarity (${JSON.stringify(targetResponses)})`);
    assert(controlResponses.every((sample) => sample.rgbPeak
      <= (NOBLE_GAS_CORE_RELIEF_VFX_LOCAL_CONTROL_PEAK[sample.name] ?? 0)
      && sample.repeatRgbPeak === 0),
    `E77 ${scale}x escaped an E25 topology/sibling/contact/wall control (${JSON.stringify(controlResponses)})`);
    const screenshots = screenshotRequest && (requestedScales.length === 1 || scale === 2)
      ? await writeNobleGasCoreReliefVfxScreenshots(screenshotRequest, scale, disabled, enabled)
      : undefined;
    scales.push({
      scale, geometry: disabled.geometry, semantic: disabled.semantic, backing: disabled.geometry.backing,
      alphaSupport: disabled.backing, field: disabled.field, walls: disabled.walls,
      rawControls: disabled.rawControls, targetResponses, controlResponses,
      exactRepeatedOff: true, screenshots,
    });
  }
  if (scales.length > 1) {
    const reference = scales.find(({ scale }) => scale === 2) ?? scales[0];
    const spread = (values) => Math.max(...values) - Math.min(...values);
    for (const entry of scales.filter(({ scale }) => scale !== reference.scale)) {
      assertCanvasRectsEqual(reference.geometry.canvas, entry.geometry.canvas,
        `E77 ${reference.scale}x/${entry.scale}x CSS geometry`);
      assert(JSON.stringify(reference.semantic) === JSON.stringify(entry.semantic)
        && JSON.stringify(reference.field) === JSON.stringify(entry.field)
        && JSON.stringify(reference.walls) === JSON.stringify(entry.walls),
      `E77 ${entry.scale}x changed exact fixture ownership across output scales`);
    }
    const bounds = NOBLE_GAS_CORE_RELIEF_VFX_ACCEPTANCE.crossScale;
    for (const name of ['NOBLCoreCrown', 'NOBLCorePocket']) {
      const samples = scales.map((entry) => entry.targetResponses.find((sample) => sample.name === name));
      assert(samples.every(Boolean)
        && spread(samples.map((sample) => sample.rgbRms)) <= bounds.rgbRms
        && spread(samples.map((sample) => sample.chromaRms)) <= bounds.chromaRms
        && spread(samples.map((sample) => sample.signedMean)) <= bounds.signedMean
        && spread(samples.map((sample) => sample.coverage)) <= bounds.coverage
        && spread(samples.map((sample) => sample.spatialRgbRms)) <= bounds.spatialRgbRms
        && spread(samples.map((sample) => sample.responseMicroContrast))
          <= bounds.responseMicroContrast
        && spread(samples.map((sample) => sample.rgbPeak)) <= bounds.rgbPeak
        && [0, 1, 2].every((channel) => spread(
          samples.map((sample) => sample.responseRgb[channel]),
        ) <= bounds.responseRgb),
      `E77 ${name} response drifted across output scales (${JSON.stringify(samples)})`);
    }
  }
  return {
    calibration: 'e77-noble-gas-core-relief-v1', acceptance: NOBLE_GAS_CORE_RELIEF_VFX_ACCEPTANCE,
    scales, trueEightXExcluded: true,
    trueEightX: await auditEightXNobleGasCoreReliefVfxExclusion(cdp, dpr),
  };
}

async function navigateNobleGasCoreReliefVfxState(cdp, mode, scale, enabled, label) {
  const query = new URLSearchParams({
    scene: 'render-lab', inputAudit: '1', blankAudit: '1', auditStage: 'blank',
    nobleGasCoreReliefVfxAudit: '1', renderScale: String(scale), renderLook: 'realistic',
    volumeVfx: '0', liquidBodyVfx: '0', liquidSurfaceVfx: '0', gasBodyVfx: '1',
    gasMotionVfx: '0', powderBodyVfx: '0', powderLightVfx: '0', powderSolidContactVfx: '0',
    translucentEdgeVfx: '0', organicSubsurfaceVfx: '0', wetSedimentVfx: '0',
    gasLightVfx: '0', liquidSolidMeniscusVfx: '0', gasCoreDepthVfx: '0',
    nobleGasBillowVfx: '1', nobleGasPrismVfx: '1', nobleGasCoreReliefVfx: enabled ? '1' : '0',
    smokeSoftnessVfx: '0', smokeBillowDepthVfx: '0', plasmaCoreVfx: '0', solidBodyVfx: '0',
    platinumBodyVfx: '0', ceramicGlazeVfx: '0', botanicalBodyVfx: '0',
    botanicalMesostructureVfx: '0', botanicalPigmentVfx: '0', woodBarkReliefVfx: '0',
    glassBodyVfx: '0', oilBodyVfx: '0', rockRoughnessVfx: '0', rockMesostructureVfx: '0',
    waterBodyVfx: '0',
  });
  await cdp.send('Page.navigate', { url: `${AUDIT_BASE_URL}?${query}` });
  await waitFor(() => evaluate(cdp, `(() => {
    const p = new URLSearchParams(location.search); const audit = window.__ANIFOR_INPUT_AUDIT__;
    const isolated = ['volumeVfx', 'liquidBodyVfx', 'liquidSurfaceVfx', 'gasMotionVfx',
      'powderBodyVfx', 'powderLightVfx', 'powderSolidContactVfx', 'translucentEdgeVfx',
      'organicSubsurfaceVfx', 'wetSedimentVfx', 'gasLightVfx', 'liquidSolidMeniscusVfx',
      'gasCoreDepthVfx', 'smokeSoftnessVfx', 'smokeBillowDepthVfx', 'plasmaCoreVfx', 'solidBodyVfx',
      'platinumBodyVfx', 'ceramicGlazeVfx', 'botanicalBodyVfx', 'botanicalMesostructureVfx',
      'botanicalPigmentVfx', 'woodBarkReliefVfx', 'glassBodyVfx', 'oilBodyVfx',
      'rockRoughnessVfx', 'rockMesostructureVfx', 'waterBodyVfx'];
    return p.get('nobleGasCoreReliefVfxAudit') === '1'
      && p.get('renderScale') === ${JSON.stringify(String(scale))} && p.get('renderLook') === 'realistic'
      && p.get('gasBodyVfx') === '1' && p.get('nobleGasBillowVfx') === '1'
      && p.get('nobleGasPrismVfx') === '1'
      && p.get('nobleGasCoreReliefVfx') === ${JSON.stringify(enabled ? '1' : '0')}
      && isolated.every((name) => p.get(name) === '0')
      && typeof audit?.prepareNobleGasBillowVfxFixture === 'function'
      && typeof audit?.nobleGasBillowVfxFixture === 'function';
  })()`), scale === 4 ? 45_000 : 15_000, `E77 ${label} ${scale}x page`);
  await waitFor(() => evaluate(cdp,
    `window.__ANIFOR_INPUT_AUDIT__.backend().backend === ${JSON.stringify(mode)}`),
  scale === 4 ? 30_000 : 15_000, `E77 ${label} ${scale}x backend`);
  const fixture = await evaluate(cdp, `(() => {
    const audit = window.__ANIFOR_INPUT_AUDIT__;
    audit.prepareNobleGasBillowVfxFixture(); return audit.nobleGasBillowVfxFixture();
  })()`);
  for (let pass = 0; pass < 5; pass++) {
    const before = await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()');
    await evaluate(cdp, 'window.__ANIFOR_INPUT_AUDIT__.refreshPresentationFields(); true');
    await waitFor(() => evaluate(cdp,
      `window.__ANIFOR_INPUT_AUDIT__.presentationRefreshAudit()?.dynamicSequence > ${before.dynamicSequence}`),
    scale === 4 ? 15_000 : 5_000, `E77 ${label} ${scale}x presentation refresh ${pass + 1}`);
  }
  await waitFor(() => nobleGasBillowVfxFixtureReady(cdp, fixture),
    20_000, `E77 ${label} ${scale}x fixture/atmosphere hydration`);
  const hdrPipeline = await evaluate(cdp, `(() => {
    const canvas = document.querySelector('canvas.semantic-field-canvas'); if (!canvas) return undefined;
    const isolatedSelectors = {
      volumeVfx: canvas.dataset.volumeVfx, liquidBodyVfx: canvas.dataset.liquidBodyVfx,
      liquidSurfaceVfx: canvas.dataset.liquidSurfaceVfx, gasMotionVfx: canvas.dataset.gasMotionVfx,
      powderBodyVfx: canvas.dataset.powderBodyVfx, powderLightVfx: canvas.dataset.powderLightVfx,
      powderSolidContactVfx: canvas.dataset.powderSolidContactVfx,
      translucentEdgeVfx: canvas.dataset.translucentEdgeVfx,
      organicSubsurfaceVfx: canvas.dataset.organicSubsurfaceVfx, wetSedimentVfx: canvas.dataset.wetSedimentVfx,
      gasLightVfx: canvas.dataset.gasLightVfx,
      liquidSolidMeniscusVfx: canvas.dataset.liquidSolidMeniscusVfx,
      gasCoreDepthVfx: canvas.dataset.gasCoreDepthVfx, smokeSoftnessVfx: canvas.dataset.smokeSoftnessVfx,
      smokeBillowDepthVfx: canvas.dataset.smokeBillowDepthVfx,
      plasmaCoreVfx: canvas.dataset.plasmaCoreVfx, solidBodyVfx: canvas.dataset.solidBodyVfx,
      platinumBodyVfx: canvas.dataset.platinumBodyVfx, ceramicGlazeVfx: canvas.dataset.ceramicGlazeVfx,
      botanicalBodyVfx: canvas.dataset.botanicalBodyVfx,
      botanicalMesostructureVfx: canvas.dataset.botanicalMesostructureVfx,
      botanicalPigmentVfx: canvas.dataset.botanicalPigmentVfx,
      woodBarkReliefVfx: canvas.dataset.woodBarkReliefVfx, glassBodyVfx: canvas.dataset.glassBodyVfx,
      oilBodyVfx: canvas.dataset.oilBodyVfx, rockRoughnessVfx: canvas.dataset.rockRoughnessVfx,
      rockMesostructureVfx: canvas.dataset.rockMesostructureVfx, waterBodyVfx: canvas.dataset.waterBodyVfx,
    };
    return { look: canvas.dataset.renderLook, state: canvas.dataset.hdrPipeline,
      reason: canvas.dataset.hdrPipelineReason, bloomBacking: canvas.dataset.bloomBacking,
      gasBodyVfx: canvas.dataset.gasBodyVfx, nobleGasBillowVfx: canvas.dataset.nobleGasBillowVfx,
      nobleGasPrismVfx: canvas.dataset.nobleGasPrismVfx,
      nobleGasCoreReliefVfx: canvas.dataset.nobleGasCoreReliefVfx, isolatedSelectors };
  })()`);
  const expectedBloom = `${WORLD_WIDTH * scale / 2}x${WORLD_HEIGHT * scale / 2}`;
  assert(hdrPipeline?.look === 'realistic' && hdrPipeline.state === 'active'
    && hdrPipeline.bloomBacking === expectedBloom && hdrPipeline.gasBodyVfx === 'active'
    && hdrPipeline.nobleGasBillowVfx === 'active' && hdrPipeline.nobleGasPrismVfx === 'active'
    && hdrPipeline.nobleGasCoreReliefVfx === (enabled ? 'active' : 'inactive')
    && Object.values(hdrPipeline.isolatedSelectors).every((state) => state === 'inactive'),
  `E77 ${label} ${scale}x HDR/selector isolation failed (${JSON.stringify(hdrPipeline)})`);
  const capture = await waitForStablePageCapture(
    cdp, `E77 ${label} ${scale}x framebuffer`, scale === 4 ? 45_000 : scale === 2 ? 30_000 : 15_000, 1,
  );
  return {
    fixture, capture, geometry: await metrics(cdp), semantic: await hdrVfxSemanticDigest(cdp),
    backing: await sampleVolumeVfxCanvasAlphaSupport(cdp),
    field: await nobleGasBillowVfxFieldDigest(cdp, fixture), walls: await nobleGasBillowVfxWallDigest(cdp),
    rawAll: await sampleVolumeVfxRawWorldPixels(cdp, nobleGasBillowVfxAllRawPoints(fixture)),
    rawControls: await sampleVolumeVfxRawWorldPixels(cdp, nobleGasBillowVfxRawControlPoints(fixture)),
    hdrPipeline,
  };
}

async function writeNobleGasCoreReliefVfxScreenshots(source, scale, disabled, enabled) {
  const paths = {
    off: variantScreenshotPath(source, `e77-noble-gas-core-relief-${scale}x-off`),
    on: variantScreenshotPath(source, `e77-noble-gas-core-relief-${scale}x-on`),
  };
  await writeFile(paths.off, Buffer.from(disabled.capture.capture.data, 'base64'));
  await writeFile(paths.on, Buffer.from(enabled.capture.capture.data, 'base64'));
  return paths;
}

